// Generated — per-app "Try it yourself" guide: missions to experience in the app, exercises to try in your own app, one reflection question. KO/EN.
// Written on 2026-10-17 for the 264 apps in the ADA archive and field guide, using only facts in insights-data.js, wow-data.js and the field guide observation points.
window.TRY_DATA = {"written":"2026-10-17","apps":{"grug":{"time":5,"setup":null,"missions":[{"ko":"앱을 처음 열고 아무것도 누르지 말고 첫 문구가 나올 때까지 기다려 보세요. 로그인이나 설정 질문 없이 바로 시작되는지 확인해 보세요.","en":"Open the app for the first time and wait for the first lesson without tapping anything. Check whether it starts with no login or setup questions."},{"ko":"오늘의 문구가 한 획씩 써지는 순간을 끝까지 지켜보세요. 글자가 찍히는 게 아니라 누가 쓰는 것처럼 느껴지는 이유를 속도와 획 순서에서 찾아보세요.","en":"Watch today's lesson being written stroke by stroke until it finishes. Look at the speed and stroke order to see why it feels written rather than printed."},{"ko":"상태 표시줄, 탭 바의 날짜, 릴리스 노트를 차례로 살펴보세요. 보통 시스템 글꼴이 나올 자리까지 손글씨가 이어지는지 확인해 보세요.","en":"Look at the status bar, the tab bar dates and the release notes in turn. Check whether the handwriting continues even where you would expect the system font."},{"ko":"문구 위에 그림을 그려 공유하고, 홈 화면 위젯으로도 띄워 보세요. 기능이 이것뿐인데도 부족하게 느껴지는지 스스로 물어보세요.","en":"Draw on the lesson, share it, then pin it as a Home Screen widget. Ask yourself whether such a small feature set feels lacking."}],"make":[{"ko":"내 앱의 화면 하나를 골라 텍스트가 한 번에 뜨지 않고 글자나 줄 단위로 써지는 애니메이션을 SwiftUI로 만들어 보세요.","en":"Pick one screen in your app and build a SwiftUI animation where its text is written out letter by letter or line by line instead of appearing all at once."},{"ko":"내 앱의 기능 목록을 적고, 하루 한 번 쓰는 핵심 행동 하나만 남긴다면 무엇을 지울지 표시해 보세요.","en":"List your app's features and mark what you would delete if only one once-a-day core action remained."},{"ko":"내 앱에서 시스템 기본 모습 그대로인 곳(설정, 릴리스 노트, 위젯 등) 하나를 골라 앱의 톤으로 다시 그려 보세요.","en":"Choose one place in your app that still looks like stock system UI, such as settings, release notes or a widget, and redraw it in your app's own voice."}],"ask":{"ko":"이 앱의 손글씨가 기능이 아니라 정체성으로 느껴진 순간은 어디였나요?","en":"At what moment did the handwriting stop feeling like a feature and start feeling like the app's identity?"}},"Sago Mini Jinja's Garden":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요하고, 3~6세 아이와 함께 해 보면 가장 잘 보여요.","en":"Requires Apple Arcade, and it shows best when you play it with a child aged 3 to 6."},"missions":[{"ko":"첫 1분 동안 글은 무시하고 스와이프만으로 정원을 돌아다녀 보세요. 글을 못 읽는 아이도 길을 찾을 수 있게 해 주는 단서가 어디 있는지 찾아보세요.","en":"For the first minute, ignore any text and move around the garden with swipes only. Look for the cues that would let a child who cannot read find their way."},{"ko":"씨앗을 심고 수확해서 요리까지 이어 가 보세요. 단계가 끝날 때마다 어떤 소리와 움직임으로 잘했다는 신호를 주는지 들어 보세요.","en":"Plant something, harvest it and carry it through to cooking. Listen for the sounds and motions that tell you each step went well."},{"ko":"일부러 엉뚱한 순서로 움직이거나 한참 가만히 있어 보세요. 실패 화면이나 타이머 없이 게임이 그 행동을 어떻게 받아 주는지 확인해 보세요.","en":"Deliberately do things in an odd order or stay idle for a while. See how the game absorbs it without fail screens or timers."},{"ko":"세 구역 중 다른 곳으로 옮겨 가서 꾸미기나 교환을 해 보세요. 메뉴를 열지 않아도 다음에 할 일이 보이는지 살펴보세요.","en":"Move to another of the three areas and try decorating or trading. Notice whether the next thing to do is visible without opening any menu."}],"make":[{"ko":"내 앱 첫 화면의 글자를 모두 가리고, 아이콘과 동작만으로 첫 행동을 할 수 있는지 다른 사람에게 시켜 보세요.","en":"Cover every word on your app's first screen and ask someone to complete the first action using only icons and gestures."},{"ko":"내 앱에서 오류나 실패를 알리는 화면 하나를 골라, 막는 대신 바로 다시 해 볼 수 있게 받아 주는 버전으로 바꿔 보세요.","en":"Pick one error or failure screen in your app and redesign it to absorb the mistake and invite an immediate retry instead of blocking."}],"ask":{"ko":"글을 전혀 읽지 않고도 다음 행동을 알게 해 준 단서는 무엇이었나요?","en":"What cue told you the next action without reading anything at all?"}},"Tide Guide: Charts & Tables":{"time":10,"setup":null,"missions":[{"ko":"내 주변이나 관심 있는 바닷가의 조석 정보를 처음으로 띄워 보세요. 원하는 정보가 보이기까지 몇 단계가 걸리는지 세어 보세요.","en":"Bring up tide data for a coast near you or one you care about for the first time. Count how many steps it takes before the information you want appears."},{"ko":"전체 화면 조석 곡선을 손가락으로 천천히 끌어 보세요. 시간마다 바뀌는 물 높이와 애니메이션이 손가락을 얼마나 바로 따라오는지 느껴 보세요.","en":"Slowly drag your finger along the full-screen tide curve. Feel how closely the hour-by-hour water height and the animation follow your finger."},{"ko":"곡선 옆에 함께 그려진 일출과 일몰, 월출, 달의 위상 정보를 찾아보세요. 이 많은 데이터가 한 화면에서도 읽히는 이유를 정리해 보세요.","en":"Find the sunrise, sunset, moonrise and moon phase data drawn alongside the curve. Work out why so much data still reads on a single screen."},{"ko":"아침, 낮, 저녁에 한 번씩 앱을 열어 색을 비교해 보세요. 시계를 보지 않고도 지금이 어느 시간대인지 알 수 있는지 확인해 보세요.","en":"Open the app once in the morning, at midday and in the evening and compare the colors. Check whether you can tell the time of day without looking at a clock."},{"ko":"홈 화면 위젯이나 Dynamic Island의 라이브 액티비티를 켜 보세요. 같은 곡선이 작은 크기에서 무엇을 남기고 무엇을 버리는지 보세요.","en":"Turn on a Home Screen widget or the Live Activity in the Dynamic Island. See what the same curve keeps and what it drops at a small size."}],"make":[{"ko":"내 앱의 차트 하나에 Swift Charts로 드래그해서 값을 읽는 스크러빙을 붙여 보세요. 손가락 위치에 맞춰 값이 바로 바뀌게 만드세요.","en":"Add drag-to-read scrubbing to one chart in your app with Swift Charts, so the value updates right under the finger."},{"ko":"내 앱의 배경색이나 강조색이 시간대에 따라 바뀌는 프로토타입을 만들어, 색만으로 상태를 전달할 수 있는지 시험해 보세요.","en":"Prototype your app's background or accent color shifting with the time of day, and test whether color alone can communicate a state."}],"ask":{"ko":"하늘색을 따라가는 테마는 나에게 정보였나요, 분위기였나요?","en":"Did the sky-matched theme work for you as information or as mood?"}},"Cyberpunk 2077 Ultimate Edition":{"time":30,"setup":{"ko":"Apple silicon Mac 전용이고 ₩92,900이에요. 헤드 트래킹 공간 음향을 느끼려면 AirPods가 있으면 좋아요.","en":"Mac only, for Apple silicon, at ₩92,900. AirPods let you feel the head-tracked Spatial Audio."},"missions":[{"ko":"처음 실행하면 그래픽 설정을 열어 보세요. 내 칩에 맞춘 Mac 전용 프리셋이 무엇을 대신 정해 주는지, 직접 만질 게 얼마나 남는지 보세요.","en":"On first launch, open the graphics settings. See what the Mac-specific preset for your chip decides for you and how much is left to tweak."},{"ko":"첫 실내 장면에서 멈춰 서서 주변을 천천히 둘러보세요. 소품과 조명이 얼마나 빽빽한지, 프레임이 끊기는 순간이 있는지 살펴보세요.","en":"Stop in the first interior scene and look around slowly. Notice how dense the props and lighting are and whether the frame rate ever stutters."},{"ko":"AirPods를 끼고 고개를 좌우로 돌려 보세요. 소리가 머리를 따라 움직이지 않고 화면 쪽에 머무는지 느껴 보세요.","en":"Put on AirPods and turn your head left and right. Feel whether the sound stays anchored to the screen instead of moving with your head."},{"ko":"차량을 타고 거리를 달려 보세요. 빠른 속도에서도 차량 디자인과 도시의 밀도가 유지되는지, HDR 조명이 어떻게 보이는지 확인해 보세요.","en":"Take a vehicle and drive through the streets. Check whether vehicle design and city density hold up at speed and how the HDR lighting looks."}],"make":[{"ko":"내 앱에서 사용자가 고르기 어려워하는 설정 하나를 골라, 기기 종류에 맞춰 기본값을 자동으로 정하도록 바꿔 보세요.","en":"Pick one setting in your app that users struggle to choose and make its default set automatically based on the device."},{"ko":"AirPods나 디스플레이 같은 Apple 기기 기능을 장식이 아니라 경험의 일부로 쓸 수 있는 내 앱의 장면 하나를 찾아 스케치해 보세요.","en":"Find one moment in your app where an Apple hardware feature such as AirPods or the display could be part of the experience rather than a checkbox, and sketch it."}],"ask":{"ko":"이 게임에서 Mac이라서 더 좋았던 순간은 언제였나요?","en":"When did it feel better specifically because it was running on a Mac?"}},"Evolve: Daily Self-Care Coach":{"time":10,"setup":null,"missions":[{"ko":"처음 실행해서 개인화 질문에 답해 보세요. 어떤 질문이 주류 웰니스 앱과 다르고, 그 질문이 나를 어떻게 대한다고 느껴지는지 적어 보세요.","en":"Launch the app and answer the personalization questions. Note which ones differ from mainstream wellness apps and how they make you feel addressed."},{"ko":"커밍아웃 지원이나 차별에서 회복하기 같은 LGBTQIA+ 콘텐츠 하나를 열어 보세요. 문장의 톤이 일반 명상 앱과 어떻게 다른지 비교해 보세요.","en":"Open one LGBTQIA+ piece, such as coming-out support or healing from discrimination. Compare its tone with a typical meditation app."},{"ko":"기분이나 습관을 하나 기록하고 결과 화면을 살펴보세요. 연속 기록을 강요하는 장치가 있는지, 압박 없는 진행이 어떻게 표현되는지 보세요.","en":"Log one mood or habit and study the screen that follows. Look for any streak pressure and how progress without pressure is expressed."},{"ko":"기기 설정에서 글자 크기를 키우고 동작 줄이기와 고대비를 켠 뒤 앱으로 돌아와 보세요. 레이아웃이 버티는지, 색 없이도 구분되는지 확인하세요.","en":"Raise the text size and turn on Reduce Motion and high contrast in device settings, then return. Check that layouts hold and things are distinguishable without color."},{"ko":"4-7-8 호흡이나 박스 호흡을 하나 따라 해 보세요. 안내가 화면, 소리, 움직임 중 무엇으로 전달되는지 관찰해 보세요.","en":"Follow one 4-7-8 or box breathing exercise. Observe whether the guidance comes through the screen, sound or motion."}],"make":[{"ko":"내 앱의 온보딩 질문을 모두 적고, 특정 사용자 집단 하나를 정해 그 사람들에게만 와닿는 질문 하나로 바꿔 써 보세요.","en":"Write out your onboarding questions, choose one specific user group, and rewrite one question so it speaks directly to them."},{"ko":"내 앱을 가장 큰 글자 크기와 동작 줄이기 설정으로 켜고, 깨지는 화면 세 곳을 찾아 고쳐 보세요.","en":"Run your app at the largest text size with Reduce Motion on, find three screens that break, and fix them."},{"ko":"내 앱의 알림이나 연속 기록 문구 하나를 빠뜨린 날을 탓하지 않는 문장으로 다시 써 보세요.","en":"Rewrite one notification or streak message in your app so it does not blame the user for a missed day."}],"ask":{"ko":"이 앱이 누구를 위한 앱인지 첫 5분 안에 어디서 알 수 있었나요?","en":"Where in the first five minutes could you tell who this app is for?"}},"Gears & Goo":{"time":20,"setup":{"ko":"Apple Vision Pro 전용이고 Apple Arcade 구독이 필요해요. 컨트롤러는 없어도 돼요.","en":"Apple Vision Pro only and requires Apple Arcade. No controller needed."},"missions":[{"ko":"처음 시작할 때 전장이 내 앞에 어떻게 놓이는지 지켜보세요. 떠 있는 섬이 시선 쪽으로 기울어 있어 목이 편한지 느껴 보세요.","en":"At the start, watch how the battlefield is placed in front of you. Feel whether the floating island tilts toward your gaze and keeps your neck relaxed."},{"ko":"메뉴 항목을 바라보고 손가락을 집어 선택해 보세요. 마우스로 고를 때보다 빠르게 느껴지는지 비교해 보세요.","en":"Look at a menu item and pinch to select it. Compare whether it feels faster than picking with a mouse."},{"ko":"유닛을 바라보고 집어서 원하는 곳에 내려놓아 보세요. 레이저 포인터 같은 배치 표시가 손 추적의 흔들림을 어떻게 메워 주는지 보세요.","en":"Look at a unit, pinch to pick it up and drop it where you want. See how the laser-pointer-style indicator covers for hand-tracking wobble."},{"ko":"몸을 숙여 금속, 돌, 반투명 슬라임 재질을 가까이 들여다보세요. 실제 방 풍경과 어떻게 섞이는지, 소리가 어느 방향에서 들리는지 확인하세요.","en":"Lean in and look closely at the metal, stone and translucent slime. Check how they blend with your real room and where the sounds come from."},{"ko":"한 레벨을 끝내 별 점수를 확인한 뒤 샌드박스 모드에서 압박 없이 디오라마를 만들어 보세요. 두 모드의 긴장감 차이를 느껴 보세요.","en":"Finish a level and check its star score, then build a diorama in Sandbox mode with no pressure. Feel the difference in tension between the two."}],"make":[{"ko":"내 앱에서 정밀한 위치 지정이 필요한 동작 하나를 골라, 놓기 전에 도착 위치를 미리 보여 주는 표시를 프로토타입으로 만들어 보세요.","en":"Pick one precise placement action in your app and prototype an indicator that previews where it will land before the user commits."},{"ko":"개발팀이 어지러운 실제 책상 때문에 설계를 바꾼 것처럼, 내 앱을 가장 불편한 실제 환경에서 써 보고 그에 맞춰 배치 하나를 바꿔 보세요.","en":"Like the team that redesigned because real desks are cluttered, use your app in its worst real-world setting and change one layout decision to fit it."}],"ask":{"ko":"전장을 떠 있는 섬으로 만든 결정이 플레이에서 어떻게 느껴졌나요?","en":"How did the choice of a floating island instead of your real table feel in play?"}},"Ahoy! From Picardy":{"time":20,"setup":{"ko":"Apple Vision Pro 전용이고 ₩7,700이에요. 무대 주위를 걸어 다닐 공간이 있으면 좋아요.","en":"Apple Vision Pro only, at ₩7,700. Have enough room to walk around the stage."},"missions":[{"ko":"시작하자마자 무대가 놓이는 순간을 지켜보고, 무대를 원하는 자리로 옮겨 보세요. 화면 틀 대신 공간이 구도를 어떻게 만드는지 보세요.","en":"Watch the stage appear at the start, then move it where you want. See how space, rather than a frame, creates the composition."},{"ko":"이야기가 흐르는 동안 무대 주위를 한 바퀴 걸어 보세요. 각도가 바뀔 때 손으로 만든 모형과 손으로 그린 배경이 어떻게 보이는지 살펴보세요.","en":"Walk once around the stage while the story plays. Notice how the handmade models and hand-painted backdrops look as your angle changes."},{"ko":"인물 하나에 가까이 다가가 들여다보세요. 단순한 형태에 손으로 칠한 질감이 디테일 부족이 아니라 스타일로 읽히는지 판단해 보세요.","en":"Step close to one character and study it. Judge whether the simple shapes with hand-painted textures read as style rather than missing detail."},{"ko":"음악을 따라 16분을 끊지 말고 끝까지 보세요. 상호작용이 나오는 순간을 기억해 두고, 그 순간이 이야기를 끊는지 이어 주는지 판단해 보세요.","en":"Watch the full 16 minutes in one sitting, following the music. Remember each interactive moment and judge whether it breaks or carries the story."}],"make":[{"ko":"종이나 점토로 작은 물건을 만들어 iPhone으로 찍고 내 앱 화면의 장식 이미지로 넣어 보세요. 손맛이 화면 인상을 어떻게 바꾸는지 비교해 보세요.","en":"Make a small object from paper or clay, photograph it with your iPhone and use it as artwork in your app. Compare how the handmade feel changes the screen."},{"ko":"내 앱의 핵심 경험을 3분 안에 끝나는 짧은 이야기로 묶는다면 어떤 순서가 될지 스토리보드 여섯 칸으로 그려 보세요.","en":"Draw a six-panel storyboard of how your app's core experience would unfold as a short story that ends within three minutes."}],"ask":{"ko":"이 작품이 게임이 아니라 단편 영화라는 걸 언제 받아들이게 됐나요?","en":"When did you accept that this is a short film rather than a game?"}},"WHAT THE CAR?":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires Apple Arcade."},"missions":[{"ko":"첫 레벨을 아무 설명 없이 시작해 보세요. 기어 스틱과 핸들만으로 무엇을 해야 하는지 몇 초 만에 알게 되는지 세어 보세요.","en":"Start the first level without reading anything. Count how many seconds it takes to understand what to do with just the gear stick and steering wheel."},{"ko":"차에 다리가 돋아나는 순간까지 가 보세요. 같은 조작으로 전혀 다른 움직임이 나올 때 웃음이 터지는 타이밍을 관찰해 보세요.","en":"Play until the car sprouts legs. Watch for the exact moment the same controls produce a completely different movement and make you laugh."},{"ko":"몇 레벨을 연달아 하면서 레벨마다 새로 생긴 동작을 메모해 보세요. 글자 없이 새 규칙을 알려 주는 방식을 찾아보세요.","en":"Play several levels in a row and note the new verb each one adds. Look for how it teaches each new rule without text."},{"ko":"막히거나 떨어지면 바로 다시 해 보세요. 실패가 벌처럼 느껴지는지, 또 하나의 몸개그처럼 느껴지는지 확인해 보세요.","en":"When you get stuck or fall, retry right away. Check whether failing feels like punishment or like one more physical gag."}],"make":[{"ko":"내 앱의 핵심 동작 하나를 정하고, 그 결과가 예상과 다르게 나오는 장난스러운 변형 세 가지를 스케치해 보세요.","en":"Choose one core action in your app and sketch three playful variations where its result is not what the user expects."},{"ko":"내 앱의 튜토리얼 문장을 모두 지우고, 첫 화면 하나만으로 조작을 가르칠 수 있는지 프로토타입으로 시험해 보세요.","en":"Delete all tutorial text from your app and prototype whether the first screen alone can teach the controls."}],"ask":{"ko":"조작은 그대로인데 매번 새롭게 느껴진 이유는 무엇이었나요?","en":"Why did each level feel new even though the controls never changed?"}},"Copilot Money":{"time":15,"setup":{"ko":"미국 스토어 앱이고, 미국 금융 계좌 연결과 구독이 필요해요.","en":"A US App Store app that needs US financial accounts to link and a subscription."},"missions":[{"ko":"처음 실행해서 계좌를 연결하기까지의 흐름을 따라가 보세요. 민감한 금융 정보를 맡기기 전에 앱이 신뢰를 주려고 무엇을 보여 주는지 살펴보세요.","en":"Follow the flow from first launch to linking an account. Notice what the app shows to earn your trust before you hand over financial data."},{"ko":"새 거래를 확인하는 대기열을 열고 몇 건을 확인해 보세요. 자동화를 믿되 사람에게 한 번 묻는 이 단계가 귀찮은지 안심되는지 느껴 보세요.","en":"Open the review queue and confirm a few new transactions. Feel whether this human check on top of automation is a chore or a relief."},{"ko":"잘못 분류된 거래 하나의 카테고리를 고치고, 비슷한 다음 거래가 어떻게 분류되는지 지켜보세요. 앱이 내 수정을 배우는 순간을 확인해 보세요.","en":"Recategorize one wrongly sorted transaction, then watch how the next similar one is categorized. Look for the moment the app learns from you."},{"ko":"예산과 차트 화면을 훑어보세요. 정보가 빽빽한데도 깔끔하게 읽히는 이유를 여백, 색, 글자 크기에서 찾아보세요.","en":"Scan the budget and chart screens. Find why such dense information still reads cleanly by looking at spacing, color and type size."}],"make":[{"ko":"내 앱에서 자동으로 처리되는 결과 하나를 골라, 사용자가 한 번에 확인하거나 고칠 수 있는 확인 목록 화면을 만들어 보세요.","en":"Pick one automatic result in your app and build a review list where the user can confirm or correct items in one pass."},{"ko":"사용자가 고친 값을 기억했다가 다음번 기본값으로 쓰는 로직을 내 앱의 입력 하나에 붙여 보세요.","en":"Add logic to one input in your app that remembers the user's correction and uses it as the next default."}],"ask":{"ko":"이 앱은 AI가 틀릴 수 있다는 사실을 어디서 인정하고 있었나요?","en":"Where did this app admit that its automation might be wrong?"}},"The Wreck":{"time":30,"setup":{"ko":"무료로 받을 수 있지만 슬픔과 상실을 다루는 이야기라 조용한 시간에 해 보는 게 좋아요.","en":"Free to download, but it deals with grief and loss, so play it at a quiet time."},"missions":[{"ko":"게임을 시작해 첫 대화 장면에서 생각을 나타내는 단어들을 눌러 보세요. 대사를 고르는 게 아니라 인물의 머릿속을 돌아다니는 느낌이 어디서 오는지 보세요.","en":"Start the game and tap the thought words in the first conversation. Notice where the feeling of moving through her mind, rather than picking lines, comes from."},{"ko":"대화 중 주인공이 버거워져 사고가 나는 순간까지 가 보세요. 이야기 속 사고가 게임 규칙으로 바뀌는 전환을 어떻게 연출하는지 지켜보세요.","en":"Play until the heroine becomes overwhelmed mid-conversation and crashes. Watch how the story's crash turns into a game rule."},{"ko":"같은 대화를 다시 겪으며 이번에는 다른 생각을 골라 보세요. 무엇이 달라지는지, 반복이 지루한지 아니면 정리되는 느낌인지 확인해 보세요.","en":"Relive the same conversation and choose different thoughts this time. Check what changes and whether the repetition feels tedious or healing."},{"ko":"기억 장면이 나오면 건너뛰지 말고 끝까지 보세요. 비주얼 노벨 화면에서 3D 연출로 넘어갈 때 장면의 무게가 어떻게 달라지는지 느껴 보세요.","en":"When a memory sequence starts, watch it through without skipping. Feel how the weight shifts when the visual-novel screen gives way to 3D staging."}],"make":[{"ko":"내 앱의 선택지 화면 하나를 버튼 목록 대신 키워드를 눌러 생각을 따라가는 방식으로 바꾼 스케치를 그려 보세요.","en":"Sketch one choice screen in your app redesigned so the user taps keywords to follow a line of thought instead of picking from buttons."},{"ko":"내 앱에서 사용자가 실패하는 순간 하나를 골라, 그 순간을 다시 해 볼 기회로 바꾸는 흐름을 화면 세 장으로 그려 보세요.","en":"Pick one moment where users fail in your app and draw a three-screen flow that turns it into a chance to try again."}],"ask":{"ko":"사고가 반복될 때 그것은 벌이었나요, 기회였나요?","en":"When the crash repeated, did it feel like punishment or like a second chance?"}},"djay":{"time":15,"setup":{"ko":"수상한 손 제스처 경험은 Apple Vision Pro 버전에서만 할 수 있고, iPhone에서는 턴테이블과 Neural Mix를 해 볼 수 있어요.","en":"The award-winning hand-gesture experience needs Apple Vision Pro; on iPhone you can try the turntables and Neural Mix."},"missions":[{"ko":"장비 없이 앱을 처음 열고 첫 믹스를 시도해 보세요. 초보자가 첫 성공을 하기까지 자동 믹스가 무엇을 대신해 주는지 살펴보세요.","en":"Open the app for the first time with no gear and try your first mix. Notice what the automatic mix does for you on the way to a first success."},{"ko":"턴테이블을 손가락으로 돌려 스크래치해 보세요. 레코드라는 메타포가 처음 쓰는 사람에게 조작법을 어떻게 알려 주는지 느껴 보세요.","en":"Spin a turntable with your finger and scratch. Feel how the vinyl metaphor teaches the controls to someone who has never DJed."},{"ko":"아무 곡이나 틀고 Neural Mix로 보컬만 남기거나 드럼만 빼 보세요. 실시간으로 소리가 갈라지는 반응 속도를 귀로 확인해 보세요.","en":"Play any track and use Neural Mix to keep only the vocals or drop the drums. Listen for how instantly the sound splits apart."},{"ko":"Vision Pro가 있다면 손을 귀에 대 미리 듣기를 하고, 3D 레코드를 덱 위로 끌어 보세요. 몸짓이 그대로 기능이 되는 방식을 관찰해 보세요.","en":"If you have Vision Pro, raise a hand to your ear to preview a track and drag a 3D record onto a deck. Observe how a gesture becomes the function itself."}],"make":[{"ko":"내 앱의 복잡한 기능 하나를 현실 물건의 메타포로 바꾼 화면을 스케치하고, 설명 없이 이해되는지 한 사람에게 보여 주세요.","en":"Sketch one complex feature of your app as a real-world object metaphor and show it to one person to see if it makes sense without explanation."},{"ko":"내 앱에서 초보자가 첫 성공을 하기까지의 단계를 세고, 앱이 대신해 줄 수 있는 단계 하나를 자동화해 보세요.","en":"Count the steps a beginner takes to their first success in your app, then automate one step the app could do for them."}],"ask":{"ko":"처음 해 보는데도 DJ가 된 것 같았던 순간은 언제였나요?","en":"When did you feel like a DJ despite never having done it before?"}},"Ancient Board Game Collection":{"time":15,"setup":null,"missions":[{"ko":"처음 열고 게임 하나를 골라 3~4문장의 규칙 설명과 짧은 규칙 애니메이션을 봐 보세요. 처음 보는 게임을 몇 초 만에 이해하는지 재 보세요.","en":"Open the app, pick a game and read its three-to-four-sentence rules and short rules animation. Time how quickly you understand a game you have never seen."},{"ko":"VoiceOver를 켜고 눈을 감은 채 AI와 한 판 두어 보세요. 판 위의 말 위치를 소리만으로 어떻게 알려 주는지 들어 보세요.","en":"Turn on VoiceOver, close your eyes and play a round against the AI. Listen to how piece positions are conveyed by sound alone."},{"ko":"고대비 보드 옵션을 켜 보세요. 말이 색이 아니라 모양이나 글자로도 구분되는지 확인해 보세요.","en":"Switch on a high-contrast board option. Check whether pieces are told apart by shape or text, not just color."},{"ko":"다른 게임 두세 개를 열어 보드 그림을 비교해 보세요. 그 게임이 온 지역의 작가가 그린 그림이 각각 어떤 분위기를 만드는지 보세요.","en":"Open two or three other games and compare their boards. See what mood each artist from the game's home region creates."}],"make":[{"ko":"내 앱을 VoiceOver만으로 켜서 핵심 작업 하나를 끝까지 해 보고, 막히는 요소마다 접근성 레이블을 붙여 보세요.","en":"Complete one core task in your app using only VoiceOver, and add an accessibility label to every element where you get stuck."},{"ko":"내 앱에서 색으로만 구분되는 요소 하나를 찾아 모양이나 글자로도 구분되게 바꿔 보세요.","en":"Find one element in your app distinguished only by color and make it distinguishable by shape or text as well."},{"ko":"내 앱의 도움말이나 안내 하나를 3~4문장으로 줄여 다시 써 보세요.","en":"Rewrite one help or instruction text in your app in three to four sentences."}],"ask":{"ko":"눈을 감고 둘 때 가장 도움이 된 소리 정보는 무엇이었나요?","en":"When playing with your eyes closed, which spoken information helped you most?"}},"Shuffles by Pinterest":{"time":10,"setup":null,"missions":[{"ko":"처음 열었을 때 앱이 무엇부터 하게 하는지 따라가 보세요. 콜라주라는 낯선 활동을 첫 화면에서 어떻게 시작하게 만드는지 보세요.","en":"Follow what the app asks you to do first. See how the first screen gets you started on something as unfamiliar as collage-making."},{"ko":"내 카메라로 찍은 사진에서 물건 하나를 한 번의 탭으로 오려 내 보세요. 오려지는 순간의 반응과 손맛을 느껴 보세요.","en":"Cut an object out of one of your own camera photos with a single tap. Feel the response and tactility of the moment it lifts out."},{"ko":"오린 요소에 흔들기, 회전, 맥박 같은 움직임을 넣고 음악을 붙여 보세요. 멈춰 있던 콜라주가 영상이 되기까지 몇 번 탭했는지 세어 보세요.","en":"Add a motion such as shake, spin or pulse to a cutout and set it to music. Count how many taps it took for a still collage to become a motion piece."},{"ko":"Pinterest 이미지에서 가져온 요소 하나를 눌러 원래 핀으로 이어지는지 확인해 보세요. 표현에서 발견과 쇼핑으로 넘어가는 연결을 살펴보세요.","en":"Tap an element taken from a Pinterest image and check that it links back to its pin. Notice how self-expression connects to discovery and shopping."}],"make":[{"ko":"Vision 프레임워크의 피사체 분리로 사진에서 물체를 오려 스티커로 만드는 작은 프로토타입을 만들어 보세요.","en":"Build a small prototype that uses the Vision framework's subject lifting to cut an object out of a photo as a sticker."},{"ko":"내 앱에서 사용자가 만든 결과물 하나에 움직임 한 가지를 더해, 공유할 때 더 눈에 띄게 만들어 보세요.","en":"Add one motion effect to something users create in your app so it stands out more when shared."}],"ask":{"ko":"오려 내기가 한 번의 탭이라는 점이 재미를 얼마나 바꿨나요?","en":"How much did one-tap cutout change how fun it felt?"}},"Gentler Streak Health Fitness":{"time":10,"setup":{"ko":"Apple Watch가 있으면 가장 잘 느낄 수 있어요. 핵심 기록은 무료이고 프리미엄 단계가 따로 있어요.","en":"Best with an Apple Watch. Core tracking is free, with a separate premium tier."},"missions":[{"ko":"처음 실행해서 건강 데이터 접근을 허용하기까지 따라가 보세요. 권한을 묻기 전에 왜 필요한지 어떻게 설명하는지 보세요.","en":"Follow first launch up to granting Health data access. See how it explains why it needs the data before asking."},{"ko":"오늘의 활동 추천을 확인해 보세요. 고정된 목표 대신 내 최근 기록과 회복에 맞춘 제안이 어떤 말로 설명되는지 읽어 보세요.","en":"Check today's activity recommendation. Read how a suggestion based on your recent history and recovery, rather than a fixed goal, is explained."},{"ko":"Activity Path를 열어 내가 개인 기준선에서 어디쯤 있는지 찾아보세요. 통계를 보여 주는 대신 해석해 준다는 느낌이 어디서 오는지 보세요.","en":"Open the Activity Path and find where you sit relative to your personal baseline. Notice where the sense of being explained to, not just shown stats, comes from."},{"ko":"마스코트 Yorhart가 나오는 순간을 찾아보세요. 같은 데이터도 이 캐릭터가 말할 때 어떤 감정으로 다가오는지 느껴 보세요.","en":"Find a moment where the mascot Yorhart appears. Feel how the same data lands emotionally when it speaks."},{"ko":"월간 요약을 열어 보세요. 다른 사람이 아니라 과거의 나와 비교하는 화면이 동기에 어떤 차이를 만드는지 생각해 보세요.","en":"Open the Monthly Summary. Think about how comparing you with your past self, not others, changes your motivation."}],"make":[{"ko":"내 앱의 차트 하나에 숫자 대신 지금 상태를 한 문장으로 해석해 주는 설명을 붙여 보세요.","en":"Add a one-sentence interpretation of the current state to one chart in your app, instead of only numbers."},{"ko":"내 앱의 목표나 연속 기록 문구 하나를 쉬는 날도 인정하는 문장으로 다시 써 보세요.","en":"Rewrite one goal or streak message in your app so it acknowledges rest days."}],"ask":{"ko":"쉬어도 괜찮다고 말해 주는 앱이 내 동기를 높였나요, 낮췄나요?","en":"Did an app that says rest is fine raise or lower your motivation?"}},"Navi":{"time":15,"setup":{"ko":"대화할 사람이 한 명 더 필요해요. 대면 자막은 상대 기기에도 Navi가 있어야 하고, 번역은 구독 기능이에요.","en":"You need a second person. In-person captions need Navi on their device too, and translation is a subscription feature."},"missions":[{"ko":"처음 실행해서 권한 요청과 첫 화면을 살펴보세요. 청각장애가 있는 사용자와 번역이 필요한 사용자 중 누구를 먼저 맞이하는지 보세요.","en":"Look at the permission requests and first screen on launch. See whether it greets deaf and hard-of-hearing users or translation users first."},{"ko":"친구와 FaceTime 통화를 하며 SharePlay로 실시간 자막을 띄워 보세요. 말과 자막 사이의 지연이 대화 흐름을 깨는지 느껴 보세요.","en":"Start live subtitles over SharePlay during a FaceTime call with a friend. Feel whether the lag between speech and captions breaks the flow."},{"ko":"가까이 있는 사람 기기에도 Navi를 켜고 마주 앉아 이야기해 보세요. 서로의 화면에 자막이 바로 뜨는 순간을 확인해 보세요.","en":"Have someone nearby open Navi too and talk face to face. Watch captions appear instantly on both screens."},{"ko":"상대에게 다른 언어로 한 문장 말해 달라고 하고 번역 자막과 읽어 주기를 들어 보세요. 무료 자막과 유료 번역의 경계가 어디인지 보세요.","en":"Ask the other person to say a sentence in another language and check the translated captions and spoken translation. Notice where free captions end and paid translation begins."}],"make":[{"ko":"Speech 프레임워크로 말한 내용을 실시간 텍스트로 띄우는 화면 하나를 내 앱에 만들어 보세요.","en":"Build one screen in your app that shows speech as live text using the Speech framework."},{"ko":"내 앱의 유료 기능 목록을 보고, 접근성에 해당하는 기능이 결제 뒤에 잠겨 있지 않은지 점검해 보세요.","en":"Go through your app's paid features and check that nothing accessibility-related is locked behind the paywall."}],"ask":{"ko":"자막이 있는 대화와 없는 대화는 무엇이 달랐나요?","en":"What was different about the conversation with captions compared with one without?"}},"Slopes":{"time":15,"setup":{"ko":"실제 기록은 스키장에서만 할 수 있고 Apple Watch가 있으면 좋아요. 비시즌이라면 지도와 기록 화면 위주로 살펴보세요.","en":"Real tracking only works at a ski resort, ideally with an Apple Watch. Off season, focus on the maps and log screens."},"missions":[{"ko":"처음 실행해서 기록을 시작하기까지 몇 번 탭하는지 세어 보세요. 장갑 낀 손으로 리프트 위에서 해도 될 만큼 단순한지 판단해 보세요.","en":"Count the taps from first launch to starting a recording. Judge whether it is simple enough to do with gloves on a chairlift."},{"ko":"스키장에 있다면 기록을 켜고 휴대폰을 주머니에 넣은 채 몇 번 타 보세요. 나중에 활강과 리프트가 자동으로 나뉘었는지 확인해 보세요.","en":"If you are at a resort, start recording, pocket the phone and do a few runs. Check afterwards that runs and lifts were split automatically."},{"ko":"3D 리조트 지도에서 런 하나를 다시 재생하거나 아는 리조트의 트레일 지도를 열어 보세요. 속도와 고도 변화가 지도 위에서 어떻게 읽히는지 보세요.","en":"Replay a run on the 3D resort map, or open the trail map of a resort you know. See how speed and elevation read on the map."},{"ko":"유료 기능에 처음 닿는 순간을 찾아보세요. 시즌권과 일일권처럼 생긴 패스가 일반 구독과 어떻게 다르게 느껴지는지 보세요.","en":"Find the first moment you hit a premium feature. Notice how season and day passes feel different from a typical subscription."},{"ko":"기록 보관 화면을 살펴보세요. 시즌이 끝나도 앱을 지우지 않게 만드는 장치가 무엇인지 찾아보세요.","en":"Look through the log archive. Find what keeps people from deleting the app after the season ends."}],"make":[{"ko":"내 앱의 기록 동작 하나를 시작만 누르면 나머지는 자동으로 되도록 줄인 흐름을 화면 두 장으로 그려 보세요.","en":"Draw a two-screen flow that reduces one logging action in your app to a single start tap, with everything else automatic."},{"ko":"내 앱에 기간 이용권이나 하루 이용권을 가정한 가격 화면 한 장을 만들어 기존 구독 화면과 나란히 비교해 보세요.","en":"Mock up a pricing screen for your app based on a season or day pass and compare it side by side with your current subscription screen."}],"ask":{"ko":"앱을 쓰지 않는 계절에도 이 앱을 지우지 않을 이유가 있었나요?","en":"Did you find a reason to keep this app during the months you would not use it?"}},"Alien: Isolation":{"time":20,"setup":{"ko":"처음 두 미션은 무료이고 전체 게임은 인앱 구입 한 번으로 열려요. 헤드폰을 끼고 해 보세요.","en":"The first two missions are free and one in-app purchase unlocks the full game. Play with headphones."},"missions":[{"ko":"게임을 시작해 첫 1분 동안 화면 조이스틱으로 걸어 다녀 보세요. 콘솔 게임이 터치 화면에서 얼마나 자연스럽게 움직이는지 느껴 보세요.","en":"Start the game and walk around with the on-screen joystick for the first minute. Feel how naturally a console game moves on a touchscreen."},{"ko":"화면 버튼과 조이스틱의 크기와 위치를 내 손에 맞게 바꿔 보세요. 바꾸기 전과 후에 실수가 얼마나 줄었는지 비교해 보세요.","en":"Resize and reposition the on-screen buttons and joystick to fit your hands. Compare how many mistakes you make before and after."},{"ko":"헤드폰을 끼고 불을 끈 채 숨어 있어 보세요. 화면보다 소리가 긴장을 만드는 순간을 세어 보세요.","en":"Put on headphones, turn off the lights and stay hidden for a while. Count the moments when sound, not the picture, creates the tension."},{"ko":"에일리언에게 들켜 실패한 뒤 다시 시도해 보세요. 같은 자리에서 에일리언이 이전과 다르게 움직이는지 관찰해 보세요.","en":"Get caught by the Alien, then retry. Watch whether it behaves differently in the same spot the second time."}],"make":[{"ko":"내 앱에서 가장 자주 누르는 버튼 하나를 사용자가 크기와 위치를 바꿀 수 있게 만드는 프로토타입을 만들어 보세요.","en":"Prototype letting users resize and move the button they press most often in your app."},{"ko":"내 앱의 무료 범위를 기능 단위가 아니라 처음 몇 단계까지로 정한 페이월 화면을 스케치해 보세요.","en":"Sketch a paywall for your app that sets the free tier as the first few steps of the experience rather than a set of features."}],"ask":{"ko":"두 미션을 마친 뒤 결제하고 싶어졌다면 결정적인 순간은 무엇이었나요?","en":"If you wanted to pay after the two free missions, what was the deciding moment?"}},"A Monster's Expedition":{"time":15,"setup":{"ko":"앱 스토어에서 내려가서 지금은 받을 수 없어요. 개발사가 공개한 트레일러와 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through the developer's own trailer and screenshots."},"missions":[{"ko":"트레일러 첫 장면을 소리를 켜고 봐 보세요. 글자 튜토리얼 없이 첫 섬에서 무엇을 해야 할지 화면만으로 짐작되는지 확인해 보세요.","en":"Watch the opening of the trailer with sound on. Check whether you can guess what to do on the first island from the picture alone, with no text tutorial."},{"ko":"통나무가 구르고, 쌓이고, 다리가 되는 장면에서 영상을 멈춰 보세요. 규칙 하나가 다음 규칙을 어떻게 가르치는지 순서대로 적어 보세요.","en":"Pause the trailer where logs roll, stack and become bridges. Write down in order how one rule sets up the next."},{"ko":"스크린샷에서 타일과 통나무 상태를 하나씩 읽어 보세요. 누워 있는지 서 있는지 헷갈리는 칸이 하나라도 있는지 찾아보세요.","en":"Read each tile and log state in the screenshots. Try to find a single one where it is unclear whether a log is standing or lying down."},{"ko":"인간의 물건을 해석한 박물관 전시 장면을 찾아보세요. 퍼즐 흐름을 끊지 않고 이야기와 웃음을 넣는 방법을 관찰해 보세요.","en":"Find the museum exhibits that interpret human objects. Observe how they add story and humor without interrupting the puzzles."}],"make":[{"ko":"내 앱의 기능 하나를 글자 설명 없이 가르치는 세 단계 화면을 그려 보세요. 각 단계에서 사용자가 직접 해 보며 하나만 배우게 하세요.","en":"Draw three screens that teach one feature of your app without any text, where each step lets the user learn exactly one thing by doing it."},{"ko":"내 앱에서 되돌릴 수 없는 동작 하나를 골라 즉시 되돌리기가 가능하게 바꿔 보세요.","en":"Pick one irreversible action in your app and make it instantly undoable."}],"ask":{"ko":"글 한 줄 없이 규칙을 가르친다는 게 영상만 보고도 믿겼나요?","en":"From the footage alone, were you convinced the rules could be taught without a single line of text?"}},"CARROT Weather":{"time":10,"setup":null,"missions":[{"ko":"처음 실행해서 첫 예보가 뜰 때 어떤 말투로 말을 거는지 읽어 보세요. 일반 날씨 앱과 첫인상이 어떻게 다른지 적어 보세요.","en":"On first launch, read how the first forecast talks to you. Note how the first impression differs from a typical weather app."},{"ko":"성격 단계를 가장 점잖은 쪽과 가장 거친 쪽으로 바꿔 가며 같은 예보를 읽어 보세요. 데이터는 같은데 앱이 얼마나 달라지는지 비교해 보세요.","en":"Switch between the most professional and the most unhinged personality levels and read the same forecast. Compare how different the app feels with identical data."},{"ko":"한 섹션에 나오는 데이터 항목을 직접 골라 레이아웃을 바꿔 보세요. 자유도가 높은데도 화면이 어지러워지지 않는지 보세요.","en":"Choose which data points appear in one section and rearrange the layout. See whether the screen stays tidy despite all that freedom."},{"ko":"위젯이나 Apple Watch 컴플리케이션을 하나 추가해 보세요. 같은 데이터가 작은 크기에서 어떻게 다시 잘려 나오는지 관찰해 보세요.","en":"Add a widget or an Apple Watch complication. Observe how the same data is re-cut for a small size."},{"ko":"업적이나 비밀 장소 같은 게임 요소를 찾아보세요. 날씨 말고도 앱을 열 이유가 생기는지 느껴 보세요.","en":"Look for the game layer, such as achievements or secret locations. Feel whether it gives you a reason to open the app beyond the weather."}],"make":[{"ko":"내 앱의 알림이나 빈 화면 문구 하나를 점잖은 버전과 장난스러운 버전으로 써서 사용자가 고를 수 있게 만들어 보세요.","en":"Write one notification or empty-state message in a straight version and a playful version, and let users choose between them."},{"ko":"내 앱의 주요 데이터 하나를 작은 위젯과 중간 위젯에서 각각 무엇을 남길지 정해 그려 보세요.","en":"Decide what one key piece of your app's data keeps in a small widget versus a medium widget, and draw both."}],"ask":{"ko":"말투 하나가 이 앱을 다시 열게 만들 만큼 강했나요?","en":"Was the voice alone strong enough to make you open this app again?"}},"Loóna":{"time":15,"setup":{"ko":"무료 체험 뒤 구독이 필요해요. 잠들기 전 저녁에 해 보는 게 좋아요.","en":"Subscription after a free trial. Try it in the evening before bed."},"missions":[{"ko":"처음 실행해서 첫 Sleepscape를 시작하기까지 따라가 보세요. 그 사이 화면의 색, 글자, 움직임이 이미 긴장을 낮추려 하는지 느껴 보세요.","en":"Follow first launch to the start of your first Sleepscape. Feel whether the colors, type and motion are already trying to calm you along the way."},{"ko":"3D 색칠하기를 손가락으로 천천히 해 보세요. 생각이 많을 때 손에 단순한 일을 주는 것이 실제로 머리를 비워 주는지 관찰해 보세요.","en":"Slowly do the 3D coloring with your finger. Notice whether giving your hands a simple task actually quiets your mind."},{"ko":"내레이션과 배경 소리를 들으며 끝까지 따라가 보세요. 소리, 이야기, 색칠이 하나의 저녁 의식으로 이어지는지 확인해 보세요.","en":"Stay with the narration and soundscape to the end. Check whether sound, story and coloring join into one evening ritual."},{"ko":"끝난 뒤 건강 앱에 기록이 남았는지 확인해 보세요. 마무리 화면이 다시 휴대폰을 만지게 하는지, 내려놓게 하는지도 보세요.","en":"Afterwards, check whether the session was logged in Apple Health. Also notice whether the ending pulls you back into your phone or lets you put it down."}],"make":[{"ko":"내 앱의 화면 하나를 밤 버전으로 다시 만들어 보세요. 색 대비, 애니메이션 속도, 글자 굵기를 낮춰 긴장을 줄이는 방향으로 조정하세요.","en":"Remake one screen of your app as a night version, lowering color contrast, animation speed and font weight to reduce arousal."},{"ko":"내 앱에서 사용자가 가만히 보기만 하는 화면 하나에 손으로 할 수 있는 아주 단순한 행동 하나를 더해 보세요.","en":"Add one very simple hands-on action to a screen in your app where users currently only watch."}],"ask":{"ko":"세션이 끝났을 때 실제로 졸렸나요, 그냥 차분했나요?","en":"When the session ended, were you actually sleepy or just calm?"}},"Looom":{"time":20,"setup":{"ko":"₩17,000 유료 앱이에요. Apple Pencil이 있으면 필압과 두 번 탭 지우기를 쓸 수 있어요.","en":"A paid app at ₩17,000. With an Apple Pencil you get pressure and double-tap to erase."},"missions":[{"ko":"처음 열면 메뉴를 찾지 말고 바로 한 장을 그려 보세요. 다음 장으로 스와이프할 때 이전 그림이 흐리게 남는 걸 확인해 보세요.","en":"On first open, skip the menus and draw a frame right away. Swipe to the next cel and check that the previous drawing stays faintly visible."},{"ko":"서너 장을 그린 뒤 반복 재생해 보세요. 타임라인 없이 루프로 도는 애니메이션이 악기를 연주하는 느낌인지 보세요.","en":"Draw three or four frames and play them in a loop. See whether an animation looping with no timeline feels like playing an instrument."},{"ko":"BPM을 바꿔 재생 속도를 조절해 보세요. 초 단위 대신 박자로 시간을 다루는 것이 어떻게 다르게 느껴지는지 보세요.","en":"Change the BPM to adjust playback speed. Notice how handling time in beats instead of seconds feels different."},{"ko":"톱니바퀴와 노브처럼 생긴 장난감 같은 조작을 돌려 보세요. 빽빽한 타임라인 패널보다 덜 겁나는 이유를 찾아보세요.","en":"Turn the toy-like gears and knobs. Find out why they feel less intimidating than a dense timeline panel."},{"ko":"스레드(레이어)를 하나씩 더 만들어 보세요. 개수가 적게 제한된 것이 작품을 어떻게 단순하게 지켜 주는지 느껴 보세요.","en":"Add threads (layers) one at a time. Feel how the small limit keeps your composition simple."}],"make":[{"ko":"내 앱의 설정 화면에서 슬라이더 하나를 돌리는 노브나 다이얼 형태로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype replacing one slider on your app's settings screen with a knob or dial you turn."},{"ko":"내 앱에서 사용자가 만들 수 있는 항목 개수에 일부러 상한을 두고, 그 덕분에 단순해지는 화면이 있는지 시험해 보세요.","en":"Put a deliberate cap on how many items users can create in your app and test which screen gets simpler because of it."}],"ask":{"ko":"타임라인이 없다는 게 불편했나요, 해방감이었나요?","en":"Did having no timeline feel limiting or freeing?"}},"Peloton":{"time":10,"setup":{"ko":"미국 스토어 앱이에요. 바이크나 트레드 없이 앱 멤버십만으로 해 볼 수 있어요.","en":"A US App Store app. You can try it with just the app membership, no bike or treadmill."},"missions":[{"ko":"처음 실행해서 목표와 좋아하는 운동을 묻는 온보딩에 답해 보세요. 무료 체험 제안이 어느 시점에 나오는지 기록해 보세요.","en":"Launch the app and answer the onboarding questions about goals and preferred workouts. Note exactly when the free trial offer appears."},{"ko":"기기가 없는 사용자에게 처음 무엇을 보여 주는지 살펴보세요. 하드웨어 이야기가 화면 어디에 얼마나 등장하는지 확인해 보세요.","en":"Look at what it shows first to someone without the hardware. Check where and how often the bike or treadmill comes up."},{"ko":"라이브나 온디맨드 클래스 하나를 짧게 따라 해 보세요. 리더보드, 강사의 호명, 마일스톤 배지가 혼자 하는 운동을 어떻게 바꾸는지 보세요.","en":"Follow a live or on-demand class for a few minutes. See how the leaderboard, instructor shout-outs and milestone badges change a solo workout."},{"ko":"마라톤 훈련 같은 여러 주짜리 플랜을 찾아보세요. 단발 운동을 장기 루틴으로 묶는 화면 구성을 살펴보세요.","en":"Find a multi-week program such as marathon training. Study how the screens bundle one-off workouts into a long-term routine."}],"make":[{"ko":"내 앱의 온보딩에 목표를 묻는 질문 하나를 넣고, 그 답에 따라 첫 화면 추천이 바뀌게 만들어 보세요.","en":"Add one goal question to your app's onboarding and make the first screen's recommendation change based on the answer."},{"ko":"내 앱에서 혼자 하는 행동 하나에 다른 사람도 함께하고 있다는 신호를 붙인 화면을 스케치해 보세요.","en":"Sketch a screen that adds a signal that others are doing it too to one solo action in your app."}],"ask":{"ko":"기기가 없는 나에게 이 앱은 무엇을 팔고 있었나요?","en":"Without the hardware, what was this app actually selling you?"}},"Tinder":{"time":10,"setup":null,"missions":[{"ko":"가입부터 첫 카드가 보이는 순간까지 걸린 시간을 재 보세요. 어떤 정보는 꼭 받고 어떤 정보는 뒤로 미루는지 살펴보세요.","en":"Time how long it takes from sign-up to seeing the first card. Notice which details it insists on and which it postpones."},{"ko":"카드를 좌우로 스와이프하며 열 장쯤 넘겨 보세요. 결정을 둘 중 하나로 줄인 덕분에 손이 얼마나 빨라지는지 느껴 보세요.","en":"Swipe left and right through about ten cards. Feel how much faster you go when every decision is reduced to one of two."},{"ko":"방금 넘긴 카드를 되돌려 보려고 해 보세요. Rewind 같은 기능이 어느 단계의 결제에 묶여 있는지 확인해 보세요.","en":"Try to undo the card you just swiped. Check which paid tier a feature like Rewind is tied to."},{"ko":"Super Like나 Boost 같은 소모성 아이템이 처음 제안되는 순간을 찾아보세요. 구독과 별개의 결제가 어떤 순간에 나타나는지 보세요.","en":"Find the first time a consumable such as Super Like or Boost is offered. Notice the moment when this payment, separate from subscriptions, appears."},{"ko":"매치가 생기면 그 순간의 화면 전환과 피드백을 살펴보세요. 스와이프에 대한 보상이 얼마나 크게 연출되는지 보세요.","en":"If you get a match, study the transition and feedback at that moment. See how big the payoff for a swipe is made to feel."}],"make":[{"ko":"내 앱의 목록 화면 하나를 카드 스택으로 바꾸고 좌우 스와이프로 두 가지 결정만 하게 하는 SwiftUI 프로토타입을 만들어 보세요.","en":"Build a SwiftUI prototype that turns one list in your app into a card stack where left and right swipes are the only two decisions."},{"ko":"내 앱의 무료 사용자가 가장 불편해하는 지점 하나를 적고, 그것을 유료로 푸는 것이 공정한지 따져 보세요.","en":"Write down the biggest pain point for free users of your app and judge whether charging to remove it would be fair."}],"ask":{"ko":"스와이프 하나로 결정하게 만드는 것은 사용자에게 도움이었나요, 함정이었나요?","en":"Is reducing every decision to one swipe a help to users or a trap?"}},"TapTapSee":{"time":5,"setup":{"ko":"VoiceOver를 켜고 해 보면 설계 의도가 가장 잘 느껴져요.","en":"Turn on VoiceOver to feel the design intent best."},"missions":[{"ko":"앱을 처음 열고 화면에 무엇이 있는지 살펴보세요. 버튼이 사실상 하나뿐인 첫 화면이 사용자에게 얼마나 적은 것을 요구하는지 보세요.","en":"Open the app and look at what is on the screen. See how little a first screen with essentially one button asks of you."},{"ko":"눈을 감고 화면 오른쪽을 두 번 탭해 물건 하나를 찍어 보세요. 결과가 소리로 나오기까지 몇 초 걸리는지 세어 보세요.","en":"Close your eyes and double-tap the right side of the screen to photograph an object. Count the seconds until the result is spoken."},{"ko":"화면 왼쪽을 두 번 탭해 짧은 동영상으로 물건을 인식시켜 보세요. 사진과 동영상을 위치로만 나눈 것이 기억하기 쉬운지 확인해 보세요.","en":"Double-tap the left side to identify an object with a short video. Check whether splitting photo and video by position alone is easy to remember."},{"ko":"마지막 결과 다시 듣기와 카메라 롤 이미지 분석을 써 보세요. 부가 기능이 핵심 동작을 방해하지 않게 어디에 놓였는지 보세요.","en":"Try repeating the last result and analyzing a camera roll image. See where these extras are placed so they never get in the way of the core action."}],"make":[{"ko":"내 앱의 핵심 동작 하나를 화면 어디든 두 번 탭하면 실행되게 바꾸고, 눈을 감고 써 보세요.","en":"Make one core action in your app trigger with a double-tap anywhere on the screen, then use it with your eyes closed."},{"ko":"내 앱의 결과 화면 하나를 VoiceOver가 읽어 주는 한 문장만으로 이해할 수 있게 접근성 레이블을 다시 써 보세요.","en":"Rewrite the accessibility labels on one result screen so VoiceOver can convey it in a single sentence."}],"ask":{"ko":"화면을 보지 않고도 쓸 수 있게 하려면 내 앱에서 무엇부터 지워야 할까요?","en":"To make your app usable without looking, what would you remove first?"}},"Overcast":{"time":10,"setup":null,"missions":[{"ko":"처음 열고 팟캐스트 하나를 찾아 구독하기까지 따라가 보세요. 빈 상태에서 앱이 무엇부터 하게 하는지 보세요.","en":"Follow the path from first launch to subscribing to one podcast. See what the empty app asks you to do first."},{"ko":"말이 많은 에피소드를 틀고 Smart Speed를 켰다 껐다 해 보세요. 단순 배속과 달리 목소리가 변하지 않는지 귀로 확인해 보세요.","en":"Play a talk-heavy episode and toggle Smart Speed on and off. Listen for whether the voice stays natural, unlike plain speed-up."},{"ko":"음량이 작은 에피소드에서 Voice Boost를 켜 보세요. 두 기능이 재생 화면 어디에 놓였는지, 찾기 쉬웠는지 확인해 보세요.","en":"Turn on Voice Boost for a quiet episode. Check where both features sit on the playback screen and how easy they were to find."},{"ko":"커스텀 스크러버로 재생 위치와 속도를 미세하게 조절해 보세요. 기본 슬라이더보다 손가락에 잘 맞는지 비교해 보세요.","en":"Fine-tune position and speed with the custom scrubber and controls. Compare how well they fit your finger against a standard slider."}],"make":[{"ko":"내 앱의 기본 Slider 하나를 더 큰 터치 영역과 단계 표시가 있는 커스텀 컨트롤로 바꿔 보세요.","en":"Replace one standard Slider in your app with a custom control that has a bigger touch area and visible steps."},{"ko":"내 앱의 가장 강력한 기능 하나에 닿기까지 몇 번 탭하는지 세고, 한 단계 더 가까운 곳으로 옮겨 보세요.","en":"Count the taps to reach your app's most powerful feature and move it one step closer."}],"ask":{"ko":"이 앱이 아껴 준 시간을 실제로 느낄 수 있었나요?","en":"Could you actually feel the time this app saved you?"}},"Google Sheets":{"time":10,"setup":{"ko":"Google 계정이 필요하고, 동시 편집을 보려면 함께할 사람이나 두 번째 기기가 있으면 좋아요.","en":"Needs a Google account, plus a second person or device to see co-editing."},"missions":[{"ko":"새 시트를 만들어 몇 칸 입력해 보세요. 저장 버튼 없이 자동 저장된다는 사실을 화면이 어떻게 알려 주는지 찾아보세요.","en":"Create a new sheet and fill in a few cells. Find how the screen tells you it auto-saved without a save button."},{"ko":"파일을 보내는 대신 링크로 공유하고 상대에게 같은 시트를 열어 달라고 하세요. 상대의 커서와 선택 영역이 색으로 어떻게 보이는지 관찰해 보세요.","en":"Share the sheet as a link instead of a file and have someone open it. Watch how their cursor and selection show up in color."},{"ko":"둘이 동시에 가까운 칸을 편집해 보세요. 글자 단위로 변경이 보일 때 누가 어디를 만지는지 바로 알 수 있는지 확인해 보세요.","en":"Edit nearby cells at the same time. Check whether character-level changes make it instantly clear who is touching what."},{"ko":"휴대폰에서 수식 입력, 정렬, 서식을 해 보세요. 모바일에서 허용한 범위와 빠진 기능의 경계가 어디인지 찾아보세요.","en":"Enter a formula, sort and format on your phone. Find where the line falls between what mobile allows and what was left out."},{"ko":"비행기 모드에서 몇 칸을 고친 뒤 다시 연결해 보세요. 동기화되는 순간 앱이 무엇을 보여 주는지 살펴보세요.","en":"Edit a few cells in Airplane Mode, then reconnect. Notice what the app shows when it syncs."}],"make":[{"ko":"내 앱에 저장 버튼이 있다면 하나를 골라 자동 저장과 저장됨 상태 표시로 바꿔 보세요.","en":"If your app has a save button, replace one with auto-save and a saved-state indicator."},{"ko":"내 앱의 iPad나 Mac 기능 목록을 적고, iPhone에서 뺄 기능과 남길 기능을 이유와 함께 나눠 보세요.","en":"List your app's iPad or Mac features and sort them into keep and cut for iPhone, with a reason for each."}],"ask":{"ko":"모바일에서 이 정도까지만 허용한 결정이 맞다고 느꼈나요?","en":"Did the limit on what you can do on mobile feel like the right call?"}},"오늘의집":{"time":10,"setup":null,"missions":[{"ko":"처음 열고 1분 동안 목적 없이 피드를 둘러보세요. 언제 처음으로 상품이 궁금해졌는지 기록해 보세요.","en":"Open the app and browse the feed with no goal for one minute. Note the first moment you got curious about a product."},{"ko":"집들이 사진 속 상품 태그를 눌러 보세요. 사진에서 상품 페이지로 넘어가는 순간이 광고처럼 느껴지는지 자연스러운지 판단해 보세요.","en":"Tap a product tag in a home tour photo. Judge whether the jump from photo to product page feels like an ad or feels natural."},{"ko":"마음에 드는 사진을 스크랩해 보세요. 스크랩이 나중의 구매 흐름으로 어떻게 이어지는지 따라가 보세요.","en":"Save a photo you like. Follow how that save connects to a purchase later."},{"ko":"3D 방꾸미기로 가구 하나를 배치해 보세요. 사기 전에 공간에 맞을지에 대한 불안을 얼마나 줄여 주는지 느껴 보세요.","en":"Place a piece of furniture with the 3D room planner. Feel how much it eases worry about whether it will fit before buying."}],"make":[{"ko":"내 앱의 콘텐츠 화면 하나에 이미지 위 태그를 누르면 관련 상세 화면으로 바로 넘어가는 프로토타입을 만들어 보세요.","en":"Prototype tappable tags on an image in one content screen of your app that jump straight to a related detail screen."},{"ko":"내 앱의 첫 화면이 사게 만드는지 둘러보게 만드는지 한 문장으로 쓰고, 그에 맞게 첫 섹션 순서를 바꿔 보세요.","en":"Write one sentence on whether your app's first screen makes people buy or browse, then reorder its first sections to match."}],"ask":{"ko":"사진에서 상품으로 넘어갈 때 신뢰가 생긴 이유는 무엇이었나요?","en":"What made you trust the product when you moved from the photo to it?"}},"Blippo+":{"time":20,"setup":{"ko":"Mac 전용이고 ₩19,000 일회성 유료 앱이에요.","en":"Mac only, a one-time purchase at ₩19,000."},"missions":[{"ko":"처음 켜자마자 썸네일 목록 대신 무엇이 나오는지 보세요. 채널을 돌리는 행동 자체가 탐색이라는 걸 언제 알게 되는지 확인해 보세요.","en":"Notice what appears on first launch instead of a thumbnail grid. Check when you realize that flipping channels is the navigation."},{"ko":"채널을 빠르게 여러 번 돌려 보세요. 큰 채널 번호와 픽셀 글꼴이 진짜 방송처럼 느껴지게 만드는 순간을 찾아보세요.","en":"Flip through channels quickly several times. Find the moments when the big channel numbers and pixel fonts make it feel like real broadcast TV."},{"ko":"화면에 가까이 다가가 주사선과 색 번짐을 관찰해 보세요. 필터가 아니라 실제 아날로그 장비로 찍은 영상이 어떻게 다른지 느껴 보세요.","en":"Lean in and study the scanlines and color bleed. Feel how footage shot on real analog equipment differs from a filter."},{"ko":"문자 정보 페이지, 광고, 뉴스를 보며 Planet Blip과 The Bend에 대해 알게 된 단서 세 가지를 적어 보세요.","en":"Watch the teletext pages, ads and news and write down three clues you picked up about Planet Blip and The Bend."},{"ko":"신호 보정을 한동안 무시해 보세요. 화질이 망가지는 방식이 어떤 피드백으로 느껴지는지 보세요.","en":"Ignore the signal calibration for a while. See how the degrading picture works as feedback."}],"make":[{"ko":"내 앱의 목록 화면 하나를 채널 돌리듯 하나씩 넘기는 방식으로 바꾼 프로토타입을 만들어 보세요. 고르는 부담이 줄어드는지 확인하세요.","en":"Prototype one list in your app as a one-at-a-time channel flip. Check whether it reduces the burden of choosing."},{"ko":"내 앱의 설정이나 정보 화면 하나를 앱의 세계관 톤으로 다시 써 보세요. 평범한 iOS 화면처럼 보이는 곳을 줄이는 연습이에요.","en":"Rewrite one settings or info screen in your app in the voice of your app's world, to shrink the places that look like generic iOS."}],"ask":{"ko":"고르지 않고 돌리기만 하는 경험이 편했나요, 답답했나요?","en":"Did flipping instead of choosing feel relaxing or frustrating?"}},"Sid Meier's Civilization VII":{"time":30,"setup":{"ko":"Apple Arcade 구독이 필요하고 A17 Pro 이상 칩을 쓴 기기에서만 실행돼요.","en":"Requires Apple Arcade and a device with an A17 Pro-class chip or newer."},"missions":[{"ko":"새 게임을 시작해 첫 몇 턴 동안 탭과 제스처만으로 유닛을 옮기고 도시를 세워 보세요. PC 게임이 터치로 오며 어디서 탭이 늘었는지 세어 보세요.","en":"Start a new game and move units and found a city with taps and gestures for the first few turns. Count where a PC game needed extra taps on touch."},{"ko":"문명과 지도자 목록을 훑어보세요. 주류 게임에서 보기 드문 문명과 지도자가 어떻게 소개되는지 살펴보세요.","en":"Browse the civilizations and leaders. Notice how ones rarely seen in mainstream games are introduced."},{"ko":"턴을 넘기다 위기나 실수가 생기면 그 순간을 되짚어 보세요. 작은 화면에서 원인을 찾을 정보가 충분히 보였는지 확인해 보세요.","en":"When something goes wrong over a few turns, trace back what happened. Check whether the small screen gave you enough information to see why."},{"ko":"iPhone에서 저장한 뒤 iPad나 Mac에서 이어서 열어 보세요. 크로스 세이브로 넘어갈 때 조작과 화면이 기기에 맞게 어떻게 바뀌는지 보세요.","en":"Save on iPhone and continue on iPad or Mac. See how controls and layout adapt to each device through cross-save."}],"make":[{"ko":"내 앱의 iPad나 Mac 화면 하나에서 하는 작업을 iPhone 터치로 몇 번 탭에 끝내는지 세고, 한 단계를 줄여 보세요.","en":"Count how many taps one task from your app's iPad or Mac screen takes on iPhone, then remove one step."},{"ko":"내 앱의 진행 상황을 다른 기기에서 이어서 여는 흐름을 화면 두 장으로 설계해 보세요.","en":"Design a two-screen flow for picking up your app's progress on another device."}],"ask":{"ko":"큰 게임을 작은 화면에 넣으면서도 포기하지 않았다고 느낀 부분은 무엇이었나요?","en":"What did this game refuse to give up when it moved to a small screen?"}},"Grand Mountain Adventure 2":{"time":10,"setup":{"ko":"무료로 받고 전체 게임은 한 번의 결제로 열려요.","en":"Free to download, with a one-time unlock for the full game."},"missions":[{"ko":"게임을 켜고 바로 내려가 보세요. 왼쪽, 오른쪽, 점프만으로 카빙이 손에 붙기까지 몇 초 걸리는지 재 보세요.","en":"Launch the game and head straight downhill. Time how many seconds it takes for carving with just left, right and jump to feel natural."},{"ko":"트릭을 시도하다 일부러 넘어져 보세요. 넘어진 뒤 다시 달리기까지의 시간과 그때의 피드백을 관찰해 보세요.","en":"Try a trick and wipe out on purpose. Watch how long it takes to get going again and what feedback you get."},{"ko":"정해진 길을 벗어나 숲이나 백컨트리로 내려가 보세요. 코스 목록이 아니라 어디든 갈 수 있다는 자유가 어떻게 느껴지는지 보세요.","en":"Leave the groomed route and ride into the forest or backcountry. Feel the freedom of going anywhere instead of picking from a course list."},{"ko":"리프트를 타고 다른 스키어나 챌린지를 만나 보세요. 실제 스키장을 아는 사람이 만든 디테일을 찾아보세요.","en":"Ride a lift and run into other skiers or challenges. Look for details that only people who know real resorts would add."}],"make":[{"ko":"내 앱의 핵심 조작을 입력 세 개로만 줄인다면 무엇이 남을지 적고, 그 세 개로 동작하는 프로토타입 화면을 만들어 보세요.","en":"Write down what would remain if your app's core interaction had only three inputs, then build a prototype screen that works with just those."},{"ko":"내 앱 첫 실행에서 설명 화면 하나를 지워, 사용자가 몇 초 안에 무언가를 해낼 수 있게 해 보세요.","en":"Remove one explanation screen from your app's first run so users accomplish something within seconds."}],"ask":{"ko":"입력이 세 개뿐인데도 실력이 늘고 있다고 느낀 순간은 언제였나요?","en":"When did you feel yourself getting better even with only three inputs?"}},"Arknights: Endfield":{"time":30,"setup":{"ko":"무료지만 가챠 과금이 있어요. 헤드폰이 있으면 공간 음향을 느낄 수 있어요.","en":"Free to play with gacha monetization. Headphones let you hear the Spatial Audio."},"missions":[{"ko":"첫 실행부터 첫 전투까지 따라가 보세요. 산업 SF 분위기와 넓은 환경이 첫 장면부터 어떻게 드러나는지 보세요.","en":"Follow the game from first launch to the first fight. See how the industrial sci-fi look and large environments show themselves from the start."},{"ko":"분대 실시간 전투를 해 보세요. 3D 전투 조작이 터치에 얼마나 맞는지, 지면 어떻게 다시 시작하게 하는지 확인해 보세요.","en":"Play a real-time squad fight. Check how well the 3D combat controls suit touch and how the game gets you back in after a loss."},{"ko":"공장 자동화(AIC) 단계에 들어가 시설을 몇 개 배치해 보세요. PC급 공장 화면이 작은 화면에서 어떻게 정리되는지 관찰해 보세요.","en":"Reach the factory automation (AIC) layer and place a few facilities. Observe how a PC-class factory interface is organized on a small screen."},{"ko":"공장이 돌아가는 상태에서 캐릭터와 주변을 가까이 들여다보세요. 지원 기기라면 레이 트레이싱 반사와 그림자가 어디서 보이는지 찾아보세요.","en":"With the factory running, look closely at characters and surroundings. On a supported device, find where ray-traced reflections and shadows show."}],"make":[{"ko":"내 앱에서 정보가 가장 빽빽한 화면 하나를 골라 iPhone 크기에서 접거나 숨길 부분을 정하고 다시 배치해 보세요.","en":"Pick your app's densest screen and decide what to collapse or hide at iPhone size, then rearrange it."},{"ko":"내 앱의 다음 3개월 업데이트를 이벤트 중심으로 짜서, 언제 사용자가 돌아올 이유가 생기는지 달력에 표시해 보세요.","en":"Plan your app's next three months of updates around events and mark on a calendar when users get a reason to come back."}],"ask":{"ko":"전투와 공장 중 어느 쪽이 모바일에 더 잘 맞았나요?","en":"Which fit mobile better, the combat or the factory building?"}},"Train Fitness":{"time":20,"setup":{"ko":"Apple Watch(또는 AirPods)와 근력 운동을 할 공간이 필요해요. 지금은 Motra라는 이름으로 바뀌었어요.","en":"Needs an Apple Watch (or AirPods) and space for strength training. It has since been rebranded as Motra."},"missions":[{"ko":"처음 실행해서 운동을 시작하기까지 따라가 보세요. 손목 기기만으로 기록한다는 약속을 어떻게 설명하는지 보세요.","en":"Follow first launch up to starting a workout. See how it explains the promise of logging from your wrist alone."},{"ko":"화면을 보지 않고 아는 운동 한 세트를 해 보세요. 끝난 뒤 운동 종류와 반복 횟수가 맞게 기록됐는지 확인해 보세요.","en":"Do one set of an exercise you know without looking at any screen. Afterwards, check whether the exercise and rep count were logged correctly."},{"ko":"다른 운동 두세 가지를 이어서 해 보세요. 인식이 틀렸을 때 고치는 흐름이 얼마나 가벼운지 보세요.","en":"Do two or three other exercises in a row. When recognition gets something wrong, notice how light the correction flow is."},{"ko":"휠체어 운동 모드나 팔다리 차이를 위한 모드를 찾아보세요. 몸이 한 가지 형태라고 가정하지 않는 설계를 관찰해 보세요.","en":"Find the wheelchair or limb-difference modes. Observe a design that does not assume a single body type."}],"make":[{"ko":"내 앱에서 사용자가 직접 입력하는 값 하나를 센서나 기존 데이터로 추정해 기본값으로 채우는 프로토타입을 만들어 보세요.","en":"Prototype pre-filling one value users type in your app with an estimate from sensors or existing data."},{"ko":"VoiceOver를 켜고 화면을 보지 않은 채 내 앱의 핵심 작업 하나를 해 보며 막히는 곳을 적어 보세요.","en":"Turn on VoiceOver and try one core task in your app without looking, noting every place you get stuck."}],"ask":{"ko":"운동 중에 화면을 안 만져도 된다는 게 얼마나 컸나요?","en":"How much did not having to touch a screen matter mid-workout?"}},"Taobao":{"time":15,"setup":{"ko":"수상한 3D 상품 경험은 Apple Vision Pro 버전에서만 할 수 있어요.","en":"The award-winning 3D product experience is only on the Apple Vision Pro version."},"missions":[{"ko":"Vision Pro에서 처음 열고 상품 하나를 3D 모델로 띄워 보세요. 돌려 가며 재질과 마감이 얼마나 실물처럼 보이는지 살펴보세요.","en":"Open it on Vision Pro and bring up one product as a 3D model. Turn it around and see how real the material and finish look."},{"ko":"냉장고 같은 큰 상품을 실제 크기로 거실에 놓아 보세요. 자리에 맞는지 판단하기까지 걸린 시간과 조작 횟수를 세어 보세요.","en":"Place a large item like a refrigerator at real size in your living room. Count the time and steps it takes to decide whether it fits."},{"ko":"여러 상품을 창 여러 개로 나란히 띄워 비교해 보세요. 스펙 표 대신 공간에서 비교할 때 무엇이 쉬워지는지 보세요.","en":"Open several products in separate windows side by side. See what gets easier when you compare in space instead of on a spec sheet."},{"ko":"샤오미 전기차 시승이나 DJI 드론 비행 같은 몰입 체험을 해 보세요. 쇼핑 앱이 보여 주기에서 해 보기로 넘어가는 순간을 느껴 보세요.","en":"Try an immersive experience such as the Xiaomi EV test drive or DJI drone flight. Feel the moment a shopping app moves from showing to letting you try."}],"make":[{"ko":"내 앱에서 크기나 모양이 중요한 대상 하나를 골라, AR Quick Look으로 USDZ 모델을 실제 공간에 띄우는 화면을 만들어 보세요.","en":"Pick one thing in your app where size or shape matters and build a screen that places a USDZ model in the room with AR Quick Look."},{"ko":"내 앱의 비교 화면 하나를 표 대신 대상을 나란히 놓고 직접 보는 방식으로 다시 그려 보세요.","en":"Redraw one comparison screen in your app so items sit side by side to be looked at, instead of in a table."}],"ask":{"ko":"3D로 본 상품은 사진보다 사고 싶었나요, 아니면 확신이 들었나요?","en":"Did seeing the product in 3D make you want it more, or just make you more sure?"}},"Feather: Draw in 3D":{"time":20,"setup":{"ko":"iPad 전용이고 ₩25,000 일회성 유료 앱이에요. Apple Pencil이 필요해요.","en":"iPad only, a one-time purchase at ₩25,000. You need an Apple Pencil."},"missions":[{"ko":"처음 열고 바로 한 획을 그어 보세요. 손가락으로 장면을 돌려 그 선이 3D 공간 어디에 놓였는지 확인해 보세요.","en":"Open the app and draw one stroke right away. Rotate the scene with your fingers and check where that line sits in 3D space."},{"ko":"3D 가이드 면을 먼저 그리고 그 위에 선을 그어 보세요. 꼭짓점이나 돌출 없이도 입체가 생기는 두 단계 방식을 느껴 보세요.","en":"Draw a 3D guide surface first, then draw strokes on it. Feel how the two-step method creates form with no vertices or extrusions."},{"ko":"펜슬로 그리고 손가락으로 회전, 이동, 확대를 번갈아 해 보세요. 펜과 손가락의 역할이 섞이지 않아 생기는 편안함을 관찰해 보세요.","en":"Alternate drawing with the Pencil and orbiting, panning and zooming with your fingers. Notice the ease that comes from never mixing their roles."},{"ko":"구, 원기둥, 원뿔 같은 기본 도형이나 대칭 도구를 찾아 써 보세요. 단순한 화면 뒤에 고급 기능이 어떻게 숨어 있는지 보세요.","en":"Find and use a primitive such as a sphere, cylinder or cone, or the mirror tool. See how advanced features hide behind a minimal interface."},{"ko":"완성한 스케치를 AR 보기로 실제 공간에 띄워 보세요. 화면 속 선이 내 방에 놓일 때 느낌이 어떻게 달라지는지 보세요.","en":"Place your finished sketch in the real world with the AR viewer. Notice how the lines feel different once they sit in your room."}],"make":[{"ko":"PencilKit으로 Apple Pencil은 그리기, 손가락은 화면 이동만 하도록 역할을 나눈 프로토타입을 만들어 보세요.","en":"Build a PencilKit prototype where the Apple Pencil only draws and fingers only move the canvas."},{"ko":"내 앱의 고급 기능 세 가지를 골라 첫 화면에서 숨기고, 필요할 때만 나타나도록 배치를 바꿔 보세요.","en":"Pick three advanced features in your app, hide them from the first screen and make them appear only when needed."}],"ask":{"ko":"3D는 어렵다는 생각이 깨진 순간은 언제였나요?","en":"When did the idea that 3D is hard fall apart for you?"}},"Hello Kitty Island Adventure":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요. 하루 제한이 실시간으로 초기화되니 이틀에 나눠 해 보면 좋아요.","en":"Requires Apple Arcade. Daily limits reset in real time, so try it across two days."},"missions":[{"ko":"게임을 시작해 첫 몇 분 동안 섬을 돌아다녀 보세요. 산리오 캐릭터를 처음 만나는 순간이 어떤 기분으로 연출되는지 보세요.","en":"Start the game and wander the island for the first few minutes. See how meeting a Sanrio character for the first time is staged."},{"ko":"캐릭터 한 명에게 선물을 주고 우정이 쌓이는 피드백을 관찰해 보세요. 그 반응이 내일 다시 오고 싶게 만드는지 느껴 보세요.","en":"Give a character a gift and watch the friendship feedback. Feel whether that reaction makes you want to return tomorrow."},{"ko":"하루 제한에 닿을 때까지 해 보세요. 돈으로 건너뛸 수 없는 기다림이 답답한지 오히려 편안한지 확인해 보세요.","en":"Play until you hit a daily limit. Check whether a wait you cannot pay to skip feels frustrating or oddly relaxing."},{"ko":"낚시, 제작, 퍼즐, 집 꾸미기 중 두 가지를 해 보세요. 각 활동이 어떤 유형의 플레이어를 붙잡을지 생각해 보세요.","en":"Try two of fishing, crafting, puzzles and home decorating. Think about which kind of player each activity would hook."}],"make":[{"ko":"내 앱에 하루에 한 번만 열리는 작은 보상이나 콘텐츠 하나를, 결제로 건너뛸 수 없는 형태로 설계해 화면을 그려 보세요.","en":"Design and draw one small reward or piece of content in your app that unlocks once a day and cannot be skipped by paying."},{"ko":"내 앱의 사용자 유형 세 가지를 적고, 각자가 다시 열 이유가 되는 기능 하나씩을 짝지어 보세요.","en":"Write down three types of users for your app and pair each with one feature that gives them a reason to come back."}],"ask":{"ko":"내일 다시 켜고 싶은 이유가 생겼다면 그것은 무엇이었나요?","en":"If you wanted to come back tomorrow, what was the reason?"}},"SmartGym":{"time":15,"setup":{"ko":"핵심을 느끼려면 Apple Watch가 필요해요. 적응형 트레이너는 7일 체험이 있는 프리미엄 구독 기능이에요.","en":"You need an Apple Watch to feel the core idea. The adaptive trainer is a premium subscription feature with a 7-day trial."},"missions":[{"ko":"처음 실행해서 운동 하나를 고르기까지 따라가 보세요. 애니메이션 동작 시연이 초보자의 망설임을 어떻게 줄여 주는지 보세요.","en":"Follow first launch up to picking an exercise. See how the animated demos reduce a beginner's hesitation."},{"ko":"iPhone을 두고 Apple Watch만 찬 채 한 세트를 기록해 보세요. 휴대폰이나 인터넷 없이도 막히는 곳이 없는지 확인해 보세요.","en":"Leave your iPhone behind and log a set with only your Apple Watch. Check that nothing stalls without the phone or internet."},{"ko":"손목 화면에서 무게와 횟수를 입력해 보세요. 작은 화면에서 몇 번 탭이 필요한지 세어 보세요.","en":"Enter weight and reps on the wrist. Count how many taps it takes on that small screen."},{"ko":"기록을 마친 뒤 AI Smart Trainer가 다음 운동을 어떻게 제안하는지 보세요. 고정 플랜과 달리 내 기록이 반영됐다고 느껴지는지 확인해 보세요.","en":"After logging, see what the AI Smart Trainer suggests next. Check whether it feels shaped by your performance rather than a static plan."}],"make":[{"ko":"내 앱의 핵심 기능 하나를 watchOS 화면 한 장으로 끝나게 설계해 보세요.","en":"Design one core feature of your app so it can be finished on a single watchOS screen."},{"ko":"내 앱에서 사용자의 지난 기록을 보고 다음 기본값을 한 단계 올려 제안하는 로직을 하나 넣어 보세요.","en":"Add logic to your app that looks at the user's last entry and suggests a next default one step higher."}],"ask":{"ko":"손목만으로 운동을 기록할 때 가장 아쉬웠던 점은 무엇이었나요?","en":"What did you miss most when logging a workout from your wrist alone?"}},"How We Feel":{"time":10,"setup":null,"missions":[{"ko":"처음 실행해서 첫 감정 체크인까지 가 보세요. 데이터가 기기에 머문다는 안내가 언제 어떻게 나오는지 보세요.","en":"Go from first launch to your first emotion check-in. See when and how it tells you your data stays on device."},{"ko":"쾌적함과 에너지로 나뉜 색 격자에서 지금 감정을 찾아보세요. 이모지 하나보다 정확한 단어를 고를 때 어떤 기분인지 관찰해 보세요.","en":"Find your current feeling on the color grid of pleasantness and energy. Notice how picking a precise word feels compared with a single emoji."},{"ko":"감정을 고른 뒤 제안되는 짧은 영상 전략 하나를 따라 해 보세요. 알아차림에서 행동으로 넘어가는 연결이 자연스러운지 보세요.","en":"After naming the feeling, follow one of the short video strategies it offers. See whether the step from awareness to action feels natural."},{"ko":"친구와 감정을 나누는 기능을 찾아보세요. 감정 공유를 가벼운 의식처럼 만드는 장치가 무엇인지 살펴보세요.","en":"Find the feature for sharing how you feel with friends. Look at what makes emotional sharing feel like a light ritual."}],"make":[{"ko":"내 앱의 선택지 목록 하나를 두 축 격자로 바꿔, 사용자가 위치로 고르게 하는 프로토타입을 만들어 보세요.","en":"Prototype turning one list of options in your app into a two-axis grid where users choose by position."},{"ko":"내 앱에서 기록을 남긴 직후 바로 해 볼 수 있는 작은 행동 하나를 제안하는 화면을 붙여 보세요.","en":"Add a screen right after logging in your app that suggests one small action to take next."}],"ask":{"ko":"감정에 정확한 이름을 붙인 것만으로 무언가 달라졌나요?","en":"Did giving your feeling a precise name change anything by itself?"}},"Blackbox":{"time":15,"setup":{"ko":"2024년 수상작인 Vision Pro 버전은 $9.99 유료 앱이고, iPhone에서는 원래의 iOS 게임으로 해 볼 수 있어요.","en":"The 2024 award-winning Vision Pro version is a $9.99 paid app; on iPhone you can play the original iOS game."},"missions":[{"ko":"처음 열고 화면을 누르지 않은 채 무엇이 반응하는지 탐색해 보세요. 설명 없이 이 게임의 규칙을 알아채기까지 얼마나 걸리는지 재 보세요.","en":"Open the game and explore what responds without tapping the screen. Time how long it takes to grasp the rule with no explanation."},{"ko":"퍼즐 하나를 골라 밝기를 바꾸거나 볼륨을 올리거나 충전기를 꽂아 보세요. 화면 밖 행동에 화면이 답할 때의 놀라움을 느껴 보세요.","en":"Pick a puzzle and try changing the brightness, raising the volume or plugging in a charger. Feel the surprise when the screen answers something you did off it."},{"ko":"막힌 퍼즐에서 공략을 찾지 말고 기기의 버튼과 센서를 하나씩 떠올리며 시도해 보세요. 어떤 단서가 다음 시도를 이끌었는지 적어 보세요.","en":"On a puzzle that stumps you, skip the walkthrough and try the device's buttons and sensors one by one. Write down which cue led to your next attempt."},{"ko":"Vision Pro가 있다면 레벨 선택용 비눗방울을 건드려 터뜨려 보세요. 공간 구석구석을 둘러보게 만드는 장치를 찾아보세요.","en":"If you have Vision Pro, touch and pop the soap bubbles used for level selection. Look for what pushes you to explore every corner of the space."}],"make":[{"ko":"내 앱에 화면 터치 대신 기기 기울기, 흔들기, 밝기 같은 센서 하나로 실행되는 숨은 동작을 프로토타입으로 만들어 보세요.","en":"Prototype a hidden action in your app triggered by a sensor such as tilt, shake or brightness instead of a screen tap."},{"ko":"내 앱의 튜토리얼 하나를 지우고, 사용자가 스스로 발견하게 할 단서 하나만 화면에 남겨 보세요.","en":"Delete one tutorial from your app and leave a single on-screen cue that lets users discover it themselves."}],"ask":{"ko":"어떻게 한 거지 싶었던 순간에 설명이 없었던 게 더 좋았나요?","en":"In the moments you thought how did they do that, was it better that nothing was explained?"}},"Finding Hannah":{"time":15,"setup":{"ko":"무료로 시작할 수 있고, 전체 게임은 3.99달러 한 번 구입으로 열려요.","en":"Free to start; the full game unlocks with a single $3.99 purchase."},"missions":[{"ko":"첫 장면을 시작해 보세요. 물건 찾기가 시작되기 전에 한나와 가족 이야기가 어떻게 소개되는지, 몇 번째 탭에 처음 무언가를 찾게 되는지 보세요.","en":"Start the first scene. Notice how Hannah and her family are introduced before the search begins, and on which tap you first look for something."},{"ko":"손그림 장면 하나에서 시간 신경 쓰지 말고 물건을 찾아보세요. 재촉하는 장치가 없을 때 내 속도와 눈의 움직임이 어떻게 달라지는지 느껴 보세요.","en":"Search one hand-drawn scene without worrying about time. Feel how your pace and the way your eyes move change when nothing is rushing you."},{"ko":"한나에게 필요한 셀프케어 아이템을 합쳐 보세요. 합친 결과가 새 장면이나 이야기로 어떻게 이어지는지 확인해 보세요.","en":"Merge the self-care items Hannah needs. Check how the result leads into a new scene or the next beat of the story."},{"ko":"이야기를 따라가며 시대가 바뀌는 순간을 찾아보세요. 월세나 일에 대한 불만 같은 어른의 고민이 장면에 어떻게 녹아 있는지 메모해 보세요.","en":"Follow the story until the time period shifts. Note how grown-up worries like rent or job dissatisfaction show up in the scenes."},{"ko":"무료로 할 수 있는 부분이 끝날 때까지 가 보세요. 에너지나 코인 대신 한 번 구입 제안이 어떤 타이밍과 말로 나오는지 보세요.","en":"Play until the free part ends. Notice when and in what words the one-time unlock is offered instead of energy or coins."}],"make":[{"ko":"내 앱의 보상 하나를 골라, 점수 대신 사용자의 이야기나 상황이 한 걸음 나아가는 보상으로 문구와 화면을 다시 써 보세요.","en":"Pick one reward in your app and rewrite its copy and screen so it moves the user's story or situation forward instead of adding points."},{"ko":"내 앱 결제 안내를 한 문장으로 줄여 보세요. 무엇을 얼마에 한 번에 여는지 처음 보는 사람이 5초 안에 말할 수 있는지 확인해 보세요.","en":"Cut your app's purchase pitch to one sentence. Check that a newcomer can say what unlocks, for how much, within five seconds."}],"ask":{"ko":"이 게임이 숨은그림찾기 장르에서 바꾼 것 하나와 그대로 둔 것 하나는 무엇인가요?","en":"What is one thing this game changed about the hidden-object genre, and one thing it kept?"}},"Automatoys":{"time":10,"setup":{"ko":"처음 세 레벨은 무료이고, 전체 게임은 1.99달러 한 번 구입으로 열려요.","en":"The first three levels are free; the full game unlocks with a single $1.99 purchase."},"missions":[{"ko":"첫 레벨에서 동전을 넣고 공을 내보내 보세요. 설명 없이 무엇을 해야 하는지 알아채기까지 몇 초 걸렸는지 세어 보세요.","en":"In the first level, insert a coin and release the ball. Count how many seconds it takes to figure out what to do without instructions."},{"ko":"장치를 탭하고 돌리고 기울여 공을 끝까지 보내 보세요. 소리와 햅틱이 언제 오는지, 손끝에 장난감을 만지는 느낌이 드는지 집중해 보세요.","en":"Tap, turn and tilt the contraptions to get the ball to the end. Focus on when sound and haptics fire and whether it feels like touching a real toy."},{"ko":"일부러 타이밍을 틀려 공을 떨어뜨려 보세요. 실패한 뒤 다시 시도하기까지의 흐름이 짜증스러운지 가벼운지 느껴 보세요.","en":"Miss the timing on purpose and drop the ball. Feel whether getting back to another try is annoying or light."},{"ko":"같은 레벨을 더 빠르게 다시 깨 보세요. 완료 시간에 따른 별 등급이 첫 플레이에서는 얼마나 조용히 뒤에 있었는지 보세요.","en":"Replay the same level faster. Notice how quietly the time-based star ratings stayed in the background during your first run."},{"ko":"레벨 하나를 깬 뒤 내가 쓴 입력 방식이 몇 가지였는지 세어 보세요. 한 사람이 만든 12레벨 게임이 입력을 줄여 완성도를 낸 방식을 보세요.","en":"After clearing a level, count how many kinds of input you used. See how a 12-level game by one person gets its polish by keeping input minimal."}],"make":[{"ko":"내 앱의 주요 버튼 하나에 UIImpactFeedbackGenerator와 짧은 효과음을 붙이고, 붙이기 전과 후를 번갈아 눌러 비교해 보세요.","en":"Add a UIImpactFeedbackGenerator and a short sound to one key button in your app, then tap the before and after versions back to back."},{"ko":"SpriteKit으로 공 하나가 경사로를 굴러가고 탭하면 문이 열리는 한 화면짜리 프로토타입을 만들어, 탭 한 번만으로 퍼즐이 되는지 시험해 보세요.","en":"Build a one-screen SpriteKit prototype where a ball rolls down a ramp and a tap opens a gate, and test whether a single tap can carry a puzzle."}],"ask":{"ko":"이 게임의 어려움은 손놀림과 장치 이해 중 어디에 있었고, 그걸 어떻게 알 수 있었나요?","en":"Was the challenge in dexterity or in understanding the machine, and how could you tell?"}},"Riveo":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사 트레일러나 스크린샷에서 편집 화면이 처음 나오는 장면을 찾아보세요. 폰 화면 안에 영상, 도구, 레이어가 어떤 비율로 나뉘는지 보세요.","en":"Find the first editing screen in the developer's trailer or screenshots. Notice how the phone screen is divided between video, tools and layers."},{"ko":"텍스트, 오버레이, 효과가 겹친 편집 장면에서 영상을 멈춰 보세요. 데스크톱 타임라인을 줄이는 대신 여러 레이어를 어떻게 정리했는지 보세요.","en":"Pause on a shot where text, overlays and effects are stacked. See how layers are organized instead of shrinking a desktop timeline."},{"ko":"키프레임, 마스크, 블렌드 모드, 3D 텍스트 애니메이션이 나오는 순간을 찾아보세요. 이 많은 기능이 손가락 크기에 맞게 어떻게 배치됐는지 보세요.","en":"Look for moments showing keyframes, masks, blend modes and 3D text animation. Notice how so many tools fit finger-sized controls."},{"ko":"지금 쓰는 폰 영상 편집 앱을 열어 텍스트와 효과를 세 겹 이상 쌓아 보세요. 몇 겹째부터 화면이 답답해지는지 Riveo 장면과 비교해 보세요.","en":"Open a phone video editor you use and stack three or more layers of text and effects. Compare when it starts to feel cramped against what Riveo showed."}],"make":[{"ko":"내 앱의 가장 복잡한 편집 화면을 골라, 지금 다루는 대상 하나만 크게 보이고 나머지는 접히는 폰 크기 목업을 그려 보세요.","en":"Take your app's most complex editing screen and sketch a phone-sized mockup where only the item you are working on is large and the rest folds away."},{"ko":"내 앱이 내일 앱스토어에서 내려간다면 사용자가 잃는 것을 세 줄로 적고, 내보내기나 백업 경로가 있는지 확인해 보세요.","en":"Write three lines on what users would lose if your app left the App Store tomorrow, and check whether an export or backup path exists."}],"ask":{"ko":"Riveo가 폰 화면에서 여러 겹의 편집을 다루기 쉽게 만든 방법을 한 문장으로 말한다면요?","en":"In one sentence, how did Riveo make layered editing manageable on a phone screen?"}},"Noted.":{"time":15,"setup":{"ko":"녹음해 볼 팟캐스트나 강의 영상, 또는 잠깐 대화해 줄 사람이 있으면 좋아요.","en":"Have a podcast or lecture to record, or someone to talk with for a few minutes."},"missions":[{"ko":"앱을 처음 열고 첫 녹음을 시작하기까지 몇 번 탭했는지 세어 보세요. 마이크 권한 요청이 어떤 맥락에서 나오는지도 보세요.","en":"Open the app for the first time and count the taps until your first recording starts. Notice the context in which the microphone permission appears."},{"ko":"팟캐스트를 녹음하면서 중요한 순간마다 짧게 메모해 보세요. 끝난 뒤 메모를 탭해 재생이 그 순간으로 바로 넘어갈 때, 받아 적던 손이 얼마나 덜 바빴는지 느껴 보세요.","en":"Record a podcast and jot a short note at key moments. Afterward, tap a note and as playback jumps there, feel how much less your hands had to do."},{"ko":"두 사람 대화를 녹음하며 실시간 전사와 화자 구분을 확인해 보세요. 누가 말했는지 어떻게 표시되는지, 특정 단어를 검색해 찾을 수 있는지 보세요.","en":"Record a two-person conversation with live transcription. See how speakers are labeled and whether you can search for a specific word."},{"ko":"텍스트 크기를 가장 크게 하고 VoiceOver를 켠 채 녹음 하나를 열어 보세요. 레이아웃이 버티는지, 타임스탬프가 어떻게 읽히는지 들어 보세요.","en":"Set text to its largest size, turn on VoiceOver and open a recording. Check whether the layout holds and listen to how timestamps are read."}],"make":[{"ko":"AVPlayer로 오디오 하나와 메모 목록을 붙이고, 메모를 탭하면 그 시간으로 seek하는 프로토타입을 만들어 보세요.","en":"Build a prototype with AVPlayer and a list of notes where tapping a note seeks the audio to that time."},{"ko":"내 앱 화면 하나를 Dynamic Type 가장 큰 접근성 크기로 띄워 스크린샷을 찍고, 잘리거나 겹치는 텍스트를 모두 고쳐 보세요.","en":"Run one screen of your app at the largest accessibility Dynamic Type size, screenshot it, and fix every clipped or overlapping label."}],"ask":{"ko":"메모와 녹음 시간을 묶은 설계가 학습 차이가 있는 학생에게 왜 특히 중요할까요?","en":"Why does tying notes to the recording's timeline matter most for students with learning differences?"}},"Gibbon: Beyond the Trees":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"ko":"스토리 모드를 시작해 첫 1분 동안 화면을 누르고 떼어 보세요. 누르면 매달려 흔들리고 떼면 날아간다는 걸 몸이 언제 이해하는지 보세요.","en":"Start Story mode and spend the first minute pressing and releasing. Notice when your body understands that holding swings and letting go flies."},{"ko":"놓는 타이밍을 바꿔 가며 빈틈을 넘고 백플립을 이어 보세요. 속도가 붙는 순간의 쾌감과 타이밍을 놓쳤을 때 무엇이 끊기는지 느껴 보세요.","en":"Vary your release timing to clear gaps and chain backflips. Feel the rush when speed builds and what breaks when you mistime it."},{"ko":"공중에서 다른 긴팔원숭이를 만나면 함께 움직여 보세요. 혼자 하던 플랫폼 게임이 협력처럼 느껴지는 순간을 찾아보세요.","en":"When you meet another gibbon mid-air, move with it. Find the moment a solo platformer starts to feel like cooperation."},{"ko":"계속 나아가며 배경을 지켜보세요. 정글이 농장과 도시로 바뀌는 지점에서 글 한 줄 없이 스윙의 기분이 어떻게 무거워지는지 느껴 보세요.","en":"Keep going and watch the background. Where the jungle turns into plantations and cities, feel how the swinging gets heavier without a single line of text."},{"ko":"리버레이션 모드나 데일리 런을 한 판 해 보세요. 점수 없는 스토리 모드와 같은 조작이 목표에 따라 얼마나 다르게 느껴지는지 비교해 보세요.","en":"Play one round of Liberation or the Daily Run. Compare how the same controls feel with a goal versus the scoreless Story mode."}],"make":[{"ko":"내 앱의 핵심 동작 하나를 누르기와 떼기 두 입력만으로 표현한 프로토타입을 만들고, 설명 없이 친구가 30초 안에 알아채는지 확인해 보세요.","en":"Prototype your app's core action using only press and release, then see whether a friend gets it within 30 seconds without explanation."},{"ko":"내 앱이 전하고 싶은 메시지 하나를 텍스트 대신 배경색이나 일러스트가 점점 바뀌는 방식으로 보여 주는 화면을 한 장 그려 보세요.","en":"Sketch one screen that conveys your app's message through a gradually changing background or illustration instead of text."}],"ask":{"ko":"스윙의 재미와 서식지 파괴라는 무거운 주제는 서로를 방해했나요, 강화했나요?","en":"Did the joy of swinging and the heavy theme of habitat loss work against each other or strengthen each other?"}},"Behind the Frame":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사 트레일러의 첫 장면을 보세요. 대사 없이 주인공이 화가 지망생이고 제출 마감을 앞뒀다는 사실이 어떻게 전달되는지 보세요.","en":"Watch the opening of the developer's trailer. Notice how, without dialogue, it tells you the hero is an aspiring artist facing a submission deadline."},{"ko":"아파트 창밖 풍경이 나오는 장면들을 이어서 보세요. 같은 시점에서 빛과 분위기가 시간에 따라 어떻게 바뀌는지 비교해 보세요.","en":"Watch the shots of the apartment view one after another. Compare how light and mood shift over time from the same viewpoint."},{"ko":"길 건너 이웃을 지켜보는 장면을 찾아보세요. 말 대신 행동과 사물로 이야기가 쌓이는 방식을 메모해 보세요.","en":"Find the scenes of watching the neighbor across the street. Note how the story builds through actions and objects instead of words."},{"ko":"그림을 완성하는 퍼즐 장면에서 손가락이 무엇을 하는지 상상하며 보세요. 간단한 탭이 어떻게 그림 그리는 기분을 주는지 보세요.","en":"In the painting puzzle shots, imagine what your finger is doing. See how simple taps can feel like painting."}],"make":[{"ko":"내 앱 화면 하나에서 설명 문장을 모두 지우고 아이콘과 일러스트만 남긴 뒤, 같은 뜻이 전해지는지 다른 사람에게 보여 확인해 보세요.","en":"Remove every explanatory sentence from one screen of your app, leave only icons and illustration, and check with someone whether the meaning still comes through."},{"ko":"배경 이미지 하나를 아침, 저녁, 밤 세 가지 색조로 바꾸는 SwiftUI 프로토타입을 만들어, 시간의 흐름을 색만으로 표현해 보세요.","en":"Build a SwiftUI prototype that tints one background for morning, evening and night, expressing the passage of time through color alone."}],"ask":{"ko":"대사 없이 이야기를 전하려면 화면에 무엇이 반드시 있어야 할까요?","en":"What must be on screen to tell a story without dialogue?"}},"Alba: A Wildlife Adventure":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"ko":"게임을 시작해 섬에 도착하는 첫 몇 분을 보세요. 전투나 점수 대신 휴대폰 카메라가 언제 손에 쥐어지는지 보세요.","en":"Start the game and watch the first few minutes on the island. Notice when the phone camera is put in your hands instead of a weapon or score."},{"ko":"처음 만난 동물을 사진으로 찍어 도감에 남겨 보세요. 셔터를 누르고 동물이 식별되기까지의 반응이 관찰 자체를 즐겁게 만드는지 느껴 보세요.","en":"Photograph the first animal you meet and log it. Feel whether the response between pressing the shutter and identification makes observing itself fun."},{"ko":"쓰레기를 줍거나 다리를 고치는 일을 하나 해 보세요. 내 행동 뒤에 섬의 모습이나 마을 사람들 반응이 어떻게 눈에 보이게 바뀌는지 확인해 보세요.","en":"Pick up litter or help repair the bridge. Check how the island or the townspeople visibly change after you act."},{"ko":"아이 주인공의 말을 따라 호텔 개발 이야기를 진행해 보세요. 환경 운동이라는 주제가 어떤 말투로 다가오는지 보세요.","en":"Follow the child hero through the hotel development story. Notice the tone in which environmental activism reaches you."}],"make":[{"ko":"내 앱의 핵심 동작을 완료할 때마다 화면 배경에 작은 요소가 하나씩 늘어나도록, 사용자의 행동이 세계를 바꾸는 흔적을 만들어 보세요.","en":"Make your app's core action leave a trace: each completion adds one small element to the background, so the user's actions change the world."},{"ko":"내 앱 사용이 현실의 무엇과 연결될 수 있는지 한 문장 약속으로 써 보고, 그 약속을 앱 안 어디에 보여 줄지 화면에 배치해 보세요.","en":"Write a one-sentence promise linking use of your app to something real, and place it on the screen where users would see it."}],"ask":{"ko":"사진 찍기라는 동사가 이 게임을 폭력 없이도 재미있게 만든 이유는 무엇인가요?","en":"Why does photography as the core verb make this game fun without violence?"}},"Craft":{"time":15,"setup":null,"missions":[{"ko":"앱을 처음 열고 첫 문서를 만들어 보세요. 빈 화면에서 제목과 첫 문장을 쓰기까지 무엇이 안내되고, 기본 글꼴과 여백이 어떤 인상을 주는지 보세요.","en":"Open the app and create your first document. Notice what guides you to a title and first sentence, and what impression the default typography gives."},{"ko":"문서 안의 블록 하나를 페이지로 바꿔 그 안에 내용을 써 보세요. 폴더 없이 문서 안에 문서가 들어간 구조가 카드 모양 링크로 어떻게 보이는지 보세요.","en":"Turn one block into a page and write inside it. See how a document inside a document, with no folders, appears as a card-style link."},{"ko":"블록을 드래그해 순서를 바꿔 보세요. 손가락을 따라오는 움직임과 놓을 때의 반응이 얼마나 매끄러운지 느껴 보세요.","en":"Drag blocks to reorder them. Feel how smoothly they follow your finger and how they settle when you let go."},{"ko":"만든 문서를 웹 페이지로 공개해 보세요. 링크가 생기기까지 탭 수를 세고, 다른 기기 브라우저에서 열었을 때 모습을 확인해 보세요.","en":"Publish the document as a web page. Count the taps until you have a link, and open it in a browser on another device."},{"ko":"업그레이드 안내가 어디서 나오는지 살펴보세요. 첫 실행이 아니라 블록 수나 저장 공간처럼 사용량과 연결된 순간에 나오는지 보세요.","en":"Look for where upgrade prompts appear. Notice whether they come at first launch or when usage like block count or storage grows."}],"make":[{"ko":"내 앱 목록 항목을 탭하면 같은 형식의 하위 목록이 열리도록, 항목과 페이지를 같은 모델로 다루는 SwiftUI 프로토타입을 만들어 보세요.","en":"Build a SwiftUI prototype where tapping a list item opens a sub-list of the same kind, treating items and pages as one model."},{"ko":"내 앱의 유료 전환 안내를 사용량이 일정 수준을 넘는 순간으로 옮긴다면 기준을 무엇으로 할지 정하고, 그때 띄울 문구를 써 보세요.","en":"If your upgrade prompt appeared only when usage crossed a threshold, decide what that threshold is and write the prompt's copy."}],"ask":{"ko":"모든 것이 블록이라는 원칙이 나에게 준 자유와 혼란은 각각 무엇이었나요?","en":"What freedom and what confusion did the everything-is-a-block principle give you?"}},"Beyond a Steel Sky":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"ko":"게임을 시작해 첫 장면을 보세요. 셀 셰이딩 3D와 만화 같은 텍스트 상자가 화면을 그래픽 노블처럼 만드는 방식을 보세요.","en":"Start the game and watch the opening. See how cel-shaded 3D and comic-style text boxes turn the screen into a graphic novel."},{"ko":"터치로 캐릭터를 움직이고 사물을 조사해 보세요. 포인트 앤 클릭 조작이 손가락에 어떻게 옮겨졌는지, 어디를 눌러야 할지 헷갈린 순간을 세어 보세요.","en":"Move the character and inspect objects by touch. Notice how point-and-click translates to fingers, and count the moments you weren't sure where to tap."},{"ko":"처음 만나는 해킹 퍼즐에서 기계의 논리를 바꿔 보세요. 규칙 하나를 바꿨을 때 세상이 다르게 움직이는 순간의 쾌감을 느껴 보세요.","en":"At the first hacking puzzle, rewire a machine's logic. Feel the payoff when changing one rule makes the world behave differently."},{"ko":"유니언 시티를 돌아다니며 완벽해 보이는 도시의 균열을 하나 찾아보세요. 단서가 대사와 배경 중 어디서 나왔는지 메모해 보세요.","en":"Explore Union City and find one crack in its seemingly perfect surface. Note whether the clue came from dialogue or the environment."}],"make":[{"ko":"내 앱 설정 하나를 조건과 결과를 직접 연결하는 규칙 블록 형태로 바꾼 목업을 만들어, 사용자가 동작을 직접 고치는 느낌을 시험해 보세요.","en":"Mock up one of your app's settings as a rule block that links a condition to a result, and test how it feels to rewire behavior directly."},{"ko":"내 앱 안내 문구 하나를 만화 말풍선 같은 텍스트 상자로 바꿔 보고, 일반 알림창과 나란히 놓아 분위기 차이를 비교해 보세요.","en":"Restyle one in-app message as a comic-style text box and compare its mood side by side with a standard alert."}],"ask":{"ko":"해킹이라는 퍼즐 방식은 고전 포인트 앤 클릭의 어떤 답답함을 줄였나요?","en":"What frustration of classic point-and-click did the hacking mechanic reduce?"}},"StaffPad":{"time":20,"setup":{"ko":"iPad 전용 앱이고 77,000원 한 번 구입이 필요해요. Apple Pencil이 있으면 가장 좋아요.","en":"iPad only, with a one-time ₩77,000 purchase. An Apple Pencil is best."},"missions":[{"ko":"새 악보를 열고 설명을 찾지 말고 오선 위에 음표 하나를 손으로 써 보세요. 손글씨가 정식 악보로 바뀌는 순간까지 얼마나 걸리는지 보세요.","en":"Open a new score and, without looking for help, handwrite one note on the staff. Notice how fast your scribble becomes engraved notation."},{"ko":"짧은 멜로디를 몇 마디 쓰고 스타카토나 크레셴도도 손으로 그려 보세요. 팔레트를 찾지 않고 종이에 쓰듯 이어지는 흐름을 느껴 보세요.","en":"Write a few bars and draw a staccato or crescendo by hand. Feel how it flows like pen on paper with no palette to hunt through."},{"ko":"재생을 눌러 오케스트라가 방금 쓴 악보를 연주하게 해 보세요. 쓰고 바로 들을 때 고치고 싶은 곳이 어떻게 생기는지 보세요.","en":"Press play and let the orchestra perform what you just wrote. Notice how hearing it right away makes you want to edit."},{"ko":"펜 압력을 바꿔 가며 지워 보세요. 살짝 누를 때와 세게 누를 때 지워지는 범위가 어떻게 다른지 비교해 보세요.","en":"Erase with different pencil pressure. Compare how much is erased with a light touch versus a firm one."}],"make":[{"ko":"PencilKit 캔버스를 하나 만들고, 동그라미 같은 단순한 손 그림을 감지하면 버튼 동작이 실행되는 프로토타입을 만들어 보세요.","en":"Build a PencilKit canvas prototype that triggers an action when it detects a simple drawn shape such as a circle."},{"ko":"내 앱에서 메뉴를 열어야 하는 입력 하나를 골라, 제스처나 손글씨로 바로 입력한다면 어떤 모양일지 세 가지 스케치해 보세요.","en":"Pick one input in your app that requires opening a menu and sketch three ways it could be entered directly by gesture or handwriting."}],"ask":{"ko":"팔레트 없이 손으로 쓰는 입력이 작곡 속도를 어떻게 바꿨다고 느꼈나요?","en":"How did handwriting without a palette change your speed of composing?"}},"Blinkist":{"time":15,"setup":{"ko":"결제하지 않아도 돼요. 온보딩 끝의 무료 체험 결제 화면을 관찰한 뒤 닫아도 충분해요.","en":"No purchase needed; you can study the free-trial payment screen at the end of onboarding and close it."},"missions":[{"ko":"앱을 처음 열고 온보딩을 끝까지 따라가 보세요. 관심 분야와 목표를 묻는 질문이 몇 개인지, 각 답이 무엇을 약속하는지 세어 보세요.","en":"Open the app and go through onboarding to the end. Count the questions about interests and goals and what each answer promises."},{"ko":"온보딩 마지막의 무료 체험 결제 화면을 자세히 보세요. 앞의 답이 문구에 다시 나오는지, 건너뛰기와 체험 기간 안내가 얼마나 눈에 띄는지 보세요.","en":"Study the free-trial payment screen at the end. See whether your answers reappear in the copy and how visible skipping and trial terms are."},{"ko":"블링크 하나를 골라 텍스트로 읽다가 중간에 오디오로 바꿔 보세요. 같은 위치에서 이어지는지, 15분이라는 길이가 시작을 얼마나 쉽게 하는지 느껴 보세요.","en":"Pick a Blink, read it as text, then switch to audio midway. Check that it resumes in the same spot and feel how the 15-minute length lowers the barrier to start."}],"make":[{"ko":"내 앱 온보딩 질문을 모두 적고, 각 답이 이후 어느 화면에서 쓰이는지 화살표로 연결해 보세요. 연결되지 않는 질문은 지워 보세요.","en":"List every onboarding question in your app and draw an arrow to the screen where each answer is used. Delete the ones with no arrow."},{"ko":"내 앱의 핵심 콘텐츠 하나를 몇 분짜리 단위로 포장할지 정하고, 목록 화면 각 항목에 그 시간을 표시한 버전을 만들어 보세요.","en":"Decide how many minutes one unit of your app's core content should take, and show that duration on each item in a list screen."}],"ask":{"ko":"온보딩 끝이 곧 결제 화면인 구조가 나에게 공정하게 느껴졌나요, 그 이유는요?","en":"Did ending onboarding on the payment screen feel fair to you, and why?"}},"Widgetsmith":{"time":15,"setup":null,"missions":[{"ko":"앱을 처음 열고 위젯 하나를 만들어 보세요. 소, 중, 대 크기 중 무엇부터 고르게 하는지, 디자인 지식 없이도 글꼴과 색을 정할 수 있는지 보세요.","en":"Open the app and make your first widget. Notice which size you are asked to pick first and whether you can choose fonts and colors without design knowledge."},{"ko":"만든 위젯을 실제 홈 화면에 올려 보세요. 앱 안 미리보기와 홈 화면 실제 모습이 얼마나 같은지 비교해 보세요.","en":"Put the widget on your real Home Screen. Compare how closely the in-app preview matches what you see there."},{"ko":"시간대마다 다른 위젯이 보이도록 일정을 짜 보세요. 정해 둔 시간이 지나 홈 화면 위젯이 바뀌는 순간을 직접 확인해 보세요.","en":"Schedule different widgets for different times of day. Check the moment your Home Screen widget switches after the set time."}],"make":[{"ko":"내 앱 위젯을 작은 크기에서 꼭 남길 정보 하나만 남기고 나머지를 지운 WidgetKit 미리보기로 만들어 보세요.","en":"Make a WidgetKit preview of your app's small widget that keeps only the one piece of information that must stay."},{"ko":"TimelineProvider로 오전과 오후에 다른 내용을 보여 주는 위젯 프로토타입을 만들어 보세요.","en":"Build a widget prototype with a TimelineProvider that shows different content in the morning and afternoon."}],"ask":{"ko":"시스템 신기능 하나에 집중한 앱이 그렇게 빨리 퍼진 이유를 한 문장으로 말한다면요?","en":"In one sentence, why did an app focused on a single new system feature spread so fast?"}},"Shazam":{"time":5,"setup":{"ko":"주변에서 음악이 나오고 있어야 해요.","en":"You need music playing nearby."},"missions":[{"ko":"음악을 틀어 놓고 앱을 연 뒤 곡이 인식될 때까지 탭 수를 세어 보세요. 버튼이 파동처럼 퍼지는 대기 애니메이션이 몇 초의 기다림을 어떻게 바꾸는지 보세요.","en":"Play music, open the app and count taps until the song is recognized. Notice how the rippling listening animation changes those seconds of waiting."},{"ko":"인식이 성공했을 때와 실패했을 때를 모두 만들어 보세요. 앨범 아트가 펼쳐지는 성공 화면과 다시 시도를 권하는 실패 메시지가 어떻게 다른지 비교해 보세요.","en":"Try to get both a success and a failure. Compare the success screen where album art expands with the short retry message on failure."},{"ko":"앱을 열지 않고 제어 센터에서 음악 인식을 시작해 보세요. 앱 안에서 할 때와 걸린 시간, 손의 움직임을 비교해 보세요.","en":"Start music recognition from Control Center without opening the app. Compare the time and hand movement with doing it in the app."},{"ko":"액션 버튼이 있는 iPhone이라면 액션 버튼으로도 인식해 보세요. 화면을 보지 않고 곡을 찾을 수 있는지 느껴 보세요.","en":"If your iPhone has an Action button, use it to recognize a song. Feel whether you can do it without looking at the screen."}],"make":[{"ko":"내 앱에서 가장 자주 쓰는 동작 하나를 App Intents로 만들어 단축어나 제어 센터에서 앱을 열지 않고 실행되게 해 보세요.","en":"Expose your app's most frequent action as an App Intent so it runs from Shortcuts or Control Center without opening the app."},{"ko":"내 앱의 기다리는 상태 하나에 대기, 성공, 실패 세 가지 화면을 따로 디자인해 SwiftUI로 전환해 보세요.","en":"Design separate waiting, success and failure states for one loading moment in your app and switch between them in SwiftUI."}],"ask":{"ko":"앱 밖의 진입점이 많아질수록 앱 첫 화면은 어떻게 달라져야 할까요?","en":"As entry points outside the app multiply, how should the app's first screen change?"}},"Photomator":{"time":10,"setup":{"ko":"어둡게 찍혀 노이즈가 많은 사진이나 해상도가 낮은 사진이 보관함에 있으면 좋아요.","en":"Have a noisy low-light photo or a low-resolution photo in your library."},"missions":[{"ko":"앱을 처음 열어 보세요. 가져오기 없이 사진 보관함이 바로 보이는지, 사진 하나를 편집하기까지 몇 번 탭하는지 세어 보세요.","en":"Open the app for the first time. See whether your photo library appears with no import step, and count taps until you are editing a photo."},{"ko":"노이즈 많은 사진에 Denoise를 적용해 보세요. 복잡한 설정 없이 버튼 하나로 끝나는지, 처리 중 진행 상태가 어떻게 보이는지 보세요.","en":"Apply Denoise to a noisy photo. Notice whether one button is all it takes and how progress is shown while it works."},{"ko":"작은 사진에 Super Resolution을 적용하고 확대해 전후를 비교해 보세요. 결과를 되돌릴 수 있다는 사실이 시도를 얼마나 편하게 만드는지 느껴 보세요.","en":"Apply Super Resolution to a small photo and zoom in to compare. Feel how knowing you can undo makes trying it easier."},{"ko":"편집을 마치고 기본 사진 앱을 열어 보세요. 내보내기 없이 결과가 이미 반영돼 있는지 확인해 보세요.","en":"Finish editing and open the Photos app. Check whether the result is already there without exporting."}],"make":[{"ko":"내 앱에서 설정이 많은 기능 하나를 골라, 기본값으로 바로 실행되는 버튼 하나와 고급 설정 링크로 나눈 화면을 그려 보세요.","en":"Pick a settings-heavy feature in your app and sketch a screen split into one run-with-defaults button and an advanced-options link."},{"ko":"시간이 걸리는 작업 하나에 진행 표시와 전후 비교, 되돌리기를 붙인 SwiftUI 프로토타입을 만들어 보세요.","en":"Build a SwiftUI prototype that adds a progress indicator, before-and-after comparison and undo to one slow operation."}],"ask":{"ko":"강력한 기술을 버튼 하나 뒤에 숨길 때 사용자가 잃는 것은 무엇일까요?","en":"What does a user lose when powerful technology is hidden behind a single button?"}},"토스":{"time":10,"setup":{"ko":"실제 송금 흐름을 보려면 본인 계좌가 연결돼 있어야 해요. 소액으로 해 보세요.","en":"To see the real transfer flow you need your own account linked; try it with a small amount."},"missions":[{"ko":"앱을 열고 송금을 시작해 받는 사람, 금액, 확인까지 화면이 몇 번 바뀌는지 세어 보세요.","en":"Open the app, start a transfer and count how many screens it takes from recipient to amount to confirmation."},{"ko":"각 화면에서 묻는 질문이 몇 개인지 보세요. 한 화면에 한 가지만 물을 때 한 번에 내려야 하는 결정이 얼마나 가벼워지는지 느껴 보세요.","en":"Count the questions on each screen. Feel how much lighter each decision becomes when a screen asks only one thing."},{"ko":"가족이나 친구에게 소액을 보내 끝까지 완료해 보세요. 버튼과 안내 문구가 딱딱한 금융 용어 대신 어떤 말투로 쓰였는지 메모해 보세요.","en":"Send a small amount to family or a friend all the way through. Note the tone of the buttons and copy compared with stiff banking language."},{"ko":"평소 쓰는 은행 앱으로 같은 송금을 해 보세요. 인증 단계와 화면 수를 토스와 나란히 비교해 보세요.","en":"Make the same transfer in your usual bank app. Compare the authentication steps and screen count side by side with Toss."}],"make":[{"ko":"내 앱의 입력 폼 하나를 한 화면 한 질문으로 쪼갠 프로토타입을 NavigationStack으로 만들어, 원래 폼과 완료 시간을 비교해 보세요.","en":"Split one of your app's forms into one question per screen with NavigationStack, and compare completion time with the original."},{"ko":"내 앱의 확인 대화상자 문구 다섯 개를 골라, 딱딱한 표현을 대화체로 바꿔 다시 써 보세요.","en":"Pick five confirmation messages in your app and rewrite the stiff phrasing in a conversational tone."}],"ask":{"ko":"한 화면 한 질문 방식이 오히려 느려지는 경우는 언제일까요?","en":"When might one question per screen actually slow people down?"}},"Metaballs":{"time":15,"setup":{"ko":"원래 앱은 Vision Pro용이에요. iPhone과 iPad에서는 별도의 Metaballs Mobile 판에서 탭과 드래그로 해 볼 수 있어요.","en":"The original is for Vision Pro; on iPhone and iPad, try the separate Metaballs Mobile edition with tap and drag."},"missions":[{"ko":"앱을 처음 열고 첫 도형을 장면에 넣어 보세요. 툴바 없이 무엇을 해야 하는지 어떻게 알게 되는지 보세요.","en":"Open the app and drop your first primitive into the scene. Notice how you know what to do without any toolbar."},{"ko":"도형 두 개를 손으로 잡아 천천히 가까이 가져가 보세요. 둘이 하나의 매끈한 덩어리로 녹아 붙는 순간과 다시 잡아떼는 느낌에 집중해 보세요.","en":"Grab two primitives and slowly bring them together. Focus on the moment they melt into one smooth blob and the feel of pulling them apart."},{"ko":"방 조명을 켜고 끄거나 창가 쪽으로 움직여 보세요. 젤리 같은 재질이 실제 빛 변화에 어떻게 반응하는지 지켜보세요.","en":"Switch the room lights on and off or move toward a window. Watch how the gelatinous material responds to the real change in light."},{"ko":"만든 형태를 USDZ로 내보내는 과정을 찾아보세요. 유료 기능이라면 결제 안내가 어떤 순간에 나오는지 보세요.","en":"Look for how to export your shape as USDZ. If it is a paid feature, notice the moment the purchase prompt appears."}],"make":[{"ko":"RealityKit으로 구 두 개를 놓고 드래그 제스처로 직접 움직이는 프로토타입을 만들어, 툴바 없이 잡는 조작이 어떤지 확인해 보세요.","en":"Build a RealityKit prototype with two spheres moved directly by drag gestures, and see how grabbing without a toolbar feels."},{"ko":"내 앱 편집 화면에서 툴바 버튼 하나를 없애고 그 동작을 대상에 직접 하는 제스처로 바꾼 버전을 만들어 보세요.","en":"Remove one toolbar button from an editing screen in your app and replace it with a gesture performed directly on the object."}],"ask":{"ko":"툴바가 없는데도 무엇을 할 수 있는지 알 수 있었던 이유는 무엇인가요?","en":"With no toolbar, how did you still know what you could do?"}},"NBA: Live Games & Scores":{"time":20,"setup":{"ko":"멀티뷰와 테이블탑 모드는 Vision Pro에서 해 볼 수 있고, 생중계 경기가 있는 시간이어야 해요.","en":"Multiview and Tabletop mode need Vision Pro and a time when games are live."},"missions":[{"ko":"Vision Pro에서 앱을 처음 열어 보세요. 2D 앱을 옮겨 온 느낌인지, 공간에 맞게 새로 설계된 느낌인지 첫 창의 배치를 보세요.","en":"Open the app on Vision Pro for the first time. Judge from the first window's layout whether it feels ported from 2D or designed for space."},{"ko":"메인 경기 하나를 고르고 좌우에 경기를 더해 다섯 개까지 띄워 보세요. 고개를 돌릴 때 시선과 소리가 어떻게 정리되는지 몸으로 느껴 보세요.","en":"Pick a main game and add games to the left and right until five are running. Feel physically how your gaze and audio stay organized as you turn your head."},{"ko":"테이블탑 모드로 3D 코트를 중계 옆에 놓고 몸을 움직여 다른 각도에서 보세요. 선수 움직임과 영상이 맞는지, 스포일러가 생기지 않는지 확인해 보세요.","en":"Place the Tabletop 3D court next to the broadcast and walk around it. Check that players stay in sync with the video and nothing spoils the play."},{"ko":"박스 스코어 같은 통계 패널을 열어 보세요. 경기를 덮지 않고 옆에 놓이는 방식이 화면 위 오버레이와 어떻게 다른지 비교해 보세요.","en":"Open a stats panel such as the box score. Compare how sitting beside the game differs from an overlay covering it."}],"make":[{"ko":"내 앱에서 콘텐츠를 덮는 오버레이 하나를 찾아, 옆에 나란히 놓이는 패널로 바꾼 iPad 레이아웃을 만들어 보세요.","en":"Find one overlay in your app that covers content and rebuild it as a side-by-side panel in an iPad layout."},{"ko":"visionOS 시뮬레이터에서 메인 창 하나와 보조 창 두 개를 띄우는 SwiftUI 프로토타입을 만들어, 창 크기와 거리 비율을 바꿔 보세요.","en":"Build a SwiftUI prototype in the visionOS simulator with one main window and two side windows, and experiment with their size and distance."}],"ask":{"ko":"3D 코트와 중계 영상을 맞추는 일이 왜 핵심 설계 문제였는지 직접 써 본 뒤 설명할 수 있나요?","en":"After using it, can you explain why syncing the 3D court with the live video was a core design problem?"}},"Primary: News in Depth":{"time":15,"setup":{"ko":"Vision Pro 전용 앱이에요. 무료이고 구독이나 인앱 구입이 없어요.","en":"Vision Pro only. It is free, with no subscriptions or in-app purchases."},"missions":[{"ko":"앱을 처음 열고 첫 이야기를 고르기 전까지 화면에 보이는 요소를 세어 보세요. 메뉴나 장식보다 이야기가 공간을 채우는 방식을 보세요.","en":"Open the app and count the elements you see before choosing your first story. Notice how the story, not chrome, fills the space."},{"ko":"공간 비디오 이야기 하나를 끝까지 보세요. 현장 기자가 iPhone으로 찍은 장면 속에 서 있는 듯한 느낌이 언제 가장 강한지 느껴 보세요.","en":"Watch one spatial video story to the end. Feel when the sense of standing inside a correspondent's iPhone footage is strongest."},{"ko":"보는 동안 내레이션이 무엇을 말하는지 들어 보세요. 헤드라인이 한 사람의 이야기로 좁혀지는 순간을 메모해 보세요.","en":"Listen to what the voice-over says as you watch. Note the moment a headline narrows into one person's story."},{"ko":"AI 없이 현장에서 촬영하고 검증한다는 약속이 앱 안 어디에, 어떤 말로 드러나는지 찾아보세요.","en":"Find where and in what words the promise of no AI and on-the-ground verification appears in the app."}],"make":[{"ko":"내 앱 화면 하나에서 콘텐츠가 아닌 요소를 하나씩 숨겨 보며, 어디까지 지워도 여전히 쓸 수 있는지 확인해 보세요.","en":"On one screen of your app, hide non-content elements one by one and find how far you can go while it stays usable."},{"ko":"내 앱의 신뢰 약속을 한 문장으로 쓰고, 그 문장이 사용자 눈에 처음 닿는 위치를 정해 화면에 넣어 보세요.","en":"Write your app's trust promise in one sentence and place it where users will first see it."}],"ask":{"ko":"절제된 UI가 뉴스 내용을 더 믿게 만들었나요?","en":"Did the restrained UI make you trust the reporting more?"}},"SILT":{"time":15,"setup":{"ko":"무료로 일부를 해 보고, 전체 게임은 한 번 구입으로 열려요.","en":"Free to play a portion; the full game unlocks with a one-time purchase."},"missions":[{"ko":"게임을 시작해 첫 1분을 보내 보세요. HUD도 설명도 없는 화면에서 무엇을 해야 할지 어떤 단서로 알게 되는지 보세요.","en":"Start the game and spend the first minute. Notice which cues tell you what to do on a screen with no HUD and no instructions."},{"ko":"처음 만나는 바다 생물에 빙의해 보세요. 생물마다 할 수 있는 일이 다르다는 걸 깨닫는 순간과 그때의 피드백을 보세요.","en":"Possess the first sea creature you meet. Notice the moment you realize each creature can do different things and how the game signals it."},{"ko":"좁은 터널에 들어가거나 넓은 공간이 열리는 곳에서 카메라를 지켜보세요. 확대와 축소가 긴장감과 규모를 어떻게 전하는지 느껴 보세요.","en":"Watch the camera as you squeeze through a tunnel or reach an open space. Feel how zooming in and out conveys tension and scale."},{"ko":"막혀서 실패하면 다시 시도해 보세요. 인벤토리나 힌트 없이 주변 환경에서 답을 다시 찾는 과정이 어떤지 느껴 보세요.","en":"When you get stuck or fail, try again. Feel what it is like to find the answer in the environment with no inventory or hints."},{"ko":"마음에 드는 장면 하나에서 멈춰 보세요. 색 없이 손으로 그린 명암만으로 깊은 바다의 고립감이 어떻게 만들어지는지 보세요.","en":"Stop on a scene you like. Look at how hand-drawn light and shadow alone, with no color, create the isolation of the deep sea."}],"make":[{"ko":"내 앱의 텍스트 안내 하나를 지우고, 색이나 빛, 모양 같은 환경 요소로만 다음 행동을 알려 주는 버전을 만들어 보세요.","en":"Delete one text instruction in your app and make a version that signals the next action only through color, light or shape."},{"ko":"내 앱 주요 화면을 흑백으로 바꿔 스크린샷을 찍고, 명암만으로도 가장 중요한 요소가 먼저 보이는지 확인해 보세요.","en":"Screenshot your app's main screen in grayscale and check whether the most important element still stands out through contrast alone."}],"ask":{"ko":"정보를 모두 환경에 담은 방식에서 길을 잃은 순간이 있었다면, 무엇이 다시 길을 찾게 해 줬나요?","en":"If you got lost with all information folded into the environment, what helped you find your way again?"}},"Art of Fauna":{"time":15,"setup":{"ko":"처음 10개 퍼즐은 무료이고, 나머지는 인앱 구입으로 열려요.","en":"The first 10 puzzles are free; the rest unlock with an in-app purchase."},"missions":[{"ko":"첫 퍼즐을 시작해 보세요. 고전 박물학 삽화 카드가 어떻게 놓이는지, 규칙을 무엇으로 알게 되는지 보세요.","en":"Start the first puzzle. Notice how the vintage natural-history cards are laid out and what teaches you the rules."},{"ko":"카드 앞면 그림을 맞춰 퍼즐 하나를 풀어 보세요. 조각이 맞아 들어갈 때 햅틱이 어떻게 오는지 느껴 보세요.","en":"Solve one puzzle by arranging the pictures on the front of the cards. Feel how the haptics land when pieces fit."},{"ko":"VoiceOver를 켜고 화면을 보지 않은 채 카드 뒷면 글의 순서를 바꿔 퍼즐 하나를 풀어 보세요. 별도 모드 없이 같은 퍼즐이 풀리는 경험을 직접 해 보세요.","en":"Turn on VoiceOver and, without looking, solve a puzzle by reordering the text on the cards' backs. Experience the same puzzle working with no separate mode."},{"ko":"특정 동물을 숨기는 기능과 글꼴, 색상 옵션을 앱 안에서 찾아보세요. 이런 배려가 얼마나 찾기 쉬운 곳에 있는지 보세요.","en":"Find the option to hide specific animals and the font and color settings. Notice how easy these considerate options are to reach."}],"make":[{"ko":"내 앱의 시각 중심 기능 하나를 VoiceOver만으로 끝까지 써 보고, 막히는 곳마다 accessibilityLabel이나 accessibilityAction을 붙여 보세요.","en":"Use one visually driven feature of your app end to end with VoiceOver only, and add accessibilityLabel or accessibilityAction wherever you get stuck."},{"ko":"내 앱의 이미지 하나에 같은 정보를 담은 글 설명을 붙여, 그림과 글 어느 쪽으로도 같은 일을 할 수 있게 만들어 보세요.","en":"Pair one image in your app with a text description carrying the same information, so the task can be done through either."}],"ask":{"ko":"보는 사람과 듣는 사람이 같은 퍼즐을 푸는 설계가 일반 플레이어에게도 준 것은 무엇인가요?","en":"What did designing one puzzle for both sighted and VoiceOver players give to everyone else?"}},"iA Writer":{"time":15,"setup":{"ko":"29,000원 한 번 구입이 필요해요.","en":"Requires a one-time ₩29,000 purchase."},"missions":[{"ko":"앱을 처음 열고 새 문서에 몇 문장을 써 보세요. 파란 커서와 조용한 배경, 글꼴이 쓰는 손에 어떤 느낌을 주는지 보세요.","en":"Open the app and write a few sentences in a new document. Notice how the blue cursor, quiet background and font feel as you type."},{"ko":"포커스 모드를 켜고 한 문단을 이어 써 보세요. 지금 쓰는 문장만 남고 나머지가 흐려질 때 집중이 어떻게 달라지는지 느껴 보세요.","en":"Turn on Focus Mode and keep writing a paragraph. Feel how your concentration changes when everything but the current sentence dims."},{"ko":"오른쪽으로 쓸어 라이브러리로, 왼쪽으로 쓸어 미리보기로 가 보세요. 버튼 없이 제스처만으로 오가는 속도를 느껴 보세요.","en":"Swipe right to the library and left to the preview. Feel the speed of moving with gestures alone, no buttons."},{"ko":"키보드 위 추가 줄로 제목이나 강조 같은 마크다운 기호를 넣어 보세요. 엄지가 닿는 범위에 무엇이 놓였는지 보세요.","en":"Use the extra keyboard row to insert Markdown such as a heading or emphasis. Notice what has been placed within thumb reach."},{"ko":"AI 도구에서 만든 문장을 붙여 넣어 보세요. Authorship 표시가 내가 쓴 글과 붙여 넣은 글을 어떻게 구분해 보여 주는지 보세요.","en":"Paste in text from an AI tool. See how the Authorship feature visually separates it from what you wrote yourself."}],"make":[{"ko":"내 앱의 텍스트 입력 화면에 SwiftUI 키보드 툴바로 자주 쓰는 동작 세 개를 넣고, 손이 덜 움직이는지 비교해 보세요.","en":"Add a SwiftUI keyboard toolbar with your three most-used actions to a text input screen, and compare how much less your hand moves."},{"ko":"내 앱에서 버튼으로 이동하는 화면 하나를 좌우 스와이프로도 오갈 수 있게 만들고, 버튼을 지워도 되는지 시험해 보세요.","en":"Let one button-driven navigation in your app also work with left and right swipes, and test whether the button can go."}],"ask":{"ko":"포커스 모드는 기능을 더한 것인가요, 뺀 것인가요?","en":"Is Focus Mode a feature that adds something or one that takes something away?"}},"Vocabulary – Learn words daily":{"time":10,"setup":null,"missions":[{"ko":"앱을 처음 열어 첫 단어 카드가 나오기까지 어떤 선택을 하게 되는지 보세요. 공부보다 하루의 작은 의식처럼 느껴지는지 첫인상을 적어 보세요.","en":"Open the app and notice what choices you make before the first word card appears. Write down whether it feels like study or a small daily ritual."},{"ko":"단어 카드를 몇 장 넘겨 보세요. 넘길 때마다 오는 은은한 햅틱과 한 화면에 단어 하나만 있는 리듬을 느껴 보세요.","en":"Swipe through a few cards. Feel the subtle haptic on each swipe and the rhythm of one word per screen."},{"ko":"카드 하나에서 정의, 예문, 어원이 어떤 순서와 크기로 놓였는지 보세요. 타이포그래피와 일러스트가 정보량을 어떻게 가볍게 만드는지 보세요.","en":"On one card, look at the order and size of the definition, example and etymology. See how typography and illustration make the content feel light."},{"ko":"테마를 바꾸고 홈 화면이나 잠금 화면에 단어 위젯을 올려 보세요. 앱 밖에서도 같은 분위기가 이어지는지 확인해 보세요.","en":"Change the theme and add a word widget to your Home or Lock Screen. Check whether the same feel carries outside the app."}],"make":[{"ko":"내 앱의 정보 화면 하나를 한 화면에 한 항목만 보이는 카드로 바꾼 TabView 페이지 프로토타입을 만들어 보세요.","en":"Rebuild one information screen in your app as a paged TabView prototype with a single item per screen."},{"ko":"내 앱 화면 하나의 글꼴 크기 단계를 세 가지로만 줄여 다시 정리하고, 전후 스크린샷을 나란히 비교해 보세요.","en":"Reduce one screen of your app to just three type sizes and compare before and after screenshots side by side."}],"ask":{"ko":"조용히 모든 걸 잘한다는 평가에서 내가 가장 크게 느낀 한 가지는 무엇이었나요?","en":"Of everything it quietly does right, which one did you feel most?"}},"oko":{"time":15,"setup":{"ko":"보행자 신호가 있는 실제 횡단보도에서 써 봐야 해요. 관찰은 제자리에서 하고, 건너는 판단은 직접 하세요.","en":"You need a real crosswalk with a pedestrian signal. Observe from the curb and make your own crossing decisions."},"missions":[{"ko":"앱을 처음 열고 카메라 안내가 시작되기까지 어떤 설명이 나오는지 보세요. VoiceOver를 켠 채 같은 과정을 다시 들어 보세요.","en":"Open the app and notice what explanation comes before the camera guidance starts. Then go through the same steps again with VoiceOver on."},{"ko":"횡단보도 앞에서 iPhone을 세로로 들고 보행 신호를 비춰 보세요. 제자리에서 화면을 보지 않고, 신호가 바뀔 때 진동과 소리 패턴이 어떻게 달라지는지 느껴 보세요.","en":"At a crosswalk, hold the iPhone upright and point it at the signal. From the curb, without looking, feel how the vibration and sound patterns change with the signal."},{"ko":"남은 시간 카운트다운이 나올 때까지 지켜보세요. 서둘러야 한다는 정보가 어떻게 전달되는지 보세요.","en":"Wait for the countdown. Notice how the need to hurry is communicated."},{"ko":"비행기 모드를 켜고 다시 신호를 비춰 보세요. 네트워크 없이도 인식이 그대로 빠른지 확인해 보세요.","en":"Turn on Airplane Mode and point at the signal again. Check that recognition is just as fast without a network."}],"make":[{"ko":"내 앱의 성공, 경고, 실패 상태에 서로 다른 Core Haptics 패턴을 만들고, 화면을 보지 않은 사람이 구분할 수 있는지 시험해 보세요.","en":"Create distinct Core Haptics patterns for success, warning and failure in your app, and test whether someone not looking can tell them apart."},{"ko":"내 앱 기능 목록에서 핵심 과제 하나만 남기고 이번 버전에서 뺄 기능을 적어 보세요. oko가 승차 안내를 거절한 것처럼요.","en":"From your app's feature list, keep only the core task and write down what to cut from this version, the way oko turned down transit boarding help."}],"ask":{"ko":"화면을 보지 않는 사람을 위한 피드백 가운데 보는 사람에게도 더 좋았던 것은 무엇인가요?","en":"Which feedback designed for people who can't see the screen was better for you too?"}},"Wavelength":{"time":20,"setup":{"ko":"2명 이상이 함께해야 해요. 같은 방이든 원격이든 괜찮아요.","en":"You need at least two players, in the same room or remote."},"missions":[{"ko":"앱을 처음 열고 친구를 초대해 첫 게임을 시작해 보세요. 초대부터 첫 라운드까지 몇 단계가 걸리는지 세어 보세요.","en":"Open the app, invite a friend and start your first game. Count the steps from invite to first round."},{"ko":"한 사람이 다이얼을 움직일 때 내 화면의 바늘을 지켜보세요. 바늘이 실시간으로 움직일 때 말이 저절로 터져 나오는지 느껴 보세요.","en":"Watch the needle on your screen while someone else moves the dial. Feel whether the live movement makes you start arguing out loud."},{"ko":"다이얼이 바뀔 때 아바타 반응과 이모지 반응을 써 보세요. 떨어져 있어도 테이블에 둘러앉은 느낌이 나는지 보세요.","en":"Use avatar and emoji reactions as the dial moves. See whether it feels like sitting around a table even when apart."},{"ko":"몇 라운드를 이어서 해 보세요. 중간에 광고가 끼어드는 순간이 있는지, 추가 스펙트럼 팩은 어디서 어떻게 제안되는지 보세요.","en":"Play several rounds in a row. Check whether any ad interrupts, and where and how extra spectrum packs are offered."}],"make":[{"ko":"GroupActivities로 두 기기가 슬라이더 값 하나를 실시간으로 공유하는 프로토타입을 만들어 보세요.","en":"Build a GroupActivities prototype where two devices share a single slider value in real time."},{"ko":"내 앱에서 사용자를 기다리게 하는 광고나 로딩 지점을 모두 적고, 여러 사람이 함께 쓰는 순간에 걸리는 것부터 지울 계획을 세워 보세요.","en":"List every ad or loading point in your app that makes users wait, and plan to remove the ones that hit shared, social moments first."}],"ask":{"ko":"보드게임의 어떤 재미가 화면으로 옮겨졌고, 어떤 것이 사라졌나요?","en":"Which part of the board game's fun made it to the screen, and which was lost?"}},"Ahead: Emotions Coach":{"time":10,"setup":null,"missions":[{"ko":"앱을 처음 열고 온보딩에서 분노, 불안, 미루기 같은 고민 하나를 골라 보세요. 선택 직후 계획이 나를 위해 만들어졌다고 느껴지는지 보세요.","en":"Open the app and pick one struggle such as anger, anxiety or procrastination during onboarding. See whether the plan feels made for you right after."},{"ko":"첫 활동 하나를 끝까지 해 보세요. 실제로 몇 분 걸렸는지 재고, 진행 표시가 어디에 어떻게 보이는지 확인해 보세요.","en":"Complete your first activity. Time how many minutes it really took and check where and how progress is shown."},{"ko":"활동을 마친 뒤 스트릭이나 레벨, 보상이 어떤 말투로 나오는지 보세요. 마음 건강 주제에서 게임식 보상이 가볍게 느껴지는지 부담스러운지 느껴 보세요.","en":"After the activity, notice the tone of the streaks, levels and rewards. Feel whether game-style rewards feel light or heavy for emotional work."},{"ko":"감정 프로필을 열어 보세요. 막연한 자기 이해가 어떤 시각 자료로 바뀌어 있는지 보세요.","en":"Open your emotional profile. See what kind of visual turns vague self-knowledge into something concrete."}],"make":[{"ko":"내 앱의 가장 긴 작업 하나를 5분 이내 단위로 쪼개고, 각 단위 끝에 진행 표시를 넣은 화면을 그려 보세요.","en":"Break your app's longest task into units of five minutes or less and sketch a screen with a progress marker at the end of each."},{"ko":"내 앱 첫 실행에 사용자의 고민을 고르는 질문 하나를 넣고, 답에 따라 첫 화면 제목이 바뀌는 프로토타입을 만들어 보세요.","en":"Add one first-run question where users pick their struggle, and prototype a first screen whose title changes with the answer."}],"ask":{"ko":"감정 훈련을 게임처럼 만든 방식이 오히려 마음을 편하게 했나요?","en":"Did turning emotional training into a game actually put you at ease?"}},"Sky Guide":{"time":20,"setup":{"ko":"별이 보이는 맑은 밤에 야외에서 해 보면 가장 좋아요.","en":"Best done outdoors on a clear night when stars are visible."},"missions":[{"ko":"앱을 처음 열고 바로 기기를 하늘로 들어 보세요. 아무 설정 없이 별과 별자리 이름이 나타나기까지 얼마나 걸리는지 보세요.","en":"Open the app and immediately hold the device up to the sky. Notice how long it takes, with zero setup, for stars and constellations to be named."},{"ko":"기기를 천천히 움직이며 행성이나 위성을 하나 찾아보세요. 화면이 손의 움직임을 얼마나 부드럽게 따라오는지 느껴 보세요.","en":"Move the device slowly and find a planet or satellite. Feel how smoothly the view follows your hand."},{"ko":"AR 모드로 바꿔 카메라 화면 위 별자리 그림을 실제 하늘과 맞춰 보세요. 실제 별과 그림이 얼마나 잘 겹치는지 보세요.","en":"Switch to AR mode and line up the constellation figures with the real sky. See how well the drawings overlay the actual stars."},{"ko":"시간 이동으로 하늘을 과거나 미래로 돌려 보세요. 별이 움직이는 모습과 그 조작이 손에 어떻게 느껴지는지 보세요.","en":"Use time travel to scrub the sky into the past or future. Watch the stars move and notice how the control feels in your hand."},{"ko":"비행기 모드를 켜고 다시 써 보세요. 와이파이나 GPS 없이도 그대로 작동하는지 확인해 보세요.","en":"Turn on Airplane Mode and use it again. Check that it still works without Wi-Fi or GPS."}],"make":[{"ko":"CoreMotion으로 기기 방향에 따라 화면 속 이미지가 움직이는 프로토타입을 만들어, 설정 없이 들기만 하면 반응하는 느낌을 시험해 보세요.","en":"Build a CoreMotion prototype where an image moves with device orientation, and test the feel of something that responds the moment you lift it."},{"ko":"내 앱을 비행기 모드에서 열어 보고, 데이터 없이도 보여 줄 수 있는 최소 화면을 정의해 구현해 보세요.","en":"Open your app in Airplane Mode, then define and build the minimum screen it can show without data."}],"ask":{"ko":"10년 뒤에도 다시 결선에 오를 만큼 이 앱이 지킨 핵심 경험은 무엇이라고 생각하나요?","en":"What core experience did this app keep that earned it a finalist spot again a decade later?"}},"Duolingo":{"time":10,"setup":null,"missions":[{"ko":"앱을 새로 설치해 언어와 목표를 고르고 첫 레슨을 해 보세요. 계정을 만들라는 요청이 레슨 전과 후 중 언제 나오는지 확인해 보세요.","en":"Install fresh, pick a language and goal and do the first lesson. Check whether the account prompt comes before or after the lesson."},{"ko":"레슨에서 정답과 오답을 번갈아 내 보세요. 답마다 나오는 애니메이션, 소리, 햅틱이 어떻게 다른지 느껴 보세요.","en":"Alternate right and wrong answers in a lesson. Feel how the animation, sound and haptics differ for each."},{"ko":"홈의 경로 화면을 보세요. 다음에 할 일이 한눈에 보이는지, 지금 고를 수 있는 선택지가 몇 개인지 세어 보세요.","en":"Look at the path on the home screen. See whether the next step is obvious and count how many choices you have right now."},{"ko":"며칠 이어서 스트릭을 만들고 위젯과 스트릭 동결권이 어디서 소개되는지 찾아보세요. 끊기기 직전 알림이 어떤 말투로 오는지도 보세요.","en":"Build a streak over a few days and find where widgets and streak freezes are introduced. Notice the tone of the notification just before it breaks."}],"make":[{"ko":"내 앱의 회원 가입 요청을 첫 핵심 행동 완료 뒤로 옮긴 흐름도를 그리고, 가입 전에 기기에 저장해 둘 데이터를 적어 보세요.","en":"Draw a flow that moves your sign-up prompt after the first core action, and list the data you would store on device before sign-up."},{"ko":"WidgetKit으로 내 앱의 연속 사용 일수를 보여 주는 작은 위젯을 만들어 보세요.","en":"Build a small WidgetKit widget that shows your app's consecutive-day streak."}],"ask":{"ko":"스트릭이 끊길까 봐 앱을 연다면, 그건 사용자에게 좋은 설계인가요?","en":"If people open the app just to save a streak, is that good design for them?"}},"Kimono Cats":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사 트레일러나 스크린샷에서 첫 다트 게임 장면을 찾아보세요. 위로 한 번 쓸어 던지는 동작이 설명 없이 이해되는지 보세요.","en":"Find the first darts scene in the developer's trailer or screenshots. See whether the single upward swipe to throw makes sense without explanation."},{"ko":"다트, 금붕어 건지기, 수리검 던지기 같은 미니게임을 이어서 보세요. 각 게임이 어떤 손동작 하나에 대응하는지 적어 보세요.","en":"Watch the mini-games such as darts, scooping and shuriken throwing in turn. Write down the single touch motion each one maps to."},{"ko":"마을 꾸미기 장면을 보세요. 미니게임에서 번 코인이 상점과 집, 장식으로 바뀌는 느긋한 장기 목표가 어떻게 보이는지 보세요.","en":"Look at the village-building scenes. See how coins from the mini-games turn into shops, houses and decorations as a relaxed long-term goal."},{"ko":"고양이 두 마리가 함께 나오는 장면을 찾아보세요. 성별 구분 없는 캐릭터와 입맞춤 때 나오는 무지개가 해석을 어떻게 열어 두는지 보세요.","en":"Look for scenes with two cats together. Notice how genderless characters and the rainbow when they kiss leave interpretation open."}],"make":[{"ko":"DragGesture 하나로 위로 쓸면 공이 날아가 목표에 맞는 SwiftUI 프로토타입을 만들어, 한 동작이 주는 손맛을 시험해 보세요.","en":"Build a SwiftUI prototype where one upward DragGesture sends a ball at a target, and test how satisfying a single motion can be."},{"ko":"내 앱의 기능 세 가지를 각각 손동작 하나에 대응시킨 표를 만들고, 동작이 두 개 이상 필요한 기능을 찾아 줄여 보세요.","en":"Make a table mapping three features of your app to a single touch motion each, and simplify any that need more than one."}],"ask":{"ko":"아내와 함께 할 게임을 만든다는 목표가 조작을 어떻게 단순하게 만들었을까요?","en":"How might the goal of making a game to play with his wife have simplified the controls?"}},"Diablo Immortal":{"time":20,"setup":null,"missions":[{"ko":"게임을 시작해 첫 전투까지 가 보세요. 가상 이동 스틱과 스킬 버튼 묶음이 언제 어떻게 소개되는지 보세요.","en":"Start the game and reach the first fight. Notice when and how the virtual stick and the cluster of skill buttons are introduced."},{"ko":"스킬 버튼을 드래그해 방향을 조준하며 써 보세요. 두 엄지로 이동과 조준을 동시에 할 때 손이 편한지 느껴 보세요.","en":"Drag skill buttons to aim them. Feel whether moving and aiming with two thumbs at once is comfortable."},{"ko":"전투 장면을 스크린샷으로 찍어 확대해 보세요. 휴대폰 화면에서 쿼터뷰 그래픽이 얼마나 정교한지 보세요.","en":"Take a screenshot mid-fight and zoom in. See how detailed the isometric visuals are on a phone screen."},{"ko":"짧은 현상금 임무나 던전 하나를 끝내 보세요. 실제로 몇 분이면 한 번의 성취가 끝나는지 재 보세요.","en":"Finish a quick bounty or dungeon. Time how many minutes one unit of accomplishment really takes."},{"ko":"플레이 중 결제 제안이 나오는 순간을 모두 세어 보세요. 훌륭한 조작과 그래픽 위에 어떤 수익 구조가 얹혀 있는지 직접 느껴 보세요.","en":"Count every purchase prompt you see while playing. Feel firsthand what monetization sits on top of the excellent controls and visuals."}],"make":[{"ko":"내 앱의 주요 버튼 세 개를 엄지가 닿는 영역 안에 반원으로 배치한 목업을 만들고, 한 손으로 써 보세요.","en":"Mock up your app's three main buttons in an arc within thumb reach and try using it one-handed."},{"ko":"내 앱에서 결제 제안이 나오는 모든 지점을 적고, 사용자가 불쾌하게 느낄 만한 지점 하나를 지우는 안을 써 보세요.","en":"List every point where your app asks for money and write a plan to remove the one users are most likely to resent."}],"ask":{"ko":"조작과 그래픽이 훌륭한데도 비판받은 이유를 직접 해 본 뒤 한 문장으로 말한다면요?","en":"Having played it, why was a game with great controls and visuals so heavily criticized?"}},"tint.":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"ko":"첫 레벨을 시작해 보세요. 설명 없이 물감을 섞는 규칙을 몇 번 시도 만에 이해하는지 세어 보세요.","en":"Start the first level. Count how many tries it takes to understand the color-mixing rule without explanation."},{"ko":"길을 따라 물감을 섞어 종이접기 조각의 색을 맞춰 보세요. 타이머도 점수도 없을 때 마음이 어떻게 달라지는지 느껴 보세요.","en":"Mix watercolors along the paths to match the origami pieces. Feel how your mind changes with no timer and no score."},{"ko":"색약 모드를 켜고 레벨 하나를 풀어 보세요. 색마다 다른 무늬와 소리만으로 색을 구분할 수 있는지, 가능하면 색을 보지 말고 풀어 보세요.","en":"Turn on the color-blind mode and solve a level. Try to tell colors apart only by their patterns and sounds, without relying on color."},{"ko":"일부러 잘못된 색을 섞어 보세요. 틀렸을 때의 반응이 벌처럼 느껴지는지 다시 해 보고 싶게 하는지 보세요.","en":"Mix the wrong color on purpose. See whether the response feels like a penalty or invites you to try again."}],"make":[{"ko":"내 앱에서 색으로만 구분되는 상태를 찾아, 각 상태에 무늬나 아이콘을 더한 버전을 만들어 보세요.","en":"Find states in your app distinguished only by color and add a pattern or icon to each."},{"ko":"기기의 색상 필터로 내 앱을 흑백으로 띄워 보고, 구분이 안 되는 요소를 찾아 고쳐 보세요.","en":"View your app in grayscale with the device's color filters, then find and fix anything that becomes indistinguishable."}],"ask":{"ko":"색이 전부인 게임을 색 없이 풀어 본 경험은 어땠나요?","en":"What was it like solving a game that is all about color without relying on color?"}},"Transit":{"time":10,"setup":{"ko":"대중교통이 다니는 곳에서 열어야 주변 노선의 실시간 정보를 볼 수 있어요.","en":"Open it somewhere with public transit to see real-time info for nearby lines."},"missions":[{"ko":"앱을 처음 열어 보세요. 검색하지 않고 주변 노선 카드와 출발 시간이 보이기까지 몇 번 탭했는지, 몇 초 걸렸는지 세어 보세요.","en":"Open the app for the first time. Count the taps and seconds until nearby lines and departure times appear without searching."},{"ko":"노선 카드의 색과 크기를 보세요. 큰 카드와 운영사 색이 서둘러 걷는 중에도 한눈에 읽히는지 확인해 보세요.","en":"Look at the size and color of the line cards. Check whether the big cards and agency colors read at a glance while you hurry."},{"ko":"실제로 탈 경로에서 GO 단계별 안내를 시작해 보세요. 내 위치가 다른 승객에게 공유된다는 사실이 어떻게 안내되는지 보세요.","en":"Start GO step-by-step guidance on a route you are actually taking. Notice how it tells you your location is being shared with other riders."},{"ko":"지하나 데이터가 없는 상태에서 시간표와 경로를 열어 보세요. 오프라인일 때 무엇이 보이고 무엇이 빠지는지 보세요.","en":"Open schedules and trip planning underground or without data. Notice what remains and what disappears offline."}],"make":[{"ko":"내 앱 첫 화면을 검색창 대신 사용자의 위치나 시간에 맞는 결과가 바로 보이는 화면으로 바꾼 목업을 만들어 보세요.","en":"Mock up your app's first screen so it shows results based on the user's location or time instead of a search field."},{"ko":"내 앱을 쓰기만 해도 다른 사용자에게 도움이 되는 데이터가 생길 수 있는지 찾아 한 문장으로 적고, 그 사실을 알릴 문구를 써 보세요.","en":"Find data your app could produce just by being used that would help other users, and write the copy that tells them."}],"ask":{"ko":"한 명의 승객이 모두의 실시간 정보를 만든다는 구조를 사용자는 앱 안에서 어떻게 알게 되나요?","en":"How does a rider learn, inside the app, that one person's trip creates real-time data for everyone?"}},"MD Clock":{"time":10,"setup":{"ko":"StandBy를 보려면 충전 중인 iPhone을 가로로 세워 둘 수 있어야 해요.","en":"To see StandBy, have your iPhone charging and propped up in landscape."},"missions":[{"ko":"앱을 처음 열고 시계가 전체 화면으로 뜨기까지의 흐름을 보세요. 이미 해결된 기능을 열자마자 어떤 분위기로 보여 주는지 보세요.","en":"Open the app and watch how it reaches a full-screen clock. Notice what mood it gives a long-solved function from the first moment."},{"ko":"숫자가 바뀌는 순간을 기다려 플립 애니메이션을 가까이서 보세요. 몇 초를 지켜봐도 질리지 않는 정교함이 어디서 오는지 느껴 보세요.","en":"Wait for the digits to change and watch the flip animation up close. Feel where the polish that keeps you watching comes from."},{"ko":"테마를 몇 개 바꿔 보세요. 같은 시계가 책상과 침대 옆처럼 다른 공간에 맞는 물건으로 바뀌는지 보세요.","en":"Switch between a few themes. See how the same clock becomes an object suited to a desk or a nightstand."},{"ko":"타이머나 알람을 시계 화면에 더해 보세요. 기능이 늘어도 화면이 어지럽지 않게 유지되는지 확인해 보세요.","en":"Add a timer or alarm to the clock face. Check whether the screen stays uncluttered as tools are added."},{"ko":"iPhone을 충전기에 꽂고 가로로 세워 StandBy에서 위젯을 보세요. 앱 밖에서도 같은 디자인이 이어지는지 확인해 보세요.","en":"Charge your iPhone in landscape and view the widget in StandBy. Check that the design carries over outside the app."}],"make":[{"ko":"SwiftUI로 시간 표시 하나에 contentTransition(.numericText())를 적용한 프로토타입을 만들어, 숫자 전환만으로 인상이 얼마나 바뀌는지 보세요.","en":"Build a SwiftUI time display with contentTransition(.numericText()) and see how much the digit transition alone changes the impression."},{"ko":"내 앱에서 가장 평범한 화면 하나를 골라 기능은 그대로 두고 테마 두 가지만 만들어 나란히 비교해 보세요.","en":"Pick the plainest screen in your app, leave its function alone, design two themes for it and compare them side by side."}],"ask":{"ko":"이미 해결된 기능도 디자인만으로 다시 쓸 이유가 생긴다고 느꼈나요?","en":"Did design alone give you a reason to use a long-solved function again?"}},"Me: A Kid's Diary by Tinybop":{"time":15,"setup":{"ko":"6,600원 유료 앱이에요. 아이와 함께 해 보면 가장 좋아요.","en":"A paid app at ₩6,600. Best tried together with a child."},"missions":[{"ko":"앱을 처음 열고 나와 가족, 반려동물 아바타를 만들어 보세요. 일기가 나의 세계와 관계에서 시작된다는 느낌이 드는지 보세요.","en":"Open the app and create avatars for yourself, family and a pet. Notice whether the diary feels like it starts from your own world and relationships."},{"ko":"질문 하나에 그림으로 답해 보세요. 빈 페이지 대신 질문이 있을 때 시작이 얼마나 쉬워지는지 느껴 보세요.","en":"Answer one prompt with a drawing. Feel how much easier it is to begin with a question instead of a blank page."},{"ko":"다른 질문에는 음성 녹음이나 사진으로 답해 보세요. 글을 모르는 아이도 혼자 끝까지 할 수 있을지 상상하며 해 보세요.","en":"Answer another prompt with a voice recording or photo. Imagine whether a child who can't read yet could do it alone."},{"ko":"지금까지 만든 것이 모이는 곳을 열어 보세요. 흩어진 기록이 한 아이의 모습으로 어떻게 보이는지, 점수나 공유 버튼이 있는지 보세요.","en":"Open the place where everything you made collects. See how scattered entries become a picture of one child, and whether any score or share push appears."}],"make":[{"ko":"내 앱의 빈 화면 하나를 골라, 사용자가 바로 답할 수 있는 구체적인 질문 문구 다섯 개를 써서 바꿔 보세요.","en":"Pick one empty state in your app and replace it with five concrete prompts a user could answer immediately."},{"ko":"텍스트와 음성 녹음 두 가지로 같은 기록을 남길 수 있는 입력 화면 프로토타입을 만들어 보세요.","en":"Prototype an input screen where the same entry can be made either by typing or by recording voice."}],"ask":{"ko":"질문과 여러 입력 방식 중 어떤 것이 아이의 시작을 더 쉽게 만들었나요?","en":"Which made starting easier for a child, the prompts or the multiple input modes?"}},"Nova":{"time":10,"setup":{"ko":"앱스토어에서 내려간 Mac 전용 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"This Mac-only app has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사 스크린샷에서 메인 창을 보세요. 편집, Git, 원격 파일, 미리보기가 한 창 안에 어떻게 나뉘어 있는지 보세요.","en":"Look at the main window in the developer's screenshots. See how editing, Git, remote files and preview are divided within one window."},{"ko":"Git 커밋과 비교하는 Comparison View 화면을 찾아보세요. 변경 사항이 어떻게 강조되는지 지금 쓰는 편집기와 비교해 보세요.","en":"Find the Comparison View against Git commits. Compare how changes are highlighted with the editor you use now."},{"ko":"확장 마켓플레이스 화면을 찾아보세요. 언어나 테마를 커뮤니티가 채우는 구조가 앱 안에서 어떻게 보이는지 보세요.","en":"Find the extension marketplace screen. Notice how community-built languages and themes are presented in the app."},{"ko":"지금 쓰는 코드 편집기를 열고 활성 상태 보기에서 메모리 사용량을 확인해 보세요. 네이티브로 다시 쓴 이유를 숫자로 떠올려 보세요.","en":"Open the code editor you use and check its memory in Activity Monitor. Use the number to understand why Panic rewrote everything natively."}],"make":[{"ko":"Instruments로 내 앱의 메모리와 에너지 사용을 5분 동안 측정하고, 가장 큰 항목 하나를 줄여 보세요.","en":"Profile your app's memory and energy use with Instruments for five minutes and cut the single biggest item."},{"ko":"내 앱에 가장 많이 들어온 요청 하나를 골라 Vim 모드처럼 정식 기능으로 넣는다면 어떤 화면이 될지 스케치해 보세요.","en":"Take the most requested feature for your app and sketch how it would look shipped as a first-class feature, the way Vim mode was."}],"ask":{"ko":"모두가 Electron으로 갈 때 네이티브로 다시 쓴 선택에서 내 앱에 가져올 교훈은 무엇인가요?","en":"What lesson for your own app do you take from rewriting natively while everyone moved to Electron?"}},"Mission to Mars AR":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사가 공개한 트레일러나 스크린샷으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사 트레일러에서 로버가 거실에 처음 놓이는 장면을 찾아보세요. 1:1 크기가 방 안 가구와 비교해 어떻게 느껴지는지 보세요.","en":"Find the moment in the developer's trailer where the rover first appears in a living room. Notice how its 1:1 scale reads next to the furniture."},{"ko":"공포의 7분 착륙 장면을 보세요. 영상으로 보는 착륙과 방 안을 걸어 다니며 보는 착륙이 어떻게 다를지 상상해 보세요.","en":"Watch the Seven Minutes of Terror landing sequence. Imagine how walking around it in your room would differ from watching a video."},{"ko":"AR 장면의 그림자와 빛을 자세히 보세요. 가상 물체가 실제 바닥과 조명에 어떻게 맞춰졌는지 보세요.","en":"Look closely at the shadows and lighting in the AR shots. See how the virtual objects are matched to the real floor and light."},{"ko":"iPhone에서 AR Quick Look으로 아무 USDZ 모델이나 방에 놓고 그 주위를 걸어 보세요. 크기와 그림자가 실재감을 얼마나 바꾸는지 느껴 보세요.","en":"Place any USDZ model in your room with AR Quick Look on iPhone and walk around it. Feel how scale and shadows change its sense of presence."}],"make":[{"ko":"RealityKit으로 실제 크기의 물체 하나를 바닥에 놓는 프로토타입을 만들고, 그림자를 켤 때와 끌 때 실재감을 비교해 보세요.","en":"Build a RealityKit prototype that places a real-scale object on the floor, and compare its presence with shadows on and off."},{"ko":"내 앱의 설명 영상 하나를 사용자가 주위를 돌며 볼 수 있는 3D 장면으로 바꾼다면 무엇을 보여 줄지 장면 세 개로 스케치해 보세요.","en":"If one explanatory video in your app became a 3D scene users could walk around, sketch three scenes of what it would show."}],"ask":{"ko":"추상적인 주제를 AR로 만들 때 가장 중요한 것은 크기, 빛, 움직임 중 무엇이라고 생각하나요?","en":"When turning an abstract subject into AR, which matters most: scale, light or movement?"}},"Darkroom":{"time":15,"setup":{"ko":"편집해 볼 사진이 사진 보관함에 여러 장 있어야 해요.","en":"Have several photos in your Photos library to edit."},"missions":[{"ko":"앱을 처음 열어 보세요. 가져오기 단계 없이 사진 보관함이 바로 보이는지, 첫 편집까지 몇 번 탭하는지 세어 보세요.","en":"Open the app for the first time. See whether your library appears with no import step and count the taps to your first edit."},{"ko":"사진 하나에 커브와 톤을 조정하며 히스토그램과 클리핑 경고를 지켜보세요. 전문 도구가 손가락 크기로 어떻게 줄어들었는지 느껴 보세요.","en":"Adjust curves and tone on a photo while watching the histogram and clipping warnings. Feel how pro tools were sized for a finger."},{"ko":"편집 기록에서 몇 단계 전으로 되돌렸다가 다시 앞으로 가 보세요. 원본이 안전하다는 확신이 실험을 얼마나 과감하게 만드는지 느껴 보세요.","en":"Step back several edits in history, then forward again. Feel how confidence that the original is safe makes you experiment more boldly."},{"ko":"한 사진의 조정을 복사해 다른 사진 여러 장에 붙여 보세요. 한 번의 촬영 전체를 폰에서 처리하는 속도를 재 보세요.","en":"Copy one photo's adjustments and paste them onto several others. Time how fast you could process a whole shoot on a phone."}],"make":[{"ko":"PhotoKit으로 보관함 사진을 바로 보여 주고 편집 결과를 원본 자리에 저장하는 프로토타입을 만들어, 가져오기 단계를 없애 보세요.","en":"Build a PhotoKit prototype that shows library photos directly and saves edits back in place, removing the import step."},{"ko":"내 앱에서 사용자가 같은 작업을 여러 번 반복하는 곳을 찾아, 설정 복사와 붙여넣기로 한 번에 처리하는 흐름을 그려 보세요.","en":"Find a place in your app where users repeat the same work, and sketch a copy-and-paste-settings flow that does it in one go."}],"ask":{"ko":"가져오기 단계를 없앤 것이 편집 습관을 어떻게 바꿨나요?","en":"How did removing the import step change the way you edit?"}},"Calm":{"time":20,"setup":{"ko":"잠자리에 들기 전에 이어폰이나 스피커와 함께 해 보세요.","en":"Try it at bedtime with earphones or a speaker."},"missions":[{"ko":"앱을 처음 열고 첫 3초를 지켜보세요. 로그인이나 설명보다 먼저 소리와 영상이 무엇을 느끼게 하는지 보세요.","en":"Open the app for the first time and watch the first three seconds. Notice what the sound and visuals make you feel before any login or explanation."},{"ko":"온보딩에서 잠을 더 잘 자고 싶다는 목표를 골라 보세요. 이후 추천 화면과 체험 안내가 그 답에 맞춰 어떻게 바뀌는지 보세요.","en":"Choose the sleep-better goal during onboarding. See how the recommendations and trial offer that follow are shaped by that answer."},{"ko":"Sleep Stories 하나를 고르고 타이머를 맞춘 뒤 불을 끄고 들어 보세요. 잠들기 전 이야기를 듣는다는 루틴이 몸에 어떻게 느껴지는지 보세요.","en":"Pick a Sleep Story, set the timer, turn off the lights and listen. Notice how the routine of a bedtime story feels in your body."},{"ko":"어두운 방에서 화면을 다시 켜 보세요. 밤에 보는 화면의 밝기와 색이 눈을 덜 자극하게 설계됐는지 보세요.","en":"Turn the screen back on in the dark room. Check whether the brightness and colors are designed not to jolt your eyes at night."}],"make":[{"ko":"내 앱 첫 실행의 첫 3초에 로그인 대신 핵심 가치를 감각으로 보여 주는 소리나 애니메이션 하나를 넣은 프로토타입을 만들어 보세요.","en":"Prototype a first launch where the first three seconds show your core value through a sound or animation instead of a login."},{"ko":"내 앱 콘텐츠 하나에 끝나면 저절로 멈추는 타이머를 붙여, 사용자가 화면을 보지 않아도 되는 흐름을 만들어 보세요.","en":"Add an auto-stop timer to one piece of content in your app so users never need to look at the screen to end it."}],"ask":{"ko":"Sleep Stories는 기능인가요, 새로운 습관인가요?","en":"Are Sleep Stories a feature or a new habit?"}},"Uber":{"time":15,"setup":{"ko":"실제로 차를 부르면 요금이 나오니 이동할 일이 있을 때 해 보세요.","en":"Calling a car costs money, so try it when you actually need a ride."},"missions":[{"ko":"앱을 열고 어디로 가는지 묻는 첫 입력부터 호출까지 몇 번 탭했는지 세어 보세요. 최근 장소와 저장 장소가 얼마나 일을 줄여 주는지 보세요.","en":"Open the app and count taps from the where-to field to requesting a ride. Notice how much recent and saved places save you."},{"ko":"배차 뒤 지도 위 차량 움직임과 도착 예정 시간을 지켜보세요. 숫자와 움직임이 기다림의 불안을 얼마나 줄이는지 느껴 보세요.","en":"After a driver is assigned, watch the car move on the map and the ETA. Feel how the number and motion ease the anxiety of waiting."},{"ko":"앱을 닫고 잠금 화면의 Live Activity를 보세요. 앱을 다시 열지 않고도 차량 정보와 번호판을 확인할 수 있는지 보세요.","en":"Close the app and look at the Live Activity on your Lock Screen. Check whether you can see the car details and plate without reopening the app."},{"ko":"Dynamic Island가 있는 iPhone이라면 축소 상태와 길게 눌러 펼친 상태를 비교해 보세요. 각 상태에 무엇이 남고 무엇이 더해지는지 보세요.","en":"On an iPhone with Dynamic Island, compare the compact view with the expanded one. Notice what stays and what is added in each."}],"make":[{"ko":"ActivityKit으로 내 앱의 기다리는 상태 하나를 Live Activity로 만들어, 잠금 화면에 숫자 하나만 크게 보이게 해 보세요.","en":"Turn one waiting state in your app into a Live Activity with ActivityKit, showing a single large number on the Lock Screen."},{"ko":"내 앱에서 사용자가 기다리는 순간을 하나 골라, 남은 시간이나 진행 상황을 보여 주는 화면으로 다시 디자인해 보세요.","en":"Pick one moment where users wait in your app and redesign it to show remaining time or progress."}],"ask":{"ko":"기다리는 동안 내가 가장 자주 확인한 정보는 무엇이었고, 그것은 어디에 있었나요?","en":"What did you check most often while waiting, and where was it shown?"}},"Apple Music":{"time":15,"setup":{"ko":"가사와 Sing 기능을 써 볼 수 있게 가사가 있는 좋아하는 곡 몇 개를 골라 두고, 이어폰을 준비해 두세요.","en":"Pick a few favorite songs that have lyrics so you can try lyrics and Sing, and have earphones ready."},"missions":[{"ko":"앱을 열고 곡 하나를 틀어 하단 미니 플레이어가 나타나는 순간을 보세요. 전체 화면으로 올리기까지 몇 번의 동작이 필요한지 세어 보세요.","en":"Play a song and watch the mini player appear. Count the moves it takes to bring up the full-screen player."},{"ko":"앨범 아트 색이 전혀 다른 곡 두 개를 번갈아 틀어 보세요. 배경 분위기가 바뀌어도 컨트롤이 계속 잘 읽히는지 확인해 보세요.","en":"Alternate between two songs with very different album art. Check that controls stay readable as the background color shifts."},{"ko":"미니 플레이어, 전체 플레이어, 가사, 대기열을 차례로 오가 보세요. 블러의 두께와 시트 전환만으로 지금 어느 층에 있는지 알 수 있는지 보세요.","en":"Move from mini player to full player to lyrics to queue. Notice whether blur thickness and sheet transitions alone tell you which layer you are on."},{"ko":"시간 동기화 가사를 열고 뒤쪽 줄 하나를 탭해 보세요. 가사가 곧 탐색 막대가 되는 순간을 느껴 보세요.","en":"Open synced lyrics and tap a line further down. Feel the moment the lyrics become the scrubber."},{"ko":"Apple Music Sing으로 보컬 볼륨을 줄여 한 소절 따라 불러 보세요. 기존 가사 화면이 어떻게 노래방으로 확장됐는지 보세요.","en":"Use Apple Music Sing to lower the vocals and sing a line. Notice how the lyrics view stretches into karaoke."}],"make":[{"ko":"내 앱의 상세 화면 하나에서 대표 이미지 색을 뽑아 흐린 배경으로 깔고, 위 텍스트 대비가 유지되는지 확인해 보세요.","en":"On one detail screen, pull a color from its main image as a blurred background and check that the text on top keeps its contrast."},{"ko":"내 앱의 시트나 모달이 두 단계 이상 겹치는 곳을 찾아, 층마다 머티리얼 두께를 다르게 줘서 깊이를 구분해 보세요.","en":"Find a spot where sheets or modals stack two deep and give each layer a different material thickness to show depth."},{"ko":"내 앱의 긴 목록 하나에서 항목을 탭하면 해당 위치로 바로 이동하게 해, 내용 자체가 내비게이션이 되게 만들어 보세요.","en":"In one long list, make tapping an item jump straight to that point so the content itself becomes navigation."}],"ask":{"ko":"층이 여러 개였는데도 길을 잃지 않았다면, 무엇이 지금 위치를 알려 줬나요?","en":"If you never got lost across all those layers, what told you where you were?"}},"Draw Things":{"time":20,"setup":{"ko":"기본 생성은 무료지만 모델을 기기에 내려받아야 하니 저장 공간과 Wi-Fi를 확보해 두세요. Mac이나 iPad에서도 해 볼 수 있어요.","en":"Local generation is free, but models download to the device, so free up storage and use Wi-Fi. It also runs on Mac and iPad."},"missions":[{"ko":"처음 열어 프롬프트 입력과 생성 버튼만 보이는 첫 화면을 살펴보세요. 고급 설정이 얼마나 숨겨져 있는지 보세요.","en":"Open the app and look at a first screen with just a prompt field and a generate button. Notice how much of the advanced settings is tucked away."},{"ko":"짧은 문장으로 첫 이미지를 만들어 보세요. 모델을 받고 생성하는 동안 시간과 진행 상황을 어떻게 알려 주는지 지켜보세요.","en":"Make a first image from a short prompt. Watch how it tells you about time and progress while the model downloads and generates."},{"ko":"비행기 모드를 켜고 한 번 더 생성해 보세요. 프롬프트와 결과가 기기 밖으로 나가지 않는다는 걸 몸으로 느껴 보세요.","en":"Turn on Airplane Mode and generate again. Feel that your prompt and result never leave the device."},{"ko":"이번엔 샘플러, 스텝 같은 고급 설정을 펼쳐 하나만 바꿔 보세요. 초보자 화면과 전문가 화면이 어떻게 같은 자리에 공존하는지 보세요.","en":"Now expand the advanced settings and change one, like the sampler or steps. Notice how the beginner and expert views share the same space."},{"ko":"무한 캔버스나 인페인팅으로 이미지 일부를 고쳐 보세요. 단순한 첫 화면 뒤에 기능이 얼마나 깊이 있는지 확인해 보세요.","en":"Fix part of an image with the infinite canvas or inpainting. See how deep the features run behind the simple first screen."}],"make":[{"ko":"내 앱의 설정이 많은 화면 하나를 골라, 꼭 필요한 입력 두 개만 남기고 나머지는 펼쳐 보기 아래로 접어 보세요.","en":"Pick your most crowded settings screen, keep only two essential inputs, and fold the rest under an expandable section."},{"ko":"내 앱에서 서버로 보내는 작업 하나를 골라, 기기 안에서 처리한다면 화면에 어떤 문장으로 그 장점을 알릴지 써 보세요.","en":"Pick one task your app sends to a server and write the line you would show if it ran on device instead."},{"ko":"무료, 계정 기반 무료, 유료로 이어지는 세 단계 요금 구조를 내 앱에 적용하면 각 단계에 무엇을 둘지 표로 나눠 보세요.","en":"Map your app onto a three-step plan of free, free with an account and paid, and list what sits in each tier."}],"ask":{"ko":"고급 설정을 처음 펼친 순간, 기대보다 복잡했나요 아니면 준비된 느낌이었나요?","en":"When you first expanded the advanced settings, did it feel overwhelming or like you were ready for it?"}},"당근":{"time":15,"setup":{"ko":"동네 인증은 GPS로 실제 위치를 확인하니 위치 권한이 필요하고, 집 근처에서 하는 게 좋아요.","en":"Neighborhood verification checks your real location by GPS, so allow location access and do it near home."},"missions":[{"ko":"가입하고 동네 인증을 해 보세요. 실제로 그 동네에 있어야 한다는 제약을 어떤 말로 설득하는지 보세요.","en":"Sign up and verify your neighborhood. Notice how it frames the requirement to be physically there."},{"ko":"판매 글을 훑어보며 물건이 어디까지의 동네에서 올라오는지 확인해 보세요. 거래 반경 제한이 직거래를 어떻게 기본값으로 만드는지 생각해 보세요.","en":"Browse listings and check how far away they come from. Think about how the limited radius makes meeting in person the default."},{"ko":"판매자 몇 명의 매너온도와 후기를 비교해 보세요. 숫자 하나가 처음 보는 사람에 대한 느낌을 어떻게 바꾸는지 관찰해 보세요.","en":"Compare the manner temperature and reviews of a few sellers. Notice how one number changes how you feel about a stranger."},{"ko":"중고거래 말고 동네생활, 알바, 동네 가게, 모임 같은 다른 영역으로 옮겨 다녀 보세요. 동네라는 축 하나로 묶인 구조가 자연스러운지 보세요.","en":"Leave secondhand trading and visit community posts, jobs, local shops or groups. Notice whether one neighborhood axis holds them together naturally."}],"make":[{"ko":"내 앱의 제약 하나(지역, 인원, 시간 등)를 골라, 그것을 단점이 아니라 신뢰의 이유로 설명하는 첫 화면 문구를 써 보세요.","en":"Pick one constraint in your app, like area, group size or time, and write first-screen copy that presents it as a reason to trust."},{"ko":"사용자끼리 만나는 지점 하나에, 거래나 만남이 끝난 뒤 서로 남기는 후기가 지표 하나로 모이는 흐름을 그려 보세요.","en":"For one place where users meet, sketch how mutual reviews after the exchange roll up into a single indicator."},{"ko":"내 앱의 기능들을 하나의 공통 축으로 묶는다면 그 축이 무엇일지 정하고, 그 축으로 탭 구성을 다시 짜 보세요.","en":"Decide what single axis could tie your app's features together and rearrange your tabs around it."}],"ask":{"ko":"동네 인증이라는 제약이 귀찮았나요, 아니면 오히려 안심이 됐나요?","en":"Did the neighborhood check feel like a hassle or a reassurance?"}},"Is This Seat Taken?":{"time":15,"setup":{"ko":"9,900원 유료 게임이고, 광고나 인앱 결제는 없어요.","en":"A paid game at 9,900 won, with no ads or in-app purchases."},"missions":[{"ko":"아무것도 읽지 말고 첫 레벨을 시작해 보세요. 글자 없이 아이콘만으로 규칙을 이해한 순간이 언제였는지 기억해 두세요.","en":"Start the first level without reading anything. Note the exact moment you understood a rule from icons alone."},{"ko":"승객 하나를 일부러 맞지 않는 자리에 끌어다 놓아 보세요. 캐릭터 표정이 어떻게 바뀌며 틀렸다고 알려 주는지 보세요.","en":"Drag a passenger into a seat you know is wrong. Watch how their face tells you it is wrong."},{"ko":"창가를 원하거나 시끄러운 승객을 피하고 싶은 캐릭터를 찾아 만족시켜 보세요. 성공 반응이 실패 반응과 어떻게 다른지 비교해 보세요.","en":"Find a character who wants the window or wants to avoid the noisy one and satisfy them. Compare the success reaction with the failure one."},{"ko":"새로운 장소로 넘어가 보세요. 튜토리얼 없이 익숙한 규칙을 섞어 난이도를 올리는 방식을 관찰해 보세요.","en":"Move on to a new setting. Notice how difficulty rises by recombining familiar rules instead of adding tutorials."}],"make":[{"ko":"내 앱의 안내 문구 하나를 골라 글자 없이 아이콘과 표정만으로 같은 뜻을 전하는 시안을 만들어 보세요.","en":"Pick one instructional line in your app and mock up a version that says the same thing with only an icon and an expression."},{"ko":"드래그 앤 드롭이 있는 화면에서 맞게 놓았을 때와 틀리게 놓았을 때의 반응을 하나씩 다르게 붙여 보세요.","en":"On a drag-and-drop screen, add one distinct reaction for a correct drop and another for a wrong drop."}],"ask":{"ko":"글이 하나도 없었는데 규칙을 이해할 수 있었던 이유는 무엇인가요?","en":"Why could you understand the rules without a single line of text?"}},"D-Day: The Camera Soldier":{"time":30,"setup":{"ko":"Apple Vision Pro 전용이고 6,600원 유료 앱이에요.","en":"Apple Vision Pro only, and a paid app at 6,600 won."},"missions":[{"ko":"시작 부분을 보며 첫 몇 분이 평면 영상인지 입체 영상인지 기억해 두세요. 이야기에 들어가는 문을 어떻게 여는지 보세요.","en":"Watch the opening and note whether the first minutes are flat or spatial. Notice how it opens the door into the story."},{"ko":"원본 상륙 장면이 나오면 가상 카메라 하우징 안에서 보는 느낌에 집중해 보세요. 그의 렌즈로 본다는 연출이 감정을 어떻게 바꾸는지 느껴 보세요.","en":"When the original landing footage plays, focus on watching it from inside the virtual camera housing. Feel how seeing through his lens changes the emotion."},{"ko":"타임캡슐에서 헬멧, 편지, 카메라 3D 스캔을 집어 돌려 보세요. 보기만 할 때와 손에 들 때의 차이를 느껴 보세요.","en":"In a time capsule, pinch to pick up and rotate the scanned helmet, letters and camera. Feel the difference between watching and holding."},{"ko":"기록 영상, 3D 영상, 몰입형 영상, 재구성 장면으로 형식이 바뀌는 순간을 세어 보세요. 각 전환이 이야기의 어느 순간과 맞물리는지 보세요.","en":"Count the switches between archival, 3D, immersive and reconstructed footage. Notice which story moment each switch lines up with."},{"ko":"딸의 내레이션이 기술적인 장면 사이를 어떻게 이어 주는지 들어 보세요.","en":"Listen to how the daughter's narration ties the technical scenes together."}],"make":[{"ko":"내 앱의 콘텐츠 하나를 골라 이야기 단계마다 글, 이미지, 영상 중 무엇이 가장 맞는지 표로 나눠 보세요.","en":"Take one piece of content in your app and map each story beat to text, image or video in a simple table."},{"ko":"사용자가 보기만 하던 물건이나 이미지 하나를 직접 돌리거나 확대할 수 있게 만드는 작은 프로토타입을 만들어 보세요.","en":"Prototype one object or image users only look at so they can rotate or zoom it themselves."}],"ask":{"ko":"가장 강하게 남은 순간은 영상을 볼 때였나요, 물건을 손에 들었을 때였나요?","en":"Was your strongest moment watching the footage or holding an object?"}},"Katha Room":{"time":15,"setup":{"ko":"무료로 받을 수 있지만 구독형 앱이고 무료 체험이 있어요.","en":"Free to download, but it runs on a subscription with a free trial."},"missions":[{"ko":"처음 열고 이야기 목록을 훑어보세요. 글을 못 읽는 아이도 곤드 화풍 그림만으로 이야기를 구분할 수 있을지 판단해 보세요.","en":"Open the app and scan the story list. Judge whether a child who cannot read could tell stories apart by the Gond-style artwork alone."},{"ko":"이야기 하나를 틀고 화면을 내려놓아 보세요. 소리만으로 이야기에 빠져드는지 관찰해 보세요.","en":"Play a story and put the screen away. Notice whether the audio alone holds your attention."},{"ko":"같은 이야기를 다른 언어로 바꿔 들어 보세요. 다섯 언어 사이를 오가는 과정이 얼마나 간단한지 보세요.","en":"Switch a story to another of its five languages. Notice how simple it is to move between them."},{"ko":"잠자리 타이머를 맞춰 보세요. 어두운 방에서 부모가 한 손으로 할 수 있는 동작인지 생각해 보세요.","en":"Set the bedtime timer. Ask whether a parent could do it one-handed in a dark room."}],"make":[{"ko":"내 앱의 목록 화면에서 항목마다 고유한 그림이나 색을 붙이고, 글자를 가려도 구분되는지 테스트해 보세요.","en":"Give each item in one of your list screens its own artwork or color, then test whether items stay distinguishable with text hidden."},{"ko":"화면을 보지 않고도 써야 하는 기능 하나를 골라 소리와 타이머만으로 끝나는 흐름을 그려 보세요.","en":"Pick one feature that should work without looking and sketch a flow that finishes with only audio and a timer."}],"ask":{"ko":"화면을 보지 않아도 됐던 순간은 언제였고, 그때 무엇이 나를 안내했나요?","en":"When did you not need the screen at all, and what guided you then?"}},"CapWords":{"time":10,"setup":{"ko":"사진으로 찍을 일상 물건 몇 개를 주변에 준비해 두세요.","en":"Have a few everyday objects nearby to photograph."},"missions":[{"ko":"처음 실행해 배울 언어를 고르고 첫 사진을 찍기까지 따라가 보세요. 앱이 언제 카메라를 내미는지 보세요.","en":"Pick a language and follow the path to your first photo. Notice when the app hands you the camera."},{"ko":"컵이나 신발 같은 물건을 찍어 보세요. 배경이 사라지고 오려 낸 스티커가 되는 순간을 천천히 지켜보세요.","en":"Photograph something like a cup or a shoe. Watch slowly as the background vanishes and it becomes a die-cut sticker."},{"ko":"인식을 기다리는 동안 화면을 유심히 보세요. 스피너 대신 어떤 애니메이션이 기다림을 채우는지 확인해 보세요.","en":"Watch closely while it recognizes the object. Note what animation fills the wait instead of a spinner."},{"ko":"완성된 스티커에서 발음을 듣고 모은 스티커들을 다시 열어 보세요. 내 주변으로 만든 단어장이 어떤 느낌인지 느껴 보세요.","en":"Play the pronunciation on the finished sticker, then open your collection. Notice how a word list made from your own surroundings feels."}],"make":[{"ko":"내 앱에서 네트워크를 기다리는 지점 하나를 골라, 스피너를 결과물이 만들어지는 과정처럼 보이는 애니메이션으로 바꿔 보세요.","en":"Pick one network wait in your app and replace the spinner with an animation that looks like the result being made."},{"ko":"내 앱의 핵심 흐름을 캡처, 정리, 확인, 결과처럼 네 단계로 적고 단계마다 사용자가 보는 화면을 하나씩 그려 보세요.","en":"Write your core flow as four steps like capture, clean up, confirm and result, and sketch the one screen the user sees at each."}],"ask":{"ko":"기다리는 시간이 기다림처럼 느껴지지 않았던 이유는 무엇이었나요?","en":"Why did the waiting not feel like waiting?"}},"puffies.":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"ko":"첫 스티커 팩을 열고 하나를 붙여 보세요. 붙는 순간의 햅틱 블롭을 손끝으로 느껴 보세요.","en":"Open your first pack and place a sticker. Feel the haptic blop of placement in your fingertips."},{"ko":"기기를 천천히 기울여 보세요. 스티커 표면의 빛이 어떻게 움직이며 반짝이는 비닐 질감을 만드는지 보세요.","en":"Tilt the device slowly. Watch how light slides across the stickers to sell the glossy vinyl."},{"ko":"일부러 다른 스티커 위에 겹쳐 놓아 보세요. 실패 화면 대신 스티커가 팩 가장자리로 돌아가는 모습을 관찰해 보세요.","en":"Drop a sticker on top of another on purpose. Watch it zip back to the pack edge instead of a failure screen."},{"ko":"접근성 옵션에서 스냅 거리나 손가락 오프셋을 바꾸고 다시 붙여 보세요. 같은 동작이 얼마나 쉬워지는지 비교해 보세요.","en":"Change the snap distance or finger offset in the accessibility options and place again. Compare how much easier the same move gets."}],"make":[{"ko":"내 앱에서 가장 자주 누르는 동작에 햅틱을 붙이고, 세기와 종류를 세 가지로 바꿔 가며 가장 기분 좋은 것을 골라 보세요.","en":"Add a haptic to your app's most frequent tap and try three intensities or styles to find the most satisfying one."},{"ko":"사용자가 자주 실수하는 지점 하나를 골라 오류 메시지 대신 원래 자리로 부드럽게 되돌리는 동작으로 바꿔 보세요.","en":"Pick one spot where users often make mistakes and replace the error message with a gentle return to where things were."},{"ko":"드래그 동작에 스냅 거리 설정을 추가하고, 손이 크거나 떨리는 사람을 가정해 직접 테스트해 보세요.","en":"Add a snap distance setting to a drag interaction and test it as someone with large or unsteady hands."}],"ask":{"ko":"한 번도 실패하지 않았는데도 계속하고 싶었던 이유는 무엇인가요?","en":"Why did you want to keep going even though you could never fail?"}},"Mela – Recipe Manager":{"time":15,"setup":{"ko":"레시피가 실린 블로그 하나와 종이 요리책이 있으면 좋아요.","en":"Have a recipe blog in mind and a printed cookbook nearby."},"missions":[{"ko":"앱 안 브라우저로 레시피 블로그를 열어 보세요. 레시피를 감지해 깔끔한 화면으로 바꿔 주는 순간을 지켜보세요.","en":"Open a recipe blog in the in-app browser. Watch the moment it detects the recipe and shows it in a clean native view."},{"ko":"한 번 탭해 저장해 보세요. 블로그의 군더더기가 사라진 뒤 남은 정보가 어떤 순서로 놓였는지 보세요.","en":"Save it with one tap. Notice what order the remaining information takes once the blog clutter is gone."},{"ko":"저장한 레시피로 Cook Mode를 켜고 한 걸음 물러나 보세요. 큰 글씨와 현재 단계만 밝은 화면이 조리대 거리에서 읽히는지 확인해 보세요.","en":"Start Cook Mode on that recipe and step back. Check whether the large type and the single lit step read from across the counter."},{"ko":"재료를 체크하고 타이머를 켠 뒤 앱을 나가 보세요. 타이머가 Dynamic Island에서 어떻게 이어지는지 보세요.","en":"Check off ingredients, start a timer and leave the app. Watch how the timer carries on in the Dynamic Island."},{"ko":"장보기 목록을 미리 알림 앱에서 열어 보세요. 직접 만들지 않고 시스템 앱을 쓰는 선택의 장점을 생각해 보세요.","en":"Open the grocery list in Reminders. Think about what Mela gains by using a system app instead of building its own."}],"make":[{"ko":"사용자가 화면에서 떨어져 쓰는 상황 하나를 골라, 글씨를 키우고 현재 단계 외에는 흐리게 하는 모드를 프로토타입해 보세요.","en":"Pick a moment when users are away from the screen and prototype a mode with larger type that dims everything but the current step."},{"ko":"내 앱이 직접 만든 목록이나 일정 기능 하나를 Reminders나 Calendar로 넘기면 얻는 것과 잃는 것을 적어 보세요.","en":"List what you would gain and lose by handing one of your own list or schedule features to Reminders or Calendar."}],"ask":{"ko":"블로그 글이 레시피 화면으로 바뀐 순간, 사라져서 가장 반가웠던 것은 무엇인가요?","en":"When the blog turned into a recipe view, what were you happiest to see disappear?"}},"CellWalk":{"time":15,"setup":null,"missions":[{"ko":"처음 열어 세포 전체가 보이는 화면에서 시작해 보세요. 무엇을 만져야 할지 어떻게 알려 주는지 보세요.","en":"Start from the view of a whole cell. Notice how it tells you what to touch first."},{"ko":"핀치로 계속 확대해 세포에서 분자 기계까지 내려가 보세요. 끊김 없는 줌이 크기 감각을 어떻게 만드는지 느껴 보세요.","en":"Keep pinching in from the whole cell down to molecular machines. Feel how the unbroken zoom builds a sense of scale."},{"ko":"구조물을 돌리고 잘라 안을 들여다보세요. 손으로 해부한다는 감각이 설명 글보다 무엇을 더 알려 주는지 생각해 보세요.","en":"Orbit a structure and cut into it. Think about what slicing it yourself teaches that a caption cannot."},{"ko":"색이 선명한 부분과 채도가 빠진 부분을 비교해 보세요. 내 시선이 어디로 끌려가는지 관찰해 보세요.","en":"Compare the vivid parts with the desaturated ones. Notice where your eye is pulled."},{"ko":"요소 하나를 탭해 설명을 열고 Concept Chains도 따라가 보세요. 설명이 내 수준에 맞게 바뀌는지 확인해 보세요.","en":"Tap an element for its explanation and follow a Concept Chain. Check whether the explanation adapts to your level."}],"make":[{"ko":"내 앱의 정보가 많은 화면 하나에서 가장 중요한 요소만 색을 남기고 나머지는 채도를 낮춘 시안을 만들어 보세요.","en":"On one dense screen in your app, keep color only on the most important element and desaturate the rest."},{"ko":"목록에서 상세로 넘어가는 전환 하나를 화면 이동 대신 확대 애니메이션으로 이어지게 바꿔 보세요.","en":"Change one list-to-detail transition so it zooms into the item instead of pushing a new screen."}],"ask":{"ko":"색을 뺀 부분이 오히려 무엇을 더 잘 보이게 했나요?","en":"What did the desaturated areas make easier to see?"}},"Crayola Adventures":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요하고, 아이와 함께 해 보면 더 좋아요.","en":"Requires Apple Arcade, and it is best tried with a child."},"missions":[{"ko":"처음 시작해 캐릭터를 만들어 보세요. 피부색, 능력, 체형, 대명사 선택이 어떤 순서로 나오고 성별을 묻는지 보세요.","en":"Create a character. Notice the order of skin tone, abilities, body type and pronouns, and whether it ever asks for gender."},{"ko":"화면의 글은 읽지 말고 내레이션만 따라 진행해 보세요. 튜토리얼이 끝난 뒤에도 끝까지 들려주는지 확인해 보세요.","en":"Play by following only the narration, without reading. Check that it keeps narrating well past the tutorial."},{"ko":"장식 만들기, 퍼즐, 이야기책을 하나씩 해 보세요. 활동이 바뀔 때마다 부담이 어떻게 달라지는지 보세요.","en":"Try decorating, a puzzle and a storybook in turn. Notice how the pressure changes with each activity."},{"ko":"아이나 다른 사람에게 기기를 건네 혼자 해 보게 하세요. 어디서 도움을 청하는지 지켜보세요.","en":"Hand the device to a child or someone else and let them play alone. Watch where they ask for help."}],"make":[{"ko":"내 앱의 프로필이나 아바타 설정을 열어 이분법적인 선택지를 찾고, 대신 쓸 수 있는 항목을 적어 보세요.","en":"Open your app's profile or avatar setup, find any binary choices, and write the options you could offer instead."},{"ko":"핵심 화면 하나를 글을 못 읽는 사람이 소리만으로 끝낼 수 있도록 안내 문장을 쓰고, 음성 합성으로 읽혀 보세요.","en":"Write spoken guidance so someone who cannot read could finish one key screen by sound alone, and play it through speech synthesis."}],"ask":{"ko":"글을 하나도 읽지 않고 진행하면서 막혔던 순간이 있었나요, 있었다면 무엇 때문이었나요?","en":"Did you get stuck at any point without reading, and if so, why?"}},"Call of Duty: Warzone Mobile":{"time":10,"setup":{"ko":"앱스토어에서 내려가 직접 할 수 없어요. Activision의 공식 트레일러나 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through Activision's own trailers and screenshots."},"missions":[{"ko":"공식 트레일러를 처음부터 보며 첫 장면이 무엇을 약속하는지 적어 보세요. 휴대폰 게임이라는 점을 어떻게 드러내는지 보세요.","en":"Watch an official trailer from the start and write down what the first shot promises. Notice how it signals that this is on a phone."},{"ko":"120명 로비와 Verdansk 맵을 보여 주는 장면을 찾아 보세요. 그 규모가 휴대폰 화면에서 어떻게 읽힐지 상상해 보세요.","en":"Find shots showing the 120-player lobby and Verdansk. Imagine how that scale reads on a phone screen."},{"ko":"터치 조작 화면과 컨트롤러 장면이 나오면 비교해 보세요. 화면 위 버튼이 몇 개인지 세어 보세요.","en":"Compare touch-control footage with controller footage if both appear. Count the on-screen buttons."},{"ko":"콘솔과 진행도가 이어진다는 점을 어떻게 알리는지 찾아보세요.","en":"Look for how it communicates that progress carries over from console and PC."}],"make":[{"ko":"내 앱의 기능 하나를 터치와 하드웨어 키보드나 컨트롤러 두 가지로 쓸 수 있게 할 때 바뀌는 화면 요소를 적어 보세요.","en":"List what changes on screen if one feature in your app works with both touch and a hardware keyboard or controller."},{"ko":"내 앱의 iPhone과 다른 기기 사이에 이어져야 할 진행 상태 하나를 골라 동기화 흐름을 그려 보세요.","en":"Pick one piece of progress that should carry between iPhone and another device and sketch the sync flow."}],"ask":{"ko":"앱스토어에서 사라진 지금, 트레일러가 약속한 것 중 휴대폰에서 정말 가치 있었던 것은 무엇이라고 보나요?","en":"Now that it is gone, which of the trailer's promises do you think truly mattered on a phone?"}},"Cityscapes: Sim Builder":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"ko":"첫 도시를 시작해 도로와 주거지를 놓아 보세요. 터치로 배치하는 감각이 처음부터 손에 붙는지 보세요.","en":"Start your first city and lay down roads and housing. Notice whether touch placement feels natural from the start."},{"ko":"공장과 도로를 늘려 보세요. 오염이 어디서 생기고 화면에 어떻게 드러나는지 관찰해 보세요.","en":"Add industry and more roads. Watch where pollution appears and how the screen shows it."},{"ko":"시민이나 조언자가 문제를 말하면 그 말을 따라가 보세요. 수치표 대신 대화로 문제를 알게 되는 느낌을 비교해 보세요.","en":"When a citizen or advisor raises a problem, follow it. Compare learning about it through conversation versus a stats panel."},{"ko":"거리 때문에 생긴 문제를 교통이나 배치를 바꿔 해결해 보세요. 결과가 다시 대화로 돌아오는지 확인해 보세요.","en":"Fix a distance problem by changing transport or zoning. Check whether the result comes back to you as conversation."}],"make":[{"ko":"내 앱의 통계나 수치 화면 하나를 골라, 그 숫자가 뜻하는 문제를 캐릭터의 한 마디로 바꿔 써 보세요.","en":"Pick one stats screen in your app and rewrite what its numbers mean as a single line spoken by a character."},{"ko":"그 한 마디 옆에 해결 행동 하나를 바로 붙여, 문제 발견에서 행동까지 탭 수를 줄인 시안을 만들어 보세요.","en":"Attach one fix action right next to that line and mock up a flow with fewer taps from spotting the problem to acting on it."}],"ask":{"ko":"재난 없이 오염과 교통만으로 긴장감이 생겼나요, 생겼다면 어느 순간이었나요?","en":"Did pollution and transit alone create tension without disasters, and if so, when?"}},"NBA":{"time":20,"setup":{"ko":"여러 경기 동시 보기와 3D 코트는 Apple Vision Pro에서, 몰입형 환경은 League Pass가 있을 때 볼 수 있어요.","en":"Multiview and the 3D court need Apple Vision Pro, and the immersive environments need League Pass."},"missions":[{"ko":"iPhone에서 앱을 열어 첫 화면에 무엇이 먼저 보이는지 보세요. 실시간 점수와 짧은 영상 중 무엇을 앞세우는지 확인해 보세요.","en":"Open the app on iPhone and see what comes first. Check whether live scores or short clips lead."},{"ko":"Vision Pro에서 멀티뷰로 큰 화면 하나와 주변 경기를 배치해 보세요. 고개만 돌려 경기를 오가는 감각을 느껴 보세요.","en":"On Vision Pro, set up multiview with one big game and others around it. Feel what it is like to switch games by turning your head."},{"ko":"지원되는 경기에서 Court View를 켜고 테이블 위 3D 미니어처 코트를 보세요. 중계 화면과 무엇이 다르게 읽히는지 보세요.","en":"On a supported game, turn on Court View and watch the 3D miniature court on your table. Notice what reads differently from the broadcast."},{"ko":"선수 기록 오버레이나 다른 중계 스트림을 켜 보세요. 같은 경기가 어떻게 다른 시청 방식이 되는지 비교해 보세요.","en":"Turn on live stat overlays or an alternate stream. Compare how the same game becomes a different way of watching."}],"make":[{"ko":"내 앱의 화면 하나를 큰 주 영역과 작은 보조 영역 여러 개로 나눈 배치를 iPad 크기로 스케치해 보세요.","en":"Sketch one of your screens at iPad size as one large main area with several small secondary ones."},{"ko":"같은 데이터를 가볍게 보는 사람용과 깊게 보는 사람용 두 가지 보기로 바꾸는 토글 하나를 만들어 보세요.","en":"Build one toggle that switches the same data between a casual view and a deep view."}],"ask":{"ko":"여러 경기를 동시에 볼 때, 실제로 집중한 화면은 몇 개였나요?","en":"When watching several games at once, how many did you actually pay attention to?"}},"Afterplace":{"time":20,"setup":{"ko":"11,000원 유료 게임이고 광고는 없어요. 컨트롤러가 있으면 함께 준비해 두세요.","en":"A paid game at 11,000 won with no ads. Have a controller ready if you own one."},"missions":[{"ko":"시작하자마자 화면 아무 곳이나 터치해 움직여 보세요. 조작을 익히는 데 몇 초 걸렸는지 세어 보세요.","en":"As soon as it starts, touch anywhere to move. Count how many seconds it takes to learn the controls."},{"ko":"두 엄지로 패드처럼 잡아 보고, 있다면 컨트롤러도 연결해 보세요. 쥐는 방식에 따라 게임이 어떻게 맞춰 주는지 보세요.","en":"Hold it with two thumbs like a gamepad, then connect a controller if you have one. Notice how the game adapts to your grip."},{"ko":"목적지 표시 없이 한 방향으로 무작정 걸어가 보세요. 무엇이 나를 다음 장소로 이끄는지 관찰해 보세요.","en":"With no waypoints, just walk in one direction. Notice what pulls you toward the next place."},{"ko":"만나는 사물이나 캐릭터에게 말을 걸어 보세요. 요즘식 유머가 옛날 픽셀 그래픽과 어떻게 부딪히는지 느껴 보세요.","en":"Talk to the objects and characters you meet. Feel how the modern humor plays against the vintage pixel art."}],"make":[{"ko":"내 앱의 주요 동작 하나를 화면 어디를 눌러도 되도록 터치 영역을 넓힌 프로토타입을 만들어 보세요.","en":"Prototype one main action in your app with its touch target widened to the whole screen."},{"ko":"내 앱의 안내 화살표나 툴팁 하나를 지우고, 없이도 찾을 수 있게 하는 시각 단서 하나를 넣어 보세요.","en":"Remove one guide arrow or tooltip from your app and add a single visual cue that lets people find the way without it."}],"ask":{"ko":"목적지 표시가 없었는데도 길을 잃지 않았다면, 무엇 덕분이었나요?","en":"If you did not get lost without waypoints, what kept you oriented?"}},"Headspace":{"time":15,"setup":{"ko":"조용한 곳과 이어폰을 준비해 두세요.","en":"Find a quiet spot and have earphones ready."},"missions":[{"ko":"처음 열어 목표와 경험 수준 질문에 답해 보세요. 첫 세션이 시작될 때까지 걸린 시간을 재 보세요.","en":"Answer the opening questions about your goals and experience. Time how long it takes to reach your first session."},{"ko":"호흡 운동 하나를 따라 해 보세요. 커졌다 작아지는 애니메이션에 숨을 맞추며 그 속도가 몸에 맞는지 느껴 보세요.","en":"Follow a breathing exercise. Match your breath to the expanding and contracting animation and feel whether the pace fits your body."},{"ko":"운동 중 나오는 안내 문장을 소리 내 읽어 보세요. 문장 길이와 말투가 긴장을 어떻게 낮추는지 보세요.","en":"Read the on-screen copy aloud during the exercise. Notice how its length and tone lower tension."},{"ko":"메인 화면의 일러스트 캐릭터를 살펴보세요. 둥근 모양과 따뜻한 색이 정신 건강이라는 주제를 어떻게 부드럽게 하는지 관찰해 보세요.","en":"Look at the illustrated characters on the main screens. Notice how round shapes and warm colors soften the topic of mental health."}],"make":[{"ko":"내 앱의 로딩이나 대기 애니메이션 하나를 사람의 숨처럼 천천히 커졌다 작아지는 주기로 바꿔 보세요.","en":"Change one loading or waiting animation in your app to grow and shrink slowly like a breath."},{"ko":"내 앱의 오류나 경고 문구 세 개를 짧고 대화하듯 다시 써 보세요.","en":"Rewrite three error or warning messages in your app to be short and conversational."},{"ko":"첫 실행 질문 두 개로 사용자를 서로 다른 첫 화면으로 보내는 분기 흐름을 그려 보세요.","en":"Sketch a first-run flow where two questions send people to different starting screens."}],"ask":{"ko":"앱을 연 뒤 첫 숨을 쉬기까지 걸린 시간이 적당했나요, 무엇을 더 줄일 수 있었을까요?","en":"Was the time from opening the app to your first breath about right, and what could have been cut?"}},"SwingVision: A.I. Tennis App":{"time":30,"setup":{"ko":"테니스 코트와 iPhone이나 iPad를 세울 거치대가 필요하고, Apple Watch가 있으면 점수 조작도 해 볼 수 있어요.","en":"You need a court and a stand for your iPhone or iPad, and an Apple Watch lets you try scoring from the wrist."},"missions":[{"ko":"처음 실행해 녹화를 시작하기까지 무엇을 묻고 안내하는지 따라가 보세요. 코트 옆에서 한 손으로 할 수 있는지 보세요.","en":"Follow what it asks before your first recording. Notice whether you could do it one-handed beside the court."},{"ko":"기기를 세워 두고 랠리를 몇 번 해 보세요. 라켓에 센서 없이 속도와 깊이가 기록되는 걸 확인해 보세요.","en":"Prop the device up and play a few rallies. Check that speed and depth are recorded with no sensor on the racket."},{"ko":"라인 근처 공에 대한 판정을 내 판정과 비교해 보세요. 몇 번 의견이 갈렸는지 세어 보세요.","en":"Compare its calls on balls near the line with your own. Count how often you disagreed."},{"ko":"녹화가 끝나면 자동 하이라이트를 열어 보세요. 긴 영상이 포인트 단위로 어떻게 잘렸는지 보세요.","en":"Open the automatic highlights after recording. See how the long video was cut into points."},{"ko":"Apple Watch로 점수를 기록해 보세요. 경기 중 손목만으로 얼마나 쉽게 되는지 느껴 보세요.","en":"Keep score on Apple Watch. Feel how easy it is from the wrist during play."}],"make":[{"ko":"사용자가 긴 기록을 다시 보지 않는 곳을 찾아, 핵심 순간만 모아 보여 주는 요약 화면을 그려 보세요.","en":"Find a place where users never revisit long records and sketch a summary screen with only the key moments."},{"ko":"내 앱의 입력 하나를 Apple Watch 버튼 하나로 끝낼 수 있게 줄인 화면을 스케치해 보세요.","en":"Sketch a watch screen that reduces one input in your app to a single button."}],"ask":{"ko":"사람 눈과 기계의 판정이 갈렸을 때, 나는 어느 쪽을 믿고 싶었나요?","en":"When your eye and the machine disagreed, which did you want to trust?"}},"(Not Boring) Habits":{"time":10,"setup":null,"missions":[{"ko":"첫 습관을 만들어 보세요. 만들자마자 어떤 풍경이 나타나는지 보세요.","en":"Create your first habit. Notice what landscape appears right away."},{"ko":"체크인을 해 보세요. 햅틱과 소리, 풍경이 앞으로 나아가는 순간을 손끝과 귀로 느껴 보세요.","en":"Check in. Feel the haptic, hear the sound and watch the landscape move forward."},{"ko":"하루 여러 번 하는 습관이나 10/30분처럼 나눠진 목표를 만들어 보세요. 진행 표시가 어떻게 달라지는지 보세요.","en":"Make a habit with several check-ins a day or an incremental goal like 10/30 minutes. See how progress is shown differently."},{"ko":"Grid, Climb, Streak 위젯을 홈 화면에 하나씩 놓아 보세요. 같은 기록이 어떻게 다르게 보이는지 비교해 보세요.","en":"Add the Grid, Climb and Streak widgets to your Home Screen. Compare how the same record looks in each."}],"make":[{"ko":"내 앱의 완료 버튼에 햅틱, 짧은 소리, 작은 애니메이션을 붙이고 하나씩 빼 보며 무엇이 가장 큰 차이를 만드는지 비교해 보세요.","en":"Add a haptic, a short sound and a small animation to your done button, then remove them one at a time to see which matters most."},{"ko":"내 앱에 연속 기록이 있다면, 하루를 놓쳐도 0이 되지 않고 누적 횟수로 보여 주는 화면을 시안으로 만들어 보세요.","en":"If your app has streaks, mock up a screen that shows a running total instead of dropping to zero after a missed day."}],"ask":{"ko":"60회 누적 모델을 보고 나서, 하루를 놓친다는 상상이 어떻게 달라졌나요?","en":"After seeing the 60-rep model, how did the idea of missing a day feel different?"}},"Vectornator: Vector Design":{"time":20,"setup":{"ko":"지금은 Linearity Curve라는 이름이고, iPad와 Apple Pencil이 있으면 가장 잘 느낄 수 있어요. 내보내기와 AI 기능은 Pro 구독이에요.","en":"It is now called Linearity Curve and is best on iPad with Apple Pencil. Export and AI features need a Pro subscription."},"missions":[{"ko":"처음 열어 빈 캔버스에 닿기까지 따라가 보세요. 구독 안내가 언제 나오는지도 보세요.","en":"Follow the path to an empty canvas. Notice when the subscription pitch appears."},{"ko":"펜 도구로 곡선 몇 개를 그리고 노드를 움직여 보세요. Pencil 압력과 손가락 조작이 어떻게 나뉘는지 느껴 보세요.","en":"Draw a few curves with the pen tool and move the nodes. Feel how Pencil pressure and finger input are divided."},{"ko":"손그림이나 사진에 Auto Trace를 써 보세요. 그림이 벡터로 바뀌는 데 걸리는 시간을 보세요.","en":"Run Auto Trace on a sketch or photo. Notice how long it takes to become vectors."},{"ko":"도형 두 개를 겹치고 Shape Builder로 합치거나 빼 보세요. 메뉴 대신 직접 문질러 연산하는 감각을 느껴 보세요.","en":"Overlap two shapes and combine or subtract them with Shape Builder. Feel what it is like to do booleans by touch instead of menus."}],"make":[{"ko":"내 앱에서 메뉴로 실행하는 명령 하나를 골라, 대상을 직접 드래그하거나 문질러 실행하는 방식으로 바꿔 보세요.","en":"Pick one menu command in your app and prototype doing it by dragging or swiping directly on the object."},{"ko":"내 앱의 무료와 유료 경계 하나를 골라, 작업을 다 만든 뒤 막히는 흐름과 시작 전에 알게 되는 흐름을 그려 비교해 보세요.","en":"Pick one free-versus-paid boundary in your app and sketch two flows, blocked after the work is done versus told before starting."}],"ask":{"ko":"Shape Builder처럼 직접 만지는 방식이 메뉴보다 나았던 이유를 한 문장으로 말한다면?","en":"In one sentence, why was touching shapes directly better than using a menu?"}},"MARVEL Future Revolution":{"time":10,"setup":{"ko":"앱스토어에서 내려가 직접 할 수 없어요. Netmarble의 공식 트레일러나 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through Netmarble's own trailers and screenshots."},"missions":[{"ko":"공식 트레일러에서 영웅이 하늘을 나는 장면을 찾아 보세요. 스테이지가 아닌 끊김 없는 넓은 지역이 어떻게 보이는지 확인해 보세요.","en":"Find the flight scenes in an official trailer. See how large seamless zones look compared to separate stages."},{"ko":"전투 장면에서 콤보가 이어지는 구간을 멈춰 가며 보세요. 영웅마다 스킬 흐름이 어떻게 다른지 비교해 보세요.","en":"Pause through a combat sequence where combos chain. Compare how each hero's skill flow differs."},{"ko":"컷신과 영웅 모델이 가까이 잡힌 장면을 확대해 보세요. 모바일에서 이 정도 디테일을 보여 주려 한 이유를 생각해 보세요.","en":"Zoom into cutscenes and close-ups of the hero models. Think about why it aimed for this level of detail on mobile."}],"make":[{"ko":"내 앱의 대표 화면 하나를 골라, 트레일러 첫 장면으로 써도 될 만큼 한눈에 읽히는지 스크린샷으로 점검해 보세요.","en":"Take a screenshot of your app's signature screen and check whether it would read at a glance as a trailer's first shot."},{"ko":"단계로 나뉜 내 앱의 흐름 하나를 이어진 한 화면으로 합치면 무엇이 달라지는지 화면 지도를 그려 보세요.","en":"Draw a screen map of what changes if one stepped flow in your app becomes a single continuous screen."}],"ask":{"ko":"출시 2년 만에 서비스가 끝났다는 걸 알고 보니, 화려한 기술 말고 무엇이 더 필요했다고 생각하나요?","en":"Knowing it shut down two years after launch, what do you think it needed beyond impressive technology?"}},"Little Orpheus":{"time":10,"setup":{"ko":"앱스토어에서 내려가 직접 할 수 없어요. The Chinese Room의 공식 트레일러나 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through The Chinese Room's own trailers and screenshots."},"missions":[{"ko":"트레일러의 플레이 장면에서 플레이어가 하는 동작이 몇 가지인지 세어 보세요.","en":"In the trailer's gameplay shots, count how many kinds of actions the player performs."},{"ko":"그 단순한 조작 위에 얹힌 카메라 움직임과 연출을 따라가 보세요. 영화처럼 느껴지는 순간이 언제인지 표시해 보세요.","en":"Follow the camera work and staging layered over those simple controls. Mark the moments that feel cinematic."},{"ko":"우주비행사가 심문관에게 이야기하는 장면을 찾아 들어 보세요. 믿기 어려운 화자가 장면들을 어떻게 이어 주는지 느껴 보세요.","en":"Find the scenes of the cosmonaut talking to his interrogator. Notice how the unreliable narrator stitches the scenes together."},{"ko":"챕터마다 다른 환경을 스크린샷으로 나란히 놓아 보세요. 짧은 회차마다 무엇이 새로워지는지 비교해 보세요.","en":"Line up screenshots from different chapters. Compare what each short episode makes new."}],"make":[{"ko":"내 앱의 긴 흐름 하나를 몇 분 안에 끝나는 짧은 회차로 나누고 회차마다 새로운 점 하나를 적어 보세요.","en":"Split one long flow in your app into short episodes of a few minutes and write one new thing each episode brings."},{"ko":"내 앱의 안내 문구 세 개를 한 인물이 들려주는 말투로 바꿔 써 보세요.","en":"Rewrite three of your app's guidance lines in the voice of one storyteller."}],"ask":{"ko":"조작이 단순한데도 영화처럼 느껴졌다면, 그 감각은 무엇에서 왔나요?","en":"If it felt cinematic despite simple controls, where did that feeling come from?"}},"Sp!ng":{"time":10,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"Requires an Apple Arcade subscription."},"missions":[{"ko":"첫 레벨에서 화면을 눌러 보세요. 아무 설명 없이 누르고 떼는 것만으로 무엇을 배우게 되는지 보세요.","en":"Press the screen in the first level. Notice what you learn from holding and releasing with no explanation."},{"ko":"떼는 타이밍을 일부러 빠르게, 또 늦게 해 보세요. 입력 하나가 얼마나 다른 결과를 만드는지 느껴 보세요.","en":"Release deliberately early, then late. Feel how one input produces very different results."},{"ko":"실패한 뒤 다시 시작해 보세요. 다시 날기까지 몇 초 걸리는지 재 보세요.","en":"Fail and retry. Time how many seconds it takes before you are flinging again."},{"ko":"Zen이나 One Life처럼 다른 모드를 해 보세요. 같은 조작이 기분을 어떻게 바꾸는지 비교해 보세요.","en":"Try another mode such as Zen or One Life. Compare how the same control changes the mood."}],"make":[{"ko":"내 앱의 핵심 기능을 입력 하나로만 쓸 수 있게 줄이면 무엇이 남는지 종이에 적어 보세요.","en":"On paper, write what would remain if your app's core feature allowed only a single input."},{"ko":"같은 핵심 동작을 느긋한 버전과 도전 버전 두 모드로 나눠 쓰는 화면을 그려 보세요.","en":"Sketch the same core action offered as a relaxed mode and a challenge mode."}],"ask":{"ko":"입력이 하나뿐인데도 지루하지 않았던 이유는 무엇인가요?","en":"Why did one input not get boring?"}},"(Not Boring) Weather":{"time":10,"setup":null,"missions":[{"ko":"처음 열어 내 위치의 날씨가 3D 장면으로 나타나는 순간을 보세요. 숫자보다 먼저 무엇이 눈에 들어오는지 확인해 보세요.","en":"Open the app and watch your weather appear as a 3D scene. Notice what catches your eye before any number."},{"ko":"화면 이곳저곳을 탭해 보세요. 아무 반응이 없는 곳이 있는지 찾아보세요.","en":"Tap all over the screen. Try to find any spot that does nothing."},{"ko":"탭할 때 나는 소리와 아주 약한 햅틱에 집중해 보세요. 알아챌 듯 말 듯한 세기가 어떤 느낌인지 느껴 보세요.","en":"Focus on the sounds and faint haptics as you tap. Feel what just-noticeable feedback is like."},{"ko":"분 단위 강수, 대기질, 꽃가루 정보를 찾아보세요. 3D 장면과 상세 데이터 사이를 어떻게 오가는지 보세요.","en":"Find minute-by-minute precipitation, air quality and pollen. Notice how you move between the 3D scene and the detailed data."},{"ko":"스킨이나 아이콘을 바꿔 보세요. 앱 전체 디자인이 함께 바뀌는지 확인해 보세요.","en":"Change the skin or icon. Check whether the whole app's design changes with it."}],"make":[{"ko":"내 앱의 한 화면에서 탭해도 아무 일도 없는 요소를 모두 찾아 각각 작은 반응 하나씩 붙여 보세요.","en":"Find every element on one of your screens that does nothing when tapped and give each a small response."},{"ko":"색 값을 한곳에 모아 바꾸면 앱 전체가 바뀌도록 정리하고, 두 번째 스킨을 하나 만들어 보세요.","en":"Gather your colors into one place so a change restyles the whole app, then make a second skin."}],"ask":{"ko":"모든 것이 반응하는 화면을 써 보고 나니, 내 앱에서 죽어 있는 곳은 어디가 떠오르나요?","en":"After a screen where everything responds, which dead spots in your own app come to mind?"}},"Sayonara Wild Hearts":{"time":10,"setup":{"ko":"앱스토어에서 내려가 직접 할 수 없어요. Simogo나 Annapurna의 공식 트레일러와 스크린샷으로 경험해 보세요.","en":"It has left the App Store, so experience it through Simogo's or Annapurna's own trailers and screenshots."},"missions":[{"ko":"소리를 켜고 트레일러를 처음부터 보세요. 화면 움직임이 박자에 맞아떨어지는 순간을 세어 보세요.","en":"Watch a trailer from the start with sound on. Count the moments where motion lands on the beat."},{"ko":"플레이 장면에서 입력이 스와이프와 탭 정도로 단순해 보이는지 확인해 보세요. 단순한 조작이 화면을 얼마나 비워 두는지 보세요.","en":"Check whether the gameplay inputs look as simple as swipes and taps. Notice how much screen that leaves clear."},{"ko":"핑크와 보라 네온, 카메라 시점이 바뀌는 순간에서 멈춰 캡처해 보세요. 전환이 얼마나 자주 일어나는지 보세요.","en":"Pause and capture the moments of pink and purple neon and shifting camera angles. Notice how often they change."},{"ko":"트레일러에서 가장 어려워 보이는 구간을 골라 보세요. 여러 번 실패하면 건너뛰기를 제안한다는 점을 떠올리며 내가 막혔다면 어땠을지 생각해 보세요.","en":"Pick the hardest-looking section in the trailer. Remembering that it offers a skip after repeated failures, imagine how being stuck there would feel."}],"make":[{"ko":"내 앱의 전환 애니메이션 하나를 좋아하는 곡의 박자에 맞춰 길이를 조정해 보세요.","en":"Retime one transition in your app to the beat of a song you like."},{"ko":"사용자가 같은 단계에서 여러 번 실패하면 건너뛰기를 제안하는 조건과 문구를 설계해 보세요.","en":"Design the trigger and the wording for offering a skip when someone fails the same step several times."}],"ask":{"ko":"박자에 맞춘 움직임이 같은 장면을 어떻게 다르게 느끼게 했나요?","en":"How did motion synced to the beat change the way the same scene felt?"}},"Strava":{"time":20,"setup":{"ko":"밖에서 짧게 걷거나 달릴 시간이 필요하고, Apple Watch가 있으면 휴대폰 없이도 해 볼 수 있어요.","en":"You need time outdoors for a short walk or run, and an Apple Watch lets you try it without the phone."},"missions":[{"ko":"가입하다가 위치 권한 요청이 나오는 순간을 잘 보세요. 시스템 팝업 전에 왜 필요한지 먼저 설명하는 화면이 어떤 말을 하는지 읽어 보세요.","en":"Watch for the location request during sign-up. Read what the explanation screen says before the system prompt appears."},{"ko":"짧게 걷거나 달리고 기록을 저장해 보세요. 그 기록이 피드 게시물로 바뀌는 순간을 지켜보세요.","en":"Take a short walk or run and save it. Watch the moment your workout becomes a feed post."},{"ko":"내가 지나간 세그먼트의 리더보드를 찾아보세요. 같은 길을 달린 사람들과 비교될 때 혼자 한 운동이 어떻게 달라 보이는지 느껴 보세요.","en":"Find the leaderboard for a segment you covered. Feel how a solo workout changes once it is compared with others on the same route."},{"ko":"다른 사람의 활동에 쿠도스를 보내고 클럽도 둘러보세요. 기록 앱 위에 SNS 구조가 어떻게 얹혀 있는지 보세요.","en":"Give kudos to someone's activity and browse clubs. Notice how a social layer sits on top of a tracking app."},{"ko":"프라이버시 존과 활동 공개 범위 설정을 찾아보세요. 집 근처 경로가 남에게 어떻게 보일지 직접 확인해 보세요.","en":"Find privacy zones and activity visibility settings. Check how a route near your home would look to others."}],"make":[{"ko":"내 앱의 권한 요청 하나를 골라, 시스템 팝업 앞에 이유를 한 문장으로 설명하는 사전 화면을 만들어 보세요.","en":"Pick one permission request in your app and build a pre-permission screen that explains the reason in one sentence before the system prompt."},{"ko":"내 앱에서 혼자 남기는 기록 하나를 골라, 같은 조건의 다른 사람과 비교하는 작은 순위표 시안을 그려 보세요.","en":"Pick one solo record in your app and sketch a small leaderboard comparing it with people under the same conditions."},{"ko":"내 앱이 공유하는 데이터 하나를 골라, 기본 공개 범위와 숨길 수 있는 영역 설정을 설계해 보세요.","en":"Pick one piece of data your app shares and design its default visibility and a way to hide sensitive areas."}],"ask":{"ko":"권한 설명 화면을 본 뒤 허용을 누를 때, 망설임이 줄었나요?","en":"After the explanation screen, did you hesitate less before allowing location?"}},"Instagram":{"time":10,"setup":null,"missions":[{"ko":"앱을 열고 상단 원형 스토리 트레이에서 스토리 하나를 열어 보세요. 새 스토리와 이미 본 스토리가 어떻게 구분되는지 먼저 보세요.","en":"Open the app and tap a story from the round tray at the top. First notice how new stories differ from ones you have seen."},{"ko":"스토리를 탭으로 넘기고, 길게 눌러 멈추고, 아래로 스와이프해 닫아 보세요. 설명 없이 이 제스처들을 알 수 있었는지 생각해 보세요.","en":"Tap through a story, hold to pause and swipe down to close. Ask whether you knew these gestures without being told."},{"ko":"가로로 천천히 스와이프하다가 중간에 손을 멈추거나 되돌려 보세요. 3D 큐브 전환이 손가락을 그대로 따라오는지 느껴 보세요.","en":"Swipe sideways slowly, then stop or reverse halfway. Feel whether the 3D cube transition tracks your finger exactly."},{"ko":"피드 사진을 더블탭해 좋아요를 누르고, 핀치로 확대했다가 손을 떼 보세요. 제자리로 튕겨 돌아오는 피드백을 관찰해 보세요.","en":"Double-tap a feed photo to like it, then pinch to zoom and let go. Watch it spring back into place."},{"ko":"게시물을 올리는 과정을 따라가며 마지막 버튼을 누른 뒤 얼마나 빨리 끝나는지 보세요. 기다림이 짧게 느껴지는지 판단해 보세요.","en":"Go through posting something and watch how quickly it finishes after the final tap. Decide whether the wait feels short."}],"make":[{"ko":"내 앱의 화면 전환 하나를 손가락을 따라 움직이고 중간에 멈추거나 되돌릴 수 있는 인터랙티브 전환으로 바꿔 보세요.","en":"Turn one transition in your app into an interactive one that follows the finger and can be paused or reversed midway."},{"ko":"내 앱의 이미지 화면에 핀치 확대 후 손을 떼면 제자리로 튕겨 돌아오는 동작을 붙여 보세요.","en":"Add pinch to zoom with a springy return on release to an image screen in your app."},{"ko":"내 앱에서 사용자가 확인을 누른 뒤 시작되는 작업 하나를 골라, 그 전 단계에서 미리 처리를 시작해 보세요.","en":"Pick one task that starts after the user confirms and begin processing it a step earlier."}],"ask":{"ko":"가장 자연스럽게 느껴진 제스처는 무엇이었고, 왜 그랬나요?","en":"Which gesture felt most natural, and why?"}},"Notion":{"time":15,"setup":null,"missions":[{"ko":"처음 열어 빈 페이지 하나를 만들어 보세요. 빈 화면에서 무엇부터 하라고 알려 주는지 보세요.","en":"Create a blank page. Notice what the empty screen suggests you do first."},{"ko":"키보드를 올리고 슬래시(/)를 입력해 블록 유형을 바꿔 보세요. 키보드 툴바가 서식 도구를 어떻게 숨겨 뒀다가 꺼내는지 보세요.","en":"Bring up the keyboard and type a slash to change a block type. Notice how the keyboard toolbar keeps formatting tools hidden until needed."},{"ko":"페이지 안에 페이지를 세 단계쯤 넣고 맨 아래로 들어가 보세요. 상단 브레드크럼과 스와이프 백으로 위치를 얼마나 쉽게 파악하는지 보세요.","en":"Nest pages about three levels deep and go to the bottom one. See how easily the breadcrumb and swipe back keep you oriented."},{"ko":"가장 깊은 페이지에서 사이드바, 검색, 즐겨찾기로 다른 곳에 바로 점프해 보세요. 계층을 거슬러 오르지 않아도 되는지 확인해 보세요.","en":"From the deepest page, jump elsewhere with the sidebar, search or favorites. Check that you never have to climb back up."},{"ko":"데이터베이스 하나를 만들고 표, 보드, 캘린더, 갤러리로 뷰를 바꿔 보세요. 같은 데이터가 모양만 바뀌는 순간을 지켜보세요.","en":"Create a database and switch it between table, board, calendar and gallery. Watch the same data change only its shape."}],"make":[{"ko":"내 앱의 입력창 하나에 슬래시를 치면 서식이나 동작 몇 가지가 뜨는 명령 메뉴를 프로토타입해 보세요.","en":"Prototype a command menu in one of your text fields that appears when you type a slash."},{"ko":"내 앱의 깊은 화면 하나에 상단 브레드크럼을 붙이고, 어느 단계로든 바로 돌아갈 수 있게 해 보세요.","en":"Add a breadcrumb to one deep screen in your app so people can jump straight back to any level."},{"ko":"내 앱의 목록 하나를 같은 데이터 그대로 목록과 그리드 두 가지 뷰로 전환할 수 있게 만들어 보세요.","en":"Let one list in your app switch between list and grid views over the same data."}],"ask":{"ko":"페이지를 깊이 넣었을 때 길을 잃지 않게 해 준 장치는 무엇이었나요?","en":"What kept you from getting lost once pages were nested deep?"}},"ChatGPT":{"time":10,"setup":null,"missions":[{"ko":"처음 열어 첫 질문을 입력하고 보내 보세요. 첫 글자가 화면에 나타나기까지 걸린 시간을 느껴 보세요.","en":"Type and send your first question. Feel how long it takes for the first words to appear."},{"ko":"긴 답이 필요한 질문을 보내고 전송 버튼 자리를 보세요. 생성 중에 정지 버튼으로 바뀐 그 자리에서 바로 멈춰 보세요.","en":"Ask something that needs a long answer and watch the send button. Stop the response from the same spot once it turns into a stop button."},{"ko":"다시 긴 답을 받으며 중간에 위로 스크롤해 보세요. 자동 스크롤이 멈춰 읽던 곳을 지켜 주는지 확인해 보세요.","en":"Get another long answer and scroll up midway. Check that auto-scroll stops and leaves you where you were reading."},{"ko":"답이 끝난 뒤 그 아래에 복사, 재생성, 피드백 버튼이 언제 나타나는지 보세요. 재생성을 눌러 결과가 어떻게 바뀌는지 관찰해 보세요.","en":"Notice when copy, regenerate and feedback buttons appear under a finished answer. Press regenerate and watch what changes."},{"ko":"음성 모드로 대화하다가 답 중간에 말을 끊고 끼어들어 보세요. 음성 상태를 보여 주는 애니메이션이 어떻게 반응하는지 보세요.","en":"Talk in voice mode and interrupt it mid-answer. Watch how the voice-state animation reacts."}],"make":[{"ko":"내 앱의 실행 버튼 하나를 작업 중에는 같은 자리에서 정지 버튼으로 바뀌게 만들어 보세요.","en":"Make one action button in your app turn into a stop button in the same spot while the task runs."},{"ko":"내 앱에서 결과 위에 붙는 후속 버튼들을 작업이 끝난 뒤에만 나타나도록 상태별로 나눠 보세요.","en":"Split the follow-up buttons on a result in your app so they appear only once the task has finished."},{"ko":"내 앱의 자동 스크롤 화면 하나에, 사용자가 위로 스크롤하면 자동 이동을 멈추는 규칙을 넣어 보세요.","en":"Add a rule to one auto-scrolling screen so it stops moving once the user scrolls up."}],"ask":{"ko":"답이 흘러나오는 동안 나는 기다리고 있다고 느꼈나요, 읽고 있다고 느꼈나요?","en":"While the answer streamed, did you feel like you were waiting or reading?"}},"카카오톡":{"time":15,"setup":null,"missions":[{"ko":"앱을 열고 하단 탭을 하나씩 눌러 보세요. 메신저 앱에 어떤 기능이 붙어 탭이 구성됐는지 순서대로 적어 보세요.","en":"Open the app and tap each bottom tab. Write down, in order, which features have been attached to the messenger."},{"ko":"친구 탭을 열어 보세요. 2025년 9월 피드형 개편 이후 친구 한 명을 찾으려면 몇 번 움직여야 하는지 세어 보세요.","en":"Open the Friends tab. Count how many moves it takes to find one friend after the September 2025 feed-style redesign."},{"ko":"채팅방에서 이모티콘을 보내 보고 이모티콘 스토어도 둘러보세요. 대화 속 표현이 어떻게 상품이 되는지 관찰해 보세요.","en":"Send an emoticon in a chat and browse the emoticon store. Notice how expression inside conversations becomes a product."},{"ko":"채팅방에서 송금이나 선물하기로 가는 입구를 찾아 보내기 직전까지 진행해 보세요. 메신저에서 결제로 넘어갈 때 화면 분위기가 어떻게 바뀌는지 보세요.","en":"Find the way into sending money or gifts from a chat and go right up to sending. Notice how the mood changes as you move from messaging to payment."},{"ko":"단체방 하나를 열어 보세요. 한국 사용자의 단체방 사용 방식에 맞춘 기능이 무엇인지 찾아보세요.","en":"Open a group chat. Look for features shaped around how Korean users use group chats."}],"make":[{"ko":"내 앱의 탭 구성을 바꾼다고 가정하고, 기존 사용자에게 바뀐 점을 알리고 되돌릴 길을 주는 화면을 그려 보세요.","en":"Assume you are changing your tab layout and sketch a screen that tells existing users what changed and offers a way back."},{"ko":"내 앱의 핵심 흐름 안에 부가 기능 하나로 가는 입구를 넣되, 핵심 동작을 방해하지 않는 위치 세 곳을 비교해 보세요.","en":"Add an entry point to one secondary feature inside your core flow and compare three spots that do not get in the way."},{"ko":"내 앱 계정으로 다른 서비스 하나에 로그인한다고 가정하고, 연결 동의 화면에 보여 줄 정보를 정해 보세요.","en":"Imagine your app's account being used to sign in to another service and decide what the consent screen should show."}],"ask":{"ko":"친구 탭에서 예전과 달라 가장 불편했던 점은 무엇이었고, 그건 어떤 습관을 깨서였나요?","en":"What felt most off in the Friends tab, and which habit did it break?"}},"Ball x Pit":{"time":20,"setup":null,"missions":[{"ko":"첫 판을 시작해 공을 날려 보세요. 설명 없이 조작을 이해하기까지 몇 초 걸렸는지 보세요.","en":"Start your first run and fling a ball. Count the seconds until the controls make sense without explanation."},{"ko":"공 두 개를 합치거나 하나를 진화시켜 보세요. 효과가 섞인 공이 연쇄 반응으로 화면을 채우는 순간을 지켜보세요.","en":"Fuse two balls or evolve one. Watch the moment the combined effects set off chain reactions across the screen."},{"ko":"내려오는 벽에 밀려 한 판을 져 보세요. 졌다는 사실보다 다음 판에 대한 기대가 어떻게 만들어지는지 보세요.","en":"Lose a run to the descending wall. Notice how the game builds anticipation for the next run more than regret for this one."},{"ko":"판 사이 마을에서 일꾼을 배치하고 건물을 지어 보세요. 짧은 판이 긴 목표로 이어지는 감각을 느껴 보세요.","en":"Between runs, assign workers and build in the village. Feel how short runs connect to a longer goal."}],"make":[{"ko":"내 앱의 기본 동작 하나는 그대로 두고, 그 위에 사용자가 고르는 조합 선택 두 가지를 얹은 프로토타입을 만들어 보세요.","en":"Keep one basic action in your app unchanged and prototype two combinable choices layered on top of it."},{"ko":"짧은 사용이 끝날 때마다 쌓이는 진척 하나를 보여 주는 요약 화면을 그려 보세요.","en":"Sketch a summary screen that shows one piece of progress that accumulates at the end of each short session."}],"ask":{"ko":"조작은 그대로인데 판마다 달라졌던 것은 무엇이었나요?","en":"With the controls never changing, what made each run feel different?"}},"Detail: AI Video Editor":{"time":15,"setup":{"ko":"조용한 장소가 좋고, 대화 장면을 찍을 사람 한 명이 있으면 더 좋아요.","en":"Find a quiet spot, and ideally a second person to record a conversation with."},"missions":[{"ko":"처음 실행해 녹화를 시작하기까지 따라가 보세요. 카메라와 편집기가 한 흐름이라는 걸 어디서 느끼는지 보세요.","en":"Follow the path to your first recording. Notice where you feel that camera and editor are one flow."},{"ko":"대략적인 개요를 적어 텔레프롬프터 대본으로 바꾼 뒤 렌즈를 보며 읽어 보세요. 스크롤 속도가 말하는 속도와 맞는지 확인해 보세요.","en":"Write a rough outline, turn it into a teleprompter script and read it to the lens. Check whether the scrolling keeps pace with your speech."},{"ko":"다른 사람과 대화를 한 번에 찍고 Auto Edit을 실행해 보세요. 한 대로 찍은 영상이 확대와 반응 컷으로 나뉘는 결과를 보세요.","en":"Record a conversation in one take and run Auto Edit. Watch a single shot turn into zooms and reaction cuts."},{"ko":"침묵이 잘린 부분을 원본과 비교해 보세요. 녹화부터 공유할 수 있는 영상까지 몇 초 걸렸는지 재 보세요.","en":"Compare the silence-trimmed cut with the raw take. Time how long it took from recording to a shareable video."}],"make":[{"ko":"내 앱에서 다른 앱으로 넘겨 처리하는 작업 하나를 골라, 앱 안에서 끝나게 하면 줄어드는 단계를 적어 보세요.","en":"Pick one task your users finish in another app and list the steps saved if it stayed inside yours."},{"ko":"사용자가 직접 하던 정리 작업 하나를 앱이 먼저 해 두고 사용자는 확인만 하는 화면을 그려 보세요.","en":"Sketch a screen where your app does one cleanup task first and the user only confirms it."}],"ask":{"ko":"자동 편집 결과에서 내가 고치고 싶었던 컷이 있었나요, 있었다면 왜였나요?","en":"Was there a cut in the auto edit you wanted to change, and why?"}},"Harvee":{"time":10,"setup":{"ko":"HRV, 안정 시 심박, 수면 데이터를 쓰기 때문에 Apple Watch가 필요해요.","en":"You need an Apple Watch, since it reads HRV, resting heart rate and sleep."},"missions":[{"ko":"처음 열어 건강 데이터 접근을 허용하는 과정을 따라가 보세요. 왜 필요한지, 데이터가 기기 밖으로 나가지 않는다는 점을 어떻게 알리는지 보세요.","en":"Follow the health data permission flow. Notice how it explains why it is needed and that the data stays on the phone."},{"ko":"홈 화면 가운데의 캐릭터를 보세요. 그래프 없이 지금 내 상태를 몇 초 만에 알 수 있는지 확인해 보세요.","en":"Look at the character in the middle of the home screen. Check how many seconds it takes to read your state without a chart."},{"ko":"오늘의 회복 추천을 읽어 보세요. 전문 용어 없이 쉬운 말로 설명하는지 보세요.","en":"Read today's recovery recommendation. Notice whether it explains things in plain language."},{"ko":"카페인이나 수분을 기록한 뒤 7일 히트맵을 열어 보세요. 생활 습관과 스트레스가 연결돼 보이는지 관찰해 보세요.","en":"Log caffeine or water, then open the 7-day heat map. See whether habits and stress look connected."}],"make":[{"ko":"내 앱의 차트 하나를 골라, 그 차트의 결론을 좋음, 보통, 나쁨 세 가지 캐릭터 표정으로 그려 보세요.","en":"Pick one chart in your app and draw its conclusion as three character expressions for good, okay and bad."},{"ko":"그 표정 아래에 숫자 대신 한 문장 설명을 붙이고, 원래 차트는 탭해야 보이도록 숨겨 보세요.","en":"Put a one-sentence explanation under that expression and hide the original chart behind a tap."}],"ask":{"ko":"캐릭터 표정이 숫자보다 더 잘 알려 준 것과 덜 알려 준 것은 각각 무엇이었나요?","en":"What did the character tell you better than numbers, and what did it tell you less well?"}},"Lumy":{"time":10,"setup":{"ko":"7,500원 유료 앱이고, Apple Watch가 있으면 컴플리케이션도 확인할 수 있어요.","en":"A paid app at 7,500 won, and an Apple Watch lets you try the complications."},"missions":[{"ko":"처음 열어 사진, 하이킹, 명상, 여행 같은 모드 중 하나를 골라 보세요. 첫 화면에 무엇이 맨 위에 오는지 보세요.","en":"Pick a mode such as Photography, Hiking, Mindfulness or Travel. Notice what lands at the top of the first screen."},{"ko":"모드를 바꿔 다시 보세요. 같은 데이터가 순서만 바뀌어 다르게 읽히는 걸 비교해 보세요.","en":"Switch modes and look again. Compare how the same data reads differently just by changing its order."},{"ko":"시간 슬라이더를 끌어 하루를 훑어보세요. 시간에 따라 색이 빛처럼 바뀌는 순간을 지켜보세요.","en":"Drag the time slider through the day. Watch the palette shift like the light itself."},{"ko":"위젯이나 Live Activity를 켜 보세요. 앱을 열지 않고 다음 골든 아워를 알 수 있는지 확인해 보세요.","en":"Turn on a widget or Live Activity. Check whether you can tell the next golden hour without opening the app."}],"make":[{"ko":"내 앱의 첫 화면을 사용자 유형 두 가지로 나누고, 같은 정보를 다른 순서로 놓은 시안 두 개를 만들어 보세요.","en":"Split your first screen by two user types and mock up two versions with the same information in different orders."},{"ko":"내 앱에서 가장 자주 확인하는 정보 하나를 위젯 하나에 한 줄로 담아 보세요.","en":"Fit the single most-checked piece of information in your app into one line of a widget."}],"ask":{"ko":"모드를 바꿨을 때 가장 크게 달라진 정보는 무엇이었고, 그 순서가 왜 맞다고 느꼈나요?","en":"Which information moved most when you switched modes, and why did that order feel right?"}},"Land of Livia":{"time":20,"setup":{"ko":"VoiceOver를 켜고 이어폰을 준비해 두세요.","en":"Turn on VoiceOver and have earphones ready."},"missions":[{"ko":"VoiceOver를 켠 채 처음 열어 보세요. 눈을 감고 첫 메뉴를 지나 첫 퀘스트를 시작할 수 있는지 해 보세요.","en":"Open the app with VoiceOver on. Close your eyes and try to get past the first menu into your first quest."},{"ko":"퀘스트 하나를 소리만으로 진행해 보세요. 사운드와 햅틱이 게임 상태를 어떻게 알려 주는지 들어 보세요.","en":"Play through one quest by sound alone. Listen for how sound and haptics carry the game state."},{"ko":"퀘스트를 걸어 두고 앱을 나갔다가 돌아와 보세요. 없는 동안 무엇이 진행됐는지 확인해 보세요.","en":"Start a quest, leave the app and come back. Check what progressed while you were away."},{"ko":"글자 크기를 키우거나 Atkinson Hyperlegible 글꼴로 바꿔 보세요. 화면 배치가 그대로 버티는지 보세요.","en":"Increase the text size or switch to Atkinson Hyperlegible. See whether the layout holds up."}],"make":[{"ko":"내 앱의 한 화면에서 VoiceOver로 모든 라벨을 들어 보고, 의미가 전달되지 않는 라벨 세 개를 직접 고쳐 보세요.","en":"Listen to every label on one screen of your app with VoiceOver and rewrite three that do not make sense."},{"ko":"자주 하는 복잡한 동작 하나를 App Intent로 만들어 Siri나 단축어로 한 번에 실행되게 해 보세요.","en":"Turn one common multi-step action into an App Intent so it runs in one go from Siri or Shortcuts."}],"ask":{"ko":"눈을 감고 했을 때 가장 먼저 길을 잃은 곳은 어디였고, 무엇이 있었다면 괜찮았을까요?","en":"With your eyes closed, where did you first get lost, and what would have helped?"}},"DREDGE":{"time":20,"setup":{"ko":"컨트롤러가 있으면 터치와 비교해 볼 수 있어요.","en":"A controller lets you compare it with touch."},"missions":[{"ko":"첫 항해를 나가 첫 물고기를 잡아 보세요. 낚시 미니게임이 터치로 얼마나 빨리 손에 붙는지 보세요.","en":"Head out and catch your first fish. Notice how quickly the fishing mini-game clicks under your thumb."},{"ko":"잡은 것을 화물칸 격자에 넣어 보세요. 모양을 돌리고 끼우며 무엇을 버릴지 고민하는 순간을 느껴 보세요.","en":"Fit your catch into the cargo grid. Feel the moment of rotating shapes and deciding what to leave behind."},{"ko":"밤이 될 때까지 바다에 남아 보세요. 전투 없이 불안이 어떻게 쌓이는지 화면과 소리로 관찰해 보세요.","en":"Stay out at sea until night. Watch and listen to how tension builds without any combat."},{"ko":"컨트롤러가 있다면 연결해 같은 낚시를 해 보세요. 터치와 무엇이 달라지는지 비교해 보세요.","en":"If you have a controller, connect it and fish again. Compare what changes from touch."}],"make":[{"ko":"내 앱의 목록이나 저장 공간 하나에 개수 대신 모양과 크기로 제한을 두면 어떤 선택이 생기는지 종이 시안을 만들어 보세요.","en":"On paper, try limiting one list or storage space in your app by shape and size instead of count, and see what choices it creates."},{"ko":"시간에 따라 분위기가 바뀌면 좋을 화면 하나를 골라 낮과 밤 두 가지 색 상태를 만들어 보세요.","en":"Pick one screen that would benefit from a changing mood and create day and night color states for it."}],"ask":{"ko":"화물칸 정리가 귀찮은 일이 아니라 퍼즐로 느껴진 순간은 언제였나요?","en":"When did packing the cargo stop feeling like a chore and start feeling like a puzzle?"}},"Infinity Nikki":{"time":30,"setup":{"ko":"무료 게임이지만 뽑기(가챠) 과금이 있어요.","en":"Free to play, but it uses gacha monetization."},"missions":[{"ko":"시작해 첫 의상을 입고 걸어 보세요. 드레스가 흔들리고 반짝이는 움직임을 가까이서 보세요.","en":"Start, put on your first outfit and walk. Watch up close how the dress sways and sparkles."},{"ko":"빛이 다른 장소로 옮겨 다니며 같은 옷을 보세요. 조명에 따라 옷감이 어떻게 달라 보이는지 비교해 보세요.","en":"Move between places with different light while wearing the same outfit. Compare how the fabric changes under each."},{"ko":"이동 능력을 주는 옷으로 갈아입고 써 보세요. 옷이 곧 능력이라는 구조를 몸으로 느껴 보세요.","en":"Change into a piece that grants a traversal ability and use it. Feel how clothing itself is the progression."},{"ko":"Stylist Duel에 도전해 보세요. 코디를 고르는 일이 어떻게 승부가 되는지 보세요.","en":"Take on a Stylist Duel. Notice how choosing an outfit becomes a contest."}],"make":[{"ko":"내 앱의 꾸미기나 설정 요소 하나가 실제 기능을 열어 주도록 바꾸면 사용 동기가 어떻게 달라질지 흐름을 그려 보세요.","en":"Sketch how motivation would change if one cosmetic or customization option in your app unlocked a real capability."},{"ko":"내 앱에 확률형 보상이 있다면, 일정 횟수 뒤 보상을 보장하는 규칙과 그 안내 문구를 써 보세요.","en":"If your app has random rewards, write a guarantee-after-N rule and the copy that explains it."}],"ask":{"ko":"옷이 능력이 되는 구조에서, 나는 예뻐서 골랐나요 아니면 쓸모 때문에 골랐나요?","en":"When clothes were abilities, did you pick them for looks or for use?"}},"Complete Anatomy 2024":{"time":20,"setup":{"ko":"iPad나 Mac에서 해 보면 가장 잘 느낄 수 있어요.","en":"Best experienced on iPad or Mac."},"missions":[{"ko":"처음 열어 3D 인체 모델에 닿기까지 과정을 따라가 보세요. 첫 모델로 무엇을 보여 주는지 보세요.","en":"Follow the path to the first 3D body model. Notice which model it shows you first."},{"ko":"모델을 돌리고 구조를 하나씩 떼어 내거나 흐리게 해 보세요. 손가락으로 해부하는 감각을 느껴 보세요.","en":"Rotate the model and isolate or fade structures one by one. Feel what dissecting with your fingers is like."},{"ko":"모델의 피부색과 표현형을 바꿔 보세요. 선택지가 얼마나 넓은지, 바꾸는 과정이 얼마나 쉬운지 보세요.","en":"Change the model's skin tone and phenotype. Notice how wide the range is and how easy it is to change."},{"ko":"뛰는 심장 모델을 열고 잘라 보세요. 움직이는 모델이 정지된 그림과 무엇이 다른지 생각해 보세요.","en":"Open the beating heart and dissect it. Think about what a moving model shows that a still picture cannot."},{"ko":"AR 모드로 인체를 방 안에 띄워 보세요. 실제 크기로 볼 때 무엇이 새롭게 보이는지 확인해 보세요.","en":"Place the anatomy in your room with AR mode. Check what you notice when it sits in real space."}],"make":[{"ko":"내 앱의 기본 아바타나 예시 사진이 누구를 기본값으로 삼는지 점검하고, 다른 기본값 세 가지를 준비해 보세요.","en":"Check who your app's default avatar or sample photos assume, and prepare three alternative defaults."},{"ko":"정보가 겹겹이 쌓인 화면 하나를 골라 층을 하나씩 흐리게 하거나 숨기는 슬라이더를 프로토타입해 보세요.","en":"Pick one layered screen and prototype a slider that fades or hides one layer at a time."}],"ask":{"ko":"모델의 피부색을 바꿀 수 있다는 걸 알았을 때, 교육 도구의 기본값에 대한 생각이 어떻게 달라졌나요?","en":"Once you saw the skin tone could change, how did your view of defaults in learning tools shift?"}},"Crouton":{"time":15,"setup":{"ko":"손글씨 레시피 카드나 요리책 한 페이지를 준비해 두세요.","en":"Have a handwritten recipe card or a cookbook page ready."},"missions":[{"ko":"처음 열어 첫 레시피를 넣기까지 무엇을 권하는지 보세요. 화면에 무엇이 빠져 있는지도 눈여겨보세요.","en":"See what it suggests before your first recipe. Also notice what is missing from the screen."},{"ko":"손글씨나 요리책 레시피를 사진으로 가져와 보세요. 재료와 분량이 어떻게 나뉘었는지 원본과 한 줄씩 대조해 보세요.","en":"Import a handwritten or printed recipe from a photo. Compare the parsed ingredients and quantities with the original line by line."},{"ko":"대충 썬 양파 같은 재료가 어떻게 해석됐는지, 장보기 목록에서 재료가 어떻게 묶였는지 확인해 보세요.","en":"Check how an ingredient like roughly chopped onion was interpreted and how items were grouped in the grocery list."},{"ko":"Step mode로 요리를 따라가 보세요. 지금 단계와 그 재료만 보이는 화면에서 단위 변환과 타이머가 어디 있는지 보세요.","en":"Cook along in Step mode. With only the current step and its ingredients on screen, find where unit conversion and the timer live."}],"make":[{"ko":"내 앱에서 정보가 가장 많은 화면을 골라 요소를 하나씩 지우며, 그 순간 꼭 필요한 것만 남겨 보세요.","en":"Take your densest screen and delete elements one at a time until only what that moment needs remains."},{"ko":"사용자가 자유롭게 쓰는 텍스트 하나를 골라 숫자, 단위, 이름으로 나눠 보여 주는 화면 시안을 만들어 보세요.","en":"Pick one free-text field in your app and mock up a view that splits it into number, unit and name."}],"ask":{"ko":"이 앱에서 빠져 있어서 오히려 좋았던 것은 무엇이었나요?","en":"What was better precisely because it was left out?"}},"The Bear":{"time":15,"setup":{"ko":"첫 챕터는 무료이고, 나머지 4개 챕터는 한 번의 인앱 구매로 열려요.","en":"The first chapter is free; the other four unlock with a single in-app purchase."},"missions":[{"ko":"게임을 켜고 동굴 속 곰을 달래 밖으로 꺼내 보세요. 설명 글 없이 무엇을 해야 할지 어떻게 알게 되는지 살펴보세요.","en":"Start the game and coax the bear out of its cave. Notice how you figure out what to do without any instructional text."},{"ko":"소리를 켜고 곰과 아이를 이끌어 첫 행성을 건너 보세요. 손그림 애니메이션과 음악이 내 손짓에 어떻게 반응하는지 느껴 보세요.","en":"With sound on, guide the bear and the little one across the first planet. Feel how the hand-drawn animation and score respond to your touch."},{"ko":"일부러 빠르게 여러 번 탭해 보세요. 상호작용이 차분한 분위기를 깨지 않도록 내 손짓을 어떻게 부드럽게 받아 주는지 관찰해 보세요.","en":"Tap quickly and repeatedly on purpose. Watch how the game softens your input so the calm mood never breaks."},{"ko":"첫 챕터를 끝까지 가 보세요. 상실이나 놓아주기 같은 감정이 글이 아닌 어떤 장면으로 전해졌는지 떠올려 보세요.","en":"Play through the whole first chapter. Recall which scenes, not words, carried feelings like loss or letting go."}],"make":[{"ko":"내 앱에서 사용자가 연타하기 쉬운 동작 하나를 골라, 애니메이션을 늦추고 부드러운 이징으로 받아 주게 바꿔 보세요.","en":"Pick one action in your app people tend to spam-tap, and slow its animation with a soft easing curve so it absorbs the input gently."},{"ko":"내 앱의 안내 문구 하나를 지우고, 화면 속 움직임이나 빛나는 대상만으로 다음 행동을 알려 주는 버전을 만들어 보세요.","en":"Delete one instructional label in your app and build a version where motion or a glowing target alone signals the next step."},{"ko":"내 앱을 첫 장은 무료, 나머지는 한 번 구매로 바꾼다면 무료 범위를 어디서 끊을지 화면 한 장에 그려 보세요.","en":"If your app became first chapter free, the rest one purchase, sketch on one screen where you would end the free part."}],"ask":{"ko":"설명 없이도 다음에 할 일을 알 수 있었던 순간은 무엇 덕분이었나요?","en":"When you knew what to do next without being told, what made that possible?"}},"Synth Riders":{"time":20,"setup":{"ko":"Apple Vision Pro 전용이고 Apple Arcade 구독이 필요해요.","en":"It runs only on Apple Vision Pro and needs an Apple Arcade subscription."},"missions":[{"ko":"컨트롤러 없이 첫 곡을 시작해 보세요. 맨손으로 노트를 잡는다는 걸 처음 몇 초 안에 어떻게 이해하게 되는지 살펴보세요.","en":"Start your first song with no controllers. Notice how, within seconds, you understand that your bare hands catch the notes."},{"ko":"이어진 레일을 손으로 끝까지 따라 그려 보세요. 목표물을 치는 느낌과 춤추는 느낌이 어디서 갈리는지 몸으로 느껴 보세요.","en":"Trace a continuous rail all the way with your hand. Feel in your body where hitting targets turns into dancing."},{"ko":"같은 곡을 완전 몰입 모드와 혼합 현실 모드로 한 번씩 해 보세요. 내 방이 포털로 바뀔 때 집중도와 안정감이 어떻게 달라지는지 비교해 보세요.","en":"Play the same song once in full immersion and once in mixed reality. Compare how focus and comfort change when your room becomes a portal."},{"ko":"박자를 놓치거나 장애물에 걸려 보세요. 실패를 어떤 비주얼과 소리로 알려 주는지 관찰해 보세요.","en":"Miss a beat or clip an obstacle. Watch which visuals and sounds tell you that you failed."},{"ko":"곡이 끝나면 메뉴로 돌아가 보세요. 음악에 반응하는 비주얼이 메뉴와 화면 이동에서도 이어지는지 확인해 보세요.","en":"When the song ends, go back to the menus. Check whether the audio-reactive visuals carry on into navigation."}],"make":[{"ko":"내 앱의 탭 버튼 하나를 길게 끄는 드래그 제스처로 바꾼 프로토타입을 만들고, 누르기와 따라 그리기의 손맛을 비교해 보세요.","en":"Prototype one tap button in your app as a long drag gesture instead, and compare how pressing and tracing feel."},{"ko":"내 앱의 배경 애니메이션 하나를 재생 중인 소리나 타이머 값에 반응하게 연결하고, 메뉴 화면에도 같은 반응을 이어 보세요.","en":"Hook one background animation in your app to live audio or a timer value, then carry the same reaction into your menu screens."}],"ask":{"ko":"레일을 따라 그릴 때 게임이 아니라 춤처럼 느끼게 만든 요소는 무엇이었나요?","en":"When tracing rails, what made it feel like dancing rather than playing a game?"}},"CREME":{"time":5,"setup":{"ko":"App Store에서 내려가 직접 해 볼 수 없어요. 개발사가 공개한 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so you can only explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사의 트레일러나 스크린숏에서 첫 장면을 보세요. 요리 테마라는 걸 몇 초 만에 알아차리는지 세어 보세요.","en":"Look at the opening shot of the developer's trailer or screenshots. Count how many seconds it takes to realize it is about cooking."},{"ko":"영상에서 요리하는 장면 하나에서 멈춰 보세요. 색, 움직임, 소리 중 무엇이 즐거움과 재미 결선작다운 유쾌함을 만드는지 적어 보세요.","en":"Pause on one cooking moment in the video. Write down whether color, motion or sound creates the playfulness of a Delight and Fun finalist."},{"ko":"스크린숏 몇 장을 나란히 놓고 보세요. 화면마다 반복되는 시각 요소가 무엇인지 찾아보세요.","en":"Line up several screenshots side by side. Find the visual elements that repeat across screens."}],"make":[{"ko":"내 앱의 평범한 동작 하나를 골라, 요리처럼 재료를 넣고 완성되는 순간이 있는 짧은 연출로 바꾼 스케치를 그려 보세요.","en":"Take one ordinary action in your app and sketch it as a short sequence with ingredients going in and a finished moment, like cooking."},{"ko":"내 앱 스크린숏 세 장만 다른 사람에게 보여 주고, 앱의 분위기를 한 단어로 말해 달라고 해 보세요.","en":"Show just three screenshots of your app to someone and ask them to describe its mood in one word."}],"ask":{"ko":"직접 해 볼 수 없는 앱을 영상만 보고 재미를 알 수 있었나요, 아니라면 무엇이 빠져 있었나요?","en":"Could you tell it was fun from footage alone, and if not, what was missing?"}},"Endling":{"time":20,"setup":{"ko":"3,500원 유료 게임이에요.","en":"It is a paid game (₩3,500)."},"missions":[{"ko":"게임을 시작하고 첫 몇 분 동안 어미 여우를 움직여 보세요. 조작을 익히는 데 얼마나 걸렸는지, 그 사이 시선이 어디에 머물렀는지 살펴보세요.","en":"Start the game and move the mother fox for the first few minutes. Notice how long the controls took to learn and where your eyes stayed meanwhile."},{"ko":"새끼들을 데리고 먹이를 찾아 나서 보세요. 새끼가 뒤따를 때 내 움직임이 얼마나 조심스러워지는지 몸으로 느껴 보세요.","en":"Head out to find food with your cubs. Feel how much more careful your movements become with them following you."},{"ko":"인간이 만든 위험이나 인간 캐릭터를 처음 만나면 잠시 멈춰 보세요. 설명 글 없이 상황과 지형만으로 어떤 메시지가 전해지는지 적어 보세요.","en":"When you first meet a man-made danger or a human character, pause. Write down what message the situation and level alone convey, with no exposition."},{"ko":"위험에 걸려 위기를 겪거나 실패해 보세요. 단순한 조작이 그 순간의 감정을 방해하지 않는지 관찰해 보세요.","en":"Get caught by a danger and face a setback or failure. Watch whether the simple controls stay out of the way of the emotion."}],"make":[{"ko":"내 앱의 핵심 화면에서 버튼이나 제스처를 하나씩 빼 보며, 꼭 필요한 조작 두세 개만 남긴 버전을 만들어 보세요.","en":"On your app's main screen, remove buttons or gestures one by one until only the two or three essential controls remain."},{"ko":"내 앱이 전하려는 메시지 하나를 문구 없이 화면 상황만으로 보여 주는 빈 상태나 온보딩을 스케치해 보세요.","en":"Sketch an empty state or onboarding screen that shows one message of your app through the situation on screen, with no copy."}],"ask":{"ko":"여우를 지켜보는 게 아니라 직접 연기한다고 느낀 순간은 언제였나요?","en":"When did you feel you were being the fox rather than watching it?"}},"MARVEL SNAP":{"time":15,"setup":null,"missions":[{"ko":"첫 대전을 시작해 보세요. 12장 덱, 3개 지역, 6턴이라는 규칙을 몇 판 만에 이해하게 되는지 살펴보세요.","en":"Start your first match. Notice how many matches it takes to grasp the 12 cards, three locations, six turns format."},{"ko":"한 판을 처음부터 끝까지 시간을 재며 해 보세요. 폰을 잠깐 꺼낸 시간에 맞는 길이인지 느껴 보세요.","en":"Time one match from start to finish. Feel whether it fits the moment you pull out your phone."},{"ko":"지역이 공개되면 그 규칙을 읽고 카드 배치를 바꿔 보세요. 덱은 그대로인데 판이 어떻게 달라지는지 관찰해 보세요.","en":"When a location is revealed, read its rule and change where you play cards. Watch how the match changes while your deck stays the same."},{"ko":"유리할 때 스냅으로 판돈을 올리고, 불리할 땐 후퇴해 보세요. 블러핑과 손실 줄이기가 손끝에서 어떤 긴장을 만드는지 느껴 보세요.","en":"Snap to double the stakes when ahead and retreat when behind. Feel the tension that bluffing and cutting losses put in your fingertips."},{"ko":"강한 카드를 낼 때 애니메이션과 햅틱에 집중해 보세요. 진동을 어느 순간에만 아껴 쓰는지 세어 보세요.","en":"Focus on the animation and haptics when you play a big card. Count the moments where vibration is used, and where it is held back."}],"make":[{"ko":"내 앱의 핵심 작업 하나에 걸리는 시간을 재고, 몇 분 안에 끝나도록 단계를 줄인 버전을 만들어 보세요.","en":"Time one core task in your app and build a version with fewer steps that finishes in a few minutes."},{"ko":"내 앱에서 가장 중요한 순간 두세 곳에만 햅틱을 넣고, 나머지는 빼서 전후를 비교해 보세요.","en":"Keep haptics only on the two or three most important moments in your app, remove the rest, and compare."},{"ko":"내 앱의 보상 하나를 기능 강화가 아니라 외형 변화로 바꾸면 어떻게 보일지 화면 하나로 만들어 보세요.","en":"Mock up one screen showing a reward in your app as a cosmetic change instead of a power boost."}],"ask":{"ko":"한 판이 짧다는 사실이 한 판 더를 누르게 만들었나요, 아니면 다른 요소였나요?","en":"Was it the short match length that made you play one more, or something else?"}},"Overboard!":{"time":30,"setup":{"ko":"9,900원 유료 게임이고 광고나 인앱 구매는 없어요.","en":"It is a paid game (₩9,900) with no ads or in-app purchases."},"missions":[{"ko":"첫 회차를 시작해 보세요. 내가 살인범이라는 사실을 게임이 얼마나 빨리, 어떤 방식으로 알려 주는지 살펴보세요.","en":"Start your first run. Notice how quickly, and how, the game tells you that you are the murderer."},{"ko":"NPC 한 명에게 거짓말을 하고 시간이 지난 뒤 다시 말을 걸어 보세요. 그 인물이 내 말이나 본 것을 기억하는지 확인해 보세요.","en":"Lie to one character, then talk to them again later. Check whether they remember what you said or what they saw."},{"ko":"일부러 위험한 선택을 하며 한 회차를 끝까지 가 보세요. 실패한 결말이 다음 회차를 위한 정보로 바뀌는지 느껴 보세요.","en":"Make risky choices on purpose and play one run to the end. Feel how a failed ending turns into information for the next run."},{"ko":"두 번째 회차를 시작해 첫 회차에서 알게 된 것을 써 보세요. 짧은 회차가 반복을 얼마나 덜 지루하게 만드는지 확인해 보세요.","en":"Start a second run and use what you learned. See how the short run length keeps repetition from feeling tedious."}],"make":[{"ko":"내 앱의 실패나 오류 화면 하나를 골라, 다음 시도에 도움이 되는 정보 한 줄을 보여 주도록 바꿔 보세요.","en":"Pick one failure or error screen in your app and change it to show one line that helps the next attempt."},{"ko":"내 앱의 다음 기능을 하루 안에 만들 수 있는 가장 작은 버전으로 줄여 범위를 목록으로 적어 보세요.","en":"Shrink your next feature to the smallest version you could build in one day, and write that scope down as a list."}],"ask":{"ko":"두 번째 회차에서 첫 회차의 실패는 어떤 정보로 쓰였나요?","en":"In your second run, what information did the first run's failure give you?"}},"What Remains of Edith Finch":{"time":30,"setup":{"ko":"7,700원 유료 게임이고, 한두 번 앉아서 끝까지 할 수 있는 길이예요.","en":"It is a paid game (₩7,700), short enough to finish in one or two sittings."},"missions":[{"ko":"게임을 시작해 집 안을 처음 걸어 보세요. 1인칭 이동이 터치로 어떻게 옮겨졌는지, 처음 몇 분간 손가락이 어디에 머무는지 살펴보세요.","en":"Start the game and take your first walk through the house. Notice how first-person movement maps to touch and where your fingers rest."},{"ko":"걸으면서 공간에 떠 있는 내레이션 글자를 따라가 보세요. 글자가 장면에 반응할 때 읽기가 탐험처럼 느껴지는지 확인해 보세요.","en":"Follow the narration text floating in the space as you walk. Check whether reading feels like exploring when the words react to the scene."},{"ko":"새 이야기로 넘어갈 때마다 조작 방식이 어떻게 바뀌는지 적어 보세요. 새 조작을 설명 없이 익히게 하는 방법을 관찰해 보세요.","en":"Each time a new story begins, note how the controls change. Watch how you learn each new scheme without explanation."},{"ko":"통조림 공장 장면에서 한 손으로 생선을 손질하며 다른 손으로 상상 속 모험을 조종해 보세요. 두 손이 따로 노는 피로와 해방감을 느껴 보세요.","en":"In the cannery, chop fish with one thumb while steering the daydream with the other. Feel the drudgery and the escape in your two hands."}],"make":[{"ko":"내 앱의 안내 문구 하나를 화면 위에 덮지 말고, 관련 콘텐츠 바로 옆이나 안에 배치한 버전을 만들어 보세요.","en":"Take one instructional message in your app off the overlay and place it right beside or inside the content it refers to."},{"ko":"내 앱에서 전하고 싶은 감정 하나를 정하고, 그 감정을 버튼이 아닌 조작 방식 하나로 표현하는 작은 프로토타입을 만들어 보세요.","en":"Pick one feeling you want your app to convey and build a small prototype that expresses it through a control scheme, not a button."}],"ask":{"ko":"통조림 공장 장면에서 조작 자체가 이야기를 대신 들려준 순간은 언제였나요?","en":"In the cannery sequence, when did the controls themselves tell the story?"}},"Odio":{"time":10,"setup":{"ko":"머리 추적 공간 음향을 느끼려면 AirPods가 필요해요. 무료로 체험할 수 있어요.","en":"You need AirPods to feel the head-tracked Spatial Audio; it is free to try."},"missions":[{"ko":"앱을 처음 열고 사운드스케이프 하나를 재생해 보세요. 첫 소리가 나오기까지 몇 번 탭했는지 세어 보세요.","en":"Open the app for the first time and play a soundscape. Count the taps until the first sound plays."},{"ko":"AirPods를 끼고 천천히 고개를 돌려 보세요. 폭포나 강물 소리가 머리를 따라오지 않고 제자리에 머무는 느낌을 확인해 보세요.","en":"Wear AirPods and slowly turn your head. Notice the waterfall or river staying in place instead of following you."},{"ko":"원형 믹싱 화면에서 소리 레이어 하나를 내 뒤쪽으로 옮겨 보세요. 슬라이더 대신 위치를 옮기는 조작이 얼마나 직관적인지 느껴 보세요.","en":"In the circular mixer, move one sound layer behind you. Feel how intuitive placing a sound is compared with a slider."},{"ko":"소리가 바뀔 때 화면 애니메이션을 지켜보세요. 움직임이 소리와 얼마나 정확히 맞물리는지 관찰해 보세요.","en":"Watch the animation as the sound changes. Observe how tightly the motion locks to the audio."}],"make":[{"ko":"내 앱의 설정 슬라이더 하나를 원 위의 점을 끌어 옮기는 방식으로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype one settings slider in your app as a dot you drag around a circle."},{"ko":"내 앱에서 소리나 햅틱이 나는 순간 하나에 화면 애니메이션 타이밍을 정확히 맞춰 보세요.","en":"Pick one moment in your app with sound or haptics and sync its on-screen animation to exactly the same timing."}],"ask":{"ko":"소리를 손으로 옮기는 경험은 슬라이더로 볼륨을 조절할 때와 무엇이 달랐나요?","en":"How did moving a sound by hand differ from adjusting volume with a slider?"}},"Pok Pok Playroom":{"time":15,"setup":{"ko":"구독형 앱이고, 2세에서 8세 사이 아이와 함께 해 보면 더 좋아요.","en":"It is a subscription app, and it is best tried alongside a child aged 2 to 8."},"missions":[{"ko":"앱을 처음 열고 놀이방 하나에 들어가 보세요. 글자 하나 없이 어디를 눌러야 할지 어떻게 알게 되는지 살펴보세요.","en":"Open the app and enter a playroom. Notice how you know where to tap without a single word on screen."},{"ko":"놀이방 안의 물건을 여러 번 탭하고 끌어 보세요. 햅틱과 효과음이 손끝에 실물 같은 느낌을 주는지 느껴 보세요.","en":"Tap and drag objects in a playroom many times. Feel whether the haptics and sounds make them seem physical."},{"ko":"5분 넘게 놀아 보세요. 점수, 실패, 보상 알림이 한 번이라도 나오는지 확인하고 그 빈자리가 어떤 느낌인지 적어 보세요.","en":"Play for more than five minutes. Check whether any score, failure or reward ever appears, and write down how that absence feels."},{"ko":"비행기 모드를 켜고 다른 놀이방을 열어 보세요. 오프라인에서도 똑같이 동작하는지 확인해 보세요.","en":"Turn on Airplane Mode and open another playroom. Confirm it works the same offline."}],"make":[{"ko":"내 앱의 한 화면에서 글자를 모두 지우고, 아이콘과 움직임만으로 쓸 수 있는지 다른 사람에게 시켜 보세요.","en":"Strip all text from one screen of your app and ask someone to use it with icons and motion alone."},{"ko":"내 앱의 탭 피드백 하나에 짧은 효과음과 가벼운 햅틱을 함께 맞춰 넣고, 넣기 전과 비교해 보세요.","en":"Add a matched short sound and light haptic to one tap in your app, and compare it with the original."},{"ko":"내 앱의 점수나 배지 하나를 없앤 버전을 만들어, 그래도 계속 쓰고 싶은지 스스로 확인해 보세요.","en":"Build a version of your app without one score or badge, and check whether you still want to keep using it."}],"ask":{"ko":"점수도 실패도 없는데 계속 만지고 싶게 만든 건 무엇이었나요?","en":"With no score and no failure, what kept you wanting to touch things?"}},"Be My Eyes":{"time":15,"setup":{"ko":"무료예요. 시각장애 사용자 흐름을 체험하려면 VoiceOver를 켤 준비를 해 두세요.","en":"It is free; be ready to turn on VoiceOver to try the blind user flow."},"missions":[{"ko":"앱을 처음 열고 첫 화면을 보세요. 사람 봉사자와 Be My AI 중 무엇을 쓸지 고르게 하는 방식과 연결까지의 단계를 살펴보세요.","en":"Open the app and look at the first screen. Notice how it lets you choose between a human volunteer and Be My AI, and count the steps to a call."},{"ko":"VoiceOver를 켜고 시각장애 사용자 쪽 흐름을 따라가 보세요. 큰 동작 하나에 닿기까지 스와이프를 몇 번 했는지 세어 보세요.","en":"Turn on VoiceOver and follow the blind user flow. Count the swipes it takes to reach the one big action."},{"ko":"Be My AI로 주변 물건 사진을 찍고 자연어로 후속 질문을 해 보세요. 답이 막힐 때 사람 봉사자 연결을 어떻게 제안하는지 살펴보세요.","en":"Photograph something nearby with Be My AI and ask follow-up questions in plain language. Notice how it offers a human volunteer when it cannot answer."},{"ko":"봉사자로 가입해 보세요. 1,140만 명 중 한 명이 되는 과정이 얼마나 짧고, 응답만을 위한 화면이 얼마나 단순한지 확인해 보세요.","en":"Sign up as a volunteer. See how short it is to become one of 11.4 million, and how minimal the answer-only flow is."}],"make":[{"ko":"내 앱의 핵심 화면을 VoiceOver로만 써 보고, 가장 중요한 동작에 닿는 스와이프 수를 줄이도록 요소 순서를 바꿔 보세요.","en":"Use your app's main screen with VoiceOver only, then reorder elements so the most important action takes fewer swipes."},{"ko":"내 앱의 첫 화면을 사용자 유형별로 큰 동작 하나만 남긴 두 버전으로 그려 보세요.","en":"Sketch two versions of your app's first screen, one per user type, each with a single large action."}],"ask":{"ko":"같은 앱이 두 사용자에게 전혀 다른 얼굴을 보여 주는 방식을 내 앱에는 어떻게 적용할 수 있을까요?","en":"How could your app show two very different faces to two kinds of users, as this one does?"}},"League of Legends: Wild Rift":{"time":30,"setup":{"ko":"무료이지만 한 경기가 15~20분 걸리니 끊기지 않을 시간을 확보하세요.","en":"It is free, but a match takes 15 to 20 minutes, so set aside uninterrupted time."},"missions":[{"ko":"첫 경기나 튜토리얼을 시작해 보세요. 가상 조이스틱과 스킬 버튼에 손가락이 자리 잡기까지 얼마나 걸리는지 살펴보세요.","en":"Start your first match or tutorial. Notice how long it takes your thumbs to settle on the virtual joystick and ability buttons."},{"ko":"스킬 버튼을 드래그해 직접 조준도 해 보고, 그냥 눌러 자동 타겟팅에도 맡겨 보세요. 두 방식이 언제 편한지 비교해 보세요.","en":"Drag an ability button to aim it yourself, then just tap and let auto-targeting help. Compare when each feels right."},{"ko":"카메라 설정을 바꾸고 다시 플레이해 보세요. 작은 화면의 시야 한계가 얼마나 보완되는지 느껴 보세요.","en":"Change the camera settings and play again. Feel how much they compensate for the small screen."},{"ko":"한 경기를 끝까지 하며 시간을 재 보세요. PC의 45분짜리 경기가 15~20분으로 압축된 밀도를 몸으로 느껴 보세요.","en":"Time a full match. Feel the density of a 45-minute PC match squeezed into 15 to 20 minutes."},{"ko":"쓰러져 부활을 기다리는 순간을 겪어 보세요. 기다림이 얼마나 짧게 느껴지는지 확인해 보세요.","en":"Get taken down and wait to respawn. Notice how short the wait feels."}],"make":[{"ko":"내 앱에서 정밀한 입력이 필요한 동작 하나에 자동 보정 기본값을 넣고, 숙련자용 수동 조절은 따로 남겨 보세요.","en":"Give one precision input in your app an assisted default, while keeping a manual option for experienced users."},{"ko":"데스크톱이나 웹에서 쓰던 기능 하나를 골라, 그대로 옮기지 않고 폰 세션 길이에 맞게 단계를 줄인 흐름을 설계해 보세요.","en":"Take one desktop or web feature and redesign it, not port it, with fewer steps sized to a phone session."}],"ask":{"ko":"이식이 아니라 다시 만들었다는 차이를 가장 크게 느낀 곳은 어디였나요?","en":"Where did you feel most clearly that it was rebuilt rather than ported?"}},"Song of Bloom":{"time":20,"setup":{"ko":"3,300원 유료 게임이고, 충전 케이블을 가까이 두세요.","en":"It is a paid game (₩3,300); keep your charging cable nearby."},"missions":[{"ko":"첫 장면을 열고 설명 없이 할 수 있는 걸 전부 시도해 보세요. 게임이 내 첫 시도에 어떤 반응을 돌려주는지 살펴보세요.","en":"Open the first scene and try everything you can without instructions. Notice how the game answers your first attempts."},{"ko":"한 장면에서 막히면 다른 갈래의 장면으로 넘어가 보세요. 막힘이 멈춤이 아니라 우회로가 되는 구조를 느껴 보세요.","en":"When stuck in one scene, move to another branch. Feel how being stuck becomes a detour rather than a dead end."},{"ko":"화면 밖 행동이 필요해 보이면 충전 케이블을 꽂는 것처럼 기기 자체로 시도해 보세요. 제4의 벽을 넘는 순간의 기분을 적어 보세요.","en":"When a puzzle seems to need something off-screen, try the device itself, like plugging in the cable. Write down how breaking the fourth wall feels."},{"ko":"장면을 옮길 때마다 점토, 뜨개질, 스케치, 조각 중 무엇으로 만든 것 같은지 맞혀 보세요. 질감이 바뀔 때 새 작품에 들어서는 느낌을 확인해 보세요.","en":"At each new scene, guess whether it was made with clay, knitting, sketching or carving. Notice how a change in texture feels like entering a new artwork."}],"make":[{"ko":"내 앱에서 충전, 기울기, 밝기 같은 기기 상태 하나를 입력으로 쓰는 작은 이스터에그를 프로토타입으로 만들어 보세요.","en":"Prototype a small easter egg in your app that uses a device state, such as charging, tilt or brightness, as input."},{"ko":"내 앱의 흐름 하나를 일직선이 아니라 두 갈래로 나눠, 한쪽에서 막혀도 다른 쪽으로 진행할 수 있게 그려 보세요.","en":"Redraw one linear flow in your app as two branches, so getting stuck on one still lets people progress on the other."}],"ask":{"ko":"기기를 직접 건드려야 했던 퍼즐은 화면 속 퍼즐과 어떻게 다르게 기억되나요?","en":"How does a puzzle that made you touch the device stick in memory differently from an on-screen one?"}},"Sleep Cycle":{"time":10,"setup":{"ko":"밤새 머리맡에 둘 폰이 필요하고, 첫 결과는 다음 날 아침에 볼 수 있어요.","en":"You need to leave your phone by your bed overnight, and the first results arrive the next morning."},"missions":[{"ko":"처음 설정을 따라가 보세요. 마이크 권한, 배터리, 폰 위치를 어떤 순서와 말투로 설명하는지 살펴보세요.","en":"Go through the first setup. Notice the order and tone used to explain microphone access, battery and phone placement."},{"ko":"기상 시간을 정하고 스마트 알람을 켜 보세요. 앱의 핵심 가치를 알람 하나로 얼마나 짧게 설명하는지 확인해 보세요.","en":"Set a wake-up time and turn on the smart alarm. See how briefly the app explains its core value through one alarm."},{"ko":"폰을 머리맡에 두고 하룻밤 자 보세요. 정한 시각보다 조금 일찍, 얕은 잠에서 깨는 느낌을 몸으로 느껴 보세요.","en":"Sleep one night with the phone by your bed. Feel what it is like to wake a little early from light sleep."},{"ko":"아침에 그래프와 수면 점수를 열어 보세요. 다음 날도 확인하고 싶어지게 만드는 요소가 무엇인지 적어 보세요.","en":"In the morning, open the graph and sleep score. Write down what makes you want to check again tomorrow."},{"ko":"코골이 감지 같은 프리미엄 기능에 닿아 보세요. 무료와 유료의 경계를 어디서 보여 주는지 관찰해 보세요.","en":"Reach a premium feature such as snore detection. Observe where the line between free and paid is drawn."}],"make":[{"ko":"내 앱이 요청하는 권한 하나를 골라, 왜 필요하고 무엇이 좋아지는지 두 줄로 설명하는 사전 안내 화면을 만들어 보세요.","en":"Pick one permission your app requests and build a pre-prompt screen that explains in two lines why it is needed and what it improves."},{"ko":"내 앱의 핵심 가치를 기능 하나로 압축한다면 무엇인지 정하고, 첫 실행 화면에 그것만 남긴 버전을 그려 보세요.","en":"Decide which single feature captures your app's core value, and sketch a first-run screen with only that."},{"ko":"내 앱의 기록을 매일 아침 확인할 숫자 하나로 요약한 위젯을 스케치해 보세요.","en":"Sketch a widget that sums up your app's data as one number worth checking every morning."}],"ask":{"ko":"밤새 마이크를 켜 두는 부담을 받아들이게 만든 설명은 무엇이었나요?","en":"What explanation made you willing to leave the microphone on all night?"}},"Obsidian":{"time":15,"setup":null,"missions":[{"ko":"처음 볼트를 만들어 보세요. 노트가 내 기기 폴더의 마크다운 파일로 저장된다는 사실을 어떤 말로 알려 주는지 살펴보세요.","en":"Create your first vault. Notice how it tells you that notes are saved as Markdown files in a folder on your device."},{"ko":"노트 두 개를 만들고 [[위키링크]]로 서로 연결해 보세요. 작은 키보드로 링크를 거는 과정이 얼마나 매끄러운지 관찰해 보세요.","en":"Make two notes and link them with a [[wikilink]]. Watch how smooth linking is on a small keyboard."},{"ko":"연결한 노트의 백링크와 그래프 뷰를 열어 보세요. 폴더 대신 연결로 정리된 정보가 작은 화면에서 어떻게 보이는지 확인해 보세요.","en":"Open the backlinks and graph view for those notes. See how information organized by links, not folders, looks on a small screen."},{"ko":"설정과 플러그인을 둘러보세요. 확장성이 모바일 화면에 얼마나 많은 메뉴 부담을 만드는지 세어 보세요.","en":"Browse the settings and plugins. Count how much menu weight that extensibility puts on a phone screen."},{"ko":"동기화 옵션을 찾아보세요. 무료 코어와 유료 Sync의 경계를 어떻게 안내하는지 살펴보세요.","en":"Look for the sync options. Notice how the free core and paid Sync are separated."}],"make":[{"ko":"내 앱 데이터 하나를 사람이 읽을 수 있는 마크다운이나 JSON 파일로 내보내는 기능을 만들어, 앱 없이도 열리는지 확인해 보세요.","en":"Build an export of one kind of data in your app as readable Markdown or JSON, and check that it opens without your app."},{"ko":"내 앱의 설정 항목을 모두 세어 보고, 처음 쓰는 사람에게 꼭 필요한 다섯 개만 앞에 남겨 보세요.","en":"Count every settings item in your app and keep only the five a first-time user really needs up front."}],"ask":{"ko":"데이터가 내 파일로 남는다는 사실이 앱을 대하는 마음을 어떻게 바꿨나요?","en":"How did knowing your data stays as your own files change how you feel about the app?"}},"Claude":{"time":15,"setup":null,"missions":[{"ko":"앱을 처음 열고 첫 질문을 보내 보세요. 답이 스트리밍으로 나타날 때 언제부터 읽기 시작할 수 있는지 살펴보세요.","en":"Open the app and send your first question. Notice when you can start reading as the answer streams in."},{"ko":"긴 설명이나 코드가 나오는 질문을 해 보세요. 제목, 목록, 코드 블록이 작은 화면에서 훑어 읽기 좋게 나뉘는지 확인해 보세요.","en":"Ask something that needs a long answer or code. Check whether headings, lists and code blocks make it skimmable on a small screen."},{"ko":"문서나 간단한 인터랙티브 결과물을 만들어 달라고 해 보세요. 아티팩트가 대화와 분리되어 열릴 때 스크롤이 얼마나 덜 복잡해지는지 느껴 보세요.","en":"Ask it to make a document or a small interactive piece. Feel how much cleaner the scroll is when the artifact opens apart from the chat."},{"ko":"카메라나 사진 보관함으로 이미지를 올려 질문해 보세요. 타이핑 없이 입력이 끝나는 흐름을 관찰해 보세요.","en":"Ask about an image from the camera or photo library. Watch how input is done without typing."},{"ko":"같은 대화를 웹이나 데스크톱에서 열어 보세요. 폰에서 시작한 작업이 그대로 이어지는지 확인해 보세요.","en":"Open the same conversation on the web or desktop. Check that the work you started on the phone carries over."}],"make":[{"ko":"내 앱에서 결과물이 긴 목록에 묻히는 화면 하나를 골라, 결과물을 별도 시트로 띄우는 프로토타입을 만들어 보세요.","en":"Pick a screen in your app where results get buried in a long list, and prototype showing the result in its own sheet."},{"ko":"내 앱의 긴 텍스트 화면 하나에 제목과 목록 위계를 적용해, 3초 안에 훑을 수 있는지 시험해 보세요.","en":"Apply heading and list hierarchy to one long text screen in your app and test whether it can be skimmed in three seconds."}],"ask":{"ko":"긴 결과물을 작은 화면에서 다룰 때 가장 도움이 된 장치는 무엇이었나요?","en":"What helped most in handling long output on a small screen?"}},"배달의민족":{"time":10,"setup":{"ko":"무료예요. 주문하지 않고 둘러보기만 해도 충분해요.","en":"It is free, and browsing without ordering is enough."},"missions":[{"ko":"앱을 열고 첫 화면의 글자체를 살펴보세요. 로고를 손으로 가려도 배민이라는 걸 알아볼 수 있는지 확인해 보세요.","en":"Open the app and study the typefaces on the first screen. Cover the logo with your hand and check whether you still know it is Baemin."},{"ko":"프로모션 배너와 문구를 몇 개 읽어 보세요. B급 유머와 말장난이 기능 설명을 방해하는지, 오히려 기억에 남게 하는지 판단해 보세요.","en":"Read a few promo banners and lines of copy. Judge whether the cheeky humor and puns get in the way or make things memorable."},{"ko":"푸시 알림을 허용하고 며칠 동안 오는 문구를 모아 보세요. 알림 한 줄에도 같은 목소리가 유지되는지 확인해 보세요.","en":"Allow push notifications and collect the messages for a few days. Check whether even one-line alerts keep the same voice."},{"ko":"배민1, B마트, 배민클럽 같은 확장 서비스로 들어가 보세요. 서비스가 달라져도 서체와 톤이 이어지는지 관찰해 보세요.","en":"Visit expansion services like Baemin1, B Mart or Baemin Club. Watch whether type and tone stay consistent across them."}],"make":[{"ko":"내 앱의 버튼과 안내 문구 열 개를 모아, 한 캐릭터가 말하는 듯한 같은 톤으로 다시 써 보세요.","en":"Gather ten button labels and messages from your app and rewrite them in one consistent voice, as if one character were speaking."},{"ko":"내 앱 화면 하나에서 로고와 앱 이름을 가리고, 글자체와 색만으로 내 앱인지 알아볼 수 있는지 다른 사람에게 물어보세요.","en":"Hide the logo and name on one of your screens and ask someone whether they can recognize your app from type and color alone."}],"ask":{"ko":"배민의 서체와 문구 중 무엇이 기능보다 먼저 기억에 남았나요?","en":"Which of Baemin's typefaces or lines of copy stuck with you before any feature did?"}},"PowerWash Simulator":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"ko":"첫 작업을 시작해 보세요. 물을 뿌리자마자 때가 사라지고 완료율이 오르는 피드백이 몇 초 만에 오는지 살펴보세요.","en":"Start your first job. Notice how many seconds it takes for grime to vanish and the completion rate to climb once you spray."},{"ko":"스크래치 모드로 바꿔 손가락으로 직접 때를 문질러 보세요. 노즐을 조준할 때와 손맛이 어떻게 다른지 느껴 보세요.","en":"Switch to Scratch Mode and rub the grime away with your finger. Feel how it differs from aiming a nozzle."},{"ko":"부품 하나를 끝까지 닦아 보세요. 완료 순간 울리는 딩 소리가 얼마나 큰 만족을 주는지 확인해 보세요.","en":"Clean one part completely. Notice how satisfying the ding is when it finishes."},{"ko":"마지막 얼룩이 안 보일 때 스마트 작업 진행 목록을 확인해 보세요. 남은 1%를 찾아 헤매는 답답함이 얼마나 줄어드는지 관찰해 보세요.","en":"When you cannot find the last spot, check the smart job progress list. Observe how much it eases the hunt for the final 1%."},{"ko":"자이로 조준을 켜고 기기를 기울여 조준해 보세요. 터치 조작과 비교해 어떤 상황에서 더 편한지 적어 보세요.","en":"Turn on gyro aiming and aim by tilting the device. Write down when it beats touch controls."}],"make":[{"ko":"내 앱의 진행 상황을 완료율 숫자로 실시간 보여 주고, 단위 하나를 끝낼 때 짧은 소리를 넣은 프로토타입을 만들어 보세요.","en":"Prototype a live completion percentage in your app, with a short sound each time one unit is finished."},{"ko":"내 앱의 체크리스트에서 아직 안 끝난 항목 위치로 바로 데려다 주는 버튼을 만들어 보세요.","en":"Add a button to a checklist in your app that jumps straight to the next unfinished item."}],"ask":{"ko":"제한 시간도 실패도 없는데 계속 닦고 싶게 만든 가장 큰 피드백은 무엇이었나요?","en":"With no timer and no failure, which feedback made you want to keep cleaning?"}},"Blue Prince":{"time":30,"setup":{"ko":"Mac 전용이고 32,000원 유료 게임이에요. 종이와 펜을 곁에 두면 좋아요.","en":"It runs only on Mac and costs ₩32,000; keep paper and a pen nearby."},"missions":[{"ko":"첫날을 시작해 저택에 들어가 보세요. 목표와 걸음 수 제한을 어떤 방식으로 알게 되는지 살펴보세요.","en":"Start your first day and enter the manor. Notice how you learn the goal and the step limit."},{"ko":"문을 열 때마다 나오는 평면도 3장 중 하나를 골라 보세요. 탐험하면서 동시에 지도를 짓는 감각을 손으로 느껴 보세요.","en":"Each time you open a door, pick one of the three floor plans. Feel what it is like to build the map while exploring it."},{"ko":"종이에 방 이름, 단서, 숫자를 적으며 플레이해 보세요. 게임이 메모하고 싶게 만드는 순간마다 표시해 보세요.","en":"Play while writing down room names, clues and numbers. Mark each moment the game makes you want to take notes."},{"ko":"걸음이 다 떨어져 하루가 끝날 때까지 가 보세요. 집이 초기화된 뒤 내게 남은 지식이 무엇인지 적어 보세요.","en":"Play until your steps run out and the day ends. Write down what knowledge you kept after the house reset."}],"make":[{"ko":"내 앱에서 고정된 메뉴 대신 무작위 선택지 세 개 중 하나를 고르게 하는 화면을 프로토타입으로 만들어 보세요.","en":"Prototype a screen in your app that offers a pick of three random options instead of a fixed menu."},{"ko":"내 앱의 실패나 초기화 순간에 사용자가 다음에 쓸 정보 하나가 남도록 기록 화면을 그려 보세요.","en":"Sketch a log screen so that a failure or reset in your app leaves the user one piece of information for next time."}],"ask":{"ko":"하루가 초기화됐는데도 다시 시작하고 싶게 만든 것은 무엇이었나요?","en":"When the day reset, what made you want to start again?"}},"Consume Me":{"time":20,"setup":{"ko":"17,000원 유료 게임이고, 섭식 장애를 다루니 내 마음 상태를 살피며 해 보세요.","en":"It is a paid game (₩17,000) about eating disorders, so check in with how you feel as you play."},"missions":[{"ko":"첫날을 시작해 보세요. 일상과 미니게임이 어떤 순서로 소개되는지, 처음 몇 분 동안 무엇을 배우는지 살펴보세요.","en":"Start the first day. Notice the order in which daily life and minigames are introduced, and what you learn in the first minutes."},{"ko":"칼로리 한도 안에서 접시에 음식을 테트리스처럼 끼워 맞춰 보세요. 조각을 밀어 넣는 손놀림에서 주인공의 불안이 느껴지는지 확인해 보세요.","en":"Fit food onto the plate like Tetris within the calorie limit. Check whether you feel the character's anxiety in the act of squeezing pieces in."},{"ko":"하루 일정을 짜며 숙제, 다이어트, 수면, 인간관계에 시간을 나눠 보세요. 무엇을 포기했고 에너지, 기분, 돈이 어떻게 바뀌었는지 적어 보세요.","en":"Plan a day by splitting time across homework, dieting, sleep and relationships. Write down what you gave up and how energy, mood and money changed."},{"ko":"무거운 장면에서 블랙 유머가 나오는 순간을 찾아보세요. 손그림 스타일이 주제의 무게를 어떻게 덜어 주는지 관찰해 보세요.","en":"Find a heavy moment where dark humor appears. Watch how the hand-drawn style eases the weight of the subject."}],"make":[{"ko":"내 앱의 평범한 입력 하나를 작은 퍼즐이나 손맛 있는 조작으로 바꾼 프로토타입을 만들어, 그 조작이 주는 감정을 적어 보세요.","en":"Turn one plain input in your app into a small puzzle or tactile gesture, and write down what feeling it creates."},{"ko":"내 앱에서 사용자가 한정된 자원을 나눠 쓰는 화면을 하나 그리고, 선택의 대가가 바로 보이게 숫자를 붙여 보세요.","en":"Sketch a screen where users split a limited resource, with numbers that show the cost of each choice right away."}],"ask":{"ko":"게임 속 조작이 주인공의 마음을 설명보다 더 잘 전한 순간은 언제였나요?","en":"When did a control in the game express the character's state of mind better than words would?"}},"Denim – Playlist Cover Maker":{"time":10,"setup":null,"missions":[{"ko":"앱을 열고 첫 커버를 만들어 보세요. 스타일 선택, 제목 입력, 미세 조정까지 몇 번 탭했는지 세어 보세요.","en":"Open the app and make your first cover. Count the taps through choosing a style, entering a title and fine-tuning."},{"ko":"장르별 스타일을 여러 개 넘겨 보세요. 스크롤 전환이 손가락을 얼마나 부드럽게 따라오는지, 햅틱이 언제 오는지 느껴 보세요.","en":"Swipe through several genre styles. Feel how smoothly the scroll transitions follow your finger and when the haptics land."},{"ko":"사진 한 장으로 커버를 만들어 보세요. 지능형 크롭과 깊이 효과가 내 손을 얼마나 덜어 주는지 관찰해 보세요.","en":"Make a cover from a photo. Observe how much work the intelligent cropping and depth effect save you."},{"ko":"Spotify, YouTube Music, Apple Music 중 쓰는 서비스를 연결해 커버를 적용해 보세요. 앱을 떠나지 않고 끝나는 흐름을 확인해 보세요.","en":"Connect Spotify, YouTube Music or Apple Music and apply the cover. Check that you finish without leaving the app."},{"ko":"Pro 안내를 찾아보세요. 월간, 연간, 평생 선택지를 어떻게 나란히 보여 주는지 살펴보세요.","en":"Find the Pro offer. Notice how monthly, yearly and lifetime options are presented side by side."}],"make":[{"ko":"내 앱의 빈 캔버스나 빈 입력 화면 하나를 골라, 세 단계 가이드 흐름으로 바꾼 프로토타입을 만들어 보세요.","en":"Pick one blank canvas or empty input screen in your app and prototype it as a three-step guided flow."},{"ko":"SwiftUI로 내 앱의 목록 하나에 스크롤 전환 효과와 메시 그래디언트 배경을 넣어 보고 전후를 비교해 보세요.","en":"In SwiftUI, add scroll transitions and a mesh gradient background to one list in your app, and compare before and after."}],"ask":{"ko":"디자이너가 아닌데도 결과물이 좋아 보인 건 어느 단계 덕분이었나요?","en":"Which step made the result look good even though you are not a designer?"}},"Play":{"time":10,"setup":{"ko":"App Store에서 내려가 직접 해 볼 수 없어요. 개발사가 공개한 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so you can only explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사의 트레일러나 스크린숏에서 첫 화면을 찾아보세요. 새 프로토타입을 어떻게 시작하게 하는지 살펴보세요.","en":"Find the first screen in the developer's trailer or screenshots. Notice how it gets you started on a new prototype."},{"ko":"영상에서 컴포넌트를 배치하는 장면에서 멈춰 보세요. 스택, 모디파이어, 상태가 코드 없이 어떻게 시각적으로 표현되는지 적어 보세요.","en":"Pause where components are being arranged. Write down how stacks, modifiers and state are shown visually without code."},{"ko":"Mac에서 고친 내용이 iPhone에 바로 반영되는 장면을 찾아보세요. 실시간 동기화가 작업 리듬을 어떻게 바꾸는지 상상해 보세요.","en":"Look for a moment where an edit on the Mac shows up on the iPhone right away. Imagine how live sync changes the rhythm of work."},{"ko":"프로토타입이 SwiftUI 코드가 되어 Xcode로 넘어가는 장면을 찾아보세요. 디자인과 개발 사이 번역 단계가 사라지는 순간을 확인해 보세요.","en":"Find where the prototype becomes SwiftUI code and moves into Xcode. Notice the moment the translation step between design and code disappears."}],"make":[{"ko":"내 앱 화면 하나를 스택과 모디파이어 단위로 쪼개 종이에 트리로 그려 보고, 그 트리 그대로 SwiftUI 코드를 써 보세요.","en":"Break one screen of your app into stacks and modifiers as a tree on paper, then write SwiftUI code that follows that tree exactly."},{"ko":"Xcode 프리뷰를 내 iPhone에서 띄워, 코드를 고칠 때마다 기기에서 바로 만져 보는 루프를 만들어 보세요.","en":"Run Xcode Previews on your own iPhone so every code change can be touched on the device right away."}],"ask":{"ko":"디자인 도구가 실제 코드를 만들어 준다면 내 작업 흐름에서 어떤 단계가 사라질까요?","en":"If a design tool produced real code, which step in your workflow would disappear?"}},"Skate City: New York":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"ko":"첫 주행을 시작해 보세요. 버튼 하나 없는 화면에서 어떻게 타야 할지 처음 몇 초 안에 이해하게 되는지 살펴보세요.","en":"Start your first run. Notice whether you understand how to ride within seconds on a screen with no buttons."},{"ko":"화면 아래쪽 절반에서 8방향으로 스와이프하며 왼쪽과 오른쪽 트릭을 번갈아 써 보세요. 방향마다 다른 기술이 손에 붙는지 느껴 보세요.","en":"Swipe in eight directions on the lower half of the screen, alternating left and right tricks. Feel whether each direction becomes muscle memory."},{"ko":"계단이나 장애물에 일부러 걸려 보세요. 자동 착지가 어디까지 도와주고 어디서 실패로 바뀌는지 확인해 보세요.","en":"Catch on stairs or an obstacle on purpose. See how far auto-landing helps and where it turns into a fall."},{"ko":"착지할 때 손에 오는 햅틱에 집중해 보세요. 보드 접지와 착지가 진동으로 어떻게 구분되는지 관찰해 보세요.","en":"Focus on the haptics as you land. Notice how grip and landing feel different through vibration."},{"ko":"프로 스케이트 모드에서 절차 생성된 뉴욕을 달려 보세요. 끝없이 이어지는 거리가 반복된다고 느껴지는 시점이 오는지 확인해 보세요.","en":"Ride the procedurally generated New York in Pro Skate mode. Check whether the endless streets ever start to feel repetitive."}],"make":[{"ko":"내 앱의 버튼 두세 개를 화면 한 영역의 방향 스와이프로 바꾼 프로토타입을 만들어, 버튼 없이도 찾을 수 있는지 시험해 보세요.","en":"Replace two or three buttons in your app with directional swipes in one area of the screen, and test whether people find them."},{"ko":"내 앱의 어려운 동작 하나에 초보자용 자동 보정을 넣고, 실패는 분명한 경우에만 일어나게 조건을 정해 보세요.","en":"Add beginner assistance to one hard action in your app, and define the few clear cases where it should still fail."}],"ask":{"ko":"버튼 없는 조작에서 깊이를 느끼게 한 건 무엇이었나요?","en":"With no buttons at all, what gave the controls their depth?"}},"Control Ultimate Edition":{"time":30,"setup":{"ko":"A17 Pro 이상이나 M 시리즈 칩의 iPhone·iPad, 또는 Apple 실리콘 Mac이 필요하고 가격은 4.99달러예요.","en":"You need an iPhone or iPad with A17 Pro or an M-series chip, or an Apple silicon Mac; it costs $4.99."},"missions":[{"ko":"게임을 시작해 첫 몇 분 동안 터치로 움직이고 조준해 보세요. 콘솔 조작을 그대로 옮기지 않고 무엇을 바꿨는지 살펴보세요.","en":"Start the game and move and aim by touch for the first few minutes. Notice what was changed instead of copying console controls."},{"ko":"염동력으로 주변 물건을 던져 보세요. 파티클과 파괴 효과가 터지는 순간 손바닥 위 기기가 버티는지 눈으로 확인해 보세요.","en":"Throw objects with telekinesis. Watch whether the device in your hands keeps up as particles and debris fly."},{"ko":"올디스트 하우스의 브루탈리즘 공간에서 잠시 멈춰 둘러보세요. 조명과 질감이 분위기를 어떻게 만드는지 관찰해 보세요.","en":"Stop and look around the brutalist spaces of the Oldest House. Observe how light and texture build the mood."},{"ko":"게임 컨트롤러가 있다면 연결해 같은 구간을 다시 해 보세요. 터치와 컨트롤러 중 어느 쪽이 이 게임에 맞는지 비교해 보세요.","en":"If you have a game controller, connect it and replay the same section. Compare which suits the game better, touch or controller."}],"make":[{"ko":"내 앱의 조작 하나를 Mac과 iPhone용으로 따로 설계해 보고, 화면 크기에 따라 무엇이 달라져야 하는지 표로 정리해 보세요.","en":"Design one interaction in your app separately for Mac and iPhone, and list in a table what must change with screen size."},{"ko":"Instruments로 내 앱에서 가장 무거운 애니메이션 화면의 프레임을 측정하고, 한 곳만 골라 최적화해 보세요.","en":"Measure frame rate on your app's heaviest animated screen with Instruments, and optimize one spot."}],"ask":{"ko":"콘솔 게임을 손바닥 위에서 했을 때 가장 놀라웠던 점과 가장 아쉬웠던 점은 무엇이었나요?","en":"Playing a console game in your hand, what surprised you most and what fell short?"}},"Tiimo":{"time":15,"setup":{"ko":"구독형 부분 유료 앱이고, Apple Watch가 있으면 손목에서도 확인해 볼 수 있어요.","en":"It is a freemium subscription app; an Apple Watch lets you try it on your wrist too."},"missions":[{"ko":"앱을 처음 열고 오늘 일정을 만들어 보세요. 첫 블록을 만들기까지 몇 번 탭했는지, 색과 아이콘을 언제 고르게 하는지 살펴보세요.","en":"Open the app and build today's plan. Count the taps to your first block and notice when it asks for a color and icon."},{"ko":"AI 코플래너에게 오늘 할 일을 말이나 글로 털어놓아 보세요. 흩어진 생각이 소요 시간이 붙은 계획으로 바뀌는 과정을 확인해 보세요.","en":"Tell the AI co-planner what is on your mind today, by voice or text. Watch scattered thoughts become a plan with durations."},{"ko":"할 일 하나를 시작하고 시각적 카운트다운을 지켜보세요. 숫자 대신 줄어드는 모양으로 남은 시간이 얼마나 직관적으로 느껴지는지 확인해 보세요.","en":"Start a task and watch the visual countdown. Notice how intuitive remaining time feels as a shrinking shape instead of a number."},{"ko":"할 일 안에 단계별 체크리스트를 넣어 보세요. 다음 할 일로 넘어가는 전환이 어떻게 부드럽게 처리되는지 살펴보세요.","en":"Add a step-by-step checklist inside a task. See how the transition to the next task is softened."},{"ko":"앱을 닫고 위젯, Live Activity, Apple Watch에서 지금 할 일을 확인해 보세요. 앱을 열지 않아도 시간이 보이는지 관찰해 보세요.","en":"Close the app and check the current task on a widget, Live Activity or Apple Watch. Observe whether time stays visible without opening the app."}],"make":[{"ko":"내 앱에서 시간이나 진행률을 숫자로만 보여 주는 곳 하나를 줄어드는 원이나 막대로 바꿔 보세요.","en":"Find one place in your app that shows time or progress only as a number, and turn it into a shrinking ring or bar."},{"ko":"내 앱의 핵심 상태 하나를 Live Activity나 위젯으로 띄워, 앱을 열지 않고도 확인되게 만들어 보세요.","en":"Surface one key state of your app as a Live Activity or widget so it can be checked without opening the app."},{"ko":"내 앱의 긴 작업 하나를 단계별 체크리스트로 쪼갠 화면을 만들어, 시작하기가 쉬워지는지 시험해 보세요.","en":"Break one long task in your app into a step checklist screen and test whether starting gets easier."}],"ask":{"ko":"시간을 색과 모양으로 본 것이 할 일을 시작하는 데 어떤 차이를 만들었나요?","en":"How did seeing time as color and shape change how easily you started a task?"}},"Rytmos":{"time":15,"setup":{"ko":"소리를 켜거나 헤드폰을 끼고 해 보세요.","en":"Play with sound on or headphones in."},"missions":[{"ko":"첫 퍼즐을 설명 없이 풀어 보세요. 글을 읽지 않고도 규칙을 알게 되기까지 몇 초가 걸리는지 세어 보세요.","en":"Solve the first puzzle without instructions. Count the seconds until you understand the rules without reading anything."},{"ko":"드래그로 끊기지 않는 경로를 완성해 보세요. 선 하나를 끝낼 때마다 악기 트랙이 쌓이는 느낌을 확인해 보세요.","en":"Drag out one unbroken path. Notice an instrument track stacking up each time you complete a line."},{"ko":"같은 퍼즐을 다른 경로로 다시 풀어 보세요. 지나는 이미터 순서가 바뀌면 음악이 어떻게 달라지는지 귀로 비교해 보세요.","en":"Solve the same puzzle again by a different route. Listen to how the music changes when you pass the emitters in another order."},{"ko":"레벨을 깬 뒤 잼 모드를 열어 마음껏 연주해 보세요. 규칙이 사라진 보상 공간이 호기심을 어떻게 채워 주는지 느껴 보세요.","en":"After clearing a level, open Jam mode and play freely. Feel how a rule-free reward space feeds your curiosity."},{"ko":"다른 행성으로 넘어가 보세요. 그곳의 음악 전통과 짧은 역사가 플레이 흐름 속에서 어떻게 소개되는지 살펴보세요.","en":"Move on to another planet. Notice how its musical tradition and short history are introduced within the flow of play."}],"make":[{"ko":"내 앱의 온보딩 설명 화면 하나를 지우고, 첫 행동을 직접 해 보며 규칙을 알게 되는 인터랙티브 버전을 만들어 보세요.","en":"Delete one onboarding explanation screen in your app and build an interactive version where people learn by doing the first action."},{"ko":"내 앱의 진행 단계마다 소리나 시각 요소가 한 겹씩 더해지게 만들어, 완성에 가까워지는 느낌을 시험해 보세요.","en":"Make each step of progress in your app add one layer of sound or visuals, and test whether it feels like building toward completion."}],"ask":{"ko":"설명 없이 규칙을 이해하게 된 결정적 순간은 무엇이었나요?","en":"What was the moment you understood the rules without being told?"}},"Lies of P":{"time":30,"setup":{"ko":"Mac 전용이고 64,900원 유료 게임이에요.","en":"It runs only on Mac and costs ₩64,900."},"missions":[{"ko":"게임을 시작해 크라트의 첫 거리를 걸어 보세요. 벨 에포크풍 도시가 첫 몇 분 안에 어떤 인상을 남기는지 적어 보세요.","en":"Start the game and walk Krat's first streets. Write down the impression the Belle Époque city leaves in the first few minutes."},{"ko":"그래픽 설정에서 MetalFX 업스케일링과 볼류메트릭 포그를 켜고 꺼 보세요. 화질과 프레임이 어떻게 맞바뀌는지 눈으로 비교해 보세요.","en":"Toggle MetalFX upscaling and volumetric fog in the graphics settings. Compare with your own eyes how image quality trades against frame rate."},{"ko":"첫 강한 적에게 지고 다시 도전해 보세요. 소울라이크다운 실패와 재도전의 리듬을 느껴 보세요.","en":"Lose to the first tough enemy and try again. Feel the soulslike rhythm of failing and retrying."},{"ko":"무기의 날과 손잡이를 바꿔 조립해 보세요. 조합에 따라 손맛이 어떻게 달라지는지 확인해 보세요.","en":"Swap a weapon's blade and handle. Notice how the feel changes with each combination."},{"ko":"대화에서 거짓말 선택지를 골라 보세요. 피노키오라는 주제가 메커니즘으로 연결되는 순간을 관찰해 보세요.","en":"Choose a lie in a conversation. Watch the Pinocchio theme turn into a mechanic."}],"make":[{"ko":"내 앱의 무거운 화면 하나에 화질 우선과 부드러움 우선 옵션을 만들어 두 모드를 비교해 보세요.","en":"Add a quality-first and a smoothness-first option to one heavy screen in your app, and compare the two."},{"ko":"내 앱의 테마를 흔한 선택 대신 의외의 시대나 장소로 옮긴 무드보드 한 장을 만들어 보세요.","en":"Make one mood board that moves your app's theme to an unexpected era or place instead of the obvious one."}],"ask":{"ko":"크라트의 비주얼 중 가장 오래 기억에 남는 장면은 무엇이고, 왜 그런가요?","en":"Which scene in Krat will you remember longest, and why?"}},"Loóna: Cozy Puzzle Games":{"time":15,"setup":{"ko":"Apple Vision Pro 전용이에요. 무료로 퍼즐 1개를 해 볼 수 있고, 더 하려면 월 구독이 필요해요.","en":"It runs only on Apple Vision Pro; one puzzle is free and more require a monthly subscription."},"missions":[{"ko":"앱을 열고 첫 퍼즐을 내 공간에 띄워 보세요. 3D 디오라마가 방 안 어디에, 어떤 크기로 나타나는지 살펴보세요.","en":"Open the app and bring the first puzzle into your space. Notice where in the room, and at what size, the 3D diorama appears."},{"ko":"조각을 손으로 맞춰 디오라마를 완성해 보세요. 완성된 조각이 움직이는 장면으로 살아나는 순간을 확인해 보세요.","en":"Assemble the pieces with your hands. Watch for the moment the finished pieces come alive as a moving scene."},{"ko":"디오라마 주변을 둘러보며 공간 음향에 귀 기울여 보세요. 소리가 장면 속 위치에서 들려오는지 느껴 보세요.","en":"Look around the diorama and listen to the spatial audio. Feel whether sounds come from their place in the scene."},{"ko":"동반 캐릭터 루모에게 포옹이나 제스처를 해 보세요. 그 반응이 경험을 얼마나 차분하게 만드는지 관찰해 보세요.","en":"Give the companion Lumo a hug or a gesture. Observe how its response calms the experience."},{"ko":"첫 퍼즐을 끝낸 뒤 다음 퍼즐로 가 보세요. 구독 안내가 언제, 어떤 말로 나오는지 살펴보세요.","en":"After the first puzzle, try to go to the next. Notice when, and in what words, the subscription offer appears."}],"make":[{"ko":"RealityKit으로 간단한 3D 모델 하나를 띄우고, 탭하면 짧은 애니메이션으로 살아나게 만들어 보세요.","en":"In RealityKit, place one simple 3D model and make it come alive with a short animation when tapped."},{"ko":"내 앱의 무료 범위를 퍼즐 1개처럼 아주 작게 잡는 안과 넉넉하게 잡는 안을 적어 놓고, 사용자가 받을 인상을 비교해 보세요.","en":"Write down a very small free tier, like one puzzle, and a generous one for your app, and compare the impression each would leave."}],"ask":{"ko":"내 방 안에 떠 있는 퍼즐은 화면 속 퍼즐과 무엇이 가장 달랐나요?","en":"What was most different about a puzzle floating in your room versus one on a screen?"}},"Chantlings":{"time":10,"setup":{"ko":"4,400원 유료 앱이고, 소리 내 노래할 수 있는 조용한 곳이 필요해요.","en":"It is a paid app (₩4,400), and you need a quiet place where you can sing out loud."},"missions":[{"ko":"앱을 열고 처음으로 소리 내 노래해 보세요. 화면을 만지지 않고도 조작된다는 걸 어떻게 알게 되는지 살펴보세요.","en":"Open the app and sing for the first time. Notice how you learn that it works without touching the screen."},{"ko":"음 하나를 길게 불러 보세요. 생물들이 내 음정과 모음 모양을 따라 하며 입과 몸을 움직이는지 확인해 보세요.","en":"Hold one long note. Check whether the creatures copy your pitch and vowel shape with their mouths and bodies."},{"ko":"일부러 음정이나 박자를 틀리게 불러 보세요. 화음이 여전히 음악적으로 들리는지, 노래가 덜 두렵게 느껴지는지 느껴 보세요.","en":"Sing off pitch or off beat on purpose. Feel whether the harmony still sounds musical and singing feels less scary."},{"ko":"헤드폰이나 블루투스 스피커로 바꿔 불러 보세요. 하울링이나 지연이 느껴지는지 확인해 보세요.","en":"Switch to headphones or a Bluetooth speaker and sing again. Check for any feedback or lag."}],"make":[{"ko":"내 앱에 마이크 음량에 반응하는 작은 프로토타입을 만들어, 소리를 낼 때 캐릭터나 도형이 움직이게 해 보세요.","en":"Build a small prototype that reacts to microphone level, so a character or shape moves when you make sound."},{"ko":"내 앱에서 사용자가 틀리는 순간 하나를 골라, 틀려도 그럴듯한 결과가 나오도록 보정하는 규칙을 적어 보세요.","en":"Pick one moment in your app where users make mistakes, and write a rule that corrects it into a decent result."}],"ask":{"ko":"노래를 잘 못해도 계속 부르고 싶게 만든 건 무엇이었나요?","en":"What made you want to keep singing even if you are not a good singer?"}},"Sago Mini First Words":{"time":15,"setup":{"ko":"만 5세 이하 아이와 함께 해 보면 좋고, 따라 말하기를 위해 마이크를 쓸 수 있어야 해요.","en":"It is best tried with a child aged five or under, and the microphone needs to be available for speaking practice."},"missions":[{"ko":"앱을 처음 열고 보호자에게 보이는 안내와 아이에게 보이는 화면이 어떻게 나뉘는지 살펴보세요.","en":"Open the app for the first time and notice how the guidance for parents is separated from the screens for the child."},{"ko":"다른 아이가 단어를 말하는 영상을 보고 직접 소리 내 따라 말해 보세요. 앱이 내 목소리를 듣고 어떻게 반응하는지 확인해 보세요.","en":"Watch a video of another child saying a word and repeat it out loud. See how the app listens and responds to your voice."},{"ko":"아이가 있다면 건네 보세요. 글을 읽지 못해도 큰 터치 영역과 캐릭터만으로 길을 찾는지 관찰해 보세요.","en":"If there is a child around, hand it over. Watch whether they find their way by large touch targets and characters alone, without reading."},{"ko":"같은 단어가 다른 사회적 상황에서 다시 나오는지 살펴보세요. 맥락을 바꿔 반복하는 방식을 적어 보세요.","en":"Look for the same word coming back in a different social situation. Write down how it repeats with a new context."}],"make":[{"ko":"내 앱의 한 화면을 보호자용 안내와 사용자용 화면으로 나눠, 각자에게 필요한 정보만 남긴 두 버전을 그려 보세요.","en":"Split one screen of your app into a guide for caregivers and a screen for the user, each with only what that person needs."},{"ko":"내 앱의 튜토리얼 하나를 글 대신 누군가 실제로 해 보이는 짧은 영상으로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype one tutorial in your app as a short video of someone actually doing it, instead of text."}],"ask":{"ko":"또래가 말하는 영상을 따라 하는 방식은 버튼을 누르는 학습과 어떻게 달랐나요?","en":"How did copying a peer on video differ from learning by tapping buttons?"}},"Camo Studio":{"time":10,"setup":{"ko":"App Store에서 내려가 직접 해 볼 수 없어요. 개발사가 공개한 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so you can only explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사의 트레일러나 스크린숏에서 처음 연결하는 장면을 찾아보세요. iPhone을 웹캠으로 쓰기까지 몇 단계를 보여 주는지 세어 보세요.","en":"Find the first-connection moment in the developer's trailer or screenshots. Count how many steps it shows before the iPhone works as a webcam."},{"ko":"스튜디오 제어판 스크린숏에서 렌즈, 노출, 화이트밸런스, 인물 흐림이 어떻게 묶여 있는지 보세요. 화상회의 앱이 숨긴 설정을 어떻게 꺼냈는지 관찰해 보세요.","en":"In screenshots of the studio panel, see how lens, exposure, white balance and portrait blur are grouped. Observe how it surfaces settings video apps hide."},{"ko":"장면과 오버레이 구성 화면을 찾아보세요. 한 번 만든 레이아웃을 여러 앱에서 그대로 쓴다는 점을 화면이 어떻게 전하는지 확인해 보세요.","en":"Find the scenes and overlays screen. Check how it conveys that one layout works across many apps."},{"ko":"지금 Mac에서 Continuity Camera로 iPhone을 웹캠으로 직접 써 보세요. Camo가 그 위에 더하려던 가치가 무엇인지 비교해 보세요.","en":"Use your iPhone as a webcam with Continuity Camera on your Mac now. Compare it with the extra value Camo set out to add on top."}],"make":[{"ko":"Apple 기본 기능 하나를 골라, 그 위에 내 앱이 더할 수 있는 가치 한 겹을 한 문장과 화면 하나로 정리해 보세요.","en":"Pick one built-in Apple feature and describe, in one sentence and one screen, the layer of value your app could add on top."},{"ko":"내 앱의 고급 설정 하나를 미리보기와 함께 바로 조절되는 패널로 만든 프로토타입을 만들어 보세요.","en":"Prototype one advanced setting in your app as a panel that adjusts live next to a preview."}],"ask":{"ko":"Apple이 같은 기능을 OS에 넣는다면 내 앱은 어떤 계층으로 자리를 옮길 수 있을까요?","en":"If Apple built your feature into the OS, what layer could your app move to?"}},"Chineasy":{"time":10,"setup":null,"missions":[{"ko":"첫 레슨을 시작해 보세요. 한자를 처음 보여 줄 때 글자와 그림 중 무엇이 먼저 눈에 들어오는지 살펴보세요.","en":"Start the first lesson. Notice whether the character or the illustration catches your eye first."},{"ko":"火나 山처럼 그림과 짝지은 한자를 익힌 뒤 화면을 보지 않고 떠올려 보세요. 그림이 기억을 얼마나 붙잡아 주는지 직접 느껴 보세요.","en":"Learn a character paired with a picture, like 火 or 山, then recall it without looking. Feel how much the picture holds the memory."},{"ko":"기본 부품이 합쳐져 복합 한자가 되는 레슨까지 가 보세요. 조립 원리를 어떤 시각적 순서로 보여 주는지 관찰해 보세요.","en":"Reach a lesson where basic parts combine into compound characters. Observe the visual order used to show how they assemble."},{"ko":"알아보기, 짝 맞추기, 말하기 연습이 번갈아 나오는 흐름을 따라가 보세요. 지루해지기 전에 형식이 바뀌는지 확인해 보세요.","en":"Follow the mix of recognition, matching and speaking practice. Check whether the format changes before it gets boring."}],"make":[{"ko":"내 앱의 어려운 개념 하나를 그림 하나와 짝지은 카드로 만들어, 다음 날 그 개념이 떠오르는지 시험해 보세요.","en":"Turn one hard concept in your app into a card paired with a single picture, and test whether you recall it the next day."},{"ko":"내 앱의 기능 설명을 작은 부품부터 조립하는 순서로 다시 배열한 온보딩 세 장을 그려 보세요.","en":"Sketch three onboarding screens that explain your app by assembling it from small building blocks."}],"ask":{"ko":"그림으로 외운 한자 중 지금도 떠오르는 것은 무엇이고, 왜 기억에 남았나요?","en":"Which character learned through a picture can you still recall, and why did it stick?"}},"Rebel Girls":{"time":15,"setup":{"ko":"이야기를 들으려면 소리가 필요하고, 아이와 함께 들으면 더 좋아요.","en":"You need sound for the stories, and listening with a child is even better."},"missions":[{"ko":"앱을 처음 열고 첫 이야기를 골라 보세요. 손으로 그린 버튼과 아이콘이 책을 펼치는 느낌을 주는지 살펴보세요.","en":"Open the app and pick your first story. Notice whether the hand-drawn buttons and icons feel like opening a book."},{"ko":"이야기 하나를 끝까지 들어 보세요. 300단어 소개글이 2,000단어 오디오 드라마가 되며 생긴 사운드와 낭독의 밀도를 느껴 보세요.","en":"Listen to one story to the end. Feel the depth of sound and narration that came from turning a 300-word bio into a 2,000-word audio drama."},{"ko":"아이가 혼자 쓴다고 생각하고 재생 화면을 조작해 보세요. 멈추고 다음 이야기로 가는 동작이 얼마나 단순한지 확인해 보세요.","en":"Use the playback screen as if you were a child alone. Check how simple it is to pause and move to the next story."},{"ko":"이야기를 오프라인으로 내려받고 비행기 모드에서 들어 보세요. 여행용 흐름이 얼마나 짧은지 관찰해 보세요.","en":"Download a story for offline and play it in Airplane Mode. Observe how short the travel flow is."},{"ko":"퀴즈나 투표 같은 인터랙티브 요소를 찾아 참여해 보세요. 이야기 밖에서 어떤 관계를 만드는지 살펴보세요.","en":"Find a quiz or poll and take part. Notice what kind of connection it builds beyond the stories."}],"make":[{"ko":"내 앱의 시스템 아이콘 두세 개를 손그림 스타일로 바꿔 보고, 앱 전체 인상이 어떻게 달라지는지 비교해 보세요.","en":"Replace two or three system icons in your app with hand-drawn ones and compare how the whole app feels."},{"ko":"내 앱의 재생이나 진행 화면을 아이 혼자 쓸 수 있을 만큼 큰 버튼 세 개로 줄인 버전을 만들어 보세요.","en":"Make a version of your app's playback or progress screen reduced to three buttons big enough for a child to use alone."}],"ask":{"ko":"함께 듣는 경험을 전제로 했다는 점이 화면 어디에서 느껴졌나요?","en":"Where on screen could you tell it was designed for listening together?"}},"Focus Noodles":{"time":10,"setup":{"ko":"6,600원 유료 앱이에요.","en":"It is a paid app (₩6,600)."},"missions":[{"ko":"앱을 처음 열고 첫 세션을 준비해 보세요. 폰을 엎어 놓으면 시작된다는 걸 어떻게 알려 주는지 살펴보세요.","en":"Open the app and set up your first session. Notice how it tells you that flipping the phone over starts it."},{"ko":"5분 세션을 정하고 폰을 화면이 아래로 가게 엎어 두세요. 아무것도 누르지 않고 시작되는 느낌을 몸으로 느껴 보세요.","en":"Choose a five-minute session and lay the phone face down. Feel what it is like to start without pressing anything."},{"ko":"세션 도중 폰을 집어 들어 보세요. 진동, 플래시, 소리가 한꺼번에 울릴 때 일반 알림과 어떻게 다르게 느껴지는지 확인해 보세요.","en":"Pick up the phone mid-session. Notice how the vibration, flash and sound together feel different from an ordinary notification."},{"ko":"세션을 끝까지 마치고 받은 동화 카드를 열어 보세요. 무엇이 나올지 모르는 보상이 다음 세션을 부르는지 관찰해 보세요.","en":"Finish a session and open the fairy-tale card you earned. Observe whether the surprise reward pulls you into another session."},{"ko":"위젯, Live Activity, 통계 화면을 둘러보세요. 라면 은유가 앱 밖에서도 이어지는지 확인해 보세요.","en":"Look at the widget, Live Activity and stats. Check whether the noodle metaphor carries beyond the app."}],"make":[{"ko":"내 앱의 시작 버튼 하나를 엎기, 흔들기, 기울이기 같은 기기 동작으로 바꾼 프로토타입을 Core Motion으로 만들어 보세요.","en":"Use Core Motion to prototype one start button in your app as a device gesture like flipping, shaking or tilting."},{"ko":"내 앱의 타이머나 진행률을 일상 사물이 익거나 자라는 은유로 바꾼 화면 하나를 그려 보세요.","en":"Sketch one screen where your app's timer or progress becomes an everyday thing cooking or growing."}],"ask":{"ko":"폰을 엎는 행동 하나가 집중하겠다는 약속처럼 느껴졌나요, 그 이유는 무엇인가요?","en":"Did flipping the phone feel like a promise to focus, and why?"}},"Poolsuite FM":{"time":10,"setup":null,"missions":[{"ko":"앱을 열고 첫 소리가 날 때까지 따라가 보세요. 검색 없이 분위기만 고르게 하는 첫 화면을 살펴보세요.","en":"Open the app and follow it until the first sound plays. Notice the first screen that asks you to pick a mood, not search."},{"ko":"채널을 몇 개 바꿔 들어 보세요. 사람이 고른 채널이 선택 피로를 얼마나 줄여 주는지 느껴 보세요.","en":"Switch between a few channels. Feel how much human-curated stations reduce choice fatigue."},{"ko":"토글과 창을 눌러 보며 효과음에 귀 기울여 보세요. 픽셀아트 UI가 장난감처럼 느껴지는 순간을 세어 보세요.","en":"Press toggles and windows and listen to the sound effects. Count the moments the pixel-art UI feels like a toy."},{"ko":"앱 안에서 Vacation 선크림이나 멤버 카드처럼 브랜드로 이어지는 요소를 찾아보세요. 광고 없이 브랜드가 어떻게 드러나는지 관찰해 보세요.","en":"Look inside the app for links to the wider brand, like Vacation sunscreen or member cards. Observe how the brand shows up without ads."}],"make":[{"ko":"내 앱의 토글 하나에 짧은 효과음과 레트로 스타일을 입혀, 플랫 버전과 나란히 놓고 비교해 보세요.","en":"Give one toggle in your app a short sound and a retro look, and compare it side by side with the flat version."},{"ko":"내 앱의 검색이나 필터 화면을 미리 고른 분위기 선택지 서너 개로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype your app's search or filter screen as three or four pre-picked mood choices."}],"ask":{"ko":"이 앱을 다시 켜고 싶게 만드는 건 음악인가요, 화면의 분위기인가요?","en":"What makes you want to open it again, the music or the mood of the interface?"}},"Brief":{"time":10,"setup":{"ko":"App Store에서 내려가 직접 해 볼 수 없어요. 개발사가 공개한 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so you can only explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사의 트레일러나 스크린숏에서 첫 화면을 찾아보세요. 끝없는 피드 대신 정해진 수의 기사가 어떻게 보이는지 살펴보세요.","en":"Find the first screen in the developer's trailer or screenshots. Notice how a fixed number of stories appears instead of an endless feed."},{"ko":"기사 화면에서 핵심 사실, 타임라인 맥락, 인용이 어떤 순서로 놓였는지 적어 보세요.","en":"On a story screen, write down the order of key facts, timeline context and quotes."},{"ko":"하루치 기사를 다 읽었을 때 어떻게 끝나는지 보여 주는 장면을 찾아보세요. 다 읽었다는 감각을 화면이 어떻게 만드는지 관찰해 보세요.","en":"Look for how the day ends once every story is read. Observe how the screen creates the feeling of being done."},{"ko":"관점 섹션 화면에서 좌우 목소리가 나란히 놓인 방식을 살펴보세요. 한쪽으로 기울지 않게 보이도록 한 배치 장치를 적어 보세요.","en":"In the Perspectives section, see how voices from left and right sit side by side. Note the layout choices that keep it from leaning one way."}],"make":[{"ko":"내 앱의 피드나 목록 하나에 끝을 정해, 다 보면 완료 화면이 나오는 버전을 만들어 보세요.","en":"Give one feed or list in your app an end, and build a version that shows a done screen when you reach it."},{"ko":"내 앱의 긴 콘텐츠 하나를 핵심 사실, 맥락, 인용 세 칸으로 압축한 카드로 다시 만들어 보세요.","en":"Rebuild one long piece of content in your app as a card with three parts: key facts, context and a quote."}],"ask":{"ko":"뉴스가 끝나는 화면이 있다면 내 사용 습관은 어떻게 달라질까요?","en":"If news had a screen that said you are done, how would your habits change?"}},"NaadSadhana":{"time":15,"setup":{"ko":"소리 내 노래할 수 있는 곳이 필요하고, 헤드폰이 있으면 더 좋아요.","en":"You need a place where you can sing out loud, ideally with headphones."},"missions":[{"ko":"앱을 처음 열고 첫 노래를 부르기까지 따라가 보세요. 라가와 스타일 같은 많은 선택지를 처음 사용자에게 어떻게 보여 주는지 살펴보세요.","en":"Open the app and follow it to your first song. Notice how it presents the many choices, like ragas and styles, to a newcomer."},{"ko":"짧은 선율을 즉흥으로 불러 보세요. 음정 정확도 피드백이 얼마나 빨리 오는지 확인해 보세요.","en":"Improvise a short melody. Check how quickly the pitch accuracy feedback arrives."},{"ko":"AI 오케스트라 반주를 켜고 다시 불러 보세요. 내 선율에 맞춰 악기들이 따라올 때 연습이 공연처럼 느껴지는지 느껴 보세요.","en":"Turn on the AI orchestra and sing again. Feel whether practice becomes a performance as the instruments follow your melody."},{"ko":"내 노래를 녹음하고 자동 믹싱 결과를 들어 보세요. 스튜디오 기능이 많은데도 녹음까지 몇 단계가 걸리는지 세어 보세요.","en":"Record yourself and listen to the auto-mix. Count how many steps recording takes despite all the studio features."}],"make":[{"ko":"내 앱의 입력 하나에 서버를 거치지 않는 온디바이스 즉시 피드백을 붙인 프로토타입을 만들어, 반응 속도 차이를 비교해 보세요.","en":"Prototype instant on-device feedback for one input in your app, with no server round trip, and compare the response speed."},{"ko":"내 앱의 고급 기능 목록을 처음 쓰는 사람용 세 개와 숙련자용 나머지로 나눠 화면 구조를 다시 그려 보세요.","en":"Split your app's advanced features into three for newcomers and the rest for experts, and redraw the screen structure."}],"ask":{"ko":"반주가 내 노래를 따라온다는 느낌이 연습 의욕을 어떻게 바꿨나요?","en":"How did having the accompaniment follow your singing change your motivation to practice?"}},"Where Cards Fall":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"ko":"첫 레벨을 시작해 보세요. 대사 없이 무엇을 해야 할지 어떻게 알게 되는지 살펴보세요.","en":"Start the first level. Notice how you know what to do without any dialogue."},{"ko":"두 손가락을 벌려 카드 집을 세우고 오므려 무너뜨려 보세요. 손가락 간격이 그대로 구조물이 되는 느낌을 확인해 보세요.","en":"Spread two fingers to raise a house of cards and pinch to collapse it. Feel your finger spread becoming the structure."},{"ko":"카드 집으로 계단이나 다리를 만들어 건너 보세요. 쉽게 무너지는 물건이 길이 되는 순간을 느껴 보세요.","en":"Build stairs or a bridge from cards and cross it. Feel the moment something fragile becomes a path."},{"ko":"카드 집을 원하는 위치에 놓기 어려운 곳에서 여러 번 시도해 보세요. 조작이 부정확하다고 느껴지는 지점을 적어 보세요.","en":"Try placing a house of cards somewhere tricky, several times. Write down where the controls feel imprecise."},{"ko":"퍼즐을 풀고 기억 장면이 다시 세워지는 연출을 지켜보세요. 글 없이 어떤 이야기가 전해졌는지 한 줄로 적어 보세요.","en":"Solve a puzzle and watch the memory rebuild itself. Write in one line what story came through without words."}],"make":[{"ko":"내 앱에서 핀치 제스처 하나로 무언가를 만들고 없애는 프로토타입을 만들어, 버튼 두 개보다 나은지 비교해 보세요.","en":"Prototype a single pinch gesture that creates and removes something in your app, and compare it with two buttons."},{"ko":"내 앱의 정밀한 조작 하나에 스냅이나 허용 오차를 넣어, 부정확하다는 느낌이 줄어드는지 시험해 보세요.","en":"Add snapping or tolerance to one precise interaction in your app and test whether it feels less imprecise."}],"ask":{"ko":"야심 찬 조작과 정확한 조작 중 이 게임은 어느 쪽에 더 가까웠나요?","en":"Did this game lean more toward ambitious controls or precise ones?"}},"Ulysses":{"time":15,"setup":{"ko":"구독형 앱이고, Mac이나 iPad가 있으면 동기화까지 확인해 볼 수 있어요.","en":"It is a subscription app; a Mac or iPad lets you test syncing too."},"missions":[{"ko":"앱을 처음 열고 첫 글을 써 보세요. 파일 저장이나 이름 짓기 없이 바로 쓰게 되는지 살펴보세요.","en":"Open the app and write your first piece. Notice whether you start writing without saving or naming a file."},{"ko":"마크다운 문법으로 제목과 강조를 넣어 보세요. 편집기가 쓰는 흐름을 얼마나 방해하지 않는지 관찰해 보세요.","en":"Add a heading and emphasis with Markdown. Observe how little the editor interrupts your writing."},{"ko":"라이브러리에서 그룹, 필터, 키워드로 글을 정리해 보세요. 파일 관리 대신 글 모음으로 생각하게 만드는 구조를 확인해 보세요.","en":"Organize writing in the library with groups, filters and keywords. See how it makes you think in collections, not files."},{"ko":"구독 결제 화면을 열어 보세요. 가격 비교와 문구가 무엇을 강조하는지 적어 보세요.","en":"Open the subscription screen. Write down what the price comparison and copy emphasize."},{"ko":"다른 기기에서 같은 글을 열어 이어 써 보세요. iCloud 동기화가 얼마나 자연스러운지 확인해 보세요.","en":"Open the same piece on another device and keep writing. Check how seamless iCloud sync feels."}],"make":[{"ko":"내 앱의 유료 모델을 바꾼다고 가정하고, 기존 사용자에게 줄 혜택과 이유를 세 문장 공지문으로 써 보세요.","en":"Imagine changing your app's pricing model and write a three-sentence notice with the reason and a benefit for existing users."},{"ko":"내 앱의 결제 화면 문구를 무엇을 위해 돈을 내는지가 한 줄로 보이도록 다시 써 보세요.","en":"Rewrite your app's paywall copy so that what people are paying for is clear in one line."}],"ask":{"ko":"결제 화면 문구 중 구독에 대한 거부감을 가장 줄여 준 한 줄은 무엇이었나요?","en":"Which line on the paywall did the most to ease your resistance to subscribing?"}},"Clear Todos":{"time":10,"setup":null,"missions":[{"ko":"앱을 처음 열고 버튼 없이 첫 항목을 만들어 보세요. 아래로 당기면 된다는 걸 무엇이 알려 주는지 살펴보세요.","en":"Open the app and create your first item without any button. Notice what tells you that pulling down is the way."},{"ko":"항목 몇 개를 오른쪽으로 밀어 완료하고 왼쪽으로 밀어 지워 보세요. 제스처마다 붙는 소리와 햅틱이 어떻게 다른지 느껴 보세요.","en":"Swipe a few items right to complete and left to delete. Feel how the sound and haptic differ for each gesture."},{"ko":"두 항목 사이를 두 손가락으로 벌려 새 항목을 끼워 넣어 보세요. 목록이 갈라지는 움직임이 어떤 물리감을 주는지 보세요.","en":"Pinch two items apart to insert a new one between them. Watch how the list splitting open feels physical."},{"ko":"항목 순서를 바꿔 본 뒤 색 그라데이션을 보세요. 글자 없이 색만으로 위쪽이 더 중요하다는 게 읽히는지 확인해 보세요.","en":"Reorder some items and look at the color gradient. Check whether color alone tells you the top items matter more."}],"make":[{"ko":"내 앱 목록 화면에서 버튼 하나를 골라 스와이프나 당기기 제스처로 바꾼 프로토타입을 만들어 보세요.","en":"Pick one button on a list screen in your app and prototype replacing it with a swipe or pull gesture."},{"ko":"내 앱의 완료 동작 하나에 짧은 햅틱과 소리를 붙이고, 붙이기 전과 후를 직접 비교해 보세요.","en":"Add a short haptic and sound to one completion action in your app and compare it before and after."},{"ko":"목록 항목의 우선순위를 텍스트 라벨 대신 배경색 단계로만 표현한 화면을 하나 만들어 보세요.","en":"Build one screen that shows list priority only through background color steps instead of text labels."}],"ask":{"ko":"버튼이 없어서 처음에 헤맨 순간이 있었다면, 앱은 그걸 어떻게 가르쳐 줬나요?","en":"If you got lost at first because there were no buttons, how did the app teach you?"}},"Airtable":{"time":15,"setup":{"ko":"무료 계정이 필요하고, 데스크톱과 비교해 보려면 컴퓨터가 있으면 좋아요.","en":"You need a free account, and a computer helps if you want to compare with desktop."},"missions":[{"ko":"앱을 처음 열고 첫 베이스가 보이기까지 따라가 보세요. 빈 화면에서 무엇을 먼저 하라고 권하는지 보세요.","en":"Open the app and follow it until your first base appears. Notice what it suggests you do first on an empty screen."},{"ko":"레코드 하나를 열어 카드로 확장해 보세요. 그리드의 한 줄이 모바일에서 어떻게 읽기 쉬운 카드가 되는지 비교해 보세요.","en":"Open a record and expand it into a card. Compare how one grid row becomes a readable card on mobile."},{"ko":"같은 데이터를 그리드에서 칸반이나 갤러리 뷰로 바꿔 보세요. 데이터는 그대로인데 화면의 정보량이 얼마나 줄어드는지 보세요.","en":"Switch the same data from grid to kanban or gallery view. See how much the screen's density drops while the data stays the same."},{"ko":"체크박스나 첨부 같은 타입이 다른 필드를 직접 입력해 보세요. 필드 타입마다 입력 방식이 어떻게 바뀌는지 보세요.","en":"Fill in fields of different types like checkbox or attachment. Notice how the input method changes per field type."},{"ko":"모바일에서 스키마 편집이나 자동화 설정을 찾아보세요. 무엇이 빠져 있고 무엇만 남겼는지 적어 보세요.","en":"Look for schema editing or automation settings on mobile. Write down what was left out and what was kept."}],"make":[{"ko":"내 앱의 데이터 목록 하나를 리스트와 카드 두 가지 뷰로 전환할 수 있게 프로토타입을 만들어 보세요.","en":"Prototype one data list in your app that can switch between a list view and a card view."},{"ko":"내 앱 기능을 모바일에 꼭 필요한 것과 큰 화면으로 미룰 것 두 칸으로 나눠 표로 정리해 보세요.","en":"Sort your app's features into two columns: needed on mobile, and safe to defer to a big screen."}],"ask":{"ko":"모바일 앱에서 덜어 낸 기능 중 가장 아쉬웠던 것과 전혀 아쉽지 않았던 것은 무엇인가요?","en":"Which removed feature did you miss most on mobile, and which did you not miss at all?"}},"Perplexity":{"time":10,"setup":null,"missions":[{"ko":"앱을 열고 첫 질문을 해 보세요. 입력부터 답이 나오기까지 몇 단계가 걸렸는지 세어 보세요.","en":"Open the app and ask your first question. Count how many steps it takes from typing to an answer."},{"ko":"답변 속 번호 각주 하나를 눌러 출처로 가 보세요. 답이 맞는지 확인하는 데 몇 초가 걸리는지 재 보세요.","en":"Tap a numbered footnote in an answer to reach its source. Time how many seconds it takes to verify the claim."},{"ko":"답변 아래 제안된 후속 질문 하나를 눌러 보세요. 검색어를 새로 떠올리지 않아도 되는 흐름이 어떻게 느껴지는지 보세요.","en":"Tap one suggested follow-up question below the answer. Notice how it feels not to think of a new query."},{"ko":"같은 질문을 음성으로 다시 해 보세요. 타이핑과 비교해 결과까지의 흐름이 얼마나 짧아지는지 보세요.","en":"Ask the same question again by voice. See how much shorter the flow to a result is compared with typing."}],"make":[{"ko":"내 앱에서 사용자가 의심할 만한 정보 하나를 골라 출처나 근거를 바로 옆에 붙인 화면을 만들어 보세요.","en":"Pick one piece of information users might doubt in your app and show its source right beside it."},{"ko":"내 앱 결과 화면 아래에 다음에 할 만한 행동 세 개를 제안하는 영역을 넣은 프로토타입을 만들어 보세요.","en":"Prototype a results screen in your app with three suggested next actions placed below it."}],"ask":{"ko":"출처 번호가 있었기 때문에 답을 더 믿게 됐나요, 아니면 직접 확인하게 됐나요?","en":"Did the source numbers make you trust the answer more, or make you check it yourself?"}},"GoodNotes":{"time":20,"setup":{"ko":"iPad와 Apple Pencil이 있으면 가장 좋고, 수백 페이지짜리 PDF 하나를 준비해 두세요.","en":"An iPad with Apple Pencil works best, and have a PDF of a few hundred pages ready."},"missions":[{"ko":"앱을 처음 열고 첫 노트를 만들어 보세요. 무료 체험과 구독, 일회성 구매 선택이 언제 어떻게 나오는지 보세요.","en":"Open the app and make your first notebook. Notice when and how the trial, subscription and one-time purchase choices appear."},{"ko":"빠르게 글씨를 쓰고 지우개로 지워 보세요. 펜 끝과 잉크 사이에 지연이 느껴지는지 종이와 비교해 보세요.","en":"Write quickly and then erase. Compare with paper and notice whether there is any lag between the pen tip and the ink."},{"ko":"큰 PDF를 불러와 페이지를 넘겨 보세요. 동기화 진행률 표시와 필요한 페이지부터 먼저 뜨는지 지켜보세요.","en":"Import a large PDF and flip through pages. Watch the sync progress indicator and whether needed pages load first."},{"ko":"손글씨로 쓴 단어를 검색해 보세요. 손글씨가 검색 가능한 데이터가 되는 순간이 어떻게 보이는지 확인해 보세요.","en":"Search for a word you wrote by hand. See how the moment handwriting becomes searchable data is shown."}],"make":[{"ko":"내 앱에서 오래 걸리는 로딩 하나를 골라 진행률과 먼저 볼 수 있는 부분을 보여 주도록 바꿔 보세요.","en":"Pick one slow load in your app and change it to show progress and the part that can be viewed first."},{"ko":"PencilKit으로 간단한 필기 화면을 만들고, 이 앱과 나란히 놓고 필기감 차이를 적어 보세요.","en":"Build a simple drawing screen with PencilKit and write down how it feels next to this app."}],"ask":{"ko":"종이 같다고 느낀 순간은 펜, 지우개, 페이지 넘기기 중 어디였나요?","en":"Where did it feel most like paper: the pen, the eraser, or turning pages?"}},"네이버 지도":{"time":15,"setup":{"ko":"한국 안에서 실제로 갈 장소 하나를 정하고 시작하세요.","en":"Pick a real place in Korea you might go to before starting."},"missions":[{"ko":"앱을 열고 첫 화면에 보이는 요소를 모두 세어 보세요. 이 많은 정보가 왜 복잡하게 느껴지지 않는지 생각해 보세요.","en":"Open the app and count every element on the first screen. Think about why this much information does not feel cluttered."},{"ko":"가고 싶은 장소까지 대중교통 길찾기를 해 보세요. 버스 실시간 도착, 빠른 환승 칸, 막차 정보가 어디에 놓였는지 보세요.","en":"Get transit directions to a place. Notice where live bus arrivals, the fast-transfer car and last-train info appear."},{"ko":"식당 하나를 골라 지도에서 리뷰, 메뉴, 예약이나 주문까지 이어서 가 보세요. 지도를 벗어나지 않고 몇 번 탭했는지 세어 보세요.","en":"Pick a restaurant and go from map to reviews, menu, and booking or ordering. Count the taps without leaving the map."},{"ko":"같은 장소를 거리뷰나 항공뷰로 열어 보세요. 국내 데이터가 해외 지도 앱과 어떤 차이를 만드는지 비교해 보세요.","en":"Open the same place in street view or aerial view. Compare what local data adds versus a foreign map app."}],"make":[{"ko":"내 앱의 상세 화면 하나에서 다음 행동(예약, 구매, 공유)으로 바로 가는 동선을 한 단계 줄여 보세요.","en":"On one detail screen in your app, cut one step from the path to the next action like booking, buying or sharing."},{"ko":"내 앱 사용자가 사는 지역에서만 의미 있는 정보 하나를 찾아 화면에 넣은 스케치를 그려 보세요.","en":"Find one piece of info that only matters in your users' region and sketch a screen that includes it."}],"ask":{"ko":"해외 지도 앱으로 같은 길을 찾는다면 가장 먼저 아쉬울 정보는 무엇인가요?","en":"If you used a foreign map app for the same trip, what info would you miss first?"}},"Guitar Wiz":{"time":20,"setup":{"ko":"기타가 있으면 좋고, VoiceOver를 켜고 끄는 법을 미리 알아 두세요. Apple Watch가 있으면 함께 준비하세요.","en":"A guitar helps, and know how to toggle VoiceOver. Have an Apple Watch ready if you own one."},"missions":[{"ko":"앱을 처음 열고 튜너, 코드, 메트로놈 같은 도구가 어떻게 한 앱에 정리돼 있는지 둘러보세요. 첫 화면이 무엇을 먼저 권하는지 보세요.","en":"Open the app and look at how tuner, chords and metronome are organized in one app. Notice what the first screen suggests."},{"ko":"VoiceOver를 켜고 눈을 감은 채 튜너로 줄 하나를 맞춰 보세요. 높다, 낮다는 음성만으로 조율이 되는지 느껴 보세요.","en":"Turn on VoiceOver, close your eyes and tune one string. Feel whether the high and low voice cues are enough."},{"ko":"VoiceOver로 튜너 바늘과 코드 다이어그램을 하나씩 짚어 보세요. 커스텀 컨트롤이 각각 무엇이라고 읽히는지 들어 보세요.","en":"Move VoiceOver across the tuner needle and a chord diagram. Listen to what each custom control is read as."},{"ko":"메트로놈을 켜고 진동으로 박자를 느껴 보세요. 소리 없이도 박자를 따라갈 수 있는지 확인해 보세요.","en":"Start the metronome and feel the beat as vibration. Check whether you can keep time without sound."},{"ko":"글자 크기를 최대로 키우고 대비 증가와 색상 없이 구별을 켠 뒤 다시 보세요. 화면이 깨지지 않고 상태가 여전히 읽히는지 보세요.","en":"Max out text size, turn on Increase Contrast and Differentiate Without Color. See if the screens still hold and read clearly."}],"make":[{"ko":"내 앱의 커스텀 컨트롤 하나에 accessibilityLabel과 accessibilityValue를 붙이고 VoiceOver로 들어 보세요.","en":"Add accessibilityLabel and accessibilityValue to one custom control in your app and listen with VoiceOver."},{"ko":"내 앱에서 색으로만 구별되는 상태 하나를 찾아 모양이나 텍스트로도 구별되게 바꿔 보세요.","en":"Find one state in your app shown only by color and make it distinguishable by shape or text too."},{"ko":"내 앱의 핵심 피드백 하나를 화면 없이 소리나 햅틱만으로 전달하는 버전을 만들어 보세요.","en":"Make a version of one key feedback in your app that works through sound or haptics alone, with no screen."}],"ask":{"ko":"눈을 감고 쓴 동안 가장 믿음직했던 신호는 음성, 진동, 소리 중 무엇이었나요?","en":"With your eyes closed, which signal did you trust most: voice, vibration, or sound?"}},"Pickle Pro":{"time":20,"setup":{"ko":"Vision Pro 전용 유료 게임이에요. 공을 휘두를 공간이 필요하고, PS VR2 Sense 컨트롤러나 Vision Pro를 가진 친구가 있으면 더 좋아요.","en":"A paid game for Vision Pro only. You need room to swing, and PS VR2 Sense controllers or a friend with a Vision Pro make it better."},"missions":[{"ko":"게임을 시작하고 코트가 내 방 바닥에 놓이는 순간을 지켜보세요. 가상 경기장이 아니라 거실에 있다는 느낌이 언제 드는지 보세요.","en":"Start the game and watch the court settle onto your floor. Notice when it starts to feel like your living room, not a virtual arena."},{"ko":"초급 AI 상대와 첫 랠리를 해 보세요. 공이 튀는 물리와 패들 반응이 실제 몸 움직임과 얼마나 맞는지 느껴 보세요.","en":"Play a first rally against a beginner AI. Feel how well the ball physics and paddle match your real movement."},{"ko":"컨트롤러가 있다면 손 제스처 대신 컨트롤러로 휘둘러 보세요. 정밀도가 어떻게 달라지는지 비교해 보세요.","en":"If you have the controllers, swing with them instead of hand gestures. Compare how precision changes."},{"ko":"AI 난이도를 올려 점수를 잃어 보세요. 상대가 사람처럼 느껴지는 순간이 있는지 살펴보세요.","en":"Raise the AI level and lose a point. Watch for any moment the opponent feels human."},{"ko":"같은 방의 Vision Pro 사용자와 SharePlay로 마주 보고 쳐 보세요. 둘이 같은 코트를 본다는 게 어떻게 느껴지는지 보세요.","en":"Play face to face with someone in the same room over SharePlay. Notice how it feels to share one court."}],"make":[{"ko":"RealityKit으로 바닥 평면에 물체 하나를 고정하는 작은 visionOS나 ARKit 프로토타입을 만들어 보세요.","en":"Build a small visionOS or ARKit prototype that anchors one object to the floor plane with RealityKit."},{"ko":"내 앱에 같은 공간의 두 사람이 함께 쓰는 장면이 있다면 어떤 화면일지 한 장으로 스케치해 보세요.","en":"Sketch on one page what your app would look like if two people in the same room used it together."}],"ask":{"ko":"실제 방 안에 코트가 있다는 것이 경기 몰입에 어떤 차이를 만들었나요?","en":"What difference did having the court in your real room make to how immersed you felt?"}},"despelote":{"time":30,"setup":{"ko":"Mac 전용 유료 게임이에요. 헤드폰을 쓰면 위치 기반 대화를 훨씬 잘 들을 수 있어요.","en":"A paid game for Mac only. Headphones make the positional dialogue much easier to hear."},"missions":[{"ko":"게임을 시작하고 첫 1분 동안 무엇을 할 수 있는지 찾아보세요. 공 차기 하나뿐이라는 걸 어떻게 알게 되는지 보세요.","en":"Start the game and find out what you can do in the first minute. Notice how you learn that kicking the ball is all there is."},{"ko":"공을 몰고 이야기하는 사람들 쪽으로 천천히 다가가 보세요. 가까워질수록 대화가 또렷해지는 순간을 느껴 보세요.","en":"Dribble slowly toward people who are talking. Feel the moment their conversation becomes clear as you get closer."},{"ko":"멈춰서 화면을 둘러보세요. 사진 스캔 배경과 흑백 손그림 캐릭터가 섞여 기억 같은 장면이 되는 방식을 관찰해 보세요.","en":"Stop and look around. Observe how photo-scanned backgrounds and black and white hand-drawn characters blend into a memory."},{"ko":"목표 없이 공을 엉뚱한 곳으로 차 보세요. 실패 조건이 없다는 게 탐험을 어떻게 바꾸는지 보세요.","en":"Kick the ball somewhere random with no goal. See how having no failure state changes the way you explore."}],"make":[{"ko":"내 앱 화면 하나에서 사용자가 할 수 있는 행동을 하나만 남긴 버전을 만들어 보고 무엇이 남는지 보세요.","en":"Make a version of one screen in your app with only one possible action and see what remains."},{"ko":"AVAudioEngine으로 화면 속 점에 가까워질수록 소리가 커지는 간단한 위치 오디오 프로토타입을 만들어 보세요.","en":"Build a simple positional audio prototype with AVAudioEngine where a sound grows louder as you approach a point."}],"ask":{"ko":"엿들은 대화 중 가장 기억에 남는 것은 무엇이고, 왜 그걸 따라갔나요?","en":"Which overheard conversation stuck with you most, and why did you follow it?"}},"Balatro":{"time":30,"setup":{"ko":"광고와 인앱 구매가 없는 유료 앱이고, Apple Arcade에서는 Balatro+로도 할 수 있어요.","en":"A paid app with no ads or in-app purchases, also available as Balatro+ on Apple Arcade."},"missions":[{"ko":"첫 판을 시작하고 포커 족보만으로 첫 핸드를 내 보세요. 규칙을 배우는 데 얼마나 걸렸는지 재 보세요.","en":"Start your first run and play a hand using only poker hands you know. Time how long the rules took to learn."},{"ko":"카드를 드래그해 정렬하고 선택해 보세요. 마우스 대신 터치에 맞춘 탭 영역과 조작이 얼마나 편한지 느껴 보세요.","en":"Drag cards to sort and select them. Feel how comfortable the touch-sized tap areas and controls are."},{"ko":"조커 효과가 겹치는 핸드를 내고 점수 계산을 지켜보세요. 칩과 배수가 한 장씩 올라갈 때 소리와 흔들림이 주는 쾌감을 느껴 보세요.","en":"Play a hand where jokers stack and watch the scoring. Feel the thrill as chips and mult climb card by card with sound and shake."},{"ko":"목표 점수를 못 넘겨 한 판을 져 보세요. 다시 시작하고 싶게 만드는 것이 무엇인지 적어 보세요.","en":"Lose a run by missing the target score. Write down what makes you want to start again."}],"make":[{"ko":"내 앱에서 숫자가 바뀌는 순간 하나를 골라 값이 단계별로 올라가며 햅틱이 붙는 애니메이션으로 바꿔 보세요.","en":"Pick one moment a number changes in your app and turn it into a step-by-step count-up with haptics."},{"ko":"내 앱의 계산 결과 하나를 공식 그대로 화면에 보여 주는 버전을 만들어, 사용자가 이유를 읽을 수 있게 해 보세요.","en":"Make a version that shows one calculation in your app as its visible formula so users can read the reason."}],"ask":{"ko":"점수 연출 중 어느 순간에 가장 큰 쾌감을 느꼈고, 그 이유는 무엇인가요?","en":"At which moment of the scoring did you feel the biggest thrill, and why?"}},"Moises":{"time":15,"setup":{"ko":"이어폰이나 헤드폰과 기기에 있는 좋아하는 노래 파일 하나를 준비하세요. 악기가 있으면 더 좋아요.","en":"Have earphones and a favorite song file on your device. An instrument makes it better."},"missions":[{"ko":"앱을 열고 첫 곡을 올려 분리되기까지 따라가 보세요. 기다리는 동안 무엇을 보여 주는지 보세요.","en":"Open the app and follow your first song from upload to separation. Notice what it shows while you wait."},{"ko":"분리된 트랙에서 드럼만 음소거하고 들어 보세요. 녹음된 곡에서 악기 하나가 사라지는 순간을 느껴 보세요.","en":"Mute only the drums in the separated tracks. Feel the moment one instrument vanishes from a recording."},{"ko":"트랙별 슬라이더를 움직여 보컬만 솔로로 들어 보세요. 전문 믹서 조작이 얼마나 쉽게 바뀌었는지 보세요.","en":"Move the track sliders to solo the vocals. Notice how a pro mixer task has been made simple."},{"ko":"템포를 늦추고 키를 바꾼 뒤 A–B 구간을 반복해 보세요. 흘러가는 코드 표시를 따라 연습이 되는지 확인해 보세요.","en":"Slow the tempo, change the key and loop an A–B section. Check whether you can practice along with the scrolling chords."}],"make":[{"ko":"내 앱의 복잡한 설정 하나를 슬라이더 몇 개로 바로 만지고 결과를 즉시 듣거나 보는 화면으로 바꿔 보세요.","en":"Turn one complex setting in your app into a few sliders with instant audible or visible results."},{"ko":"내 앱의 무료와 유료 경계를 표로 그리고, 핵심 경험이 무료 안에 다 들어 있는지 점검해 보세요.","en":"Draw your app's free and paid boundary as a table and check that the core experience fits within free."}],"ask":{"ko":"악기 하나를 뺐을 때 그 곡이 다르게 들린 부분은 어디였나요?","en":"When you removed one instrument, where did the song sound different to you?"}},"Watch Duty: Wildfire Maps":{"time":10,"setup":{"ko":"미국 App Store 계정이 필요할 수 있어요. 미국 지역 하나를 정해 알림을 켜 보세요.","en":"You may need a US App Store account. Pick a US area to turn alerts on for."},"missions":[{"ko":"앱을 처음 열고 알림 받을 카운티나 위치를 고르는 과정을 따라가 보세요. 몇 단계 만에 끝나는지 세어 보세요.","en":"Open the app and follow choosing a county or location for alerts. Count how many steps it takes."},{"ko":"지도에서 화재 경계선, 대피 구역, 바람, 대기질 레이어를 겹쳐 보세요. 정보가 많아도 우선순위가 읽히는지 보세요.","en":"Layer fire perimeters, evacuation zones, wind and air quality on the map. See if priority still reads clearly."},{"ko":"화재 하나를 골라 업데이트 타임라인을 처음부터 읽어 보세요. 시각이 찍힌 짧은 사람의 글이 자동 알림과 어떻게 다른지 느껴 보세요.","en":"Pick one fire and read its update timeline from the start. Feel how short, timestamped human posts differ from automated alerts."},{"ko":"실시간 소방 항공기를 지도에서 찾아보세요. 긴급 상황이라면 이 화면 하나로 어떤 결정을 내릴 수 있을지 생각해 보세요.","en":"Find live firefighting aircraft on the map. Think about what decision you could make from this one screen in an emergency."}],"make":[{"ko":"내 앱 푸시 알림 하나를 시각, 상황, 해야 할 행동이 한 줄에 다 들어가게 다시 써 보세요.","en":"Rewrite one push notification in your app so the time, situation and action all fit in one line."},{"ko":"내 앱의 정보 화면 하나에서 가장 급한 정보 하나만 맨 위로 올린 버전을 만들어 비교해 보세요.","en":"Make a version of one info screen in your app with only the most urgent item moved to the top, and compare."}],"ask":{"ko":"사람이 검증한 정보라는 것이 화면 어디에서 가장 분명하게 느껴졌나요?","en":"Where on screen did you most clearly feel the information was verified by people?"}},"Bears Gratitude":{"time":10,"setup":null,"missions":[{"ko":"앱을 처음 열고 첫 기록을 쓸 때까지 시간을 재 보세요. 로그인 없이 몇 초 만에 쓰기 시작하는지 보세요.","en":"Open the app and time how long until you write your first entry. Notice how few seconds it takes with no login."},{"ko":"프롬프트 카드를 옆으로 넘기며 하나를 골라 써 보세요. 빈 페이지 대신 1인칭 문구가 쓰기를 얼마나 쉽게 하는지 느껴 보세요.","en":"Swipe through the prompt cards and pick one to write. Feel how the first-person phrasing makes writing easier than a blank page."},{"ko":"기록을 마칠 때 곰 그림이 어떻게 반응하는지 보세요. 그림이 화면의 중심이 되도록 설계됐다는 게 어디서 보이는지 찾아보세요.","en":"Watch how the bear illustrations respond when you finish an entry. Find where the design clearly centers on the drawings."},{"ko":"기록하고 모으고 되돌아보는 흐름을 한 바퀴 돌아 보세요. 일반적인 앱 패턴 대신 그림책처럼 이어지는 순서를 관찰해 보세요.","en":"Go once through write, collect and look back. Observe the picture-book order instead of usual app patterns."}],"make":[{"ko":"내 앱의 빈 입력 화면 하나를 구체적인 1인칭 문구가 적힌 카드 세 장으로 바꿔 보세요.","en":"Replace one blank input screen in your app with three cards carrying specific first-person prompts."},{"ko":"내 앱 첫 실행에서 핵심 행동 전에 거치는 화면을 모두 적고, 하나라도 빼서 바로 쓰게 만들어 보세요.","en":"List every screen before the core action on your app's first run and remove at least one."}],"ask":{"ko":"그림이 없었다면 이 앱은 어떤 앱처럼 느껴졌을까요?","en":"Without the drawings, what kind of app would this have felt like?"}},"Unpacking":{"time":20,"setup":{"ko":"유료 게임이에요. 효과음을 느끼려면 소리를 켜거나 이어폰을 쓰세요.","en":"A paid game. Turn sound on or use earphones to feel the sound effects."},"missions":[{"ko":"첫 방에서 설명 없이 상자를 열어 보세요. 대사도 튜토리얼도 없이 무엇을 해야 하는지 어떻게 알게 되는지 보세요.","en":"Open a box in the first room with no instructions. Notice how you know what to do without dialogue or tutorial."},{"ko":"같은 물건을 침대, 책상, 바닥 등 다른 표면에 놓아 보세요. 표면마다 소리가 달라지는 걸 귀 기울여 들어 보세요.","en":"Place the same object on the bed, the desk and the floor. Listen closely to how the sound changes per surface."},{"ko":"방을 돌려 다른 벽을 보며 정리를 마쳐 보세요. 어색한 자리의 물건이 빨갛게 표시될 때 실패가 아니라 힌트처럼 느껴지는지 보세요.","en":"Rotate the room and finish unpacking. See whether misplaced items turning red feels like a hint rather than a failure."},{"ko":"다음 이사로 넘어가 이전 집에서 온 물건을 찾아보세요. 물건만으로 주인공의 삶이 어떻게 읽히는지 생각해 보세요.","en":"Move on to the next home and look for items from the last one. Think about how objects alone tell her life."}],"make":[{"ko":"내 앱의 드래그 앤 드롭 하나에 놓는 위치에 따라 다른 햅틱이나 소리를 붙여 보세요.","en":"Add different haptics or sounds to one drag and drop in your app depending on where it lands."},{"ko":"내 앱의 오류 메시지 하나를 글 대신 색이나 표시만으로 알려 주는 버전으로 바꿔 보세요.","en":"Change one error message in your app to a version that signals only through color or a marker, no text."}],"ask":{"ko":"어떤 물건 하나가 주인공에 대해 가장 많은 것을 말해 줬나요?","en":"Which single object told you the most about the main character?"}},"Arc Search":{"time":10,"setup":null,"missions":[{"ko":"앱을 열자마자 키보드가 이미 올라와 있는지 보세요. 첫 검색까지 몇 번 탭했는지 세어 보세요.","en":"Open the app and notice the keyboard is already up. Count the taps to your first search."},{"ko":"궁금한 주제로 Browse for Me를 써 보세요. 링크 목록 대신 인용과 링크가 들어간 요약 페이지 하나가 만들어지는 걸 지켜보세요.","en":"Use Browse for Me on a topic. Watch a single summary page with citations and links get built instead of a link list."},{"ko":"아무 웹페이지에서 핀치해 요약을 받아 보세요. 튜토리얼 없이 제스처로 기능을 알게 되는 방식이 자연스러운지 보세요.","en":"Pinch on any web page to get a summary. See whether learning a feature through a gesture feels natural."},{"ko":"휴대폰을 귀에 대고 Call Arc로 질문해 보세요. 전화하듯 묻는 동작이 어떻게 느껴지는지 보세요.","en":"Hold the phone to your ear and ask a question with Call Arc. Notice how asking like a phone call feels."},{"ko":"색이 다른 사이트 몇 곳을 열어 툴바를 보세요. 툴바 색이 페이지에 맞춰 바뀌는 순간을 관찰해 보세요.","en":"Open a few sites with different colors and watch the toolbar. Observe how it changes color to match each page."}],"make":[{"ko":"내 앱 첫 화면에서 사용자가 가장 먼저 할 입력 하나에 자동으로 포커스가 가게 만들어 보세요.","en":"Make the first input users need on your app's opening screen get focus automatically."},{"ko":"내 앱의 숨은 기능 하나를 온보딩 설명 대신 제스처나 맥락으로 발견하게 바꾼 프로토타입을 만들어 보세요.","en":"Prototype one hidden feature in your app so it is discovered through a gesture or context, not onboarding."}],"ask":{"ko":"링크를 하나도 누르지 않고 원하는 답을 얻었나요, 아니면 결국 원문을 열었나요?","en":"Did you get your answer without tapping a single link, or did you end up opening the source?"}},"Sunlitt":{"time":15,"setup":{"ko":"창가나 야외에서 하면 AR 모드를 제대로 느낄 수 있어요.","en":"Use it by a window or outdoors to really feel the AR mode."},"missions":[{"ko":"앱을 처음 열고 태양 궤적 다이얼을 보세요. 위치를 알려 준 뒤 오늘 해의 흐름이 한눈에 읽히는지 확인해 보세요.","en":"Open the app and look at the sun path dial. After sharing your location, check if today's sun reads at a glance."},{"ko":"AR 모드를 켜고 창이나 발코니를 비춰 보세요. 다른 날짜와 시간을 고르면 해 궤적이 어떻게 겹쳐지는지 보세요.","en":"Turn on AR mode and point at a window or balcony. Pick another date and time and watch the sun path overlay."},{"ko":"3D 해시계 Monolitt와 세계 그림자 지도를 열어 보세요. 시간을 움직일 때 그림자와 햅틱이 함께 반응하는지 느껴 보세요.","en":"Open the Monolitt sundial and the world shadow map. Feel whether shadows and haptics respond together as time moves."},{"ko":"홈 화면 위젯이나 라이브 액티비티를 추가해 보세요. 앱을 열지 않고도 일출, 일몰이 어떻게 보이는지 확인해 보세요.","en":"Add a home screen widget or Live Activity. See how sunrise and sunset show without opening the app."}],"make":[{"ko":"내 앱의 숫자 데이터 하나를 원형 다이얼이나 궤적 같은 그림으로 바꿔 보여 주는 SwiftUI 뷰를 만들어 보세요.","en":"Build a SwiftUI view that shows one numeric value in your app as a dial or path instead of a number."},{"ko":"내 앱 배경색 하나를 시간대에 따라 바뀌게 만들고 하루 동안 어떻게 느껴지는지 보세요.","en":"Make one background color in your app shift by time of day and see how it feels over a day."}],"ask":{"ko":"숫자 대신 그림으로 봤을 때 해에 대해 새로 알게 된 것은 무엇인가요?","en":"Seeing it as a picture instead of numbers, what did you newly learn about the sun?"}},"Universe — Website Builder":{"time":20,"setup":{"ko":"무료 플랜으로 시작할 수 있어요. VoiceOver와 큰 글씨 설정을 바꾸는 법을 알아 두세요.","en":"You can start on the free plan. Know how to change VoiceOver and large text settings."},"missions":[{"ko":"앱을 처음 열고 첫 사이트를 만들기 시작해 보세요. 컴퓨터 없이 시작한다는 게 첫 화면에서 어떻게 전달되는지 보세요.","en":"Open the app and start your first site. Notice how the first screen conveys that no computer is needed."},{"ko":"GRID 에디터에서 블록을 탭하고 끌고 핀치해 레이아웃을 만들어 보세요. 웹 레이아웃이 손 동작으로 바뀐 느낌을 느껴 보세요.","en":"Tap, drag and pinch blocks in the GRID editor to build a layout. Feel how web layout became hand gestures."},{"ko":"VoiceOver를 켜고 블록 하나를 편집해 보세요. 시각적 도구인데도 무엇이 어떻게 읽히는지 들어 보세요.","en":"Turn on VoiceOver and edit one block. Listen to how a visual tool is read aloud."},{"ko":"글자 크기를 크게 키운 뒤 에디터를 다시 보세요. 편집 화면이 깨지지 않고 쓸 수 있는지 확인해 보세요.","en":"Increase text size and look at the editor again. Check that the editing screen still holds up and works."},{"ko":"무료 플랜으로 사이트를 공개해 보세요. 휴대폰 하나로 웹에 올라가기까지 몇 단계였는지 세어 보세요.","en":"Publish the site on the free plan. Count how many steps it took to go live from one phone."}],"make":[{"ko":"내 앱에서 가장 시각적인 편집 화면 하나를 VoiceOver로만 끝까지 써 보고 막힌 지점을 적어 고쳐 보세요.","en":"Use your app's most visual editing screen with VoiceOver only, note where you got stuck, and fix one spot."},{"ko":"내 앱의 복잡한 입력 하나를 격자 블록을 탭하고 끄는 방식으로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype one complex input in your app as tapping and dragging blocks on a grid."}],"ask":{"ko":"시각적 도구를 스크린 리더로 쓸 수 있게 만드는 데 가장 중요해 보인 것은 무엇인가요?","en":"What seemed most important in making a visual tool work with a screen reader?"}},"Pocket Card Jockey: Ride On!":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"ko":"첫 경주를 시작하고 솔리테어와 경마가 어떻게 연결되는지 처음 설명받는 순간을 보세요. 이상한 조합이 언제 이해되는지 느껴 보세요.","en":"Start your first race and watch the moment solitaire and racing are first connected. Feel when the odd combo clicks."},{"ko":"골프 솔리테어를 빠르게 풀어 카드를 없애 보세요. 카드가 사라질수록 말의 에너지가 쌓이는 피드백을 지켜보세요.","en":"Clear cards fast in golf solitaire. Watch the feedback as your horse's energy builds with each card removed."},{"ko":"솔리테어 사이에 말을 안쪽 코스나 경쟁마 근처로 끌어다 놓아 보세요. 짧은 전략 판단이 카드 흐름을 어떻게 끊어 주는지 보세요.","en":"Between hands, drag your horse to the inside lane or near rivals. Notice how the quick call breaks up the card flow."},{"ko":"솔리테어를 망쳐 경주에서 져 보세요. 말의 기분과 스태미나가 어떻게 바뀌고 다음 판을 하고 싶어지는지 보세요.","en":"Botch a solitaire hand and lose a race. See how the horse's mood and stamina change and whether you want another go."}],"make":[{"ko":"내 앱의 반복 작업 하나에 짧은 미니게임이나 보상 피드백을 붙인 프로토타입을 만들어 보세요.","en":"Prototype one repetitive task in your app with a short minigame or reward feedback attached."},{"ko":"서로 상관없어 보이는 두 기능을 하나의 결과로 연결하는 아이디어를 내 앱 기준으로 세 개 적어 보세요.","en":"Write three ideas for linking two seemingly unrelated features in your app into one outcome."}],"ask":{"ko":"카드 실력이 말의 달리기로 바뀌는 연결이 언제 납득됐나요?","en":"When did the link between card skill and the horse's running start to make sense?"}},"Hindsight":{"time":30,"setup":{"ko":"유료 게임이에요. 소리를 켜고 조용한 시간에 하세요.","en":"A paid game. Play with sound on during a quiet moment."},"missions":[{"ko":"게임을 시작하고 첫 물건을 탭할 때까지 따라가 보세요. 설명 없이 한 손가락으로 무엇을 할지 알게 되는 과정을 보세요.","en":"Start the game and follow it until you tap your first object. Notice how you learn what to do with one finger and no instructions."},{"ko":"찻잔이나 사진 같은 물건을 탭해 카메라가 그 안으로 들어가는 순간을 지켜보세요. 전환 자체가 무엇을 말하는지 느껴 보세요.","en":"Tap an object like a teacup or photo and watch the camera dive inside. Feel what the transition itself says."},{"ko":"장면을 확대하고 둘러보며 다음 물건을 찾아보세요. 매치컷이 두 시기를 어떻게 이어 주는지 관찰해 보세요.","en":"Zoom and look around to find the next object. Observe how the match cut ties two periods of life together."},{"ko":"화면에 보이는 UI 요소를 모두 세어 보세요. 최소한의 UI가 무거운 이야기에 다가가기 쉽게 하는지 생각해 보세요.","en":"Count every UI element on screen. Think about whether minimal UI makes the heavy story easier to approach."}],"make":[{"ko":"내 앱의 화면 전환 하나를 탭한 요소가 다음 화면으로 커지는 matchedGeometryEffect로 바꿔 보세요.","en":"Change one transition in your app so the tapped element grows into the next screen with matchedGeometryEffect."},{"ko":"내 앱 화면 하나에서 UI 요소를 절반으로 줄인 버전을 만들어 콘텐츠가 얼마나 살아나는지 비교해 보세요.","en":"Make a version of one screen in your app with half the UI elements and compare how much the content stands out."}],"ask":{"ko":"어떤 물건의 전환이 가장 마음에 남았고, 그 전환이 무엇을 말해 줬나요?","en":"Which object's transition stayed with you, and what did it tell you?"}},"Rise: Energy & Sleep Tracker":{"time":15,"setup":{"ko":"7일 무료 체험 뒤 구독하는 앱이에요. 건강 앱 데이터 접근을 허용하면 첫날부터 볼 수 있어요.","en":"A subscription app after a 7-day trial. Allow Health data access to see results from day one."},"missions":[{"ko":"앱을 처음 열고 웨어러블 없이 첫 결과가 나오기까지 따라가 보세요. 어떤 권한을 왜 요청하는지 보세요.","en":"Open the app and follow it until a first result appears without a wearable. Notice which permissions it asks for and why."},{"ko":"수면 부채 숫자를 보세요. 점수 대신 숫자 하나가 나에게 무엇을 해야 할지 바로 알려 주는지 생각해 보세요.","en":"Look at the sleep debt number. Think about whether one number tells you what to do better than a score."},{"ko":"오늘의 에너지 곡선 타임라인을 보며 최고조와 오후 처짐 시간을 찾아보세요. 이 시간에 무슨 일을 할지 바로 정해 보세요.","en":"Find your peak and afternoon dip on today's energy curve. Decide right away what you would do in those hours."},{"ko":"습관 알림 중 하나를 켜 보세요. 카페인을 끊을 시간 같은 알림이 기록을 행동으로 어떻게 바꾸는지 보세요.","en":"Turn on one habit reminder. See how a nudge like a caffeine cutoff turns tracking into action."}],"make":[{"ko":"내 앱이 보여 주는 지표 여러 개 중 하나만 남기고, 그 숫자로 사용자가 할 행동을 한 문장으로 붙여 보세요.","en":"Keep only one of the metrics your app shows and attach one sentence telling the user what to do with it."},{"ko":"내 앱 데이터를 하루 타임라인 위에 올려 언제 무엇을 하면 좋을지 보여 주는 화면을 스케치해 보세요.","en":"Sketch a screen that lays your app's data on a daily timeline showing when to do what."}],"ask":{"ko":"에너지 곡선을 보고 실제로 오늘 일정을 바꾸고 싶어졌나요?","en":"After seeing the energy curve, did you actually want to change today's plans?"}},"Moncage":{"time":20,"setup":{"ko":"유료 게임이에요.","en":"A paid game."},"missions":[{"ko":"게임을 시작하고 큐브를 처음 돌려 보세요. 설명 없이 여섯 면이 각각 다른 장면이라는 걸 어떻게 알게 되는지 보세요.","en":"Start the game and rotate the cube for the first time. Notice how you learn each of the six faces is a different scene."},{"ko":"두 면의 파이프나 다리가 하나로 이어지게 각도를 맞춰 보세요. 착시가 맞아떨어지는 순간의 쾌감을 느껴 보세요.","en":"Line up the angle so a pipe or bridge on two faces joins into one. Feel the thrill when the illusion snaps into place."},{"ko":"막히면 손가락으로 천천히 돌리며 면 사이를 비교해 보세요. 인벤토리나 텍스트 없이 시점만으로 힌트를 주는 방식을 관찰해 보세요.","en":"When stuck, rotate slowly with your finger and compare faces. Observe how hints come only from viewpoint, with no inventory or text."},{"ko":"퍼즐을 풀고 열리는 사진을 보세요. 대사 없이 사진 한 장이 이야기를 어떻게 이어 가는지 보세요.","en":"Solve a puzzle and look at the photo it unlocks. See how one photo carries the story without dialogue."}],"make":[{"ko":"SceneKit이나 RealityKit으로 손가락으로 돌리는 큐브 하나를 만들고, 각 면에 다른 이미지를 붙여 보세요.","en":"Build a finger-rotatable cube with SceneKit or RealityKit and put a different image on each face."},{"ko":"내 앱에서 진행 보상과 이야기(또는 콘텐츠)가 같은 것이 되도록 바꿀 수 있는 지점 하나를 찾아 스케치해 보세요.","en":"Find one spot in your app where the progress reward and the content could be the same thing, and sketch it."}],"ask":{"ko":"착시가 맞아떨어진 순간, 답을 찾았다는 걸 무엇으로 확신했나요?","en":"When the illusion lined up, what made you sure you had found the answer?"}},"Active Arcade":{"time":15,"setup":{"ko":"몸을 움직일 공간과 기기를 세워 둘 곳이 필요해요. 함께할 사람이나 TV가 있으면 더 좋아요.","en":"You need room to move and a place to stand the device. A second person or a TV makes it better."},"missions":[{"ko":"앱을 처음 열고 기기를 세워 둔 뒤 한 발 물러서 보세요. 카메라가 내 몸을 잡았다는 걸 어떻게 알려 주는지 보세요.","en":"Open the app, stand the device up and step back. Notice how it tells you the camera has found your body."},{"ko":"두더지 잡기처럼 익숙한 게임 하나를 해 보세요. 규칙 설명 없이 몸이 먼저 반응하는지 느껴 보세요.","en":"Play a familiar game like whack-a-mole. Feel whether your body reacts before any rules are explained."},{"ko":"일부러 동작을 크게 또는 작게 해 보세요. 인식이 어디까지 따라오고 어디서 놓치는지 관찰해 보세요.","en":"Make your moves deliberately big or small. Observe where tracking keeps up and where it loses you."},{"ko":"다른 사람과 로컬 2인 모드를 해 보세요. 끝나고 나오는 하이라이트 영상과 개인정보 설정을 확인해 보세요.","en":"Play local two-player with someone. Check the highlight video at the end and its privacy settings."}],"make":[{"ko":"Vision 프레임워크의 신체 자세 인식으로 손을 들면 화면 색이 바뀌는 간단한 프로토타입을 만들어 보세요.","en":"Build a quick prototype using Vision body pose detection that changes screen color when you raise a hand."},{"ko":"내 앱의 새 기능 하나를 사용자가 이미 아는 놀이나 게임 형식에 빗대어 다시 설명해 보세요.","en":"Re-explain one new feature in your app by mapping it to a game or play format users already know."}],"ask":{"ko":"휴대폰을 만지지 않고 몸으로만 조작할 때 가장 놀라웠던 순간은 언제였나요?","en":"When controlling it with only your body, what moment surprised you most?"}},"Townscaper":{"time":15,"setup":{"ko":"유료 게임이에요.","en":"A paid game."},"missions":[{"ko":"게임을 시작하고 물 위를 처음 탭해 보세요. 목표도 설명도 없을 때 무엇을 하고 싶어지는지 보세요.","en":"Start the game and tap the water for the first time. Notice what you want to do with no goal or instructions."},{"ko":"같은 자리에 블록을 계속 쌓아 보세요. 블록 덩어리가 아치, 계단, 첨탑으로 저절로 바뀌는 순간을 지켜보세요.","en":"Keep stacking blocks in one spot. Watch the moment the mass turns into arches, stairs and spires by itself."},{"ko":"블록을 탭해 지웠다 다시 놓아 보세요. 되돌리기가 쉬우니 실험이 얼마나 가벼워지는지 느껴 보세요.","en":"Tap to remove blocks and place them again. Feel how easy undo makes experimenting light."},{"ko":"새 블록의 색을 바꿔 가며 마을을 이어 보세요. 비틀린 그리드 덕에 마을이 손으로 지은 듯 보이는지 관찰해 보세요.","en":"Change block colors as you extend the town. Observe whether the irregular grid makes it look hand-built."}],"make":[{"ko":"탭할 때마다 이웃 칸을 보고 모양을 바꾸는 간단한 격자 규칙을 SwiftUI로 만들어 보세요.","en":"Build a simple grid in SwiftUI where each tap changes a tile's shape based on its neighbors."},{"ko":"내 앱에서 사용자가 실패할 수 없는 놀이 공간 하나를 만든다면 어떤 화면일지 스케치해 보세요.","en":"Sketch what a playful space in your app would look like if users could not fail in it."}],"ask":{"ko":"직접 설계하지 않았는데도 내가 만들었다고 느낀 이유는 무엇인가요?","en":"Why did it feel like you built it even though you did not design it?"}},"RakugakiAR":{"time":15,"setup":{"ko":"유료 앱이에요. 종이와 펜, 그리고 생물이 돌아다닐 바닥 공간을 준비하세요.","en":"A paid app. Have paper, a pen and some floor space for the creature to roam."},"missions":[{"ko":"앱을 처음 열고 설명 없이 무엇을 하라는 건지 알아내 보세요. 그리고, 스캔하고, 논다는 흐름이 어떻게 보이는지 보세요.","en":"Open the app and figure out what to do without instructions. Notice how draw, scan, play shows itself."},{"ko":"종이에 낙서 하나를 그리고 스캔해 보세요. 그림이 3D 생물로 일어서 방을 걸어 다니는 순간을 지켜보세요.","en":"Draw a doodle on paper and scan it. Watch the moment it stands up as a 3D creature and walks around your room."},{"ko":"생물에게 먹이를 주고 쿡 찔러 보세요. 몸으로 하는 조작에 생물이 어떤 동작으로 반응하는지 보세요.","en":"Feed the creature and poke it. See how it reacts to these physical, childlike actions."},{"ko":"웃긴 장면을 녹화해 보세요. 녹화와 공유가 놀이의 마무리처럼 자연스럽게 이어지는지 확인해 보세요.","en":"Record a funny moment. Check whether recording and sharing feels like a natural end to play."}],"make":[{"ko":"내 앱의 결과 화면 하나에 사용자가 바로 녹화하거나 공유하고 싶어질 장면을 하나 넣어 보세요.","en":"Add one moment to a result screen in your app that users would want to record or share right away."},{"ko":"내 앱의 첫 사용 흐름을 글자 없이 그림 세 장으로만 설명해 보고 이해되는지 다른 사람에게 보여 주세요.","en":"Explain your app's first-use flow in three pictures with no text and test it on someone."}],"ask":{"ko":"내 낙서가 움직이는 걸 봤을 때 가장 먼저 하고 싶었던 행동은 무엇이었나요?","en":"When your doodle started moving, what was the first thing you wanted to do?"}},"If Found...":{"time":20,"setup":{"ko":"유료 게임이에요.","en":"A paid game."},"missions":[{"ko":"게임을 시작하고 첫 페이지를 손가락으로 문질러 보세요. 지우기가 진행 방식이라는 걸 어떻게 알게 되는지 보세요.","en":"Start the game and rub the first page with your finger. Notice how you learn that erasing is how you progress."},{"ko":"천천히 또는 빠르게 문질러 지워 보세요. 진짜 지우개를 쓰는 듯한 손맛이 어디서 오는지 느껴 보세요.","en":"Erase slowly, then quickly. Feel where the sense of using a real eraser comes from."},{"ko":"한 페이지를 지우고 아래 드러나는 다음 페이지를 보세요. UI와 콘텐츠가 한 면에 겹쳐 있다는 게 어떻게 보이는지 관찰해 보세요.","en":"Erase a page and look at the one revealed beneath. Observe how UI and content share a single surface."},{"ko":"카시오의 일기와 블랙홀 이야기가 바뀌는 지점을 찾아보세요. 지우는 행위가 이야기의 감정과 어떻게 겹치는지 생각해 보세요.","en":"Find where Kasio's diary switches to the black hole story. Think about how erasing overlaps with the story's emotion."}],"make":[{"ko":"Canvas나 마스크로 손가락으로 문지르면 위 레이어가 지워지며 아래가 드러나는 프로토타입을 만들어 보세요.","en":"Build a prototype with Canvas or a mask where rubbing erases the top layer to reveal what is underneath."},{"ko":"내 앱의 핵심 행동 하나를 앱의 주제와 의미가 겹치는 제스처로 바꿀 수 있을지 세 가지 안을 적어 보세요.","en":"Write three ideas for turning one core action in your app into a gesture that matches the app's theme."}],"ask":{"ko":"지우는 손동작이 이야기를 읽는 느낌을 어떻게 바꿨나요?","en":"How did the erasing motion change the way the story felt to read?"}},"Blind Drive":{"time":15,"setup":{"ko":"유료 게임이에요. 바이노럴 오디오라 헤드폰이나 이어폰이 꼭 필요해요.","en":"A paid game. Headphones or earphones are a must for the binaural audio."},"missions":[{"ko":"헤드폰을 쓰고 게임을 시작해 보세요. 화면에 점수와 생명뿐일 때 첫 1분 동안 무엇을 귀로 배우는지 보세요.","en":"Put on headphones and start the game. With only score and lives on screen, notice what you learn by ear in the first minute."},{"ko":"눈을 감고 좌우 회피 버튼만으로 역주행 차를 피해 보세요. 차가 어느 쪽에서 오는지 소리만으로 알 수 있는지 느껴 보세요.","en":"Close your eyes and dodge oncoming cars with only left and right. Feel whether sound alone tells you where cars come from."},{"ko":"일부러 충돌해 보세요. 햅틱과 소리가 실패를 어떻게 알려 주고 다시 시작하게 만드는지 보세요.","en":"Crash on purpose. See how haptics and sound signal failure and pull you into a retry."},{"ko":"VoiceOver를 켜고 메뉴부터 게임까지 들어가 보세요. 접근성이 처음부터 설계된 흐름인지 확인해 보세요.","en":"Turn on VoiceOver and go from the menu into a game. Check whether accessibility feels designed in from the start."}],"make":[{"ko":"AVAudioEnvironmentNode로 소리를 좌우에 배치해 방향을 맞히는 간단한 프로토타입을 만들어 보세요.","en":"Build a simple prototype with AVAudioEnvironmentNode that places sounds left or right for the user to guess."},{"ko":"내 앱의 핵심 화면 하나를 눈을 감고 VoiceOver로만 써 보고 막힌 곳 하나를 고쳐 보세요.","en":"Use one key screen in your app with your eyes closed and VoiceOver only, then fix one place you got stuck."}],"ask":{"ko":"눈을 감았을 때 소리 중 어떤 정보가 가장 결정적이었나요?","en":"With your eyes closed, which piece of sound information mattered most?"}},"Sky: Children of the Light":{"time":30,"setup":{"ko":"다른 플레이어를 만나야 하니 인터넷 연결이 필요해요.","en":"You need an internet connection to meet other players."},"missions":[{"ko":"게임을 시작하고 엄지 하나로 날고 걷는 첫 몇 분을 보세요. 채팅도 설명도 없이 조작을 어떻게 배우는지 관찰해 보세요.","en":"Start the game and watch the first minutes of flying and walking with one thumb. Notice how you learn controls with no chat or tutorial."},{"ko":"모르는 플레이어에게 몸짓이나 감정 표현을 해 보세요. 말 없이 소통하는 게 어떤 느낌인지 보세요.","en":"Make a gesture or emote at a stranger. Notice what communicating without words feels like."},{"ko":"다른 플레이어와 손을 잡고 함께 날아 보세요. 낯선 사람과 협력하는 것이 이동 자체에 녹아 있다는 걸 느껴 보세요.","en":"Hold hands with another player and fly together. Feel how cooperation with strangers is built into movement itself."},{"ko":"날개빛을 하나 모아 보세요. 망토 에너지가 늘어나며 탐험이 곧 보상이 되는 순간을 확인해 보세요.","en":"Collect a winged light. See the moment cape energy grows and exploring becomes the reward."},{"ko":"상점을 열어 무엇을 파는지 보세요. 꾸미기만 팔고 강해지는 요소가 없다는 게 분위기에 어떤 영향을 주는지 생각해 보세요.","en":"Open the shop and see what it sells. Think about how selling only cosmetics affects the atmosphere."}],"make":[{"ko":"내 앱의 사용자 간 기능 하나를 텍스트 대신 미리 정한 반응이나 이모트 몇 개로만 소통하게 바꾼 안을 그려 보세요.","en":"Sketch a version of one social feature in your app that uses only a few preset reactions instead of text."},{"ko":"내 앱에서 다른 사람을 도와야만 열리는 작은 기능 하나를 설계해 한 장으로 적어 보세요.","en":"Design one small feature in your app that unlocks only by helping someone else, and write it on one page."}],"ask":{"ko":"말이 통하지 않는 낯선 사람에게 처음으로 고마움을 느낀 순간은 언제였나요?","en":"When did you first feel grateful to a stranger you could not talk to?"}},"Things 3":{"time":15,"setup":{"ko":"iPhone판은 유료 일회성 구매이고 무료 체험은 Mac에만 있어요.","en":"The iPhone version is a paid one-time purchase, and the free trial is Mac only."},"missions":[{"ko":"앱을 처음 열고 사이드바의 Inbox, Today, Upcoming, Anytime, Someday 구조를 보세요. 처음 보는 사람도 어디에 둘지 알 수 있는지 생각해 보세요.","en":"Open the app and look at the sidebar of Inbox, Today, Upcoming, Anytime and Someday. Think about whether a newcomer knows where things go."},{"ko":"Magic Plus 버튼을 끌어서 목록 중간에 놓아 보세요. 추가와 위치 지정이 한 동작으로 끝나는 손맛을 느껴 보세요.","en":"Drag the Magic Plus button into the middle of a list. Feel how adding and placing happen in one motion."},{"ko":"프로젝트를 하나 만들고 Headings로 단계를 나눠 보세요. 기능이 많아도 구조가 단순하게 유지되는지 보세요.","en":"Create a project and split it into stages with Headings. See whether structure stays simple despite many features."},{"ko":"할 일 하나를 Today에서 Someday로 옮겨 보세요. 오늘과 언젠가의 구분이 마음을 어떻게 가볍게 하는지 느껴 보세요.","en":"Move a to-do from Today to Someday. Feel how the today and someday split lightens your mind."}],"make":[{"ko":"내 앱의 추가 버튼을 끌어서 원하는 위치에 놓으면 그 자리에 항목이 생기는 프로토타입으로 바꿔 보세요.","en":"Prototype your app's add button so dragging it to a spot creates the item right there."},{"ko":"내 앱의 가격 모델을 한 문장으로 쓰고, 그 문장이 사용자에게 주는 메시지가 무엇인지 적어 보세요.","en":"Write your app's pricing model in one sentence and note what message it sends to users."}],"ask":{"ko":"한 번 사는 가격표가 이 앱을 쓰는 태도를 어떻게 바꿨나요?","en":"How did a one-time price change your attitude toward using this app?"}},"Seeing AI":{"time":15,"setup":{"ko":"글자가 있는 문서, 바코드가 있는 제품, 지폐를 옆에 두고 VoiceOver를 켤 줄 알아 두세요.","en":"Keep a printed document, a product with a barcode and a bank note nearby, and know how to turn on VoiceOver."},"missions":[{"ko":"앱을 처음 열고 채널 목록을 보세요. 원하는 작업을 먼저 고르게 하는 구조가 어떻게 안내되는지 보세요.","en":"Open the app and look at the channel list. Notice how it guides you to pick your task first."},{"ko":"짧은 텍스트 채널에서 셔터 없이 카메라를 글자에 대 보세요. 글자가 잡히자마자 읽기 시작하는 속도를 느껴 보세요.","en":"In the short text channel, point the camera at text without pressing a shutter. Feel how fast it starts reading once text is caught."},{"ko":"VoiceOver를 켜고 눈을 감은 채 문서 채널로 한 페이지를 찍어 보세요. 가장자리 음성 안내만으로 구도를 맞출 수 있는지 보세요.","en":"With VoiceOver on and eyes closed, capture a page in the document channel. See if edge guidance alone lets you frame it."},{"ko":"제품 채널에서 바코드를 찾아보세요. 신호음이 빨라지는 오디오 피드백만으로 위치를 찾을 수 있는지 확인해 보세요.","en":"Find a barcode in the product channel. Check whether the speeding beeps alone lead you to it."},{"ko":"스캔한 문서에 질문을 해 보세요. 생성형 AI 설명이 기존 읽기와 어떻게 다른지 비교해 보세요.","en":"Ask a question about a scanned document. Compare the generative AI answer with plain reading."}],"make":[{"ko":"내 앱의 카메라나 입력 기능 하나에 무엇이 잘못됐는지 말로 알려 주는 안내를 붙여 보세요.","en":"Add spoken guidance to one camera or input feature in your app that says what is going wrong."},{"ko":"내 앱에서 사용자가 위치를 찾아야 하는 동작 하나에 가까워질수록 빨라지는 햅틱이나 소리를 붙여 보세요.","en":"Add haptics or sound that speeds up as the user gets closer for one find-the-spot action in your app."}],"ask":{"ko":"눈을 감고 쓸 때 가장 믿을 수 있었던 안내는 무엇이었나요?","en":"With your eyes closed, which guidance could you trust most?"}},"Spotify":{"time":10,"setup":null,"missions":[{"ko":"앱을 처음 열고 첫 곡을 재생해 보세요. 재생까지 몇 번 탭했고 무료 사용자에게 어떤 제한이 보이는지 보세요.","en":"Open the app and play your first song. Count the taps to play and notice what limits appear for free users."},{"ko":"미니 플레이어를 위로 밀어 Now Playing을 열어 보세요. 앨범 아트가 커지며 이어지는 공간 연속성을 지켜보세요.","en":"Swipe up the mini player to open Now Playing. Watch the spatial continuity as the album art grows."},{"ko":"전체 화면을 열지 않고 미니 플레이어를 좌우로 스와이프해 보세요. 가장 자주 하는 동작이 얼마나 짧아졌는지 느껴 보세요.","en":"Swipe the mini player left and right without opening full screen. Feel how short the most common action has become."},{"ko":"Now Playing에서 아래로 스크롤해 가사, 크레딧, 다음 곡 카드를 보세요. 곡마다 배경색과 Canvas가 어떻게 바뀌는지도 보세요.","en":"Scroll down in Now Playing to the lyrics, credits and up-next cards. Also notice how background color and Canvas change per song."}],"make":[{"ko":"내 앱의 작은 카드 하나가 탭하면 전체 화면으로 커지는 전환을 matchedGeometryEffect로 만들어 보세요.","en":"Build a transition with matchedGeometryEffect where a small card in your app grows into full screen on tap."},{"ko":"내 앱 화면 하나에 이미지에서 추출한 색을 배경으로 쓰는 버전을 만들어 콘텐츠마다 분위기를 바꿔 보세요.","en":"Make a version of one screen in your app that uses a color extracted from its image as the background."}],"ask":{"ko":"어떤 순간에 이 앱이 무료 사용자에게 업그레이드를 권한다고 느꼈나요?","en":"At what moment did you feel the app nudging you as a free user to upgrade?"}},"Linear":{"time":15,"setup":{"ko":"Linear 워크스페이스가 필요해요. 데스크톱이나 웹과 비교해 보면 더 좋아요.","en":"You need a Linear workspace. Comparing with desktop or web helps."},"missions":[{"ko":"앱을 처음 열고 받은편지함에 도착하기까지 따라가 보세요. 데스크톱과 달리 무엇을 먼저 보여 주는지 보세요.","en":"Open the app and follow it to the inbox. Notice what it shows first compared with desktop."},{"ko":"이슈 하나를 열고 상태를 바꿔 보세요. 서버를 기다리는 느낌 없이 즉시 바뀌는지 느껴 보세요.","en":"Open an issue and change its status. Feel whether it changes instantly with no sense of waiting for a server."},{"ko":"이동 중이라고 생각하고 빠르게 이슈 하나를 만들어 보세요. 생성까지 몇 번 탭했는지 세어 보세요.","en":"Pretend you are on the go and create an issue quickly. Count the taps to create it."},{"ko":"알림 몇 개를 처리하며 애니메이션을 관찰해 보세요. 짧은 모션이 속도감을 해치는지 살리는지 보세요.","en":"Handle a few notifications and watch the animations. See whether short motion hurts or boosts the sense of speed."}],"make":[{"ko":"내 앱에서 서버 응답을 기다리는 동작 하나를 낙관적 업데이트로 바꿔 화면을 먼저 반영해 보세요.","en":"Change one action in your app that waits for the server into an optimistic update that reflects on screen first."},{"ko":"내 앱 애니메이션 하나의 지속 시간을 절반으로 줄여 보고 속도감이 어떻게 달라지는지 비교해 보세요.","en":"Halve the duration of one animation in your app and compare how the sense of speed changes."}],"ask":{"ko":"모바일에서 데스크톱의 명령 메뉴 대신 무엇이 속도감을 만들고 있었나요?","en":"On mobile, what created the sense of speed in place of the desktop command menu?"}},"Photomath":{"time":10,"setup":{"ko":"종이에 인쇄되거나 손으로 쓴 수학 문제 몇 개를 준비하세요.","en":"Have a few printed or handwritten math problems on paper."},"missions":[{"ko":"앱을 처음 열고 카메라를 문제에 대 보세요. 인식 프레임이 뜨고 결과가 나오기까지 몇 초인지 재 보세요.","en":"Open the app and point the camera at a problem. Time the seconds from the recognition frame to a result."},{"ko":"인식 프레임을 직접 줄이거나 늘려 문제 하나만 잡아 보세요. 실패를 막을 수단을 사용자에게 먼저 주는 방식을 보세요.","en":"Shrink or stretch the recognition frame to catch just one problem. Notice how it hands you the tool to prevent failure."},{"ko":"손글씨로 쓴 수식을 일부러 흐리게 찍어 보세요. 틀린 인식을 수학 키보드로 고쳐 이어서 풀이를 받아 보세요.","en":"Snap a handwritten equation a little sloppily. Fix the misread with the math keyboard and continue to the solution."},{"ko":"단계별 풀이를 펼치고 한 단계를 탭해 보세요. 답보다 과정을 먼저 보여 주는 화면이 학습에 어떻게 다른지 생각해 보세요.","en":"Expand the step-by-step solution and tap a step. Think about how showing process before answer changes learning."}],"make":[{"ko":"내 앱의 인식이나 자동 입력 결과를 다시 시작하지 않고 그 자리에서 고칠 수 있게 바꿔 보세요.","en":"Make one recognition or auto-fill result in your app editable in place, without starting over."},{"ko":"내 앱이 보여 주는 결과 하나에 탭하면 이유가 펼쳐지는 단계별 설명을 붙여 보세요.","en":"Attach a tap-to-expand step-by-step explanation to one result your app shows."}],"ask":{"ko":"인식이 틀렸을 때 다시 찍는 것과 고치는 것 중 무엇을 택했고, 왜 그랬나요?","en":"When recognition went wrong, did you retake or fix it, and why?"}},"Working Copy":{"time":20,"setup":{"ko":"클론해 볼 Git 저장소 주소와 다른 텍스트 에디터 앱 하나가 있으면 좋아요. 푸시는 일회성 Pro 구매가 필요해요.","en":"Have a Git repository URL to clone and another text editor app. Pushing needs a one-time Pro purchase."},"missions":[{"ko":"앱을 처음 열고 저장소 하나를 클론해 보세요. 무료로 할 수 있는 것과 Pro가 필요한 것이 어디서 갈리는지 보세요.","en":"Open the app and clone a repository. Notice where free features end and Pro begins."},{"ko":"파일 앱을 열고 Working Copy 저장소를 찾아보세요. 다른 에디터 앱에서 파일을 직접 열고 저장한 뒤 변경이 잡히는지 확인해 보세요.","en":"Open the Files app and find the Working Copy repo. Edit and save a file from another editor and check the change shows up."},{"ko":"내장 에디터로 파일을 고치고 HTML 미리보기로 확인해 보세요. iPad 하나로 수정과 확인이 어떻게 이어지는지 보세요.","en":"Edit a file in the built-in editor and check it with the HTML preview. See how editing and checking flow on one iPad."},{"ko":"단축어 앱에서 Working Copy 액션 목록을 열어 보세요. 커밋이나 풀이 자동화 흐름에 어떻게 들어가는지 살펴보세요.","en":"Open the Working Copy actions in the Shortcuts app. Look at how commit or pull fits into an automation."}],"make":[{"ko":"내 앱의 핵심 동작 하나를 App Intents로 노출해 단축어에서 실행해 보세요.","en":"Expose one core action of your app through App Intents and run it from Shortcuts."},{"ko":"내 앱 데이터를 파일 앱에서 보이게 하려면 무엇이 필요한지 정리하고, 문서 폴더 공유를 켜 시험해 보세요.","en":"List what it would take to show your app's data in the Files app, then try enabling document folder sharing."}],"ask":{"ko":"다른 앱이 이 앱의 파일을 직접 편집할 수 있다는 것이 작업 흐름을 어떻게 바꿨나요?","en":"How did letting other apps edit this app's files directly change your workflow?"}},"쿠팡":{"time":10,"setup":{"ko":"한국 계정이 필요해요. 실제 결제는 하지 않아도 돼요.","en":"You need a Korean account. You do not have to actually pay."},"missions":[{"ko":"앱을 처음 열고 상품 하나를 검색해 보세요. 목록에서 가격보다 도착 예정일이 먼저 눈에 들어오는지 보세요.","en":"Open the app and search for a product. Notice whether the arrival date catches your eye before the price in the list."},{"ko":"상품 상세로 들어가 로켓배송 배지와 도착 보장 문구를 찾아보세요. 구체적인 날짜가 구매 결정을 얼마나 빨리 만드는지 느껴 보세요.","en":"Open a product page and find the Rocket badge and arrival promise. Feel how a concrete date speeds up the decision."},{"ko":"장바구니에서 결제 직전까지 가 보세요. 저장된 배송지와 결제 수단이 미리 선택돼 있어 남은 단계가 몇 개인지 세어 보세요.","en":"Go from cart to just before payment. With saved address and payment preselected, count the steps left."},{"ko":"와우 멤버십 안내가 어디서 어떻게 나오는지 찾아보세요. 쇼핑 밖의 혜택을 어떻게 묶어 보여 주는지 보세요.","en":"Find where and how the WOW membership is pitched. See how it bundles benefits beyond shopping."}],"make":[{"ko":"내 앱 목록 화면에서 사용자가 가장 걱정하는 정보 하나를 상세 화면이 아니라 목록 셀에 올려 보세요.","en":"Move the info users worry about most from the detail screen up into the list cells of your app."},{"ko":"내 앱의 핵심 완료 흐름에서 이미 아는 값을 미리 채워 단계 하나를 없애 보세요.","en":"In your app's main completion flow, prefill values you already know to remove one step."}],"ask":{"ko":"결제까지 가는 동안 멈칫한 순간이 한 번이라도 있었나요, 있었다면 어디였나요?","en":"Was there any moment you hesitated on the way to checkout, and if so where?"}},"Hearing Buddy":{"time":15,"setup":{"ko":"여러 사람이 대화하는 자리가 있으면 가장 좋고, 친구의 iPhone이나 iPad가 있으면 캡션 공유도 해 볼 수 있어요.","en":"A group conversation works best, and a friend's iPhone or iPad lets you try caption sharing."},"missions":[{"ko":"앱을 처음 열고 실시간 자막을 켜기까지 따라가 보세요. 무료와 무제한이 어떻게 전달되는지 보세요.","en":"Open the app and follow it until live captions are on. Notice how free and unlimited are communicated."},{"ko":"혼자 짧게 말하며 자막이 뜨는 속도를 보세요. 서버 없이 기기 안에서 만들어진 자막이 얼마나 빨리 따라오는지 느껴 보세요.","en":"Speak a short line on your own and watch how fast captions appear. Feel how quickly on-device captions keep up with no server."},{"ko":"여러 사람이 빠르게 주고받는 대화에 자막을 켜 보세요. 말이 겹칠 때 자막이 어떻게 따라오는지 지켜보세요.","en":"Turn on captions during a fast group conversation. Watch how the captions keep up when people talk over each other."},{"ko":"캡션 공유 모드로 다른 사람의 기기에서 같은 자막을 띄워 보세요. 한 대가 방 전체 자막이 되는 경험을 느껴 보세요.","en":"Use caption sharing to show the same captions on another person's device. Feel one phone captioning a whole room."},{"ko":"자막 언어를 한국어로 바꿔 보세요. 다른 언어와 비교해 정확도가 어떤지 보세요.","en":"Switch the caption language to Korean. Compare its accuracy with another language."}],"make":[{"ko":"SpeechAnalyzer 같은 온디바이스 음성 인식으로 말을 실시간 텍스트로 바꾸는 화면 하나를 만들어 보세요.","en":"Build one screen that turns speech into live text using on-device speech recognition like SpeechAnalyzer."},{"ko":"내 앱에서 서버로 보내는 데이터 하나를 기기 안에서 처리하면 무엇이 달라질지 비용과 개인정보 관점으로 적어 보세요.","en":"Write how one piece of data your app sends to a server would change if processed on device, in cost and privacy."}],"ask":{"ko":"자막이 가장 빛난 순간과 가장 힘들어한 순간은 각각 언제였나요?","en":"When did the captions shine most, and when did they struggle most?"}},"TR-49":{"time":30,"setup":{"ko":"유료 게임이에요. 풀 보이스라 소리를 켜거나 이어폰을 쓰세요.","en":"A paid game. It is fully voiced, so turn sound on or use earphones."},"missions":[{"ko":"게임을 시작하고 첫 1분 동안 TR-49 기계를 둘러보세요. 메뉴 대신 기계 자체가 인터페이스라는 걸 어떻게 알게 되는지 보세요.","en":"Start the game and explore the TR-49 machine for a minute. Notice how you learn the machine itself is the interface."},{"ko":"네 글자 코드를 아무렇게나 입력해 보세요. 틀린 입력에 기계가 어떻게 반응하고 다음 시도를 부르는지 보세요.","en":"Enter a random four-character code. See how the machine responds to a wrong entry and invites another try."},{"ko":"기록 조각을 읽고 저자 이니셜과 출간 연도로 코드를 추론해 입력해 보세요. 맞았을 때 오는 아하의 순간을 느껴 보세요.","en":"Read the fragments and deduce a code from author initials and publication year. Feel the aha when it works."},{"ko":"불러온 기록의 음성을 들으며 애비와 리엄의 관계를 짐작해 보세요. 순서 없이 찾은 조각이 이야기가 되는 방식을 관찰해 보세요.","en":"Listen to a retrieved record and guess at Abi and Liam's relationship. Observe how fragments found in any order become a story."}],"make":[{"ko":"내 앱의 검색이나 입력 하나를 규칙을 추론해야 열리는 작은 퍼즐로 바꾼 장난감 프로토타입을 만들어 보세요.","en":"Make a toy prototype that turns one search or input in your app into a small puzzle unlocked by deducing a rule."},{"ko":"내 앱 콘텐츠를 어떤 순서로 봐도 이해되는 조각 다섯 개로 나눠 카드로 적어 보세요.","en":"Split your app's content into five cards that make sense in any order."}],"ask":{"ko":"처음으로 코드를 스스로 맞혔을 때 무엇이 결정적인 단서였나요?","en":"When you cracked a code on your own for the first time, what was the key clue?"}},"Spilled!":{"time":20,"setup":{"ko":"처음 몇 구역은 무료이고, 전체는 한 번의 인앱 구매로 열려요.","en":"The first few areas are free, and one in-app purchase unlocks the full game."},"missions":[{"ko":"게임을 시작하고 배를 처음 몰아 보세요. 지나간 자리에 깨끗한 물이 남는 걸 보며 진행이 어떻게 보이는지 보세요.","en":"Start the game and steer the boat for the first time. Watch clean water trail behind you and how progress shows."},{"ko":"붐으로 기름띠를 모으고 자석으로 드럼통을 낚아 보세요. 도구마다 손에 오는 동작이 어떻게 다른지 느껴 보세요.","en":"Collect an oil slick with the boom and fish up a drum with the magnet. Feel how each tool moves differently."},{"ko":"호스로 불을 끄거나 강둑의 기름을 씻어 보세요. 텍스트 없이 플레이만으로 환경 메시지가 전달되는지 생각해 보세요.","en":"Use the hose to put out a fire or wash oil off the bank. Think about whether the environmental message comes through play alone."},{"ko":"무료 구역이 끝나는 지점까지 가 보세요. 먼저 해보고 사기 제안이 어떤 타이밍과 말투로 나오는지 보세요.","en":"Play until the free areas end. Notice the timing and tone of the try-before-you-buy offer."}],"make":[{"ko":"내 앱 진행 상황 하나를 퍼센트 대신 화면이 조금씩 깨끗해지거나 채워지는 시각 변화로 바꿔 보세요.","en":"Replace one progress percentage in your app with a visual change, like the screen gradually clearing or filling."},{"ko":"내 앱의 유료 전환 화면을 무료 체험이 끝나는 자연스러운 지점에 맞춰 다시 배치해 보세요.","en":"Reposition your app's upgrade screen to a natural point where the free part ends."}],"ask":{"ko":"실패 조건이 없는데도 계속 하고 싶게 만든 것은 무엇이었나요?","en":"With no failure state, what kept you wanting to play?"}},"Thank Goodness You're Here!":{"time":30,"setup":{"ko":"Mac 전용 유료 게임이에요.","en":"A paid game for Mac only."},"missions":[{"ko":"게임을 시작하고 첫 1분 동안 무엇을 할 수 있는지 찾아보세요. 때리기 하나뿐이라는 걸 어떻게 알게 되는지 보세요.","en":"Start the game and find out what you can do in the first minute. Notice how you learn slapping is the only verb."},{"ko":"눈에 보이는 사물과 사람을 아무거나 때려 보세요. 하나의 동사가 매번 다른 개그로 돌아오는 순간을 느껴 보세요.","en":"Slap anything and anyone you see. Feel how one verb comes back as a different gag every time."},{"ko":"퀘스트 하나를 따라가며 일이 어떻게 황당하게 번지는지 보세요. 반복 개그가 커지는 템포를 관찰해 보세요.","en":"Follow one quest and watch how it spirals into absurdity. Observe the tempo as running gags escalate."},{"ko":"장면이 측면 시점과 탑뷰를 오갈 때를 지켜보세요. 시점 전환이 콩트 연출처럼 쓰이는 방식을 보세요.","en":"Watch when scenes switch between side view and top view. See how the camera change is used like sketch comedy staging."}],"make":[{"ko":"내 앱의 여러 버튼을 하나의 만능 동작으로 합친다면 어떻게 될지 화면 하나로 프로토타입해 보세요.","en":"Prototype one screen of your app where several buttons are merged into one universal action."},{"ko":"내 앱에서 같은 동작을 반복할 때 반응이 조금씩 달라지는 작은 장치 하나를 넣어 보세요.","en":"Add one small touch in your app where repeating the same action gets a slightly different response."}],"ask":{"ko":"가장 크게 웃은 장면은 무엇이었고, 그 웃음은 조작과 연출 중 어디서 나왔나요?","en":"What scene made you laugh hardest, and did the laugh come from the controls or the staging?"}},"Capybara AI Meeting Translator":{"time":15,"setup":{"ko":"Apple Intelligence를 지원하는 기기와 외국어 대화나 영상 하나를 준비하세요.","en":"Have a device that supports Apple Intelligence and a foreign-language conversation or video."},"missions":[{"ko":"앱을 처음 열고 첫 녹음을 시작하기까지 따라가 보세요. 카피바라가 등장하는 순간 분위기가 어떻게 바뀌는지 보세요.","en":"Open the app and follow it to your first recording. Notice how the mood changes when the capybara appears."},{"ko":"외국어 대화를 틀어 놓고 실시간 전사를 지켜보세요. 원문 바로 아래 번역이 얼마나 즉시 붙는지 느껴 보세요.","en":"Play a foreign-language conversation and watch the live transcript. Feel how instantly the translation appears under each line."},{"ko":"녹음과 번역 사이 카피바라 애니메이션을 지켜보세요. 긴장되는 상황을 편안하게 만드는 장치로 느껴지는지 보세요.","en":"Watch the capybara animation during recording and translation. See whether it feels like a device that eases a tense moment."},{"ko":"자동 요약을 연필 아이콘으로 고치고 생각을 덧붙여 보세요. AI 결과가 출발점처럼 느껴지는지 확인해 보세요.","en":"Edit the auto summary with the pencil icon and add a thought. Check whether the AI output feels like a starting point."},{"ko":"Siri에게 이 노트를 요약해 달라고 말해 보세요. 앱을 열지 않고 어디까지 할 수 있는지 보세요.","en":"Ask Siri to summarize this note. See how far you can get without opening the app."}],"make":[{"ko":"Translation 프레임워크로 입력한 문장 바로 아래에 번역을 붙여 주는 화면 하나를 만들어 보세요.","en":"Build a screen with the Translation framework that shows a translation right below each entered sentence."},{"ko":"내 앱의 기다리는 화면 하나에 스트레스를 낮춰 줄 캐릭터나 작은 애니메이션을 넣어 보세요.","en":"Add a character or small animation to one waiting screen in your app to lower stress."},{"ko":"내 앱의 자동 생성 결과 하나를 사용자가 그 자리에서 고치고 덧붙일 수 있게 바꿔 보세요.","en":"Make one auto-generated result in your app editable and extendable in place."}],"ask":{"ko":"카피바라가 없었다면 이 앱을 쓰는 기분이 어떻게 달랐을까요?","en":"Without the capybara, how would using this app have felt different?"}},"Ground News":{"time":15,"setup":null,"missions":[{"ko":"앱을 처음 열고 첫 피드가 뜰 때까지 따라가 보세요. 편향 막대가 첫 화면부터 보이는지, 설명 없이도 의미가 읽히는지 확인해 보세요.","en":"Open the app and follow it until the first feed loads. Check whether the bias bar is visible right away and readable without explanation."},{"ko":"오늘 큰 뉴스 하나를 열어 좌·중·우 막대를 보세요. 색 비율만으로 어느 쪽이 많이 다뤘는지 몇 초 만에 알 수 있는지 재 보세요.","en":"Open one of today's big stories and look at its left, center and right bar. Time how many seconds it takes to tell which side covered it most."},{"ko":"Blindspot 피드에서 한쪽만 다룬 기사를 두세 개 열어 보세요. 내가 평소 몰랐던 이야기가 몇 개인지, 누가 침묵했는지 세어 보세요.","en":"Open two or three stories in the Blindspot feed. Count how many you had never heard of, and notice which side stayed silent."},{"ko":"기사 출처 쪽에서 매체 소유 정보를 찾아보세요. 무료로 보이는 정보와 구독 뒤에 있는 정보의 경계가 어디인지 표시해 두세요.","en":"Look for the ownership data on a story's sources. Note where the line falls between what free users see and what sits behind the subscription."}],"make":[{"ko":"내 앱의 목록 셀 하나에 숫자 대신 비율 막대 하나를 넣어 보고, 친구에게 3초 만에 의미가 읽히는지 물어보세요.","en":"Replace a number in one of your list cells with a single ratio bar, then ask a friend whether they can read it in three seconds."},{"ko":"내 앱 데이터에서 사용자가 놓치고 있는 항목만 모아 보여 주는 화면을 하나 스케치해 보세요. 이 앱의 Blindspot처럼요.","en":"Sketch one screen that gathers only what the user is missing in your app's data, the way Blindspot does."},{"ko":"내 앱의 무료 기능과 유료 기능을 표로 나눠, 무료 사용자도 핵심 가치를 직접 맛보는지 점검해 보세요.","en":"Split your app's free and paid features into a table and check that free users still taste the core value."}],"ask":{"ko":"편향 막대를 보고 기사 하나라도 다른 관점으로 다시 읽어 보게 됐나요, 그렇다면 무엇 때문이었나요?","en":"Did the bias bar make you reread even one story from another angle, and if so, what triggered it?"}},"NYT Games":{"time":15,"setup":{"ko":"주요 게임은 무료로 바로 할 수 있고, 아카이브와 전체 크로스워드는 구독이 필요해요.","en":"The headline games are free; archives and the full crossword need a subscription."},"missions":[{"ko":"앱을 열어 게임 허브를 둘러보세요. 한 게임을 하러 왔다가 옆의 다른 게임이 눈에 들어오도록 배치돼 있는지 살펴보세요.","en":"Open the app and look around the games hub. Notice how the layout puts other games in view next to the one you came for."},{"ko":"오늘의 Wordle을 끝까지 풀어 보세요. 다 풀고 나서 더 할 게 없을 때 드는 기분이 아쉬움인지 내일에 대한 기대인지 느껴 보세요.","en":"Finish today's Wordle. When there is nothing left to play, notice whether the feeling is disappointment or looking forward to tomorrow."},{"ko":"결과를 공유 격자로 복사해 메모 앱에 붙여 보세요. 답은 하나도 안 보이는데 내가 어떻게 풀었는지는 다 보이는 점을 확인하세요.","en":"Copy your result grid and paste it into Notes. See how it shows exactly how you played without revealing a single letter of the answer."},{"ko":"Connections도 한 판 해 보세요. 한 해에 112억 번 풀린 퍼즐 중 하나를 푼다는 생각으로, 틀렸을 때 다시 하고 싶게 만드는 장치를 찾아보세요.","en":"Play one round of Connections. As one of 11.2 billion solves a year, look for what makes you want to keep going after a mistake."}],"make":[{"ko":"내 앱의 핵심 콘텐츠를 하루 하나만 열리게 제한한 버전을 간단히 만들어 보고, 다음 날 다시 열 이유가 생기는지 생각해 보세요.","en":"Build a quick version of your app that unlocks only one piece of core content per day, and ask whether it creates a reason to come back."},{"ko":"내 앱의 결과 화면을 답이나 개인 정보는 숨기고 과정만 보여 주는 몇 줄짜리 공유 텍스트로 바꿔 보세요.","en":"Turn your app's result screen into a few lines of shareable text that show the process but hide the answer and personal details."}],"ask":{"ko":"하루 한 판이라는 제한이 나를 붙잡았나요, 아니면 아쉽게만 느껴졌나요?","en":"Did the one-a-day limit hook you, or did it just feel like not enough?"}},"quadline":{"time":15,"setup":{"ko":"￦3,300 유료 앱이에요.","en":"It is a paid app at 3,300 won."},"missions":[{"ko":"첫 레벨을 아무 정보 없이 시작해 보세요. 글자 하나 없이 무엇을 해야 하는지 알아차리기까지 몇 초 걸리는지 재 보세요.","en":"Start the first level with no prior info. Time how many seconds it takes to understand what to do without a single word."},{"ko":"회전 화살표나 꺾쇠 기호가 처음 나오는 레벨에서 한 번 탭해 보세요. 기호의 모양과 움직임이 규칙을 어떻게 먼저 알려 주는지 보세요.","en":"Tap once on a level where circular arrows or chevrons first appear. Notice how the symbol's shape and motion explain the rule before you act."},{"ko":"라이트 모드와 다크 모드를 번갈아 켜고 같은 판을 보세요. 흑백 도형만으로 정보가 전달돼 색 없이도 판이 읽히는지 확인하세요.","en":"Switch between light and dark mode on the same level. Check that black and white shapes alone carry every piece of information."},{"ko":"막히는 레벨에서 일부러 오래 머물러 보세요. 타이머나 재촉이 없을 때 마음이 어떤지, 해답 기능이 어떻게 도와주는지 보세요.","en":"Stay stuck on a hard level on purpose. Notice how it feels with no timer or pressure, and how the built-in solution helps."}],"make":[{"ko":"내 앱의 튜토리얼 문구 하나를 지우고 아이콘과 애니메이션만으로 같은 내용을 전달해 보세요.","en":"Delete one tutorial sentence in your app and convey the same thing with only an icon and an animation."},{"ko":"내 앱 화면을 흑백으로 캡처해 색 없이도 상태가 구분되는지 보고, 구분이 안 되는 곳에 모양 차이를 더해 보세요.","en":"Capture your app's screens in grayscale, find states that can't be told apart without color, and add a shape difference."}],"ask":{"ko":"글 없이 배운 규칙 중 가장 빨리 이해된 기호는 무엇이었고, 왜 그랬나요?","en":"Which symbol taught you its rule fastest without words, and why?"}},"Little Nightmares":{"time":20,"setup":{"ko":"￦4,400 유료 게임이고, MFi 게임 컨트롤러가 있으면 함께 준비해 보세요.","en":"It is a paid game at 4,400 won; have an MFi game controller ready if you own one."},"missions":[{"ko":"첫 장면에서 아무 안내 없이 식스를 움직여 보세요. 터치 조작을 몇 번 만에 익히는지, 대사 없이 상황이 어떻게 전달되는지 보세요.","en":"Move Six through the opening scene without guidance. Notice how quickly you learn the touch controls and how the situation comes across with no dialogue."},{"ko":"거대한 어른이 앞이나 뒤에 나타나는 장면에서 잠시 멈춰 보세요. 깊이가 있는 측면 화면이 크기와 위협을 어떻게 느끼게 하는지 보세요.","en":"Pause when a giant adult looms in the foreground or background. Notice how the 2.5D diorama conveys scale and threat."},{"ko":"숨거나 기어서 피하는 순간을 여러 번 시도해 보세요. 싸울 수 없는 무력함이 어떻게 긴장을 만드는지 몸으로 느껴 보세요.","en":"Try hiding and crawling away several times. Feel how being unable to fight is what creates the tension."},{"ko":"추격 장면에서 실패하고 다시 해 보세요. 콘솔 게임을 터치로 다시 만든 조작이 정확한 순간에 어떤지, 컨트롤러가 있다면 바꿔 비교해 보세요.","en":"Fail a chase and retry it. Judge how the console game's rebuilt touch controls hold up in precise moments, and compare with a controller if you have one."}],"make":[{"ko":"내 앱에서 정밀한 제스처가 필요한 동작 하나를 골라 같은 기능을 버튼 같은 대체 입력으로도 할 수 있게 만들어 보세요.","en":"Pick one action in your app that needs a precise gesture and make it also possible through an alternative input such as a button."},{"ko":"텍스트 없이 위험이나 중요도를 알리는 화면 하나를 크기와 원근만으로 스케치해 보세요.","en":"Sketch one screen that signals danger or importance using only size and depth, with no text."}],"ask":{"ko":"터치 조작이 공포를 키웠나요, 아니면 방해했나요?","en":"Did the touch controls heighten the fear, or get in the way?"}},"Meditate":{"time":10,"setup":{"ko":"Apple Watch가 있으면 손목 햅틱으로 명상하는 것까지 해 볼 수 있어요.","en":"If you have an Apple Watch, you can also try meditating with wrist haptics."},"missions":[{"ko":"처음 열어 첫 세션을 시작하기까지 따라가 보세요. 타이머 하나를 시작하는 데 몇 번 탭했는지 세어 보세요.","en":"Open the app for the first time and follow it until your first session starts. Count the taps it takes to start a timer."},{"ko":"짧은 명상을 한 번 끝까지 해 보세요. 눈을 감고 있을 때 인터벌 종과 햅틱이 진행 상황을 어떻게 알려 주는지 느껴 보세요.","en":"Do one short session to the end. With your eyes closed, notice how interval bells and haptics tell you where you are."},{"ko":"세션을 마치고 만다라가 피어나는 순간을 지켜보세요. 배지나 숫자 대신 그림이 자라는 보상이 어떤 기분인지 느껴 보세요.","en":"Watch the mandala bloom after the session ends. Notice how a growing picture feels compared with a badge or a number."},{"ko":"지난 며칠의 명상을 거슬러 기록하고, 잠금 화면이나 홈 화면 위젯을 하나 추가해 보세요. 앱을 열지 않고 무엇이 보이는지 확인하세요.","en":"Log a past session retroactively, then add a Lock Screen or Home Screen widget. Check what you can see without opening the app."}],"make":[{"ko":"내 앱의 연속 기록 숫자를 쌓일수록 자라는 간단한 SwiftUI 도형으로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype a version of your app where the streak count becomes a simple SwiftUI shape that grows as it builds."},{"ko":"내 앱의 완료 순간에 햅틱 하나와 짧은 애니메이션 하나를 붙이고, 붙이기 전과 비교해 보세요.","en":"Add one haptic and one short animation to your app's completion moment and compare it with the version without them."}],"ask":{"ko":"만다라가 자라는 걸 보고 내일도 명상하고 싶어졌나요?","en":"Did watching the mandala grow make you want to meditate again tomorrow?"}},"stitch.":{"time":15,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"ko":"첫 후프를 시작해 보세요. 숫자 격자 퍼즐이 자수라는 옷을 입었을 때 규칙이 어떻게 소개되는지 보세요.","en":"Start your first Hoop. Notice how the rules of a numbered-grid puzzle are introduced once it is dressed as embroidery."},{"ko":"한 영역을 빈틈없이 채워 보세요. 실의 질감이 실제 바늘땀처럼 그려지는 순간을 가까이 들여다보세요.","en":"Fill one area with no gaps. Look closely at the moment the thread texture renders like real stitches."},{"ko":"Number Outlines, Big Numbers, Reduce Motion을 하나씩 켜 보세요. 판이 어떻게 달라지는지, 차분한 분위기는 그대로인지 보세요.","en":"Turn on Number Outlines, Big Numbers and Reduce Motion one at a time. See how the board changes and whether the calm mood survives."},{"ko":"후프를 완성한 뒤 Free Stitch 모드로 색을 바꿔 보세요. 실패가 없는 마무리가 어떤 느낌인지 보세요.","en":"After finishing a Hoop, recolor it in Free Stitch mode. Notice how a no-fail ending feels."}],"make":[{"ko":"내 앱에 큰 글자, 대비 강화, 동작 줄이기 중 하나를 실제로 넣고, 켰을 때와 껐을 때 화면을 캡처해 비교해 보세요.","en":"Add one of large text, higher contrast or reduced motion to your app, then capture and compare the screen with it on and off."},{"ko":"내 앱의 평범한 진행 표시 하나를 앱 주제에 맞는 재질 표현으로 바꾸는 스케치를 해 보세요.","en":"Sketch a version of one plain progress indicator in your app that uses a material fitting your app's theme."}],"ask":{"ko":"접근성 옵션을 켰을 때 게임이 덜 아름다워졌나요, 아니면 그대로였나요?","en":"When you turned on the accessibility options, did the game become less beautiful or stay the same?"}},"Knotwords":{"time":15,"setup":null,"missions":[{"ko":"첫 Daily Mini를 열어 보세요. 단서 없이 글자 묶음만 주어졌을 때 어디서부터 손이 가는지 보세요.","en":"Open your first Daily Mini. With only sets of letters and no clues, notice where you instinctively start."},{"ko":"한 영역의 글자를 배치해 가로와 세로 단어를 맞춰 보세요. 추측이 아니라 논리로 다음 칸이 좁혀지는 순간을 찾아보세요.","en":"Arrange one region's letters so the rows and columns form words. Find the moment logic, not guessing, narrows down the next cell."},{"ko":"일부러 틀린 배치를 해 보고 다시 풀어 보세요. 정답이 딱 하나라는 확신이 풀이를 어떻게 이끄는지 느껴 보세요.","en":"Place letters wrong on purpose, then solve again. Feel how knowing there is exactly one solution guides you."},{"ko":"유료 옵션을 안내하는 화면을 찾아보세요. 구독과 한 번 구매가 함께 있을 때 구독을 싫어하는 사람에게 어떤 인상을 주는지 생각해 보세요.","en":"Find where the paid options are presented. Think about how offering both a subscription and a one-time unlock reads to someone who dislikes subscriptions."}],"make":[{"ko":"내 앱의 무료 범위를 매일 작은 하나로 정하고, 요일마다 난이도가 오르는 일주일 표를 만들어 보세요.","en":"Define your app's free tier as one small thing a day and draft a weekly table where difficulty rises each day."},{"ko":"내 앱의 결제 화면에 구독과 한 번 구매를 나란히 놓은 버전을 스케치해 보세요.","en":"Sketch a version of your paywall that puts a subscription and a one-time purchase side by side."}],"ask":{"ko":"단서 없는 크로스워드인데도 막막하지 않았다면 그 이유는 무엇이었나요?","en":"If a crossword with no clues didn't feel hopeless, what made the difference?"}},"Beecarbonize":{"time":20,"setup":null,"missions":[{"ko":"첫 판을 시작해 네 부문을 살펴보세요. 산업, 생태계, 사람, 과학이 어떻게 나뉘어 있는지, 무엇부터 손이 가는지 보세요.","en":"Start your first game and look over the four sectors. Notice how industry, ecosystems, people and science are laid out and where you reach first."},{"ko":"카드를 몇 장 골라 자원을 늘려 보세요. 그동안 배출량이 어떻게 오르고 화면에 어떻게 드러나는지 지켜보세요.","en":"Pick a few cards to grow your resources. Watch how emissions rise meanwhile and how the screen shows it."},{"ko":"일부러 배출을 방치해 홍수나 폭염이 오게 해 보세요. 실제 기후 연구에 기반한 결과가 시스템으로 이어지는 방식을 느껴 보세요.","en":"Let emissions run on purpose until floods or heatwaves hit. Feel how consequences grounded in climate research chain through the system."},{"ko":"재난 타이머가 뜨면 일시 정지를 하고 생각해 보세요. 실시간 압박과 멈출 수 있는 여유가 함께 있을 때 결정이 어떻게 달라지는지 보세요.","en":"When a disaster timer appears, pause and think. Notice how your decisions change when real-time pressure comes with the option to stop."}],"make":[{"ko":"내 앱의 기능 하나를 원인 카드와 결과 카드 두 장으로 그려 보고, 사용자가 그 연결을 바로 이해하는지 확인해 보세요.","en":"Draw one of your app's features as two cards, a cause and an effect, and check whether a user grasps the link right away."},{"ko":"내 앱에서 시간에 따라 바뀌는 화면이 있다면 일시 정지나 속도 조절을 넣은 프로토타입을 만들어 보세요.","en":"If your app has a screen that changes over time, prototype a version with pause or speed controls."}],"ask":{"ko":"게임을 하면서 기후에 대해 새로 알게 된 것 하나는 무엇인가요?","en":"What is one thing you learned about climate while playing?"}},"Procreate":{"time":20,"setup":{"ko":"iPad 전용 앱이고 ￦22,000 한 번 구매예요. Apple Pencil이 있으면 더 좋아요.","en":"It is iPad only and a one-time purchase of 22,000 won; an Apple Pencil helps."},"missions":[{"ko":"새 캔버스를 열어 보세요. 화면에 도구 장식이 얼마나 적은지, 그림이 화면을 얼마나 채우는지 보세요.","en":"Open a new canvas. Notice how little tool chrome there is and how much of the display the artwork fills."},{"ko":"몇 줄 그은 뒤 두 손가락 탭으로 실행 취소, 세 손가락 탭으로 다시 실행해 보세요. 버튼을 찾지 않아도 되는 손맛을 느껴 보세요.","en":"Draw a few strokes, then two-finger tap to undo and three-finger tap to redo. Feel what it's like not to hunt for buttons."},{"ko":"Apple Pencil 압력을 바꿔 가며 같은 선을 여러 번 그어 보세요. 선 굵기가 손의 힘을 얼마나 따라오는지 보세요.","en":"Draw the same line several times with different Apple Pencil pressure. See how closely the stroke follows your hand."},{"ko":"접근성 설정에서 떨림·동작 필터를 켜고 같은 선을 그어 보세요. 손이 떨리는 사람에게 무엇이 달라지는지 상상해 보세요.","en":"Turn on tremor and motion filtering and draw the same line. Imagine what changes for someone whose hands shake."}],"make":[{"ko":"내 앱에서 자주 쓰는 동작 하나를 제스처로 바꾸고, 기존 버튼을 숨긴 화면을 만들어 비교해 보세요.","en":"Turn one frequent action in your app into a gesture and build a screen with its button hidden, then compare."},{"ko":"내 앱에서 정밀한 입력이 필요한 곳을 적어 보고, 그중 하나에 입력 흔들림을 부드럽게 다듬는 옵션을 넣어 보세요.","en":"List the places in your app that need precise input and add a smoothing option to one of them."}],"ask":{"ko":"화면에 버튼이 거의 없는데도 길을 잃지 않았다면 그 이유는 무엇인가요?","en":"If you didn't get lost despite almost no buttons, what kept you oriented?"}},"Please, Touch The Artwork":{"time":15,"setup":{"ko":"￦6,600 유료 게임이에요.","en":"It is a paid game at 6,600 won."},"missions":[{"ko":"첫 장을 시작해 보세요. 게임 UI 없이 그림 한 장이 화면을 가득 채울 때, 어디를 만져야 할지 알게 되는 과정을 보세요.","en":"Start the first chapter. With a painting filling the screen and no game HUD, notice how you figure out where to touch."},{"ko":"몬드리안 풍 격자 퍼즐에서 선을 그어 보세요. 이 게임이 몬드리안 생성기에서 시작됐다는 걸 떠올리며, 그림의 구조가 새로 보이는지 느껴 보세요.","en":"Draw lines in a Mondrian-style grid puzzle. Knowing the game began as a Mondrian generator, notice whether the painting's structure looks new to you."},{"ko":"엔소르 그림 속 숨은 물건을 찾아보세요. 손가락으로 화면을 훑는 동작이 그림을 자세히 보는 행동이 되는지 보세요.","en":"Search for hidden objects inside an Ensor painting. Notice how sweeping your finger turns into looking closely at the art."},{"ko":"키스 해링 풍 선 그리기 퍼즐을 하나 풀어 보세요. 화가마다 조작 방식이 바뀌는 것이 어떻게 느껴지는지 보세요.","en":"Solve one Keith Haring style line-drawing puzzle. Notice how it feels when the interaction changes with each artist."}],"make":[{"ko":"내 앱의 핵심 콘텐츠를 가리는 UI 요소 하나를 골라 지우거나 접어 보고, 콘텐츠가 주인공이 되는지 보세요.","en":"Pick one UI element that covers your app's core content, remove or collapse it, and see if the content becomes the hero."},{"ko":"좋아하는 그림이나 사진 한 장을 골라 그 구조에서 탭 한 번짜리 퍼즐 규칙을 떠올리고 SwiftUI로 만들어 보세요.","en":"Choose a painting or photo you love, derive a one-tap puzzle rule from its structure, and build it in SwiftUI."}],"ask":{"ko":"게임을 하고 나서 실제 그림을 보는 눈이 달라졌나요?","en":"After playing, has the way you look at real paintings changed?"}},"Empathy":{"time":15,"setup":{"ko":"미국 스토어 기준 앱이라 지역에 따라 내려받지 못할 수도 있어요.","en":"It is a US App Store app, so it may not be available in your region."},"missions":[{"ko":"처음 열어 초반 질문들을 따라가 보세요. 사별 직후의 사용자를 상정한 말투와 질문 순서가 어떻게 배려돼 있는지 보세요.","en":"Open it for the first time and go through the early questions. Notice how the tone and order are shaped for someone who has just lost a loved one."},{"ko":"맞춤 돌봄 계획 체크리스트를 살펴보세요. 회사가 추정한 약 570시간의 일을 어떤 단위로 쪼개 하나씩 보여 주는지 보세요.","en":"Look through the personal care plan checklist. See how it breaks down what the company estimates as about 570 hours of work into single steps."},{"ko":"가족을 초대하고 할 일을 나누는 흐름을 살펴보세요. 슬픔 속의 한 사람에게 몰린 짐을 어떻게 나누는지 보세요.","en":"Explore the flow for inviting family and assigning tasks. Notice how it spreads the burden away from one grieving person."},{"ko":"일상 치유 쪽의 일기나 호흡 연습을 하나 해 보세요. 행정 할 일 바로 옆에 감정 돌봄이 놓인 배치가 어떤 느낌인지 보세요.","en":"Try one journaling or breathing exercise in the daily healing practice. Notice how it feels to have grief care right beside the logistics."}],"make":[{"ko":"내 앱에서 사용자가 가장 지쳐 있을 순간의 화면 하나를 골라, 문구를 부드럽게 고치고 할 일을 하나만 보이게 다시 만들어 보세요.","en":"Pick the screen where your user is most exhausted, soften its wording and redesign it to show only one task."},{"ko":"내 앱의 긴 작업 하나를 다섯 단계 이하의 체크리스트로 쪼개 보세요.","en":"Break one long task in your app into a checklist of five steps or fewer."}],"ask":{"ko":"이 앱이 힘든 상황의 사용자를 대하는 방식 중 내 앱에 바로 가져올 한 가지는 무엇인가요?","en":"What is one way this app treats users in a hard moment that you could bring to your app right away?"}},"HoloVista":{"time":20,"setup":{"ko":"￦4,400 유료 게임이고, 휴대폰을 들고 몸을 돌릴 공간이 있으면 좋아요.","en":"It is a paid game at 4,400 won; you'll want room to turn around with your phone."},"missions":[{"ko":"첫 방에 들어가 휴대폰을 들고 몸을 돌려 보세요. 기기가 카메라 뷰파인더가 되는 순간을 게임이 어떻게 알려 주는지 보세요.","en":"Enter the first room and turn around holding your phone. Notice how the game shows you that the device is now a viewfinder."},{"ko":"방 안의 숨은 물건 세 개를 찾아 사진을 찍어 보세요. 막히면 힌트가 남은 물건을 어떻게 가리키는지 보세요.","en":"Find and photograph the three hidden objects in a room. If you get stuck, see how the hint points toward what's left."},{"ko":"찍은 사진을 게임 속 소셜 피드에 올리고 캐릭터와 대화해 보세요. 사진 찍는 행동 자체가 이야기를 전하는 방식을 느껴 보세요.","en":"Post your photos to the in-game social feed and chat with characters. Feel how the act of taking photos carries the story."},{"ko":"접근성 옵션에서 동작 조작 대안을 켜고 앉은 채로 같은 방을 둘러보세요. 몸을 움직이지 않아도 경험이 남아 있는지 보세요.","en":"Turn on the motion-control alternative and look around the same room while seated. See whether the experience holds up without moving."}],"make":[{"ko":"내 앱에서 기기 움직임이나 특정 제스처에만 기대는 기능을 찾아 대안 입력 경로를 하나 추가해 보세요.","en":"Find a feature in your app that relies only on device motion or a specific gesture and add one alternative input path."},{"ko":"내 앱에 글자 크기, 대비, 효과 강도 조절이 있는지 점검표를 만들고, 빠진 것 하나를 구현해 보세요.","en":"Make a checklist of text size, contrast and effect intensity controls in your app and implement one that's missing."}],"ask":{"ko":"움직임 대신 대안 조작으로 했을 때 잃은 것과 남은 것은 각각 무엇이었나요?","en":"Using the alternative controls instead of motion, what did you lose and what remained?"}},"Wonderbox":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라, 개발사의 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사 트레일러를 처음부터 보세요. 스토리 캠페인, 만들기 모드, 다른 사람의 레벨이 어떤 순서로 소개되는지 적어 보세요.","en":"Watch the developer's trailer from the start. Write down the order in which the campaign, Create mode and other players' levels are introduced."},{"ko":"만들기 모드가 나오는 장면에서 멈춰 보세요. 여덟 살 아이도 쓸 수 있게 도구가 얼마나 단순한지 화면 요소 수를 세어 보세요.","en":"Pause on a Create mode shot. Count the on-screen elements to judge how simple the tools are for an eight-year-old."},{"ko":"다른 플레이어가 만든 레벨을 탐색하는 장면을 찾아보세요. 놀기와 만들기가 한 앱 안에서 어떻게 이어지는지 보세요.","en":"Find a shot of browsing levels made by other players. Notice how playing and making connect inside one app."},{"ko":"한 모험 안에서 액션, 플랫포밍, 퍼즐이 섞이는 장면을 찾아보세요. 장르가 바뀌는 순간이 어떻게 이어 붙어 있는지 보세요.","en":"Find a moment where action, platforming and puzzles mix in one adventure. See how the genre switches are stitched together."}],"make":[{"ko":"내 앱에서 사용자가 만든 것을 다른 사용자가 바로 써 보는 흐름을 세 단계 이하로 스케치해 보세요.","en":"Sketch a flow of three steps or fewer in which something one user makes can be used right away by another."},{"ko":"내 앱의 만들기 화면을 여덟 살 아이가 쓴다고 가정하고, 지워도 될 요소 세 개를 골라 실제로 숨겨 보세요.","en":"Imagine an eight-year-old using your app's creation screen, pick three elements to remove, and actually hide them."}],"ask":{"ko":"트레일러만 보고도 직접 만들어 보고 싶다는 마음이 들었나요, 그렇다면 어느 장면 때문이었나요?","en":"Did the trailer alone make you want to build something, and if so, which shot did it?"}},"Klima":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라, 개발사의 트레일러나 스크린숏으로 살펴봐야 해요.","en":"It has left the App Store, so explore it through the developer's own trailer or screenshots."},"missions":[{"ko":"개발사 영상이나 스크린숏에서 첫 계산 화면을 찾아보세요. 몇 가지 생활 질문으로 탄소 발자국을 계산하는 흐름을 보세요.","en":"Find the first calculator screen in the developer's video or screenshots. Look at how a few lifestyle questions produce a carbon footprint."},{"ko":"계산 결과가 월 구독으로 바뀌는 화면을 찾아보세요. 추상적인 숫자가 돈과 행동으로 번역되는 방식을 보세요.","en":"Find the screen where the result becomes a monthly subscription. Notice how an abstract number is translated into money and action."},{"ko":"나무 심기, 태양광, 조리기구 중 고르는 화면을 찾아보세요. 선택지를 셋으로 나눈 것이 결정을 쉽게 하는지 생각해 보세요.","en":"Find the screen for choosing tree planting, solar or clean cookstoves. Consider whether three options make the decision easier."},{"ko":"Climate Class 영상과 줄이기 팁이 소개되는 부분을 찾아보세요. 상쇄에서 끝나지 않고 생활 변화로 이어지게 한 장치를 보세요.","en":"Find where Climate Class videos and reduction tips appear. Look at how the app pushes past offsetting toward real lifestyle change."}],"make":[{"ko":"내 앱이 보여 주는 숫자 하나를 사용자가 오늘 할 수 있는 행동 하나로 번역한 문구로 바꿔 보세요.","en":"Rewrite one number your app shows as a single action the user can take today."},{"ko":"내 앱의 긴 초기 설정을 질문 다섯 개 이하로 줄인 온보딩을 스케치해 보세요.","en":"Sketch an onboarding that reduces your app's long initial setup to five questions or fewer."}],"ask":{"ko":"탄소 상쇄를 월 구독으로 만든 설계가 설득력 있었나요, 부담스러웠나요?","en":"Did turning carbon offsetting into a monthly subscription feel convincing or burdensome?"}},"Museum Alive":{"time":15,"setup":{"ko":"￦4,400 유료 앱이고, AR을 쓰니 바닥이 넓은 방에서 해 보세요.","en":"It is a paid app at 4,400 won and uses AR, so try it in a room with open floor space."},"missions":[{"ko":"처음 열어 방 바닥을 비추는 과정을 따라가 보세요. 공간 인식을 어떻게 안내하는지, 첫 화석이 놓이기까지 몇 단계인지 세어 보세요.","en":"Open it and follow the steps for scanning your floor. Notice how it guides you and count the steps until the first fossil is placed."},{"ko":"화석을 바닥에 놓고 되살아나는 순간을 지켜보세요. 실제 크기의 생물과 애튼버러의 내레이션이 내 거실을 어떻게 바꾸는지 느껴 보세요.","en":"Place a fossil and watch it come to life. Feel how a real-scale creature and Attenborough's narration transform your living room."},{"ko":"스밀로돈 주위를 걸으며 여러 각도에서 보고 상호작용 핫스폿을 눌러 보세요. 서식지 정보가 어떤 형태로 나타나는지 보세요.","en":"Walk around the Smilodon to see it from several angles and tap an interactive hotspot. Notice how habitat information is presented."},{"ko":"네 생물을 모두 둘러본 뒤 멈춰 보세요. 콘텐츠를 다 본 뒤에도 다시 열 이유가 남아 있는지 생각해 보세요.","en":"After seeing all four creatures, stop. Ask yourself whether any reason to reopen the app remains."}],"make":[{"ko":"내 앱의 콘텐츠 양을 세어 사용자가 첫 주에 다 소비할지 계산하고, 부족하면 반복 가능한 구조로 바꿀 부분을 하나 정해 보세요.","en":"Count your app's content, estimate whether a user would finish it in the first week, and pick one part to make repeatable if not."},{"ko":"RealityKit으로 간단한 모델 하나를 바닥에 실제 크기로 놓는 프로토타입을 만들어, 크기감이 주는 차이를 느껴 보세요.","en":"Prototype placing one simple model on the floor at real scale with RealityKit and feel what true size adds."}],"ask":{"ko":"실제 크기라는 점이 화면 속 영상보다 무엇을 더 전해 줬나요?","en":"What did real scale give you that a video on a screen would not?"}},"Noom":{"time":20,"setup":{"ko":"설문형 온보딩을 끝까지 하려면 시간이 걸리고, 마지막에 결제 화면이 나와요.","en":"The survey-style onboarding takes a while to finish and ends at a payment screen."},"missions":[{"ko":"설치 후 설문형 온보딩을 끝까지 따라가 보세요. 질문이 몇 개인지 세고, 상단 진행 표시가 남은 양을 어떻게 알려 주는지 보세요.","en":"Go through the survey onboarding to the end. Count the questions and notice how the top progress indicator shows how much is left."},{"ko":"질문 사이에 끼어드는 요약·설명 화면에서 멈춰 보세요. 내 답이 어떻게 반영돼 설문이 나를 이해하는 과정처럼 느껴지는지 보세요.","en":"Pause on the summary screens between questions. Notice how your answers are reflected so the survey feels like being understood."},{"ko":"마지막의 목표 달성 예측과 결제 화면을 보세요. 결제는 하지 말고, 설득이 압박으로 바뀌는 지점이 어디인지 표시해 보세요.","en":"Look at the personalized prediction and the payment screen at the end. Don't pay, but mark where persuasion turns into pressure."},{"ko":"짧은 일일 레슨을 볼 수 있다면 하나 열어 보세요. 칼로리 기록 앱이 아니라 행동 변화 프로그램으로 느껴지게 하는 요소를 찾아보세요.","en":"If you can access a short daily lesson, open one. Look for what makes it feel like a behavior change program rather than a calorie tracker."}],"make":[{"ko":"내 앱 온보딩에 진행 표시를 넣고, 질문 세 개마다 답을 반영한 한 줄 요약 화면을 끼워 보세요.","en":"Add a progress indicator to your onboarding and insert a one-line summary screen reflecting the answers after every three questions."},{"ko":"내 앱의 결제 직전 화면을 다시 보고, 거절해도 불편하지 않도록 닫기 위치와 문구를 고쳐 보세요.","en":"Revisit the screen right before your paywall and fix the close button placement and wording so saying no isn't uncomfortable."}],"ask":{"ko":"설문을 끝까지 한 건 궁금해서였나요, 아니면 이미 들인 시간이 아까워서였나요?","en":"Did you finish the survey out of curiosity, or because you'd already invested the time?"}},"Otter.ai":{"time":15,"setup":{"ko":"함께 대화할 사람이 한 명 있으면 화자 구분까지 확인할 수 있어요.","en":"Having a second person to talk with lets you see speaker separation too."},"missions":[{"ko":"첫 녹음을 시작하기 직전까지 따라가 보세요. 녹음 동의 안내가 어디서 어떻게 나오는지, 상대에게 알리게 하는 장치가 있는지 보세요.","en":"Follow the app up to your first recording. Notice where and how consent guidance appears and whether it prompts you to tell others."},{"ko":"다른 사람과 짧게 대화하며 녹음해 보세요. 전사문이 실시간으로 이어지고 화자가 자동으로 나뉘는 순간을 지켜보세요.","en":"Record a short conversation with someone. Watch the transcript appear live and split itself by speaker."},{"ko":"녹음을 마치고 전사문의 단어 하나를 탭해 보세요. 그 구간이 재생되고 잘못 들은 부분을 그 자리에서 고치는 흐름을 느껴 보세요.","en":"After recording, tap a word in the transcript. Feel the flow of hearing that moment and fixing a misheard word in place."},{"ko":"AI 요약과 하이라이트를 열어 보세요. 긴 전사문을 다 읽지 않고 결정 사항을 얼마나 빨리 찾는지 재 보세요.","en":"Open the AI summary and highlights. Time how fast you find the decisions without reading the full transcript."}],"make":[{"ko":"내 앱에서 녹음, 카메라, 위치처럼 민감한 기능을 켜기 직전 화면에 무엇을 왜 기록하는지 한 문장 안내를 넣어 보세요.","en":"Add a one-sentence notice explaining what is recorded and why, right before a sensitive feature like the mic, camera or location turns on."},{"ko":"내 앱의 긴 텍스트 결과 위에 핵심 세 줄 요약 카드를 얹은 프로토타입을 만들어 보세요.","en":"Prototype a three-line summary card on top of a long text result in your app."}],"ask":{"ko":"녹음 전에 상대의 동의를 챙기게 하는 장치가 충분하다고 느꼈나요?","en":"Did the app do enough to make you get the other person's consent before recording?"}},"Pinterest":{"time":10,"setup":null,"missions":[{"ko":"처음 열어 홈 피드가 뜨는 순간을 지켜보세요. 이미지가 로드되기 전에 칸이 대표 색으로 먼저 채워지는지 확인하세요.","en":"Open the app and watch the home feed load. Check whether cells fill with each image's dominant color before the image arrives."},{"ko":"메이슨리 그리드를 빠르게 스크롤해 보세요. 높이가 제각각인 이미지가 원래 비율대로 어긋나게 쌓이며 끝없이 이어지는 느낌을 보세요.","en":"Scroll the masonry grid quickly. Notice how images of different heights keep their ratios and stack in an endless staggered flow."},{"ko":"핀 하나를 탭해 보세요. 셀의 이미지가 커지며 상세 화면으로 이어지는 전환에서 시선이 끊기지 않는지 보세요.","en":"Tap a pin. Notice whether your eye stays on the image as it expands from the cell into the detail view."},{"ko":"상세 화면 아래의 비슷한 핀 그리드로 내려가 하나를 저장해 보세요. 저장까지 몇 번 탭했는지 세어 보세요.","en":"Scroll down to the similar pins grid under the detail view and save one. Count the taps it took to save."},{"ko":"Lens로 주변 사진의 일부를 골라 비슷한 핀을 찾아보세요. 글자를 치지 않고도 탐색이 이어지는지 보세요.","en":"Use Lens to select part of a photo of your surroundings and find similar pins. See whether exploring continues without typing."}],"make":[{"ko":"내 앱의 이미지 목록에 로딩 전 대표 색 자리표시를 넣고, 회색 상자와 나란히 비교해 보세요.","en":"Add dominant-color placeholders to an image list in your app and compare them side by side with gray boxes."},{"ko":"SwiftUI의 matchedGeometryEffect로 목록 셀의 이미지가 상세 화면으로 커지는 전환을 만들어 보세요.","en":"Use SwiftUI's matchedGeometryEffect to build a transition where a list cell's image grows into the detail view."}],"ask":{"ko":"상세 화면을 보다가 다음 핀으로 넘어간 순간, 무엇이 나를 이끌었나요?","en":"When you moved from a detail view on to another pin, what pulled you there?"}},"Figma":{"time":15,"setup":{"ko":"확인할 Figma 파일이나 프로토타입 링크가 하나 있어야 해요.","en":"You need a Figma file or prototype link to look at."},"missions":[{"ko":"앱에 로그인한 뒤 첫 화면을 보세요. 편집 도구 대신 무엇이 보이는지, 작은 화면에서 할 일을 어떻게 좁혔는지 보세요.","en":"Sign in and look at the first screen. Notice what you see instead of editing tools and how the job has been narrowed for a small screen."},{"ko":"큰 파일을 열어 핀치 줌과 두 손가락 팬으로 돌아다녀 보세요. 페이지·프레임 목록으로 원하는 화면에 가기까지 몇 번 탭하는지 세어 보세요.","en":"Open a large file and move around with pinch zoom and two-finger pan. Count the taps to jump to a specific frame from the page and frame list."},{"ko":"프로토타입을 풀스크린으로 실행해 보세요. 데스크톱 미리보기에서는 몰랐던 탭 영역이나 스크롤 감각의 어색함을 찾아보세요.","en":"Run a prototype full screen. Look for awkward tap targets or scrolling that a desktop preview would have hidden."},{"ko":"화면 하나에 댓글을 남겨 보세요. 여러 사람이 함께 편집하는 데스크톱 기능 중 무엇을 빼고 보기와 댓글만 남겼는지 생각해 보세요.","en":"Leave a comment on a frame. Think about what the mobile app dropped from desktop collaboration to keep only viewing and commenting."}],"make":[{"ko":"내 앱의 모바일 화면 하나에서 꼭 필요한 동작 세 가지만 남기고 나머지를 다른 화면으로 옮겨 보세요.","en":"On one of your app's screens, keep only the three essential actions and move the rest elsewhere."},{"ko":"내 앱 디자인을 실제 기기에서 프로토타입으로 실행해 손가락에 비해 작은 탭 영역을 세 군데 찾아 고쳐 보세요.","en":"Run your app's design as a prototype on a real device, find three tap targets too small for a finger, and fix them."}],"ask":{"ko":"모바일에서 편집이 안 되는 것이 불편했나요, 아니면 오히려 명확했나요?","en":"Was not being able to edit on mobile frustrating, or did it make things clearer?"}},"Google":{"time":10,"setup":null,"missions":[{"ko":"앱을 열고 검색창 옆 카메라 아이콘으로 렌즈에 들어가 보세요. 입력 대신 보여 주는 검색으로 넘어가기까지 몇 번 탭하는지 세어 보세요.","en":"Open the app and enter Lens from the camera icon next to the search bar. Count the taps it takes to switch from typing to showing."},{"ko":"책 표지나 상품을 비춰 보세요. 셔터를 누르기 전부터 텍스트와 물체가 하이라이트로 겹쳐 보이는 순간을 지켜보세요.","en":"Point it at a book cover or a product. Watch text and objects get highlighted before you even press the shutter."},{"ko":"번역 모드로 외국어 메뉴나 표지판을 비춰 보세요. 원래 레이아웃 위에 번역문이 그대로 덮이는 느낌을 확인하세요.","en":"Point translate mode at a foreign menu or sign. Notice how the translation is laid over the original layout."},{"ko":"인식 결과가 올라오는 하단 시트를 끌어올려 보세요. 처음엔 카메라를 가리지 않다가 결과가 점점 넓어지는 단계를 보세요.","en":"Drag up the bottom sheet with the results. Notice how it stays out of the camera's way at first and then expands step by step."},{"ko":"사진을 찍은 뒤 텍스트를 덧붙여 질문해 보세요. 이미지와 말이 하나의 검색으로 합쳐지는 방식을 보세요.","en":"Take a photo and add text to ask a question about it. See how the image and words combine into one search."}],"make":[{"ko":"내 앱의 결과 화면을 하단 시트로 바꿔, 처음엔 요약만 보이고 끌어올리면 전체가 보이도록 프로토타입을 만들어 보세요.","en":"Prototype your app's result screen as a bottom sheet that shows a summary first and the full result when dragged up."},{"ko":"VisionKit의 DataScannerViewController로 카메라 속 텍스트에 하이라이트를 띄우는 작은 화면을 만들어 보세요.","en":"Build a small screen with VisionKit's DataScannerViewController that highlights text in the camera feed."}],"ask":{"ko":"글자로 검색하는 것보다 카메라가 더 빨랐던 순간은 언제였나요?","en":"When was the camera faster than typing a search?"}},"Scriptable":{"time":30,"setup":{"ko":"무료 앱이고, JavaScript를 조금 알면 더 쉽게 해 볼 수 있어요.","en":"It is free, and a little JavaScript knowledge makes it easier."},"missions":[{"ko":"처음 열어 빈 상태를 보세요. 첫 코드를 쓰기까지 무엇이 안내되는지, 앱 안의 오프라인 문서를 어디서 찾는지 보세요.","en":"Open it and look at the empty state. Notice what guides you to your first line of code and where the in-app offline docs live."},{"ko":"ListWidget으로 글자 한 줄을 띄우는 짧은 스크립트를 써 보세요. 코드 몇 줄이 위젯이 되는 감각을 느껴 보세요.","en":"Write a short script that shows one line of text with ListWidget. Feel how a few lines of code become a widget."},{"ko":"홈 화면에 Scriptable 위젯을 추가하고 내 스크립트를 연결해 보세요. 새로고침은 iOS가 정한다는 제약을 문서가 어떻게 미리 알려 주는지 보세요.","en":"Add a Scriptable widget to your Home Screen and link your script. Notice how the docs warn upfront that iOS controls the refresh rate."},{"ko":"단축어 앱에서 내 스크립트를 실행해 보세요. 다른 앱과 이어지는 자동화 흐름이 어떻게 만들어지는지 보세요.","en":"Run your script from the Shortcuts app. See how it links into automation with other apps."}],"make":[{"ko":"내 앱의 위젯이나 화면에서 사용자가 바꿀 수 없는 것 하나를 골라 사용자 설정으로 열어 주는 옵션을 만들어 보세요.","en":"Pick one thing in your app's widget or screens that users can't change and add an option that lets them."},{"ko":"내 앱 도움말에 시스템 제약 때문에 못 하는 일을 솔직하게 한 문장으로 적어 넣어 보세요.","en":"Add one honest sentence to your app's help text about something it can't do because of system limits."}],"ask":{"ko":"코드로 위젯을 만드는 경험이 개발자가 아닌 사람에게도 열릴 수 있다고 느꼈나요?","en":"Did building a widget with code feel like something that could open up to non-developers?"}},"리멤버":{"time":15,"setup":{"ko":"받아 둔 종이 명함이 한 장 있어야 해요.","en":"You need at least one paper business card."},"missions":[{"ko":"가입부터 첫 명함 촬영까지 따라가 보세요. 카메라에 도착하기까지 몇 단계를 거치는지 세어 보세요.","en":"Follow the flow from sign-up to your first card photo. Count how many steps it takes to reach the camera."},{"ko":"명함을 찍은 직후 화면을 보세요. 사람이 직접 입력하는 동안의 대기 상태를 어떻게 보여 주는지, 기다림을 불안하지 않게 하는 장치를 찾아보세요.","en":"Look at the screen right after taking the photo. Notice how it shows the wait while a person types it in, and what keeps the wait from feeling uncertain."},{"ko":"입력이 끝난 뒤 다시 열어 보세요. 대기와 완료 상태가 어떻게 구분되는지, 결과가 OCR 앱으로 읽었을 때와 어떻게 다른지 비교해 보세요.","en":"Reopen it after the entry is done. Compare how waiting and finished states differ, and how the result compares to an OCR app."},{"ko":"저장한 명함을 휴대폰 연락처로 내보내 보세요. 직장인의 실제 업무 흐름에 어떻게 맞춰져 있는지 보세요.","en":"Export the saved card to your phone's contacts. Notice how it fits into the real workflow of office workers."}],"make":[{"ko":"내 앱에서 시간이 걸리는 작업 하나를 골라 진행 중과 완료 두 상태를 분명히 나눈 화면을 만들어 보세요.","en":"Pick one slow task in your app and build a screen that clearly separates the in-progress and finished states."},{"ko":"오래 걸리는 처리가 끝났을 때 보낼 알림 문구를 한 줄 쓰고 로컬 알림으로 직접 받아 보세요.","en":"Write a one-line notification for when a long process finishes and send it to yourself as a local notification."}],"ask":{"ko":"기다려야 하는 구조인데도 답답하지 않았다면 그 이유는 무엇인가요?","en":"If having to wait didn't feel frustrating, why not?"}},"Structured":{"time":10,"setup":null,"missions":[{"ko":"처음 열어 첫 할 일을 만들 때까지 따라가 보세요. 기기 안 AI가 제안하거나 미리 채워 주는 부분이 시작 부담을 얼마나 줄이는지 보세요.","en":"Open it and follow along until your first task is created. Notice how much the on-device AI suggestions and pre-filling ease getting started."},{"ko":"오늘 일정을 서너 개 넣어 보세요. 세로 타임라인 위에 색과 아이콘 블록으로 쌓이며 빈 시간과 과부하가 어떻게 드러나는지 보세요.","en":"Add three or four items for today. Watch them stack as colored, icon-tagged blocks on the timeline and reveal gaps and overloads."},{"ko":"휴식 시간 블록을 하나 넣어 보세요. 쉬는 시간이 할 일과 같은 무게로 놓일 때 어떤 느낌인지 보세요.","en":"Add a block for a break. Notice how it feels when downtime sits on the timeline with the same weight as tasks."},{"ko":"홈 화면이나 잠금 화면 위젯을 추가해 보세요. 앱을 열지 않고도 다음 할 일이 보이는지 확인하세요.","en":"Add a Home Screen or Lock Screen widget. Check that you can see what's next without opening the app."}],"make":[{"ko":"내 앱의 목록 화면 하나를 시간 순 세로 타임라인으로 바꿔 빈 구간이 보이도록 스케치해 보세요.","en":"Sketch one of your app's list screens as a time-ordered vertical timeline that makes empty gaps visible."},{"ko":"Foundation Models 프레임워크로 사용자가 쓴 짧은 문장에서 제목을 미리 채워 주는 기능을 프로토타입으로 만들어 보세요.","en":"Prototype a feature with the Foundation Models framework that pre-fills a title from a short sentence the user types."}],"ask":{"ko":"하루를 한 줄 타임라인으로 보니 무엇이 가장 먼저 눈에 들어왔나요?","en":"Seeing your day as a single timeline, what stood out first?"}},"Moonlitt: Moon Phase Tracker":{"time":10,"setup":{"ko":"밖이나 창가에서 해 보면 실제 달 방향과 비교할 수 있어요.","en":"Try it outdoors or by a window so you can compare with the real moon."},"missions":[{"ko":"처음 열어 온보딩을 따라가 보세요. 끝나자마자 화면 전체가 나침반이 되어 달 방향을 가리키는 순간을 보세요.","en":"Open it and go through onboarding. Watch the whole screen turn into a compass pointing at the moon right after."},{"ko":"휴대폰을 들고 화살표를 따라 몸을 돌려 보세요. 탭 한 번 없이 답을 얻는 느낌과, 실제 달이 그 방향에 있는지 확인해 보세요.","en":"Hold up your phone and turn to follow the arrow. Feel getting the answer with zero taps, and check if the moon is really there."},{"ko":"시간 슬라이더를 천천히, 또 빠르게 앞뒤로 밀어 보세요. 몇 달 동안 다듬었다는 반응과 햅틱을 손끝으로 느껴 보세요.","en":"Scrub the time slider slowly and then fast. Feel the response and haptics the team spent months tuning."},{"ko":"Liquid Glass가 쓰인 화면 요소를 찾아보세요. 반투명 재질이 달 배경 위에서 어떻게 읽히는지 보세요.","en":"Find the elements that use Liquid Glass. Notice how the translucent material reads against the moon background."}],"make":[{"ko":"내 앱의 첫 화면에 사용자가 가장 궁금해할 답 하나를 탭 없이 바로 보여 주는 버전을 만들어 보세요.","en":"Build a version of your app's first screen that shows the user's most wanted answer with zero taps."},{"ko":"내 앱의 슬라이더 하나에 sensoryFeedback으로 햅틱을 붙이고, 간격을 바꿔 가며 가장 좋은 느낌을 찾아보세요.","en":"Add haptics to one slider in your app with sensoryFeedback and try different intervals to find the best feel."}],"ask":{"ko":"탭 없이 답이 나오는 첫 화면이 내 앱에도 있다면, 그 답은 무엇이어야 할까요?","en":"If your app had a first screen that answered with zero taps, what should that answer be?"}},"Caradise":{"time":15,"setup":{"ko":"Apple Vision Pro 전용 앱이고, 무료 스타터 팩 세 대로 시작할 수 있어요.","en":"It is Apple Vision Pro only, and you can start with a free starter pack of three cars."},"missions":[{"ko":"처음 열어 스타터 팩의 차 한 대를 방에 미니어처 크기로 놓아 보세요. 놓기까지의 안내와 방 조명이 차체에 비치는 모습을 보세요.","en":"Open it and place a starter pack car in your room at miniature scale. Notice the guidance and how your room's light reflects on the body."},{"ko":"같은 차를 실제 크기로 바꿔 보세요. 크기가 바뀔 때 공간감이 어떻게 달라지는지 몸으로 느껴 보세요.","en":"Switch the same car to true scale. Feel how the sense of space changes with size."},{"ko":"문을 탭해 열고 안으로 들어가 시동을 걸어 보세요. 공간 음향의 엔진 소리와 배기 입자 효과가 나를 어떻게 둘러싸는지 느껴 보세요.","en":"Tap a door open, step inside and start the engine. Feel how the Spatial Audio engine sound and exhaust particles surround you."},{"ko":"AI Concierge에 말로 차 색을 바꿔 달라고 해 보세요. 타이핑이 어려운 환경에서 음성이 얼마나 자연스러운지 보세요.","en":"Ask the AI Concierge out loud to change the paint color. Notice how natural voice feels where typing is awkward."}],"make":[{"ko":"내 앱의 정적인 이미지 하나를 탭하면 상태가 바뀌는 인터랙티브 요소로 바꿔 보세요.","en":"Turn one static image in your app into an interactive element that changes state when tapped."},{"ko":"내 앱의 무료 범위를 스타터 팩처럼 맛보기 묶음 하나로 다시 정의해 보세요.","en":"Redefine your app's free tier as a single taster bundle, like a starter pack."}],"ask":{"ko":"차를 보는 것과 차 안에 들어가는 것 중 무엇이 더 기억에 남았나요?","en":"Which stayed with you more, looking at the car or sitting inside it?"}},"Prince of Persia: The Lost Crown":{"time":20,"setup":{"ko":"초반부는 무료로 체험할 수 있고, 전체를 하려면 구매가 필요해요.","en":"The opening is a free trial; the full game requires a purchase."},"missions":[{"ko":"무료 체험의 첫 장면을 시작해 보세요. 화면 버튼이 어디 있고 첫 공격과 회피까지 손이 얼마나 빨리 익는지 보세요.","en":"Start the free trial's opening. Notice where the on-screen buttons sit and how fast your hands learn the first attack and dodge."},{"ko":"적과 싸우며 패리를 시도하고, 실패하면 다시 해 보세요. 공격, 회피, 패리의 리듬이 터치에서 어떻게 느껴지는지 보세요.","en":"Fight an enemy and try to parry, retrying when you fail. Feel how the attack, dodge and parry rhythm works on touch."},{"ko":"자동 패리나 전투 중 시간 느리게 하기를 켜고 같은 적과 다시 싸워 보세요. 도전은 남고 손의 부담만 줄어드는지 느껴 보세요.","en":"Turn on auto-parry or combat slow-down and fight the same enemy again. Feel whether the challenge stays while the strain on your hands drops."},{"ko":"화면 버튼의 위치와 크기를 내 손에 맞게 바꿔 보세요. 바꾼 뒤 조작이 얼마나 달라지는지 보세요.","en":"Remap the on-screen buttons' position and size to fit your hands. Notice how much the controls change."},{"ko":"아직 갈 수 없는 곳을 만나면 Memory Shard로 지도에 스크린숏을 꽂아 보세요.","en":"When you hit a spot you can't reach yet, pin a screenshot to the map with a Memory Shard."}],"make":[{"ko":"내 앱에서 어려운 동작 하나를 골라 켜면 같은 결과를 더 쉽게 얻는 도움 옵션을 만들어 보세요.","en":"Pick one hard action in your app and add an assist option that reaches the same result more easily."},{"ko":"내 앱의 목록이나 지도에 사용자가 스크린숏이나 메모를 꽂아 두는 기능을 간단히 만들어 보세요.","en":"Build a simple way for users to pin a screenshot or note to a list or map in your app."}],"ask":{"ko":"도움 옵션을 켰을 때 게임이 쉬워졌다고 느꼈나요, 아니면 나에게 맞춰졌다고 느꼈나요?","en":"With assists on, did the game feel easier, or did it feel fitted to you?"}},"PBJ — The Musical":{"time":20,"setup":{"ko":"￦6,600 유료 게임이고, 소리를 켜고 해야 해요.","en":"It is a paid game at 6,600 won; play with sound on."},"missions":[{"ko":"첫 무대를 시작해 보세요. 종이 콜라주는 스톱모션처럼 끊겨 움직이는데 조작은 매끄러운 그 차이를 느껴 보세요.","en":"Start the first stage. Feel the contrast between the paper collage moving like stop-motion and the smooth controls."},{"ko":"손가락으로 오려 낸 인물을 밀고 당겨 보세요. 햅틱과 카메라 각도가 종이를 직접 만지는 느낌을 어떻게 만드는지 보세요.","en":"Push and pull a cutout figure with your finger. Notice how haptics and camera angles make it feel like touching paper."},{"ko":"한 구간에서 일부러 천천히 움직여 보세요. 음악의 연주 구간이 내 속도에 맞춰 늘어나는지 귀 기울여 보세요.","en":"Move slowly on purpose through one section. Listen for whether the instrumental parts stretch to match your pace."},{"ko":"화면 속 종이 조각의 가장자리를 가까이 들여다보세요. 아이용 안전 가위로 잘라 일부러 고르지 않게 만든 결을 찾아보세요.","en":"Look closely at the edges of the paper pieces. Find the imperfect cuts made on purpose with children's safety scissors."}],"make":[{"ko":"내 앱의 아이콘이나 일러스트 하나를 종이로 직접 오려 촬영해 넣어 보고, 손맛이 주는 차이를 비교해 보세요.","en":"Cut one icon or illustration for your app out of paper, photograph it, drop it in, and compare the handmade feel."},{"ko":"내 앱의 애니메이션이나 소리 하나가 사용자의 속도에 맞춰 길어지거나 짧아지도록 만들어 보세요.","en":"Make one animation or sound in your app stretch or shrink to match the user's pace."}],"ask":{"ko":"손으로 만든 결이 가장 크게 느껴진 순간은 언제였나요?","en":"When did you feel the handmade texture most strongly?"}},"Opal":{"time":15,"setup":null,"missions":[{"ko":"처음 열어 Screen Time 권한을 허용하는 과정을 따라가 보세요. 시스템 권한이 왜 필요한지 어떻게 설명하는지 보세요.","en":"Open it and go through granting Screen Time access. Notice how it explains why it needs a system-level permission."},{"ko":"자주 여는 앱 하나를 골라 짧은 집중 세션을 시작해 보세요. 설정까지 몇 번 탭했는지 세어 보세요.","en":"Pick an app you open often and start a short focus session. Count the taps it took to set up."},{"ko":"세션 중에 그 앱을 열어 보세요. 막히는 순간의 화면이 좌절 대신 내 의도를 어떻게 묻는지 보세요.","en":"Open that app during the session. Notice how the block screen asks about your intent instead of just frustrating you."},{"ko":"세션을 끝까지 마쳐 젬을 받을 수 있는지 보세요. 젬이 열릴 때의 햅틱 애니메이션을 손끝으로 느껴 보세요.","en":"Finish the session and see if you earn a gem. Feel the haptic animation when it unlocks."}],"make":[{"ko":"내 앱에서 사용자를 막는 화면 하나를 골라, 거절 문구 대신 다음 선택지를 묻는 문구로 바꿔 보세요.","en":"Pick one screen in your app that blocks the user and replace the refusal with a question offering next choices."},{"ko":"내 앱의 무료 한도를 지금보다 넉넉하게 늘렸을 때 사용자가 얻을 가치를 한 문장으로 적고, 한도 숫자 하나를 실제로 바꿔 보세요.","en":"Write one sentence on what users would gain if your free limit were more generous, then actually change one limit value."}],"ask":{"ko":"막힌 화면을 보고 그 앱을 다시 열고 싶었나요, 아니면 돌아섰나요?","en":"When you hit the block screen, did you still want to open the app, or did you turn away?"}},"Rooms":{"time":20,"setup":null,"missions":[{"ko":"처음 열어 빈 방에 첫 오브젝트를 놓기까지 따라가 보세요. 몇 번 탭했는지, 코드라는 말이 언제 처음 보이는지 보세요.","en":"Open it and follow along until you place the first object in an empty room. Count the taps and note when the word code first appears."},{"ko":"오브젝트 몇 개를 끌어다 놓아 작은 방을 꾸며 보세요. 작은 디테일과 소리가 놓는 행동을 어떻게 즐겁게 만드는지 느껴 보세요.","en":"Drag in a few objects to decorate a small room. Feel how tiny details and sounds make placing things satisfying."},{"ko":"놓은 오브젝트 하나의 Lua 코드를 열어 값 하나를 바꿔 보세요. 꾸미기가 프로그래밍으로 넘어가는 순간을 느껴 보세요.","en":"Open one object's Lua code and change a value. Feel the moment decorating turns into programming."},{"ko":"다른 사람이 만든 방에 들어가 상호작용해 보세요. 어떻게 만들었는지 들여다보고 배울 수 있는지 보세요.","en":"Visit a room someone else made and interact with it. See whether you can look inside and learn how it was built."}],"make":[{"ko":"내 앱의 고급 설정 하나를 기본 화면에서 숨기고, 한 단계 더 들어가면 열리는 구조로 바꿔 보세요.","en":"Hide one advanced setting from your app's main screen and make it open one level deeper."},{"ko":"내 앱에서 다른 사용자가 만든 결과물을 열어 보고 따라 만들 수 있는 진입점을 스케치해 보세요.","en":"Sketch an entry point in your app where users can open someone else's creation and remix it."}],"ask":{"ko":"코드를 열기 전과 후에 이 앱이 다르게 보였나요?","en":"Did the app look different to you before and after you opened the code?"}},"Procreate Dreams":{"time":20,"setup":{"ko":"iPad 전용 앱이고 ￦22,000 한 번 구매예요.","en":"It is iPad only and a one-time purchase of 22,000 won."},"missions":[{"ko":"새 프로젝트를 열어 첫 화면을 보세요. Procreate에서 익숙한 브러시와 제스처가 어디서 그대로 이어지는지 보세요.","en":"Open a new project and look at the first screen. Notice where Procreate's familiar brushes and gestures carry over."},{"ko":"무대에 그림 하나를 두고 녹화를 누른 채 손가락으로 끌어 보세요. Performing이 내 움직임을 애니메이션으로 기록하는 순간을 느껴 보세요.","en":"Put a drawing on stage, hit record and drag it with your finger. Feel Performing turn your movement into animation."},{"ko":"타임라인을 핀치하고 문질러 보세요. 즉시 재생되는 반응이 데스크톱의 좁은 타임라인과 어떻게 다른지 보세요.","en":"Pinch and scrub the timeline. Notice how instant playback differs from a cramped desktop timeline."},{"ko":"같은 움직임을 키프레임이나 프레임 단위로도 만들어 보세요. 세 가지 방법이 한 앱에서 어떻게 함께 있는지 보세요.","en":"Make the same motion with keyframes or frame by frame. See how the three methods coexist in one app."}],"make":[{"ko":"내 앱의 값 입력 하나를 숫자 입력 대신 손가락으로 끌어 기록하는 방식으로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype replacing one numeric input in your app with a value recorded by dragging your finger."},{"ko":"내 앱에서 시간이나 순서를 다루는 화면에 핀치로 확대 축소하는 제스처를 넣어 보세요.","en":"Add pinch to zoom to a screen in your app that deals with time or sequence."}],"ask":{"ko":"손으로 연기해 만든 움직임과 키프레임으로 만든 움직임 중 어느 쪽이 더 내 것처럼 느껴졌나요?","en":"Which felt more like yours, the motion you performed by hand or the one you built with keyframes?"}},"finity.":{"time":10,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"You need an Apple Arcade subscription."},"missions":[{"ko":"첫 레벨을 시작해 보세요. 줄 전체를 민다는 규칙을 몇 번 만에 알아채는지 세어 보세요.","en":"Start the first level. Count how many moves it takes to realize you slide whole rows."},{"ko":"줄과 열을 천천히 밀어 보세요. 블록이 손가락을 그대로 따라오는 직접 조작과 손끝 피드백을 느껴 보세요.","en":"Slide rows and columns slowly. Feel the blocks follow your finger directly and the tactile feedback."},{"ko":"이동 횟수를 거의 다 쓸 때까지 가 보세요. 한 수 차이로 실패하는 긴장과 다시 하고 싶은 마음을 느껴 보세요.","en":"Play until your move budget is almost gone. Feel the tension of missing by one move and the urge to retry."},{"ko":"같은 레벨을 다시 하며 첫 수를 오래 고민해 보세요. 단순한 규칙이 계획을 얼마나 깊게 만드는지 보세요.","en":"Replay the same level and think longer about your first move. Notice how simple rules create deep planning."}],"make":[{"ko":"내 앱의 순서 바꾸기 하나를 끌면 바로 따라오는 직접 조작으로 바꾸고 햅틱을 붙여 보세요.","en":"Turn one reordering interaction in your app into direct drag manipulation and add haptics."},{"ko":"내 앱의 무제한 행동 하나에 횟수 제한을 건다면 사용자에게 어떤 고민이 생길지 종이에 적어 보세요.","en":"On paper, write what choices users would face if one unlimited action in your app had a limit."}],"ask":{"ko":"이동 횟수 제한이 답답했나요, 아니면 재미를 만들었나요?","en":"Did the move limit feel restrictive, or did it create the fun?"}},"DEATH STRANDING DIRECTOR'S CUT":{"time":30,"setup":{"ko":"￦44,000 유료 게임이고 iPhone 15 Pro 이상이나 M1 이상의 iPad·Mac이 필요해요.","en":"It is a paid game at 44,000 won and needs an iPhone 15 Pro or an M1 or later iPad or Mac."},"missions":[{"ko":"첫 장면을 시작해 보세요. 콘솔급 화면이 휴대폰에서 펼쳐질 때 디테일과 기기 발열을 함께 살펴보세요.","en":"Start the opening. As console-level visuals play on your phone, watch both the detail and how warm the device gets."},{"ko":"터치 조작으로 첫 배달 구간을 걸어 보세요. 막히거나 실패한 순간에 터치 조작이 어떻게 느껴지는지 보세요.","en":"Walk the first delivery route with touch controls. Notice how they feel when you get stuck or fail."},{"ko":"다른 플레이어가 남긴 사다리나 밧줄, 구조물을 찾아 써 보세요. 비동기 협력이 혼자인 길을 어떻게 바꾸는지 느껴 보세요.","en":"Find and use a ladder, rope or structure another player left. Feel how asynchronous cooperation changes a lonely journey."},{"ko":"컨트롤러가 있다면 연결해 같은 구간을 다시 해 보세요. 터치와 비교해 무엇이 달라지는지 보세요.","en":"If you have a controller, connect it and replay the same stretch. Compare what changes from touch."},{"ko":"iPad나 Mac이 있다면 같은 저장을 이어서 열어 보세요. 이어하기가 얼마나 매끄러운지 보세요.","en":"If you have an iPad or Mac, continue the same save there. See how seamless the handoff is."}],"make":[{"ko":"내 앱이 두 기기 이상에서 돈다면 iCloud로 마지막 위치 하나를 이어받는 기능을 만들어 보세요.","en":"If your app runs on more than one device, build a feature that carries the last position over through iCloud."},{"ko":"내 앱에서 한 사용자가 남긴 흔적이 다른 사용자에게 도움이 되는 작은 장치를 하나 스케치해 보세요.","en":"Sketch one small mechanism in your app where traces left by one user help another."}],"ask":{"ko":"휴대폰에서 콘솔 게임을 한다는 경험이 기대와 어떻게 달랐나요?","en":"How did playing a full console game on a phone differ from what you expected?"}},"Anne":{"time":15,"setup":{"ko":"무료 앱이고, 말을 걸어 줄 사람이 한 명 있으면 좋아요.","en":"It is free; having one person to talk to you helps."},"missions":[{"ko":"VoiceOver를 켜고 첫 설정을 따라가 보세요. 도우미 없이 혼자서도 설정을 끝낼 수 있는지 보세요.","en":"Turn on VoiceOver and go through the first setup. See whether you could finish it alone without a helper."},{"ko":"눈을 감고 탭과 스와이프로 점과 선을 입력해 짧은 단어를 써 보세요. 화면을 보지 않을 때 무엇이 나를 이끄는지 느껴 보세요.","en":"Close your eyes and type a short word in dots and dashes with taps and swipes. Notice what guides you when you can't see the screen."},{"ko":"다른 사람에게 말을 걸어 달라고 하고, 그 말이 진동으로 바뀌어 오는 걸 손으로 느껴 보세요. 재생 속도를 바꿔 읽기 쉬운 속도를 찾아보세요.","en":"Have someone speak to you and feel their words arrive as vibrations. Adjust the playback speed to find one you can read."},{"ko":"메시지 기록에서 지난 메시지 하나를 다시 보내 보세요. 반복해서 쓰는 말을 어떻게 덜 수고롭게 하는지 보세요.","en":"Retransmit a message from the history. Notice how it reduces the effort of repeating common phrases."}],"make":[{"ko":"내 앱의 핵심 알림 하나를 Core Haptics로 고유한 진동 패턴으로 만들고, 화면 없이 구분되는지 시험해 보세요.","en":"Give one key alert in your app a distinct Core Haptics pattern and test whether it can be recognized without the screen."},{"ko":"내 앱 화면 하나를 눈을 감고 VoiceOver로만 끝까지 써 보고, 막힌 지점을 하나 고쳐 보세요.","en":"Use one of your app's screens end to end with your eyes closed and VoiceOver only, then fix one place where you got stuck."}],"ask":{"ko":"화면 없이 대화할 때 가장 먼저 필요했던 피드백은 무엇이었나요?","en":"Talking without the screen, what feedback did you need first?"}},"Flighty":{"time":15,"setup":{"ko":"곧 탈 항공편이 있으면 가장 좋고, 없으면 추적해 볼 항공편 하나를 정해 두세요.","en":"An upcoming flight of your own is best; otherwise choose any flight to track."},"missions":[{"ko":"처음 열어 첫 항공편이 들어오기까지 따라가 보세요. 캘린더나 이메일에서 자동으로 가져오는지, 항공편 번호를 직접 몇 번 입력했는지 보세요.","en":"Open it and follow along until your first flight appears. Notice whether it imports from Calendar or email and how much you had to type."},{"ko":"항공편의 Live Activity를 잠금 화면과 Dynamic Island에서 보세요. 지금 단계에서 가장 중요한 정보가 무엇으로 정해져 있는지 보세요.","en":"Look at the flight's Live Activity on the Lock Screen and in the Dynamic Island. Notice which information is ranked most important for the current phase."},{"ko":"항공편 화면에서 공항 출발 안내판을 닮은 글자와 배치를 찾아보세요. 시간과 게이트를 읽는 데 몇 초 걸리는지 재 보세요.","en":"Find the type and layout borrowed from airport departure boards. Time how many seconds it takes to read the time and gate."},{"ko":"도착 항공기 추적과 지연 예측 정보를 찾아보세요. 항공사 발표보다 최대 여섯 시간 먼저 안다는 게 어떤 느낌일지 상상해 보세요.","en":"Find the inbound aircraft tracking and delay prediction. Imagine knowing about a delay up to six hours before the airline says so."}],"make":[{"ko":"내 앱에 Live Activity를 하나 만들어, 잠금 화면에 보여 줄 정보를 셋 이하로 고르고 단계마다 바뀌게 해 보세요.","en":"Build a Live Activity for your app that shows three or fewer pieces of information and changes with each phase."},{"ko":"내 앱 데이터로 사용자가 자랑하고 싶어질 누적 통계 화면을 하나 스케치해 보세요.","en":"Sketch one cumulative stats screen from your app's data that users would want to show off."}],"ask":{"ko":"잠금 화면만 보고 다음에 할 일을 알 수 있었나요?","en":"Could you tell what to do next from the Lock Screen alone?"}},"Any Distance":{"time":15,"setup":{"ko":"Apple 건강에 운동 기록이 있으면 바로 살펴볼 수 있어요.","en":"Having workouts in Apple Health lets you explore right away."},"missions":[{"ko":"처음 열어 Apple 건강과 연결하는 과정을 따라가 보세요. 자체 추적을 강요하지 않고 기존 기록을 가져오는 흐름을 보세요.","en":"Open it and go through connecting Apple Health. Notice how it imports existing workouts instead of forcing its own tracker."},{"ko":"지난 운동 하나를 열어 경로가 회전하는 3D 지도로 그려지는 걸 보세요. 손가락으로 돌려 보고 AR 보기도 켜 보세요.","en":"Open a past workout and watch the route render as a rotating 3D map. Spin it with your finger and try the AR view."},{"ko":"공유용 스토리 템플릿을 만들어 보세요. 페이스, 시간, 경로를 숨기는 선택이 어디에 있는지 확인하세요.","en":"Create a shareable story template. Find where you can hide pace, time and route."},{"ko":"운동 종류 목록에서 휠체어 운동과 유모차 러닝을 찾아보세요. 포용적인 운동 모델이 목록에서 어떻게 드러나는지 보세요.","en":"Find wheelchair workouts and stroller runs in the activity list. Notice how an inclusive model shows up in the list."}],"make":[{"ko":"내 앱의 기록 하나를 공유하고 싶은 한 장짜리 이미지로 만드는 ImageRenderer 프로토타입을 만들어 보세요.","en":"Prototype turning one record in your app into a share-worthy single image with ImageRenderer."},{"ko":"내 앱의 공유 화면에 개인 정보 항목마다 숨기기 스위치를 넣어 보세요.","en":"Add a hide toggle for each personal data field on your app's share screen."}],"ask":{"ko":"같은 운동 기록인데 이 앱에서 볼 때 무엇이 달라졌나요?","en":"Looking at the same workout in this app, what felt different?"}},"Wylde Flowers":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요하고, 소리를 켜고 해야 해요.","en":"You need an Apple Arcade subscription; play with sound on."},"missions":[{"ko":"첫 장면부터 이야기를 따라가 보세요. 모든 대사가 목소리로 들릴 때 작은 화면에서도 인물이 어떻게 살아나는지 느껴 보세요.","en":"Follow the story from the first scene. Feel how full voice acting brings characters to life on a small screen."},{"ko":"첫 작물을 심고 가꿔 보세요. 농사 루프의 손맛과 속도가 어떤지 느껴 보세요.","en":"Plant and tend your first crops. Notice the feel and pace of the farming loop."},{"ko":"마을 사람 여럿과 대화해 보세요. 다양한 정체성의 인물이 곁가지가 아닌 핵심 캐릭터로 등장하는 방식을 보세요.","en":"Talk with several villagers. Notice how characters of diverse identities appear as core cast, not side additions."},{"ko":"마녀 이야기가 시작되는 순간을 찾아보세요. 평화로운 농사에 이야기가 어떤 긴장을 더하는지 보세요.","en":"Find the moment the witchcraft story begins. Notice what stakes the story adds to the cozy farming."}],"make":[{"ko":"내 앱의 예시 데이터와 일러스트 속 사람들을 점검해 다양성이 부족한 부분 하나를 고쳐 보세요.","en":"Review the people in your app's sample data and illustrations and fix one place that lacks diversity."},{"ko":"내 앱의 반복 작업 하나에 짧은 이야기 문구를 붙여 의미를 더해 보세요.","en":"Add a short narrative line to one repetitive task in your app to give it meaning."}],"ask":{"ko":"목소리 연기가 이 게임을 계속하게 만든 이유가 됐나요?","en":"Was the voice acting a reason you kept playing?"}},"Waterllama":{"time":5,"setup":null,"missions":[{"ko":"처음 열어 목표를 정하는 과정을 따라가 보세요. 몸 정보, 활동량, 날씨가 목표 계산에 어떻게 쓰이는지 보세요.","en":"Open it and go through setting your goal. Notice how body measurements, activity and weather feed into it."},{"ko":"물 한 잔을 기록해 보세요. 탭 한 번에 동물 캐릭터가 차오르는 순간을 지켜보세요.","en":"Log a glass of water. Watch the animal character fill up from a single tap."},{"ko":"커피 같은 다른 음료를 기록해 보세요. 수분과 카페인 값이 어떻게 다르게 반영되는지 보세요.","en":"Log a different drink like coffee. See how its hydration and caffeine values are counted differently."},{"ko":"위젯이나 제어 센터에서 앱을 열지 않고 한 번 더 기록해 보세요. 몇 번 만에 끝나는지 세어 보세요.","en":"Log one more drink from a widget or Control Center without opening the app. Count the steps."}],"make":[{"ko":"내 앱의 가장 작은 기록 동작 하나에 캐릭터나 도형이 차오르는 애니메이션을 붙여 보세요.","en":"Attach a filling character or shape animation to the smallest logging action in your app."},{"ko":"내 앱의 핵심 기록을 인터랙티브 위젯이나 제어 센터 컨트롤에서 바로 할 수 있게 만들어 보세요.","en":"Make your app's core log action available directly from an interactive widget or a Control Center control."}],"ask":{"ko":"캐릭터가 없었다면 물을 기록했을까요?","en":"Without the character, would you have logged the water?"}},"Halide Mark II":{"time":15,"setup":{"ko":"무료로 받을 수 있고, 연간 멤버십과 평생 구매 중 고를 수 있어요.","en":"It is a free download with a choice of annual membership or a lifetime purchase."},"missions":[{"ko":"처음 열어 카메라 화면이 뜨기까지 따라가 보세요. 첫 화면에 슬라이더가 몇 개나 보이는지 세어 보세요.","en":"Open it and follow along until the camera view appears. Count how many sliders you see on the first screen."},{"ko":"화면 아무 곳에서 위아래로 쓸어 노출을, 좌우로 쓸어 초점을 바꿔 보세요. 손가락이 필름 카메라 다이얼이 되는 느낌을 보세요.","en":"Swipe vertically anywhere for exposure and horizontally for focus. Feel your finger become a film camera's dial."},{"ko":"초점 피킹과 루페를 보며 가까운 물체에 수동 초점을 맞춰 보세요. 작은 화면에서 초점이 얼마나 확실히 확인되는지 보세요.","en":"Manually focus on a nearby object using focus peaking and the loupe. Notice how confidently you can confirm focus on a small screen."},{"ko":"Process Zero로 한 장, 기본 카메라 앱으로 한 장 같은 장면을 찍어 비교해 보세요. 대비와 입자감의 차이를 느껴 보세요.","en":"Shoot the same scene once with Process Zero and once with the built-in Camera app. Compare the contrast and grain."},{"ko":"결제 화면에서 연간 멤버십과 평생 구매가 어떻게 나란히 놓였는지 보세요.","en":"On the pricing screen, notice how the annual membership and lifetime purchase sit side by side."}],"make":[{"ko":"내 앱에서 슬라이더로 바꾸는 값 하나를 화면 전체 스와이프 제스처로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype replacing one slider-controlled value in your app with a full-screen swipe gesture."},{"ko":"내 앱의 자동 기능 하나에 끄는 선택지를 주고, 끈 상태를 하나의 기능으로 소개하는 문구를 써 보세요.","en":"Give one automatic feature in your app an off switch and write copy that presents the off state as a feature."}],"ask":{"ko":"Process Zero 사진과 기본 카메라 사진 중 어느 쪽이 더 마음에 들었고, 왜 그랬나요?","en":"Which did you prefer, the Process Zero shot or the built-in camera shot, and why?"}},"Voice Dream Reader":{"time":15,"setup":null,"missions":[{"ko":"처음 열고 웹 페이지나 PDF 하나를 불러와 읽게 해 보세요. 문서를 가져오는 경로가 몇 가지 열려 있는지 세어 보세요.","en":"Open it for the first time and load a web page or PDF to be read aloud. Count how many ways it offers to bring a document in."},{"ko":"읽는 동안 단어와 줄 하이라이트를 따라가 보세요. 소리와 강조가 어긋나는 순간이 있는지 눈으로 확인해 보세요.","en":"Follow the word and line highlighting while it reads. Watch whether the sound and the highlight ever drift apart."},{"ko":"목소리, 속도, 글꼴, 줄 간격, 배경색을 하나씩 바꿔 보세요. 기본값 하나 대신 모든 변수를 사용자에게 넘긴 구조를 느껴 보세요.","en":"Change the voice, speed, font, spacing and background color one by one. Feel how every reading variable is handed to you instead of one default."},{"ko":"VoiceOver를 켜고 문장과 단락 단위로 문서를 이동해 보세요. 접근성 도구 자체가 얼마나 접근 가능한지 살펴보세요.","en":"Turn on VoiceOver and move through the document by sentence and paragraph. Notice how accessible the accessibility tool itself is."},{"ko":"종이 문서 한 장을 카메라로 스캔해 읽게 해 보세요. 어두운 곳에서도 텍스트가 잘 잡히는지 확인해 보세요.","en":"Scan a printed page with the camera and have it read. Check whether the text still comes through in dim light."}],"make":[{"ko":"내 앱의 읽기 화면 하나를 골라 글꼴 크기, 줄 간격, 배경색을 사용자가 고를 수 있게 설정 세 개를 붙여 보세요.","en":"Pick one reading screen in your app and add three user settings for font size, line spacing and background color."},{"ko":"내 앱의 긴 텍스트 화면을 VoiceOver로 문장 단위로 끝까지 읽어 보고, 막히는 곳을 목록으로 적어 보세요.","en":"Read a long text screen in your app to the end with VoiceOver, sentence by sentence, and list every place you get stuck."}],"ask":{"ko":"내 앱에서 기본값 하나로 정해 버린 것 중 사용자에게 넘겨야 할 변수는 무엇인가요?","en":"Which variable in your app did you lock to one default that you should hand to the user?"}},"South of the Circle":{"time":15,"setup":{"ko":"앱스토어에서 내려간 게임이라 개발사의 공식 트레일러나 스크린샷으로 경험해야 해요.","en":"The game has left the App Store, so experience it through the developer's own trailer or screenshots."},"missions":[{"ko":"트레일러의 첫 30초를 소리와 함께 보세요. 1960년대 남극이라는 배경을 어떤 색과 장면으로 바로 알려 주는지 살펴보세요.","en":"Watch the first 30 seconds of the trailer with sound. Notice which colors and shots tell you right away that this is 1960s Antarctica."},{"ko":"스크린샷을 넘기며 평면 색과 실크스크린 같은 그림체를 살펴보세요. 작은 화면에서도 인물과 배경이 또렷이 구분되는 이유를 찾아보세요.","en":"Flip through the screenshots and study the flat, screenprint-like art. Find why characters and backgrounds still separate clearly on a small screen."},{"ko":"배우의 얼굴 연기가 나오는 장면을 멈춰 보세요. 모션 캡처로 담은 표정이 단순한 그림체 안에서 어떻게 살아나는지 느껴 보세요.","en":"Pause on a scene showing an actor's performance. Feel how motion-captured expression survives inside such a simple art style."},{"ko":"대사 대신 감정으로 답하는 선택 장면을 찾아보세요. 문장 고르기와 감정 고르기가 플레이어에게 주는 부담이 어떻게 다른지 생각해 보세요.","en":"Find a choice moment where you answer with a feeling instead of a line. Think about how picking a feeling weighs on the player differently from picking a sentence."}],"make":[{"ko":"내 앱의 선택지 하나를 문장 대신 감정이나 태도를 나타내는 짧은 단어로 바꾼 버전을 그려 보세요.","en":"Sketch a version of one choice in your app that uses a short word for a feeling or stance instead of a full sentence."},{"ko":"내 앱 화면 하나를 색 세 가지만 쓰는 평면 스타일로 다시 칠해 보고, 정보가 더 잘 읽히는지 비교해 보세요.","en":"Repaint one of your screens in a flat style with only three colors and compare whether it reads better."}],"ask":{"ko":"감정으로 답하게 하는 방식은 플레이어에게 무엇을 덜어 주고 무엇을 남겨 두나요?","en":"What does answering with a feeling take off the player's plate, and what does it leave in place?"}},"Attentat 1942":{"time":30,"setup":{"ko":"유료 게임($4.99)이고, 실사 영상이 많으니 소리를 켤 수 있는 조용한 곳이 좋아요.","en":"It is a paid game ($4.99), and with lots of live-action video, a quiet place with sound on works best."},"missions":[{"ko":"게임을 시작해 할아버지의 체포를 둘러싼 첫 장면을 보세요. 역사 교과서가 아니라 가족 이야기로 들어가는 첫 순간을 느껴 보세요.","en":"Start the game and watch the opening around the grandfather's arrest. Feel how you enter through a family story rather than a textbook."},{"ko":"첫 증인을 인터뷰하며 질문을 골라 보세요. 실사 배우의 반응이 내 질문에 따라 어떻게 달라지는지 지켜보세요.","en":"Interview the first witness and choose your questions. Watch how the live-action actor reacts differently to what you ask."},{"ko":"증언 중간에 나오는 만화풍 장면이나 미니게임을 플레이해 보세요. 형식이 바뀔 때 몰입이 끊기는지 이어지는지 살펴보세요.","en":"Play through a comic-style sequence or mini-game inside a testimony. Notice whether the change of format breaks or carries your focus."},{"ko":"서로 다른 증언 두 개를 비교해 보세요. 누가 맞는지 게임이 정해 주지 않을 때 내가 어떤 판단을 하게 되는지 느껴 보세요.","en":"Compare two testimonies that disagree. Feel what judgment you make when the game refuses to tell you who is right."}],"make":[{"ko":"내 앱의 설명 화면 하나를 한 사람의 목소리로 들려주는 인터뷰 형식으로 다시 써 보세요.","en":"Rewrite one explanatory screen in your app as an interview told in one person's voice."},{"ko":"같은 사건을 두 사용자가 다르게 기억하는 상황을 가정해, 내 앱이 두 관점을 나란히 보여 주는 화면을 스케치해 보세요.","en":"Assume two users remember the same event differently, and sketch a screen in your app that shows both views side by side."}],"ask":{"ko":"정답을 주지 않는 설계가 내 공감에 어떤 영향을 줬나요?","en":"How did a design that withholds the answer change your empathy?"}},"Universe":{"time":20,"setup":null,"missions":[{"ko":"처음 열고 템플릿 하나를 골라 사이트 만들기를 시작해 보세요. 첫 화면까지 몇 단계 만에 내 사이트가 생기는지 세어 보세요.","en":"Open it and start a site from a template. Count how many steps it takes before you have a site of your own."},{"ko":"블록 하나를 손가락으로 끌어 그리드에 놓아 보세요. 블록이 칸에 딱 붙는 순간의 느낌과 미리보기가 바로 바뀌는지 확인해 보세요.","en":"Drag a block onto the grid with your finger. Feel the moment it snaps into place and check that the preview updates instantly."},{"ko":"VoiceOver를 켜고 같은 페이지를 훑어 보세요. 그리드 덕분에 레이아웃이 위치별로 읽히는 방식을 들어 보세요.","en":"Turn on VoiceOver and sweep through the same page. Listen to how the grid lets the layout be read position by position."},{"ko":"상품 하나를 등록해 판매 블록을 붙여 보세요. 아이디어에서 가게까지 휴대폰만으로 가는 길이 얼마나 짧은지 느껴 보세요.","en":"Add a product and place a selling block. Feel how short the path from idea to store is with only a phone."}],"make":[{"ko":"내 앱의 자유 배치 화면 하나를 정해진 격자 위에만 놓이도록 바꾼 프로토타입을 만들어, 손가락 조작이 쉬워지는지 비교해 보세요.","en":"Prototype one free-placement screen of yours so items can only sit on a grid, and compare whether finger control gets easier."},{"ko":"내 앱 화면의 요소들을 격자 좌표로 VoiceOver 라벨에 적어 보고, 화면을 보지 않고도 배치가 그려지는지 확인해 보세요.","en":"Write grid positions into the VoiceOver labels of one screen and check whether the layout can be pictured without looking."}],"ask":{"ko":"데스크톱 도구를 줄이는 대신 휴대폰을 위해 다시 설계한 부분은 어디였나요?","en":"Where did it redesign for the phone instead of shrinking a desktop tool?"}},"Robinhood":{"time":15,"setup":{"ko":"실제 계좌 개설이나 주문은 하지 말고 확인 직전 단계까지만 따라가 보세요.","en":"Do not actually open an account or place an order; stop just before each confirmation."},"missions":[{"ko":"계좌 개설 온보딩을 시작해 보세요. 민감한 정보를 묻기 직전에 왜 필요한지와 어떻게 보호되는지를 먼저 알려 주는 문구를 찾아보세요.","en":"Start the account opening flow. Look for the short note explaining why sensitive information is needed and how it is protected, shown just before it is asked."},{"ko":"온보딩을 몇 단계 더 넘겨 보세요. 한 화면에 질문 하나와 큰 입력 필드만 두는 흐름이 증권 계좌 개설의 무게를 얼마나 덜어 주는지 느껴 보세요.","en":"Go a few more steps. Feel how one question per screen with a large field takes the weight out of opening a brokerage account."},{"ko":"종목 하나를 열어 보세요. 큰 가격 숫자, 선 하나짜리 차트, 하단에 고정된 매수 버튼만으로 화면이 이해되는지 확인해 보세요.","en":"Open a stock. Check whether the large price, single-line chart and pinned buy button are enough to understand the screen."},{"ko":"매수 흐름을 확인 직전까지 따라가 보세요. 컨페티 같은 축하 연출이 빠진 지금, 확인 화면이 어떤 분위기를 주는지 살펴보세요.","en":"Follow the buy flow up to the confirmation. Notice the mood of the confirmation now that confetti-style celebration has been removed."}],"make":[{"ko":"내 앱의 가입 화면에서 민감한 정보를 묻는 칸 하나를 골라, 바로 위에 왜 필요하고 어떻게 지키는지 한 줄 문구를 붙여 보세요.","en":"Pick one field in your sign-up that asks for sensitive data and add a one-line note above it on why it is needed and how it is protected."},{"ko":"내 앱의 긴 입력 폼 하나를 한 화면에 질문 하나씩 묻는 단계형 흐름으로 쪼갠 프로토타입을 만들어 보세요.","en":"Prototype one long form in your app as a step-by-step flow with one question per screen."},{"ko":"내 앱의 되돌릴 수 없는 행동 뒤에 나오는 연출을 적고, 축하 대신 결과를 담담히 알려 주는 버전으로 바꿔 보세요.","en":"Write down the effect after an irreversible action in your app and replace the celebration with a plain statement of the result."}],"ask":{"ko":"민감한 질문 앞에 이유를 먼저 보여 준 것이 이어서 입력하고 싶은 마음에 어떤 영향을 줬나요?","en":"How did seeing the reason before a sensitive question affect your willingness to keep going?"}},"Proloquo2Go":{"time":20,"setup":{"ko":"가격이 ￦449,000인 고가 앱이라, 구매 전 공식 소개 자료로 먼저 살펴보는 것도 좋아요.","en":"At ￦449,000 it is expensive, so you may want to study the official material before buying."},"missions":[{"ko":"처음 열었을 때 버튼 격자를 살펴보세요. 심볼과 단어가 함께 있는 버튼 하나에 담긴 정보량과 핵심어가 어디에 놓였는지 보세요.","en":"Study the button grid when it first opens. Notice how much one symbol-and-word button carries and where the core words sit."},{"ko":"버튼 몇 개를 눌러 문장 하나를 말하게 해 보세요. 말 대신 누르는 것이 어느 순간 빠르고 어느 순간 답답한지 느껴 보세요.","en":"Tap a few buttons to have it speak a sentence. Feel where pressing instead of speaking is fast and where it gets frustrating."},{"ko":"그리드 크기를 작은 쪽에서 큰 쪽으로 바꿔 보세요. 버튼이 늘어나도 같은 단어가 같은 위치에 남아 손이 기억하는지 확인해 보세요.","en":"Change the grid from a small to a large preset. Check that the same words stay in the same place so your hand can remember them."},{"ko":"목소리를 아이 목소리나 다른 목소리로 바꿔 들어 보세요. 자기 나이와 정체성에 맞는 목소리로 말한다는 것이 어떤 의미인지 생각해 보세요.","en":"Switch to a child's voice or another voice and listen. Think about what it means to speak in a voice that fits your age and identity."},{"ko":"개인 사진 한 장으로 새 버튼을 만들어 보세요. 사용자가 어휘를 직접 채우는 과정이 얼마나 간단한지 살펴보세요.","en":"Make a new button with a personal photo. See how simple it is for users to add their own vocabulary."}],"make":[{"ko":"내 앱 화면 하나를 버튼이 적은 버전과 많은 버전 두 가지로 만들고, 공통 버튼이 두 버전에서 같은 위치에 있도록 맞춰 보세요.","en":"Build one screen in two densities, few and many buttons, and keep the shared buttons in the same position in both."},{"ko":"내 앱의 메뉴 하나를 아이콘과 단어가 함께 있는 큰 버튼 9개짜리 격자로 다시 그려 보세요.","en":"Redraw one menu in your app as a grid of nine large buttons with an icon and a word each."}],"ask":{"ko":"버튼이 늘어나도 위치를 지키는 것이 왜 정보 밀도보다 중요했을까요?","en":"Why did keeping positions fixed matter more than information density?"}},"TikTok":{"time":10,"setup":null,"missions":[{"ko":"로그아웃 상태로 앱을 처음 열어 보세요. 로그인이나 설정 없이 첫 영상이 재생되기까지 몇 초 걸리는지 재 보세요.","en":"Open the app logged out. Time how many seconds pass before the first video plays with no sign-in or setup."},{"ko":"위로 빠르게 여러 번 넘겨 보세요. 다음 영상이 미리 불려 와 있어 기다림이 느껴지지 않는지 확인해 보세요.","en":"Swipe up quickly several times. Check that the next video is preloaded so you never feel a wait."},{"ko":"한 주제의 영상만 끝까지 보거나 반복해 보고 나머지는 바로 넘겨 보세요. 팔로우 없이 몇 번 만에 피드가 그쪽으로 기우는지 세어 보세요.","en":"Watch or replay only one topic and skip the rest. Count how many swipes it takes for the feed to lean that way with no follows."},{"ko":"한 손으로 좋아요, 댓글, 공유 버튼을 눌러 보세요. 오른쪽 세로 열이 엄지에 닿으면서 영상을 가리지 않는지 살펴보세요.","en":"Hit like, comment and share with one hand. Notice how the right-hand column stays in thumb reach without covering the video."},{"ko":"영상의 원본 음원을 눌러 보세요. 같은 소리를 쓴 영상 모음에서 바로 만들기로 넘어가는 길이 얼마나 짧은지 느껴 보세요.","en":"Tap a video's original sound. Feel how short the path is from the collection of videos using it to making your own."}],"make":[{"ko":"내 앱의 첫 실행에서 로그인이나 설정 단계 하나를 뒤로 미루고, 콘텐츠를 먼저 보여 주는 흐름을 스케치해 보세요.","en":"Push one sign-in or setup step later in your first run and sketch a flow that shows content first."},{"ko":"내 앱의 주요 동작 버튼을 오른손 엄지가 닿는 세로 열로 옮긴 레이아웃을 만들어 한 손으로 써 보세요.","en":"Move your app's main action buttons into a vertical column in right-thumb reach and try it one-handed."},{"ko":"내 앱의 목록에서 다음 항목을 미리 불러오는 로직을 넣고 넘길 때 대기 시간이 얼마나 줄어드는지 재 보세요.","en":"Add prefetching for the next item in one of your lists and measure how much the wait drops when moving on."}],"ask":{"ko":"콘텐츠가 곧 온보딩이 될 때 사용자가 얻는 것과 잃는 것은 무엇인가요?","en":"When content is the onboarding, what does the user gain and what do they lose?"}},"Slack":{"time":15,"setup":{"ko":"혼자보다 동료나 친구 한 명과 같은 워크스페이스에서 해 보면 구조가 더 잘 보여요.","en":"It shows its structure best in a workspace shared with one colleague or friend."},"missions":[{"ko":"워크스페이스에 들어가 첫 화면을 보세요. 채널, DM, 스레드, 멘션이 어떤 계층으로 나뉘어 있는지 살펴보세요.","en":"Enter a workspace and study the first screen. Notice how channels, DMs, threads and mentions are layered."},{"ko":"채널에 글을 올리고 그 글에 스레드로 답해 보세요. 이메일 답장과 달리 대화가 채널을 어지럽히지 않고 갈라지는 방식을 보세요.","en":"Post in a channel and reply in a thread. See how the conversation branches without cluttering the channel, unlike email replies."},{"ko":"짧은 답을 메시지 대신 이모지 리액션으로 남겨 보세요. 채널 소음이 얼마나 줄어드는지 느껴 보세요.","en":"Answer something short with an emoji reaction instead of a message. Feel how much channel noise it saves."},{"ko":"알림 설정을 전체 기본값, 채널별, 키워드나 방해 금지 순서로 들어가 보세요. 필요한 깊이에서만 조정하게 한 계층을 따라가 보세요.","en":"Walk through notification settings from global default to per channel to keywords and do not disturb. Follow how you only go as deep as you need."}],"make":[{"ko":"내 앱의 알림 설정을 전체 기본값과 항목별 예외 두 단계로 나눈 화면을 그려 보세요.","en":"Sketch your app's notification settings split into a global default and per-item exceptions."},{"ko":"내 앱의 댓글이나 메시지 화면에 짧은 반응 버튼을 넣어, 답글 없이 끝나는 대화가 얼마나 되는지 생각해 보세요.","en":"Add a quick reaction to a comment or message screen in your app and consider how many replies it would replace."}],"ask":{"ko":"알림 설정을 계층으로 나눈 것이 복잡함을 줄였나요, 숨겼나요?","en":"Did layering notification settings reduce complexity or just hide it?"}},"Drafts":{"time":10,"setup":null,"missions":[{"ko":"앱을 열어 보세요. 키보드가 올라온 빈 초안이 바로 나타나는지, 제목이나 폴더를 묻는 단계가 있는지 확인해 보세요.","en":"Open the app. Check that a blank draft with the keyboard up appears right away, and whether anything asks for a title or folder."},{"ko":"떠오르는 문장 하나를 적고 액션으로 보낼 곳을 정해 보세요. 어디에 둘지 나중에 정하는 순서가 손을 얼마나 가볍게 하는지 느껴 보세요.","en":"Type a sentence and choose where it goes with an action. Feel how deciding the destination afterward frees your hands."},{"ko":"초안 몇 개를 쌓은 뒤 Inbox, 태그, 플래그, 보관함으로 정리해 보세요. 폴더 없이 정리하는 방식이 입력 속도를 해치지 않는지 보세요.","en":"Write a few drafts, then sort them with Inbox, tags, flags and archive. See whether organizing without folders leaves input speed untouched."},{"ko":"Action Directory에서 다른 사람이 만든 액션 하나를 내려받아 써 보세요. 사용자가 워크플로를 직접 넓히는 구조를 살펴보세요.","en":"Download a community action from the Action Directory and use it. Notice how users extend their own workflow."}],"make":[{"ko":"내 앱의 입력 화면에서 제목이나 분류 같은 필수 칸을 빼고 본문부터 적게 한 뒤, 정리는 저장 후로 미룬 흐름을 만들어 보세요.","en":"Remove required fields like title or category from one input screen, let people type first, and move organizing to after saving."},{"ko":"내 앱을 열었을 때 키보드가 올라온 입력 상태로 바로 시작하는 버전을 만들어 첫 글자까지의 탭 수를 비교해 보세요.","en":"Build a version of your app that launches straight into input with the keyboard up and compare taps to the first character."}],"ask":{"ko":"먼저 쓰고 나중에 정리하는 순서가 내 앱의 어떤 기능에 맞을까요?","en":"Which feature in your app suits write first, organize later?"}},"Shortcuts":{"time":20,"setup":null,"missions":[{"ko":"새 단축어를 만들어 액션 블록 하나를 추가해 보세요. 빈 편집기에서 첫 블록을 찾기까지 얼마나 걸리는지 보세요.","en":"Create a new shortcut and add one action block. Notice how long it takes to find the first block in an empty editor."},{"ko":"블록 두세 개를 위에서 아래로 쌓아 앞 블록의 결과가 다음으로 넘어가게 해 보세요. 코드 없이 흐름을 만드는 감각을 느껴 보세요.","en":"Stack two or three blocks top to bottom so each output feeds the next. Feel what building logic without code is like."},{"ko":"액션 목록에서 서드파티 앱이 App Intents로 공개한 동작을 찾아보세요. 앱마다 어떤 동작을 내놓았는지 경쟁 앱 위주로 비교해 보세요.","en":"Find actions third-party apps expose through App Intents. Compare what each app, especially competitors, chose to offer."},{"ko":"시간이나 위치를 조건으로 하는 개인 자동화 하나를 만들어 보세요. 직접 실행하지 않아도 돌아가는 흐름을 확인해 보세요.","en":"Create a personal automation triggered by time or location. Check that it runs without you launching it."},{"ko":"갤러리에서 단축어 하나를 내려받아 열어 보세요. 남이 만든 자동화를 복사해 내 것으로 고치는 과정을 살펴보세요.","en":"Download a shortcut from the Gallery and open it. See how you copy someone else's automation and adapt it."}],"make":[{"ko":"내 앱에서 가장 자주 쓰는 기능 하나를 App Intent로 공개해 단축어 액션 목록에 보이게 만들어 보세요.","en":"Expose your app's most used feature as an App Intent so it appears in the Shortcuts action list."},{"ko":"경쟁 앱이 공개한 액션 목록을 적고, 내 앱이 내놓을 액션 세 개의 이름과 입력값을 정해 보세요.","en":"List the actions competing apps expose, then name three actions and their inputs for your own app."}],"ask":{"ko":"내 앱이 다른 사람의 자동화 재료가 된다면 어떤 블록 하나여야 할까요?","en":"If your app became an ingredient in other people's automations, what single block should it be?"}},"인프런":{"time":15,"setup":{"ko":"재생해 볼 무료 강의 하나를 미리 찾아 두면 좋아요.","en":"Find one free course in advance so you have something to play."},"missions":[{"ko":"처음 열어 로드맵이나 챌린지 같은 학습 경로를 살펴보세요. 어디서 시작할지 모르는 사람에게 첫 강의를 어떻게 안내하는지 보세요.","en":"Open it and look at learning paths like roadmaps and challenges. See how it points someone who does not know where to start to a first course."},{"ko":"강의 하나를 재생하며 속도, 자막, 스크립트 보기를 바꿔 보세요. 짧은 틈새 시간에 이어 보기에 맞춘 플레이어인지 느껴 보세요.","en":"Play a lecture and change speed, subtitles and the script view. Feel whether the player is built for picking up in short gaps."},{"ko":"강의를 오프라인으로 내려받아 비행기 모드에서 재생해 보세요. 데이터 없는 출퇴근길을 떠올리며 끊김 없이 보이는지 확인해 보세요.","en":"Download a lecture and play it in airplane mode. Picture a commute with no data and check that it plays without a hitch."},{"ko":"재생 중 중요한 장면을 스크린샷으로 저장하고 화면 잠금을 써 보세요. 필기와 복습 흐름이 끊기지 않는지 살펴보세요.","en":"Save an important moment with the screenshot feature and try screen lock during playback. Notice whether note-taking and review stay uninterrupted."}],"make":[{"ko":"내 앱의 긴 콘텐츠 하나에 마지막 위치를 기억해 다음 실행 때 바로 이어 주는 기능을 붙여 보세요.","en":"Add resume-from-last-position to one long piece of content in your app."},{"ko":"내 앱을 비행기 모드로 켜 보고, 미리 저장해 둘 수 있는 콘텐츠 하나를 정해 오프라인으로 보이게 만들어 보세요.","en":"Run your app in airplane mode, choose one piece of content that could be saved ahead, and make it work offline."}],"ask":{"ko":"이동 중 학습자를 위해 이 앱이 가장 잘 풀어낸 제약은 무엇인가요?","en":"Which constraint of learning on the move does this app solve best?"}},"Pine Hearts":{"time":20,"setup":null,"missions":[{"ko":"게임을 처음 켜고 첫 컷신 전에 나오는 접근성 설정을 살펴보세요. 플레이 전에 무엇을 고를 수 있는지 세어 보세요.","en":"Launch it and look at the accessibility settings shown before the first cutscene. Count what you can choose before playing."},{"ko":"Colour Blocking 모드를 켜고 첫 구역을 돌아다녀 보세요. 상호작용할 수 있는 것이 평면 색으로 바로 눈에 들어오는지 느껴 보세요.","en":"Turn on Colour Blocking and walk around the first area. Feel whether interactive things jump out in flat colors."},{"ko":"Simplified Controls를 켠 채 길게 누르기나 타이밍이 필요한 동작을 해 보세요. 한 번의 입력으로 바뀐 동작이 얼마나 편한지 비교해 보세요.","en":"With Simplified Controls on, try an action that would need a hold or timing. Compare how easy the single-input version is."},{"ko":"공원 방문객 한 명을 도와 보세요. 전투 대신 돕기로 진행하는 구조가 긴장감을 어떻게 바꾸는지 느껴 보세요.","en":"Help one park visitor. Feel how progressing by helping rather than fighting changes the tension."}],"make":[{"ko":"내 앱의 첫 실행 흐름 맨 앞에 글자 크기와 대비 같은 접근성 선택 화면 하나를 넣은 프로토타입을 만들어 보세요.","en":"Prototype a first-run flow that puts one accessibility choice screen, like text size and contrast, at the very start."},{"ko":"내 앱에서 길게 누르기나 빠른 연속 탭이 필요한 동작을 찾아 한 번 탭으로도 되는 대안을 만들어 보세요.","en":"Find any action in your app that needs a long press or rapid taps and add a single-tap alternative."}],"ask":{"ko":"접근성 설정을 맨 앞에 두는 것이 모든 플레이어에게 어떤 신호를 주나요?","en":"What signal does putting accessibility settings first send to every player?"}},"The Outsiders: Athlete Tracker":{"time":10,"setup":{"ko":"iOS 26 이상이 필요하고, 건강 앱에 운동과 수면 기록이 쌓여 있어야 제대로 보여요.","en":"It needs iOS 26 or later, and it shows best with workout and sleep history already in Health."},"missions":[{"ko":"처음 실행해 건강 데이터 접근을 허용해 보세요. 데이터가 기기 안에 머문다는 점을 어떻게 설명하는지 살펴보세요.","en":"Launch it and grant Health access. Notice how it explains that your data stays on the device."},{"ko":"홈 화면의 Training Readiness 점수 하나를 보세요. 숫자 하나만 보고 오늘 얼마나 운동할지 결정할 수 있는지 스스로 판단해 보세요.","en":"Look at the single Training Readiness score on the home screen. Decide whether that one number tells you how hard to train today."},{"ko":"훈련 방식을 polarized, pyramid, threshold 중에서 바꿔 보세요. 선택에 따라 안내가 어떻게 달라지는지 비교해 보세요.","en":"Switch the training approach between polarized, pyramid and threshold. Compare how the guidance changes."},{"ko":"캘린더 화면에서 힘든 주와 회복 주를 찾아보세요. Liquid Glass 화면에서 정보가 어떻게 층을 이루는지 보세요.","en":"Find hard blocks and recovery weeks in the calendar view. See how information layers on the Liquid Glass UI."}],"make":[{"ko":"내 앱 홈 화면의 지표들을 오늘 할 일을 알려 주는 숫자 하나로 합친다면 무엇일지 정하고 화면을 스케치해 보세요.","en":"Decide what single number would combine your home screen's metrics into today's guidance, and sketch it."},{"ko":"내 앱의 기능 하나가 다른 사용자층을 위한 것이라면 별도 앱으로 뺐을 때의 첫 화면을 그려 보세요.","en":"If one feature of yours serves a different audience, sketch the first screen it would have as a separate app."}],"ask":{"ko":"기존 앱을 키우는 대신 새 앱을 만든 선택은 어떤 사용자를 지켰나요?","en":"Which users did building a new app, instead of growing the old one, protect?"}},"(Not Boring) Camera":{"time":10,"setup":{"ko":"무료로 받을 수 있지만 전체 기능은 연 약 15달러 멤버십이에요.","en":"It downloads free, but the full app is a membership of about $15 a year."},"missions":[{"ko":"잠금 화면 컨트롤로 앱을 열어 첫 사진을 찍어 보세요. 1초 안에 찍히는지 직접 재 보세요.","en":"Open it from the Lock Screen control and take a first photo. Time whether you get the shot in under a second."},{"ko":"휴대폰을 천천히 기울이며 3D 카메라 화면을 보세요. 조명이 움직임에 따라 바뀌는 순간을 찾아보세요.","en":"Tilt the phone slowly while watching the 3D camera interface. Catch the lighting shifting as you move."},{"ko":"햅틱 다이얼을 돌려 설정을 바꿔 보세요. 진동과 소리가 실제 카메라처럼 손에 전해지는지 느껴 보세요.","en":"Turn a haptic dial to change a setting. Feel whether the vibration and sound land in your hand like a real camera."},{"ko":"LUT 프리셋 하나를 골라 찍고 노이즈가 필름 그레인처럼 남는지 결과를 확인해 보세요.","en":"Pick a LUT preset, shoot, and check whether the noise survives as film-like grain in the result."}],"make":[{"ko":"내 앱의 슬라이더 하나를 돌리는 다이얼로 바꾸고, 눈금마다 가벼운 햅틱을 넣어 프로토타입해 보세요.","en":"Replace one slider in your app with a dial and prototype a light haptic on each tick."},{"ko":"내 앱의 가장 중요한 기능을 잠금 화면 컨트롤이나 단축 경로로 열어, 첫 결과까지 걸리는 시간을 재 보세요.","en":"Launch your app's key feature from a Lock Screen control or shortcut and time how long the first result takes."}],"ask":{"ko":"장난감 같은 겉모습이 전문 기능을 가렸나요, 아니면 더 다가가기 쉽게 만들었나요?","en":"Did the toy-like surface hide the pro features or make them easier to reach?"}},"Speechify":{"time":10,"setup":{"ko":"기본 읽기는 무료지만 프리미엄 목소리와 더 빠른 속도는 구독이 필요해요.","en":"Basic reading is free, but premium voices and higher speeds need a subscription."},"missions":[{"ko":"처음 실행해 첫 문서를 읽게 하기까지 따라가 보세요. 결제 안내가 어느 시점에 나타나는지 확인해 보세요.","en":"Follow the first run until a document is being read. Note when the paywall appears."},{"ko":"웹 페이지나 PDF를 하나 읽게 하고 단어별 하이라이트를 따라가 보세요. 눈과 귀가 함께 움직일 때 이해가 달라지는지 느껴 보세요.","en":"Have it read a web page or PDF and follow the word-by-word highlight. Feel whether comprehension changes when eyes and ears move together."},{"ko":"재생 속도를 평소 읽기 속도보다 크게 올려 보세요. 어디까지 알아들을 수 있는지 한계를 찾아보세요.","en":"Push playback speed well past normal reading speed. Find the point where you stop understanding."},{"ko":"책 한 페이지를 카메라로 찍어 읽게 해 보세요. 종이에서 소리까지 걸리는 시간을 재 보세요.","en":"Photograph a book page and have it read aloud. Time how long it takes from paper to sound."}],"make":[{"ko":"내 앱에서 긴 글이 나오는 화면 하나에 AVSpeechSynthesizer로 읽어 주기 버튼과 속도 조절을 붙여 보세요.","en":"Add a read-aloud button with speed control to one long-text screen using AVSpeechSynthesizer."},{"ko":"내 앱의 기능 하나가 특정 장애를 가진 사용자를 위해 시작됐다면 모든 사람에게 어떤 이점이 될지 한 문단으로 적어 보세요.","en":"If one feature of yours started for users with a specific disability, write a paragraph on how it would help everyone."}],"ask":{"ko":"난독증 도구가 대중 생산성 앱이 된 지점은 어디였다고 느꼈나요?","en":"Where did you feel the dyslexia tool turned into a mainstream productivity app?"}},"Pawz":{"time":10,"setup":{"ko":"Vision Pro 전용 앱이라 Apple Vision Pro가 필요해요.","en":"It is a Vision Pro only app, so you need an Apple Vision Pro."},"missions":[{"ko":"앱을 처음 열고 반려동물이 내 방 어디에 나타나는지 지켜보세요. 가상 공간이 아니라 실제 방에 놓인다는 감각을 느껴 보세요.","en":"Open it for the first time and watch where the pet appears in your room. Feel that it sits in your real space, not a virtual scene."},{"ko":"반려동물과 함께 호흡 명상을 해 보세요. 혼자 하는 명상과 옆에 누군가 있는 명상이 어떻게 다른지 느껴 보세요.","en":"Do a guided breathing session with the pet. Feel how meditating alongside a companion differs from doing it alone."},{"ko":"미니게임에서 별을 모아 아이템으로 바꾸고 공간을 꾸며 보세요. 반려동물이 바뀐 환경에 어떻게 반응하는지 지켜보세요.","en":"Collect stars in the mini-game, trade them for items and decorate the space. Watch how the pet reacts to the change."}],"make":[{"ko":"내 앱의 반복 습관 기능 하나에 함께 해 주는 캐릭터가 있다면 어떻게 반응할지 세 가지 상태로 스케치해 보세요.","en":"Sketch three states of a companion character that would react to one habit feature in your app."},{"ko":"내 앱의 보상 구조를 적고, 경쟁 요소를 빼고도 다시 오고 싶게 만드는 장치 하나를 골라 보세요.","en":"Write out your app's reward loop and pick one hook that brings people back without any competition."}],"ask":{"ko":"실제 방에 놓인 반려동물이 명상을 다시 하고 싶게 만든 이유는 무엇이었나요?","en":"What about a pet in your real room made you want to meditate again?"}},"Neva":{"time":30,"setup":{"ko":"Mac 전용으로 안내된 유료 게임(￦33,000)이라 Mac이 필요해요.","en":"It is listed as Mac only and costs ￦33,000, so you need a Mac."},"missions":[{"ko":"게임을 시작해 첫 몇 분을 플레이해 보세요. 대사 없이 그림, 애니메이션, 음악만으로 상황이 전달되는지 확인해 보세요.","en":"Start and play the first few minutes. Check that the situation comes across with no dialogue, only art, animation and score."},{"ko":"Neva의 이름을 불러 늑대를 특정 지점으로 보내 보세요. 단순한 명령 하나가 동료와의 유대가 되는 순간을 느껴 보세요.","en":"Call Neva's name to send the wolf to a spot. Feel how one simple command becomes the bond with your companion."},{"ko":"전투에서 공격을 이어 체력을 회복해 보세요. 아이템을 찾아다니지 않아도 되는 흐름이 리듬을 어떻게 지키는지 보세요.","en":"Chain attacks in combat to regain health. See how not hunting for pickups keeps the rhythm going."},{"ko":"손으로 그린 애니메이션이 움직이는 장면에서 잠깐 멈춰 보세요. 프레임 사이를 보간하기 어려운 손그림의 질감을 살펴보세요.","en":"Pause on a hand-animated moment. Study the texture of drawings that are nearly impossible to interpolate."}],"make":[{"ko":"내 앱의 안내 문구 하나를 글 없이 애니메이션이나 그림만으로 전달하는 버전으로 바꿔 보세요.","en":"Rework one instructional message in your app so it comes across with animation or images only."},{"ko":"내 앱에서 사용자가 오래 쓸수록 바뀌는 요소 하나를 정하고, 처음과 한 달 뒤 화면을 나란히 그려 보세요.","en":"Choose one element of your app that changes with use and sketch it side by side at day one and a month later."}],"ask":{"ko":"Neva의 성장이 대사보다 더 강하게 전달된 순간은 언제였나요?","en":"When did Neva's growth say more than dialogue could?"}},"Dudel Draw":{"time":5,"setup":{"ko":"iPad와 Apple Pencil이 있으면 그리기 기능을 더 잘 느낄 수 있어요.","en":"An iPad with Apple Pencil lets you feel the drawing tools best."},"missions":[{"ko":"앱을 열고 오늘의 도형을 확인해 보세요. 빈 캔버스 대신 도형 하나가 주어졌을 때 시작이 얼마나 쉬워지는지 느껴 보세요.","en":"Open it and look at today's shape. Feel how much easier it is to start with one shape instead of a blank canvas."},{"ko":"도형을 그림으로 바꿔 그려 보세요. 두 손가락 탭으로 실행 취소, 두 번 탭으로 다시 실행을 해 보고 툴바가 없는 캔버스를 느껴 보세요.","en":"Turn the shape into a drawing. Try a two-finger tap to undo and a two-finger double-tap to redo, and feel the canvas without toolbars."},{"ko":"같은 도형으로 전혀 다른 그림을 하나 더 떠올려 그려 보세요. 선 하나가 얼마나 여러 가지로 변할 수 있는지 느껴 보세요.","en":"Draw a second, completely different idea from the same shape. Feel how many ways one squiggle can go."},{"ko":"홈 화면 위젯을 추가해 오늘의 도형과 내 그림이 어떻게 보이는지 확인해 보세요. 알림 없이 다시 부르는 방식을 살펴보세요.","en":"Add the home screen widget and see how today's shape and your drawing appear. Notice how it calls you back without notifications."}],"make":[{"ko":"내 앱의 빈 화면 하나에 매일 바뀌는 제약이나 출발점 하나를 넣어, 첫 행동을 정해 주는 버전을 만들어 보세요.","en":"Add one daily constraint or starting point to an empty screen in your app so the first action is set for the user."},{"ko":"내 앱의 연속 기록 표시를 벌주는 숫자 대신 자라는 그림으로 바꾼 시안을 그려 보세요.","en":"Draw a version of your app's streak display that grows a picture instead of a punishing counter."}],"ask":{"ko":"제약 하나가 창작을 막지 않고 오히려 열어 준 이유는 무엇일까요?","en":"Why did one constraint open up creativity instead of limiting it?"}},"Lost in Play":{"time":20,"setup":null,"missions":[{"ko":"게임을 시작해 첫 장면을 보세요. 대사 없이 손짓, 그림 기호, 소리만으로 무엇을 해야 하는지 알게 되는지 확인해 보세요.","en":"Start and watch the opening. Check whether you know what to do from gestures, pictograms and sounds alone."},{"ko":"첫 퍼즐에서 일부러 막혀 힌트를 써 보세요. 힌트가 답을 주지 않고 어느 정도까지만 밀어 주는지 살펴보세요.","en":"Get stuck on purpose at the first puzzle and use a hint. See how far it nudges you without giving the answer."},{"ko":"무서운 장면이나 놀라는 순간에 카메라가 어떻게 흔들리는지 보세요. TV 애니메이션 연출이 터치 게임에서 어떻게 살아나는지 느껴 보세요.","en":"Watch how the camera shakes on a scary or surprising beat. Feel TV animation staging come alive in a tap game."},{"ko":"퍼즐 사이에 나오는 미니게임 하나를 끝까지 해 보세요. 흐름이 바뀔 때 다시 집중이 살아나는지 느껴 보세요.","en":"Finish one mini-game between puzzles. Feel whether the change of pace brings your focus back."}],"make":[{"ko":"내 앱의 오류나 빈 상태 메시지 하나를 글 없이 그림 기호와 몸짓만으로 전달하는 버전으로 그려 보세요.","en":"Draw a version of one error or empty-state message in your app that uses only pictograms and gestures."},{"ko":"내 앱에서 사용자가 막히는 지점 하나에 답을 바로 주지 않는 단계별 힌트 세 개를 써 보세요.","en":"Write three graded hints for one place users get stuck in your app, none of which give the answer outright."}],"ask":{"ko":"말이 없어서 오히려 더 잘 전달된 장면은 무엇이었나요?","en":"Which scene came across better precisely because there were no words?"}},"Gentler Streak Fitness Tracker":{"time":10,"setup":{"ko":"Apple Watch의 심박 데이터가 있어야 활동 경로가 제대로 보여요.","en":"It shows the Activity Path properly only with heart-rate data from an Apple Watch."},"missions":[{"ko":"처음 실행해 건강 데이터 접근을 허용하고 첫 화면을 보세요. 정해진 목표 대신 내 상태에 맞춘 목표가 어떻게 제시되는지 살펴보세요.","en":"Launch it, grant Health access and study the first screen. Notice how a target fitted to your state replaces a fixed goal."},{"ko":"활동 경로에서 쉬는 날이 어떻게 표시되는지 찾아보세요. 쉬는 날도 성공으로 남는 순간 연속 기록의 압박이 어떻게 사라지는지 느껴 보세요.","en":"Find how a rest day appears on the Activity Path. Feel the streak pressure lift when rest still counts as success."},{"ko":"산책이나 집안일 같은 가벼운 활동을 기록해 보세요. 운동이 아닌 활동도 인정받는 느낌을 살펴보세요.","en":"Log a light activity like a walk or housework. Notice how it feels to have non-workout activity count."},{"ko":"위젯을 추가해 하루 요약을 확인해 보세요. 앱을 열지 않고도 오늘의 상태를 알 수 있는지 판단해 보세요.","en":"Add the widget and check the daily summary. Judge whether you know today's state without opening the app."}],"make":[{"ko":"내 앱의 연속 기록이나 목표 기능에서 하루 쉬면 무엇이 깨지는지 적고, 쉬는 날을 성공으로 처리하는 규칙을 하나 만들어 보세요.","en":"Write down what breaks in your streak or goal feature after a day off, and add one rule that counts rest as success."},{"ko":"내 앱이 사용자를 너무 몰아붙이는 순간 하나를 골라 오늘은 쉬어도 된다고 말해 주는 문구를 써 보세요.","en":"Pick one moment where your app pushes too hard and write copy that tells the user it is fine to rest today."}],"ask":{"ko":"쉬라고 말해 주는 앱을 다시 열고 싶어졌나요, 덜 열고 싶어졌나요?","en":"Did an app that tells you to rest make you want to open it more or less?"}},"Honkai: Star Rail":{"time":30,"setup":null,"missions":[{"ko":"첫 전투까지 플레이해 보세요. 턴제 전투를 한 손 탭만으로 진행할 수 있는지 직접 확인해 보세요.","en":"Play to the first battle. Check whether you can run the turn-based combat with one-handed taps."},{"ko":"궁극기를 써서 애니메이션 연출을 끝까지 보세요. 휴대폰 화면에서 콘솔급 연출이 어떤 느낌인지 살펴보세요.","en":"Fire an Ultimate and watch the full animation. Notice what console-grade cinematics feel like on a phone screen."},{"ko":"자동 전투와 배속을 켰다가 꺼 보세요. 짧은 세션을 존중하는 장치와 직접 조작의 균형을 느껴 보세요.","en":"Toggle auto-battle and speed-up on and off. Feel the balance between respecting short sessions and playing by hand."},{"ko":"전투에서 한 번 져 보거나 일부러 불리하게 싸워 보세요. 실패 후 다시 시도하는 흐름이 얼마나 빠른지 보세요.","en":"Lose a battle or fight at a deliberate disadvantage. See how quickly it lets you retry."}],"make":[{"ko":"내 앱의 반복 작업 하나에 자동으로 처리하기와 빠르게 처리하기 토글을 넣은 프로토타입을 만들어 보세요.","en":"Prototype auto and speed-up toggles for one repetitive task in your app."},{"ko":"내 앱의 핵심 성공 순간 하나에 1초짜리 전환 애니메이션을 넣어 보고 있을 때와 없을 때를 비교해 보세요.","en":"Add a one-second transition animation to one key success moment in your app and compare with and without it."}],"ask":{"ko":"깊은 전술 시스템이 휴대폰에서 부담스럽지 않았던 이유는 무엇인가요?","en":"Why didn't a deep tactics system feel heavy on a phone?"}},"Passenger Assistance":{"time":10,"setup":{"ko":"앱스토어에서 내려간 앱이라 개발사의 공식 소개 영상이나 스크린샷으로 경험해야 해요.","en":"The app has left the App Store, so experience it through the developer's own video or screenshots."},"missions":[{"ko":"공식 자료에서 프로필 만들기 화면을 찾아보세요. 장애와 필요한 도움을 한 번만 적으면 되는 구조가 어떻게 안내되는지 살펴보세요.","en":"Find the profile setup screen in the official material. See how it explains describing your needs only once."},{"ko":"예약 화면 스크린샷을 따라가며 철도 여정 하나에 도움을 요청하는 과정을 상상해 보세요. 전화 여러 통을 대신한 단계 수를 세어 보세요.","en":"Follow the booking screenshots and imagine requesting help for one rail journey. Count the steps that replaced several phone calls."},{"ko":"색상 테마 네 가지가 보이는 화면을 비교해 보세요. 고대비와 화면 낭독을 고려한 설계가 어디에 드러나는지 찾아보세요.","en":"Compare screens showing the four color themes. Find where high contrast and screen-reader support show up in the design."}],"make":[{"ko":"내 앱에서 사용자가 같은 정보를 반복해서 적는 곳을 찾아, 한 번 저장한 프로필로 채워지게 바꿔 보세요.","en":"Find where users retype the same information in your app and fill it from a profile saved once."},{"ko":"내 앱 화면 하나를 고대비 테마로 바꿔 보고 VoiceOver로 처음부터 끝까지 조작해 보세요.","en":"Switch one screen of your app to a high-contrast theme and operate it end to end with VoiceOver."}],"ask":{"ko":"다시 설명하지 않아도 된다는 것이 장애 승객에게 어떤 의미일까요?","en":"What does not having to explain again mean to a disabled passenger?"}},"Railbound":{"time":20,"setup":{"ko":"유료 게임(￦7,700)이에요.","en":"It is a paid game (￦7,700)."},"missions":[{"ko":"첫 레벨을 시작해 손가락으로 끌어 선로를 놓아 보세요. 설명 없이도 규칙을 알게 되기까지 몇 초가 걸리는지 재 보세요.","en":"Start the first level and drag to lay track. Time how many seconds it takes to grasp the rule without instructions."},{"ko":"번호가 붙은 객차를 순서대로 기관차에 이어 보세요. 틀렸을 때 게임이 무엇이 잘못됐는지 어떻게 보여 주는지 살펴보세요.","en":"Get the numbered carriages to the engine in order. Notice how the game shows what went wrong when you fail."},{"ko":"다음 월드로 넘어가 새 장치 하나가 처음 나오는 레벨을 풀어 보세요. 새 규칙이 한 번에 하나씩 소개되는 방식을 느껴 보세요.","en":"Move to the next world and solve the level that introduces a new mechanic. Feel how rules arrive one at a time."},{"ko":"레벨 하나를 깨고 월드 지도로 돌아가 보세요. 모바일에서 멈추기 좋은 지점이 어떻게 만들어졌는지 확인해 보세요.","en":"Clear a level and return to the world map. See how natural stopping points are built for mobile play."}],"make":[{"ko":"내 앱의 핵심 동작을 탭과 드래그 하나로만 할 수 있게 줄인 프로토타입을 만들어 보세요.","en":"Prototype your app's core action reduced to a single tap-and-drag."},{"ko":"내 앱의 기능들을 처음부터 한 번에 하나씩 소개하는 순서로 줄 세워 보세요.","en":"Line up your app's features in an order that introduces them one at a time from the start."}],"ask":{"ko":"입력이 단순해서 오히려 퍼즐이 깊어진 순간은 언제였나요?","en":"When did a simpler input actually make the puzzle deeper?"}},"Resident Evil Village":{"time":30,"setup":{"ko":"iPhone 15 Pro 이상이나 Apple 실리콘 iPad 또는 M1 이후 Mac이 필요하고, 전체 게임은 구매해야 해요.","en":"You need an iPhone 15 Pro or later, an Apple silicon iPad or an M1 or later Mac, and the full game is a purchase."},"missions":[{"ko":"게임을 시작해 첫 장면까지 플레이해 보세요. 휴대폰이나 Mac에서 콘솔 게임이 돌아간다는 첫인상을 확인해 보세요.","en":"Start and play to the opening scene. Take in the first impression of a console game running on your phone or Mac."},{"ko":"안개와 조명이 짙은 곳을 천천히 걸어 보세요. 프레임이 끊기는지, 화면이 흐려지는지 눈여겨보세요.","en":"Walk slowly through areas thick with fog and lighting. Watch for dropped frames or blur."},{"ko":"빠르게 움직이는 장면에서 화면 가장자리와 먼 배경의 선명함을 살펴보세요. 낮은 해상도로 그려 키우는 MetalFX 업스케일링이 티가 나는지 찾아보세요.","en":"In a fast-moving scene, study the sharpness of edges and distant backgrounds. Look for any sign of MetalFX upscaling from a lower internal resolution."}],"make":[{"ko":"내 앱에서 가장 무거운 화면 하나를 Instruments로 측정해 프레임이 떨어지는 지점을 찾아보세요.","en":"Profile your app's heaviest screen with Instruments and find where frames drop."},{"ko":"그 화면의 이미지나 효과 하나를 더 낮은 해상도로 그린 뒤 확대해 보여 주고, 눈으로 차이를 느낄 수 있는지 비교해 보세요.","en":"Render one image or effect on that screen at lower resolution, scale it up, and compare whether you can see the difference."}],"ask":{"ko":"낮게 그려서 키우는 방식이 내 앱의 어떤 화면에 쓸모 있을까요?","en":"Which screen in your app would benefit from rendering low and scaling up?"}},"Letter Rooms":{"time":10,"setup":null,"missions":[{"ko":"첫 방을 열고 화면을 보며 글자 하나를 옮겨 보세요. 규칙을 알기까지 얼마나 걸리는지 보세요.","en":"Open the first room and move a letter while looking. See how long it takes to learn the rule."},{"ko":"VoiceOver를 켜고 눈을 감은 채 다음 퍼즐 하나를 풀어 보세요. 화면을 보지 않고 글자 순서를 바꾸는 방법을 몸으로 익혀 보세요.","en":"Turn on VoiceOver, close your eyes and solve the next puzzle. Learn by feel how to rearrange letters without seeing."},{"ko":"OpenDyslexic 글꼴로 바꿔 보세요. 글자 모양이 달라질 때 읽기가 어떻게 달라지는지 느껴 보세요.","en":"Switch to the OpenDyslexic font. Feel how reading changes when the letterforms change."},{"ko":"어려운 레벨을 만나면 건너뛰어 보세요. 벌칙이 없을 때 계속하고 싶은 마음이 어떻게 달라지는지 살펴보세요.","en":"Skip a hard level when you meet one. Notice how having no penalty changes your urge to keep going."}],"make":[{"ko":"내 앱에서 드래그로만 되는 동작 하나를 찾아 VoiceOver 사용자 정의 액션으로도 할 수 있게 만들어 보세요.","en":"Find one drag-only action in your app and make it doable through a VoiceOver custom action."},{"ko":"내 앱에서 사용자가 막혀 멈추는 지점에 벌칙 없는 건너뛰기를 추가한 흐름을 만들어 보세요.","en":"Add a penalty-free skip at a point where users get stuck in your app."}],"ask":{"ko":"눈을 감고 풀었을 때 가장 놀랐던 점은 무엇인가요?","en":"What surprised you most when you solved it with your eyes closed?"}},"A Musical Story":{"time":20,"setup":{"ko":"유료 게임($4.99)이고, 이어폰을 끼고 하면 좋아요.","en":"It is a paid game ($4.99), and headphones help."},"missions":[{"ko":"게임을 시작해 첫 멜로디를 들어 보세요. 음표 길 없이 무엇을 해야 하는지 소리로 알게 되는지 확인해 보세요.","en":"Start and listen to the first melody. Check whether sound alone tells you what to do with no note highway."},{"ko":"악기 파트 하나에 맞춰 탭해 보세요. 화면을 보는 것과 눈을 감고 듣는 것 중 무엇이 더 잘 맞는지 비교해 보세요.","en":"Tap along to one instrument part. Compare whether watching or listening with eyes closed works better."},{"ko":"일부러 박자를 틀려 보세요. 실패를 어떻게 알려 주고 다시 시도하게 하는지 살펴보세요.","en":"Miss the beat on purpose. See how it signals failure and invites a retry."},{"ko":"멜로디를 완성해 다음 장으로 넘어가 보세요. 말 없이 노래 하나가 이야기를 진행시키는 순간을 느껴 보세요.","en":"Complete a melody and move to the next chapter. Feel a song advance the story without words."}],"make":[{"ko":"내 앱의 성공이나 실패 피드백 하나를 눈으로 보지 않아도 알 수 있도록 소리와 햅틱으로 다시 만들어 보세요.","en":"Remake one success or failure feedback in your app with sound and haptics so it works without looking."},{"ko":"내 앱 화면 하나에서 타이밍이 중요한 요소만 남기고 나머지 장식을 지워 보세요.","en":"On one screen of your app, remove every decoration except the elements that matter for timing."}],"ask":{"ko":"읽는 대신 듣게 한 설계가 플레이를 어떻게 바꿨나요?","en":"How did designing for listening instead of reading change the play?"}},"LEGO Star Wars: Castaways":{"time":20,"setup":{"ko":"Apple Arcade 구독이 필요해요.","en":"It requires an Apple Arcade subscription."},"missions":[{"ko":"처음 시작해 미니피규어를 만들어 보세요. 머리, 몸통, 다리를 섞는 선택이 주인공 고르기와 어떻게 다른지 느껴 보세요.","en":"Start and build your minifigure. Feel how mixing heads, torsos and legs differs from picking a hero."},{"ko":"섬 환경을 가까이 보며 모래와 절벽이 브릭으로 이뤄진 모습을 살펴보세요. 모든 브릭이 실제처럼 이어져 있는지 확인해 보세요.","en":"Look closely at the island and its sand and cliffs made of bricks. Check whether every brick connects as it would in reality."},{"ko":"우주선이나 큰 구조물을 가까이서 살펴보세요. 폴리곤을 약 90% 줄였는데도 빈틈이 느껴지는지 찾아보세요.","en":"Look closely at a ship or large structure. Look for any sign that about 90% of the polygons were cut."},{"ko":"소셜 허브에서 이모트를 쓰거나 미니게임에 참여해 보세요. 액션 게임이 어울리는 공간으로 바뀌는 순간을 느껴 보세요.","en":"Use an emote or join a mini-game in the social hub. Feel the action game turn into a place to hang out."}],"make":[{"ko":"내 앱의 무거운 화면에서 사용자가 실제로 보지 못하는 요소를 찾아 지우고, 렌더링 시간이 얼마나 줄어드는지 재 보세요.","en":"Find elements users never actually see on your heaviest screen, delete them and measure how much rendering time drops."},{"ko":"내 앱의 프로필 꾸미기를 미리 정한 캐릭터 고르기 대신 부분을 섞는 방식으로 바꾼 시안을 그려 보세요.","en":"Sketch a profile customization in your app that mixes parts instead of choosing a preset character."}],"ask":{"ko":"실제로 조립 가능하다는 제약이 화면에서 느껴졌나요?","en":"Could you feel the rule that everything must be physically buildable?"}},"1Password":{"time":15,"setup":{"ko":"새 계정을 만들면 Secret Key가 담긴 Emergency Kit를 저장할 곳을 미리 생각해 두세요.","en":"If you create a new account, plan where to keep the Emergency Kit with your Secret Key."},"missions":[{"ko":"가입 과정에서 Emergency Kit PDF를 저장하는 단계를 지나 보세요. 일부러 넣은 이 마찰이 어떻게 설명되는지 살펴보세요.","en":"Go through the sign-up step that saves the Emergency Kit PDF. Notice how this deliberate friction is explained."},{"ko":"다른 앱의 로그인 화면에서 자동 입력을 써 보세요. 복사 붙여넣기 없이 키보드 위로 계정이 올라오는 순간을 확인해 보세요.","en":"Use AutoFill on another app's login screen. Watch the credential appear above the keyboard without copy and paste."},{"ko":"패스키를 저장하는 안내를 따라가 보세요. 비밀번호 없는 로그인으로 넘어가게 하는 흐름이 얼마나 자연스러운지 느껴 보세요.","en":"Follow the prompt to save a passkey. Feel how naturally it moves you toward passwordless sign-in."},{"ko":"Watchtower에서 약하거나 재사용된 비밀번호 목록을 확인해 보세요. 보안 습관이 체크리스트로 보이는 방식을 살펴보세요.","en":"Check Watchtower's list of weak or reused passwords. See how security hygiene becomes a visible checklist."}],"make":[{"ko":"내 앱 로그인 화면의 텍스트 필드에 textContentType과 패스키 지원을 붙여 시스템 자동 입력이 뜨는지 확인해 보세요.","en":"Set textContentType on your login fields and add passkey support, then check that system AutoFill appears."},{"ko":"내 앱에서 사용자가 꼭 기억해야 할 것 하나를 정하고, 그것을 저장하게 하는 의도적인 단계 하나를 설계해 보세요.","en":"Pick one thing users must not lose in your app and design one deliberate step that makes them save it."}],"ask":{"ko":"일부러 넣은 마찰이 신뢰를 높인 순간은 언제였나요?","en":"When did deliberate friction increase your trust?"}},"Bird Alone":{"time":5,"setup":{"ko":"처음 부분은 무료이고 전체 게임은 $2.99 한 번 구매예요. 며칠에 걸쳐 매일 짧게 들러 보세요.","en":"The beginning is free and the full game is a one-time $2.99. Visit briefly every day over several days."},"missions":[{"ko":"처음 새를 만나 대화를 나눠 보세요. 탭으로 고르는 답 몇 개만으로 관계가 시작되는 느낌을 살펴보세요.","en":"Meet the bird for the first time and talk. Notice how a relationship begins with just a few tappable replies."},{"ko":"새의 배를 문지르거나 날씨를 건드려 보세요. 손가락으로 직접 만질 때 새가 화면 속에 실제로 있는 것처럼 느껴지는지 확인해 보세요.","en":"Rub the bird's belly or play with the weather. Check whether touching directly makes the bird feel present on the screen."},{"ko":"그림이나 시 하나를 만들어 보세요. 대화가 손에 남는 결과물로 바뀌는 방식을 느껴 보세요.","en":"Make a drawing or a poem. Feel how a conversation becomes something you keep."},{"ko":"다음 날 다시 들러 보세요. 실제 시간이 흘러 새와 계절이 어떻게 바뀌었는지 확인해 보세요.","en":"Come back the next day. See how the bird and season have changed in real time."}],"make":[{"ko":"내 앱에 하루 한 번만 열리는 짧은 콘텐츠 하나를 넣는다면 무엇일지 정하고 첫 화면을 그려 보세요.","en":"Decide what short once-a-day content your app could offer and sketch its first screen."},{"ko":"내 앱의 버튼 하나를 길게 누르거나 문지를 때 반응하는 직접 조작으로 바꾼 프로토타입을 만들어 보세요.","en":"Prototype one button in your app as a direct-manipulation touch that responds to a hold or rub."}],"ask":{"ko":"몰아서 하지 않고 매일 짧게 들르게 만든 힘은 무엇이었나요?","en":"What made you visit briefly each day instead of bingeing?"}},"Genshin Impact":{"time":30,"setup":{"ko":"게임 컨트롤러가 있으면 터치 조작과 비교해 볼 수 있어요.","en":"A game controller, if you have one, lets you compare it with touch controls."},"missions":[{"ko":"첫 장면부터 직접 움직여 보세요. 가상 조이스틱과 상황별 버튼이 콘솔 조작을 어떻게 옮겼는지 살펴보세요.","en":"Move from the first scene. Notice how the virtual joystick and contextual buttons translate console controls."},{"ko":"절벽을 오르고 높은 곳에서 활공해 보세요. 거의 어디든 갈 수 있는 세계가 휴대폰에서 어떻게 보이는지 느껴 보세요.","en":"Climb a cliff and glide down from somewhere high. Feel what an almost go-anywhere world looks like on a phone."},{"ko":"전투 중 탭 한 번으로 캐릭터를 바꿔 원소 반응을 일으켜 보세요. 복잡한 조합 없이 깊이가 생기는 순간을 확인해 보세요.","en":"Swap characters with one tap mid-fight to trigger an elemental reaction. See depth appear without complex combos."},{"ko":"적에게 쓰러져 보거나 높은 곳에서 떨어져 보세요. 실패 뒤 다시 이어 가는 흐름이 얼마나 빠른지 보세요.","en":"Get knocked out or fall from a height. See how quickly it lets you pick up again."}],"make":[{"ko":"내 앱에서 여러 단계가 필요한 조합 동작 하나를 한 번 탭으로 바꾸고 결과 연출로 깊이를 보여 주는 시안을 만들어 보세요.","en":"Turn one multi-step combined action in your app into a single tap and show its depth through the result."},{"ko":"내 앱 화면 하나에서 손가락이 닿는 영역에 상황에 따라 바뀌는 버튼 하나만 두는 레이아웃을 그려 보세요.","en":"Sketch a layout for one screen with a single contextual button in the thumb zone."}],"ask":{"ko":"휴대폰 화면에서 오픈 월드가 좁게 느껴지지 않았던 이유는 무엇인가요?","en":"Why didn't an open world feel cramped on a phone screen?"}},"Shapr 3D":{"time":20,"setup":{"ko":"iPad 전용으로 안내돼 있어 iPad가 필요하고, Apple Pencil이 있어야 제대로 경험할 수 있어요.","en":"It is listed as iPad only, so you need an iPad, and an Apple Pencil to experience it properly."},"missions":[{"ko":"처음 열고 무료 등급으로 첫 디자인을 시작해 보세요. 메뉴와 툴바가 얼마나 적은지 데스크톱 CAD와 비교해 보세요.","en":"Open it and start a first design on the free tier. Compare how few menus and toolbars it has against desktop CAD."},{"ko":"Apple Pencil로 단면을 그리고 손가락으로 당겨 입체로 만들어 보세요. 펜과 손가락의 역할이 나뉜 느낌을 몸으로 느껴 보세요.","en":"Sketch a profile with Apple Pencil and pull it into a solid with your finger. Feel the split between pen and finger."},{"ko":"만든 모델을 3D 프린팅용이나 CAD 형식으로 내보내 보세요. 스케치가 바로 제조 흐름으로 이어지는 단계 수를 세어 보세요.","en":"Export the model for 3D printing or a CAD format. Count the steps from sketch to manufacturing file."}],"make":[{"ko":"내 앱에서 Apple Pencil 입력과 손가락 입력에 서로 다른 역할을 주는 화면 하나를 프로토타입해 보세요.","en":"Prototype one screen in your app where Apple Pencil and finger input have different jobs."},{"ko":"내 앱의 툴바 버튼 하나를 없애고 같은 기능을 화면 위 직접 조작 제스처로 옮겨 보세요.","en":"Remove one toolbar button in your app and move its function to a direct gesture on the canvas."}],"ask":{"ko":"펜과 손가락을 나눈 설계가 메뉴를 얼마나 대신했나요?","en":"How much did splitting pen and finger replace menus?"}},"AllTrails":{"time":15,"setup":{"ko":"실제 산책로 근처 야외에서 써 보면 유료 기능의 가치가 더 잘 느껴져요.","en":"Using it outdoors near a real trail makes the paid features' value clearer."},"missions":[{"ko":"처음 열어 내 주변 트레일을 검색해 보세요. 지도, 리뷰, 사진을 무료로 어디까지 쓸 수 있는지 확인해 보세요.","en":"Open it and search for trails near you. Check how far maps, reviews and photos go for free."},{"ko":"트레일 하나를 열어 보세요. 난이도, 거리, 고도, 소요 시간, 최근 리뷰와 사진만으로 갈지 말지 판단할 수 있는지 스스로 정해 보세요.","en":"Open a trail. Decide whether difficulty, distance, elevation, time and recent reviews and photos are enough to choose whether to go."},{"ko":"그 트레일의 오프라인 지도를 저장하려 해 보세요. AllTrails+ 안내가 어느 순간 어떤 말로 나타나는지 살펴보세요.","en":"Try to save the trail's offline map. Note the moment and wording of the AllTrails+ prompt."},{"ko":"경로 이탈 알림 설명을 찾아 읽어 보세요. 신호가 끊긴 산속이라는 상황이 결제를 어떻게 설득하는지 느껴 보세요.","en":"Find and read the off-route alert explanation. Feel how the picture of losing signal in the mountains argues for paying."}],"make":[{"ko":"내 앱의 무료와 유료 경계를 적고, 유료 기능이 정말 필요한 순간에 안내가 뜨도록 위치를 옮겨 보세요.","en":"Write down your free and paid boundary and move the upgrade prompt to the moment the paid feature is truly needed."},{"ko":"내 앱의 상세 화면 하나에 사용자가 결정을 내리는 데 필요한 정보만 한 화면에 모은 버전을 만들어 보세요.","en":"Make a version of one detail screen that gathers on one screen only what users need to decide."}],"ask":{"ko":"결제하고 싶어진 순간이 있었다면 그때 앱은 어떤 상황을 떠올리게 했나요?","en":"If you felt like paying, what situation was the app making you picture?"}},"Snapchat":{"time":10,"setup":{"ko":"친구 한 명과 함께 해 보면 스토리와 사라지는 공유의 느낌을 더 잘 알 수 있어요.","en":"Trying it with one friend makes Stories and disappearing shares easier to feel."},"missions":[{"ko":"앱을 열자마자 무엇이 보이는지 확인해 보세요. 피드 대신 카메라가 뜨는 첫 화면이 보는 앱이 아니라 찍는 앱이라고 말하는지 느껴 보세요.","en":"Open the app and see what appears. Feel whether opening on the camera instead of a feed says this is an app for shooting, not watching."},{"ko":"카메라 화면에서 Lenses를 하나 얼굴에 써 보세요. 찍기 전에 놀이를 먼저 하게 되는 흐름을 살펴보세요.","en":"Try a Lens on your face from the camera screen. Notice how you end up playing before you shoot."},{"ko":"카메라에서 좌우, 상하로 스와이프해 채팅, 스토리, 추억 등으로 이동해 보세요. 숨은 화면을 찾느라 헤맨 순간을 세어 보세요.","en":"Swipe left, right, up and down from the camera to chat, Stories, Memories and more. Count the moments you got lost looking for a hidden screen."},{"ko":"사진 한 장을 My Story에 올려 보세요. 24시간 뒤 사라진다는 점이 올리기 전 망설임을 줄이는지 살펴보세요.","en":"Post a photo to My Story. Notice whether knowing it disappears in 24 hours lowers your hesitation."}],"make":[{"ko":"내 앱의 첫 화면을 가장 중요한 만들기 행동 하나로 바로 시작하게 바꾼 시안을 만들어 보세요.","en":"Make a version of your first screen that opens straight into your single most important creation action."},{"ko":"내 앱의 공유 기능에 일정 시간 뒤 사라지는 선택지를 넣는다면 어떤 화면이 될지 스케치해 보세요.","en":"Sketch what your sharing feature would look like with an option that disappears after a set time."}],"ask":{"ko":"숨겨진 제스처는 이 앱에서 장벽이었나요, 매력이었나요?","en":"Were the hidden gestures a barrier or part of the charm?"}},"Microsoft Excel":{"time":15,"setup":null,"missions":[{"ko":"새 통합 문서를 열고 도구 모음을 열어 보세요. 데스크톱 리본이 하단 시트로 접혀 홈, 삽입, 수식, 데이터 탭을 필요할 때만 펼치는 방식을 보세요.","en":"Open a new workbook and bring up the toolbar. See how the desktop ribbon folds into a bottom sheet that opens Home, Insert, Formulas and Data only when needed."},{"ko":"셀 하나에 간단한 합계 수식을 입력해 보세요. 키보드 위 수식 입력줄과 숫자, 함수 키 행이 몇 번의 탭을 줄여 주는지 세어 보세요.","en":"Type a simple sum formula into a cell. Count how many taps the formula bar and number and function key row above the keyboard save."},{"ko":"셀 선택 핸들을 끌어 범위를 잡고 탭 한 번으로 메뉴를 띄워 채우기를 해 보세요. 마우스 조작이 터치로 어떻게 번역됐는지 느껴 보세요.","en":"Drag the selection handles to set a range, tap once for the menu and use fill. Feel how mouse actions were translated to touch."},{"ko":"종이 표 하나를 카메라로 찍어 셀 데이터로 바꿔 보세요. 작은 화면 입력의 한계를 카메라가 얼마나 덜어 주는지 확인해 보세요.","en":"Photograph a paper table and turn it into cell data. Check how much the camera relieves the limits of small-screen input."}],"make":[{"ko":"내 앱의 입력 화면에 자주 쓰는 기호나 값을 담은 키보드 위 보조 행을 붙여 보세요.","en":"Add an accessory row above the keyboard with frequently used symbols or values to an input screen of yours."},{"ko":"내 앱의 메뉴 항목을 분류해 하단 시트 탭으로 묶고, 첫 화면에는 시트를 여는 버튼 하나만 남겨 보세요.","en":"Group your app's menu items into tabs inside a bottom sheet and leave only one button to open it on the main screen."}],"ask":{"ko":"데스크톱 기능을 터치로 옮길 때 이 앱이 가장 과감하게 숨긴 것은 무엇인가요?","en":"When moving desktop features to touch, what did this app hide most boldly?"}},"Photoroom":{"time":10,"setup":{"ko":"고해상도 내보내기와 워터마크 제거 같은 기능은 Pro 구독이에요.","en":"Features like high-resolution export and watermark removal need a Pro subscription."},"missions":[{"ko":"처음 열어 물건 사진 하나를 골라 보세요. 고르는 순간 배경이 사라진 결과가 나오기까지 몇 초 걸리는지 재 보세요.","en":"Open it and pick a photo of an object. Time how many seconds until the background-free result appears."},{"ko":"배경이 지워진 사진을 템플릿이나 AI 배경에 놓고 그림자나 조명을 다듬어 보세요. 기능 하나 위에 도구가 쌓인 구조를 느껴 보세요.","en":"Put the cut-out on a template or AI background and adjust shadow or lighting. Feel how tools are stacked on one feature."},{"ko":"마켓플레이스 규격 프리셋 하나를 골라 크기를 맞춰 보세요. 판매자라는 사용자를 얼마나 정확히 겨냥했는지 살펴보세요.","en":"Pick a marketplace size preset and fit the image. Notice how precisely it targets sellers."},{"ko":"결과물을 내보내 보세요. 워터마크나 해상도에서 업그레이드 안내가 어느 순간 나타나는지 확인해 보세요.","en":"Export the result. Note when the upgrade prompt appears around watermarks or resolution."}],"make":[{"ko":"Vision 프레임워크의 전경 분리로 사진 한 장의 배경을 지우는 작은 프로토타입을 만들어 보세요.","en":"Build a small prototype that removes a photo's background with the Vision framework's foreground segmentation."},{"ko":"내 앱의 핵심 기능이 끝난 바로 다음에 결과를 특정 용도에 맞춰 주는 프리셋 하나를 설계해 보세요.","en":"Design one preset right after your key feature finishes that fits the result to a specific use."}],"ask":{"ko":"첫 몇 초 안에 핵심 가치를 보여 준 것이 이후 결제 안내를 어떻게 받아들이게 했나요?","en":"How did seeing the core value in the first seconds change how you took the later upgrade prompt?"}},"밀리의 서재":{"time":15,"setup":{"ko":"구독 서비스라 해지 흐름은 실제 해지 직전까지만 따라가 보세요.","en":"It is a subscription, so follow the cancellation flow only up to the final step."},"missions":[{"ko":"처음 실행해 첫 달 무료 체험 안내가 어떻게 보이는지 살펴보세요. 가입 장벽을 낮추는 문구와 단계 수를 세어 보세요.","en":"Launch it and see how the first-month free trial is presented. Count the words and steps that lower the barrier to sign up."},{"ko":"책 한 권을 골라 전자책, 오디오북, 챗북 중 하나로 열어 보세요. 읽기 싫은 순간에도 소비할 수 있게 한 형식 차이를 느껴 보세요.","en":"Pick a book and open it as an ebook, audiobook or chat book. Feel how the formats let you keep going even when you do not feel like reading."},{"ko":"서재와 독서 기록, 완독 통계 화면을 둘러보세요. 쌓인 기록이 떠나기 어렵게 만드는 감각이 드는지 살펴보세요.","en":"Browse the library, reading log and completion stats. Notice whether the accumulated record makes leaving feel costly."},{"ko":"구독 관리에서 해지 흐름을 따라가 보세요. 남은 혜택, 읽던 책, 할인 제안이 어떤 순서로 나오는지 적어 보세요.","en":"Follow the cancellation flow in subscription management. Write down the order in which remaining benefits, books in progress and discount offers appear."}],"make":[{"ko":"내 앱의 해지나 탈퇴 흐름을 적고, 사용자가 잃게 되는 것을 정직하게 한 화면으로 보여 주는 버전을 써 보세요.","en":"Write out your cancellation or account deletion flow and draft one honest screen showing what the user would lose."},{"ko":"내 앱에서 사용자의 기록이 쌓이는 화면 하나를 골라 누적 통계 하나를 더해 보세요.","en":"Pick one screen where user history builds up in your app and add one cumulative statistic."}],"ask":{"ko":"해지 방어 화면은 붙잡는 장치였나요, 정보를 주는 화면이었나요?","en":"Was the retention screen a trap or a source of information?"}}}};
